INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37233, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前提", "is_correct": true, "explanation": "「上達の前提となる」で、練習を続けることが上達の基礎条件になるという意味に合う。"}, {"text": "包装", "is_correct": false, "explanation": "「上達の包装」は意味が通らない。包装は上達の条件にはならない。"}, {"text": "湿度", "is_correct": false, "explanation": "「上達の湿度」は合わない。湿度は上達の基礎条件を表さない。"}, {"text": "座布団", "is_correct": false, "explanation": "「上達の座布団」は意味が通らない。物の名前で、条件は表せない。"}], "explanations": {"前提": "「上達の前提となる」で、練習を続けることが上達の基礎条件になるという意味に合う。", "包装": "「上達の包装」は意味が通らない。包装は上達の条件にはならない。", "湿度": "「上達の湿度」は合わない。湿度は上達の基礎条件を表さない。", "座布団": "「上達の座布団」は意味が通らない。物の名前で、条件は表せない。"}, "sentence_index": 6, "correct_answer": "前提"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨の被害に備えて、土のうという前提を取った。", "explanation": "ここは〈対策〉の意味。前提は成り立つための条件で、被害に備えて取る手立ては対策と言い、前提とは言わない。"}, {"text": "参加者の前提を数えた。", "explanation": "ここは〈数〉の意味。前提は条件を指す言葉で、人数のように数えられるものではないので合わない。"}, {"text": "大きな前提を運んで、トラックに積んだ。", "explanation": "ここは〈荷物〉の意味。前提は条件を指す言葉で、物として運んだり積んだりはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37233, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このテストは、全員が時間内に終わることを前提と作られている。", "corrected_sentence": "このテストは、全員が時間内に終わることを前提に作られている。", "error_description": "助詞の誤り。「前提に作られている」が正しく、条件を示す「に」を使う。「前提と」は不自然で、前提を基準に作るという意味にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37233, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このイベントは、雨が降らないことを前提と計画されている。", "corrected_sentence": "このイベントは、雨が降らないことを前提に計画されている。", "error_description": "助詞の誤り。「計画されている」は前提を「に」で示す。「と」が誤りで、正しくは「に」。「前提と」は並列の意味になり、条件を表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37234, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「利便のために」の「の」で、名詞に付けて理由を示す形として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「利便がために」は成り立たない。主語を示す「が」はここには入らない。"}, {"text": "を", "is_correct": false, "explanation": "「利便をために」は不自然。目的語を示す「を」は「ために」の前には来ない。"}, {"text": "で", "is_correct": false, "explanation": "「利便でために」は成り立たない。手段の「で」ではここに入らない。"}], "correct_answer": "の", "explanations": {"の": "「利便のために」の「の」で、名詞に付けて理由を示す形として正しい。", "が": "「利便がために」は成り立たない。主語を示す「が」はここには入らない。", "を": "「利便をために」は不自然。目的語を示す「を」は「ために」の前には来ない。", "で": "「利便でために」は成り立たない。手段の「で」ではここに入らない。"}, "error_tags": {"が": "主語", "を": "対象（目的語）", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37234, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37234, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときに、便利で役に立つこと。", "primary_collocate": null, "pronunciation": "りべん", "ipa": "ɾibeɴ", "syllable_count": 3, "sentences": [{"text": "利用者の利便を考えて、駅に新しい出口を作った。", "target_word": "利便", "complexity_tier": "T3", "furigana": "利用者[りようしゃ]の利便[りべん]を考[かんが]えて、駅[えき]に新[あたら]しい出口[でぐち]を作[つく]った。", "sentence_source": "generated"}, {"text": "店は、客の利便のために夜十時まで開いている。", "target_word": "利便", "complexity_tier": "T3", "furigana": "店[みせ]は、客[きゃく]の利便[りべん]のために夜[よる]十時[じゅうじ]まで開[あ]いている。", "sentence_source": "generated"}, {"text": "市は、住民の利便を図るため、バスの本数を増やした。", "target_word": "利便", "complexity_tier": "T3", "furigana": "市[し]は、住民[じゅうみん]の利便[りべん]を図[はか]るため、バスの本数[ほんすう]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "駅の近くに店を作ると、買い物の利便が増える。", "target_word": "利便", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに店[みせ]を作[つく]ると、買[か]い物[もの]の利便[りべん]が増[ふ]える。", "sentence_source": "generated"}, {"text": "地図のアプリは、旅行者に大きな利便を与えている。", "target_word": "利便", "complexity_tier": "T3", "furigana": "地図[ちず]のアプリは、旅行者[りょこうしゃ]に大[おお]きな利便[りべん]を与[あた]えている。", "sentence_source": "generated"}, {"text": "私は広さより通勤の利便を大切にして、部屋を選んだ。", "target_word": "利便", "complexity_tier": "T3", "furigana": "私[わたし]は広[ひろ]さより通勤[つうきん]の利便[りべん]を大切[たいせつ]にして、部屋[へや]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "この町は病院も店も近く、暮らしの利便に恵まれている。", "target_word": "利便", "complexity_tier": "T3", "furigana": "この町[まち]は病院[びょういん]も店[みせ]も近[ちか]く、暮[く]らしの利便[りべん]に恵[めぐ]まれている。", "sentence_source": "generated"}, {"text": "利便だけを求めると、景色の美しさを失うことがある。", "target_word": "利便", "complexity_tier": "T3", "furigana": "利便[りべん]だけを求[もと]めると、景色[けしき]の美[うつく]しさを失[うしな]うことがある。", "sentence_source": "generated"}, {"text": "銀行は客の利便のために、スマホで手続きできるようにした。", "target_word": "利便", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]は客[きゃく]の利便[りべん]のために、スマホで手続[てつづ]きできるようにした。", "sentence_source": "generated"}, {"text": "道路が広がって、車で通う人の利便は大きく増した。", "target_word": "利便", "complexity_tier": "T3", "furigana": "道路[どうろ]が広[ひろ]がって、車[くるま]で通[かよ]う人[ひと]の利便[りべん]は大[おお]きく増[ま]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "利便", "label": "基本形"}], "register": "formal", "sense_fingerprint": "何かをするときの便利さ・役に立つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f48066bd-2190-4cb8-bbf1-f08443cd7da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37234, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利便", "is_correct": true, "explanation": "「利用者の利便を考えて」で、利用者にとっての便利さを指し、出口を作る理由として合う。"}, {"text": "包装", "is_correct": false, "explanation": "「利用者の包装を考えて」は意味が通らない。包装は便利さを表さない。"}, {"text": "天気", "is_correct": false, "explanation": "「利用者の天気を考えて」は意味が通らない。天気は出口を作る理由にならない。"}, {"text": "座布団", "is_correct": false, "explanation": "「利用者の座布団を考えて」は意味が通らない。物の名前で、便利さは表せない。"}], "explanations": {"利便": "「利用者の利便を考えて」で、利用者にとっての便利さを指し、出口を作る理由として合う。", "包装": "「利用者の包装を考えて」は意味が通らない。包装は便利さを表さない。", "天気": "「利用者の天気を考えて」は意味が通らない。天気は出口を作る理由にならない。", "座布団": "「利用者の座布団を考えて」は意味が通らない。物の名前で、便利さは表せない。"}, "sentence_index": 0, "correct_answer": "利便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "銀行に預けると利便がつく。", "explanation": "ここは〈利子〉の意味。利便は便利さを指し、預金に「つく」ものではないので合わない。"}, {"text": "彼は毎月、利便を稼いでいる。", "explanation": "ここは〈所得〉の意味。利便は便利さの意味で、お金のように稼ぐものではない。"}, {"text": "この箱の利便は五キロだ。", "explanation": "ここは〈重さ〉の意味。利便は便利さを指し、物の重さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37234, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利便", "is_correct": true, "explanation": "「暮らしの利便に恵まれている」で、暮らしやすい便利さに恵まれているという意味に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "「暮らしの手紙に恵まれている」は意味が通らない。手紙は暮らしの便利さを表さない。"}, {"text": "湿度", "is_correct": false, "explanation": "「暮らしの湿度に恵まれている」は合わない。湿度は暮らしの便利さではない。"}, {"text": "信号", "is_correct": false, "explanation": "「暮らしの信号に恵まれている」は意味が通らない。信号は便利さの内容にならない。"}], "explanations": {"利便": "「暮らしの利便に恵まれている」で、暮らしやすい便利さに恵まれているという意味に合う。", "手紙": "「暮らしの手紙に恵まれている」は意味が通らない。手紙は暮らしの便利さを表さない。", "湿度": "「暮らしの湿度に恵まれている」は合わない。湿度は暮らしの便利さではない。", "信号": "「暮らしの信号に恵まれている」は意味が通らない。信号は便利さの内容にならない。"}, "sentence_index": 6, "correct_answer": "利便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この電池は、利便が長い。", "explanation": "ここは〈寿命〉の意味。利便は便利さを指し、電池が持つ期間には使わない。"}, {"text": "会員は毎月の利便を払う。", "explanation": "ここは〈会費〉の意味。利便は便利さの意味で、お金として払うものではない。"}, {"text": "彼は利便を隠していた。", "explanation": "ここは〈年齢〉の意味。利便は便利さを指すため、隠す対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37234, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいバス路線は、通勤の利便が大きく高めた。", "corrected_sentence": "新しいバス路線は、通勤の利便を大きく高めた。", "error_description": "助詞の誤り。「高めた」は目的語を取る他動詞なので「を」が必要。「利便が」は主語になってしまい誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37234, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅の近くに住むと、通勤の利便が高まれる。", "corrected_sentence": "駅の近くに住むと、通勤の利便が高まる。", "error_description": "形の誤り。「高まる」は無生物の変化を表す自動詞で、可能形「高まれる」は人の能力を表す形のため不自然。正しくは「高まる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
