INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37235, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事が、人にとって使いやすく、都合がよいという性質。", "primary_collocate": null, "pronunciation": "りべん", "ipa": "ɾibeɴ", "syllable_count": 3, "sentences": [{"text": "この駅は、バスも電車も使えて利便がよい。", "target_word": "利便", "complexity_tier": "T3", "furigana": "この駅[えき]は、バスも電車[でんしゃ]も使[つか]えて利便[りべん]がよい。", "sentence_source": "generated"}, {"text": "山の上の家は景色はよいが、利便が悪い。", "target_word": "利便", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]の家[いえ]は景色[けしき]はよいが、利便[りべん]が悪[わる]い。", "sentence_source": "generated"}, {"text": "新しい機械は、古いものより利便に優れている。", "target_word": "利便", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]は、古[ふる]いものより利便[りべん]に優[すぐ]れている。", "sentence_source": "generated"}, {"text": "利便の差を比べて、二つの店のうち近いほうを選んだ。", "target_word": "利便", "complexity_tier": "T3", "furigana": "利便[りべん]の差[さ]を比[くら]べて、二[ふた]つの店[みせ]のうち近[ちか]いほうを選[えら]んだ。", "sentence_source": "generated"}, {"text": "駅に近いかどうかで、住む場所の利便は大きく変わる。", "target_word": "利便", "complexity_tier": "T3", "furigana": "駅[えき]に近[ちか]いかどうかで、住[す]む場所[ばしょ]の利便[りべん]は大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "家賃は安いが、利便の悪さが気になって引っ越した。", "target_word": "利便", "complexity_tier": "T3", "furigana": "家賃[やちん]は安[やす]いが、利便[りべん]の悪[わる]さが気[き]になって引[ひ]っ越[こ]した。", "sentence_source": "generated"}, {"text": "利便がよい場所は、そのぶん家賃も高くなる。", "target_word": "利便", "complexity_tier": "T3", "furigana": "利便[りべん]がよい場所[ばしょ]は、そのぶん家賃[やちん]も高[たか]くなる。", "sentence_source": "generated"}, {"text": "ネットで買い物ができるようになり、暮らしの利便が高まった。", "target_word": "利便", "complexity_tier": "T3", "furigana": "ネットで買[か]い物[もの]ができるようになり、暮[く]らしの利便[りべん]が高[たか]まった。", "sentence_source": "generated"}, {"text": "彼は景色より、会社に近いという利便を選んだ。", "target_word": "利便", "complexity_tier": "T3", "furigana": "彼[かれ]は景色[けしき]より、会社[かいしゃ]に近[ちか]いという利便[りべん]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "駅前は利便がよいので、昔から人が多く集まる。", "target_word": "利便", "complexity_tier": "T3", "furigana": "駅前[えきまえ]は利便[りべん]がよいので、昔[むかし]から人[ひと]が多[おお]く集[あつ]まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "利便", "label": "基本形"}], "register": "formal", "sense_fingerprint": "使いやすく都合がよいという性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f48066bd-2190-4cb8-bbf1-f08443cd7da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37235, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利便", "is_correct": true, "explanation": "「バスも電車も使えて利便がよい」で、使いやすく都合がよい性質を指し、文の意味に合う。"}, {"text": "寝袋", "is_correct": false, "explanation": "「使えて寝袋がよい」は意味が通らない。寝袋は駅の使いやすさを表さない。"}, {"text": "湿度", "is_correct": false, "explanation": "「使えて湿度がよい」は意味が通らない。湿度は使いやすさの性質ではない。"}, {"text": "漬物", "is_correct": false, "explanation": "「使えて漬物がよい」は意味が通らない。食べ物の名前で、性質は表せない。"}], "explanations": {"利便": "「バスも電車も使えて利便がよい」で、使いやすく都合がよい性質を指し、文の意味に合う。", "寝袋": "「使えて寝袋がよい」は意味が通らない。寝袋は駅の使いやすさを表さない。", "湿度": "「使えて湿度がよい」は意味が通らない。湿度は使いやすさの性質ではない。", "漬物": "「使えて漬物がよい」は意味が通らない。食べ物の名前で、性質は表せない。"}, "sentence_index": 0, "correct_answer": "利便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その選手は利便が重いことで有名だ。", "explanation": "ここは〈体重〉の意味。利便は物事の使いやすさを表し、人の重さには使わない。"}, {"text": "彼は利便が若く見える。", "explanation": "ここは〈年齢〉の意味。利便に若い・老いの区別はなく、年齢の話には合わない。"}, {"text": "この本は利便が薄い。", "explanation": "ここは〈厚さ〉の意味。利便は使いやすさの性質で、本の厚みは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37235, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利便", "is_correct": true, "explanation": "「利便がよい場所」で、使いやすく都合がよい性質を指し、家賃が高くなる理由として合う。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙がよい場所」は意味が通らない。手紙は場所の性質を表さない。"}, {"text": "包装", "is_correct": false, "explanation": "「包装がよい場所」は意味が通らない。包装は場所の使いやすさを表さない。"}, {"text": "座布団", "is_correct": false, "explanation": "「座布団がよい場所」は意味が通らない。物の名前で、場所の性質は表せない。"}], "explanations": {"利便": "「利便がよい場所」で、使いやすく都合がよい性質を指し、家賃が高くなる理由として合う。", "手紙": "「手紙がよい場所」は意味が通らない。手紙は場所の性質を表さない。", "包装": "「包装がよい場所」は意味が通らない。包装は場所の使いやすさを表さない。", "座布団": "「座布団がよい場所」は意味が通らない。物の名前で、場所の性質は表せない。"}, "sentence_index": 6, "correct_answer": "利便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は利便が豊かで、大きな声でよく歌う。", "explanation": "ここは〈声量〉の意味。利便は使いやすさの性質で、声の大きさには使わない。"}, {"text": "このスープは利便が濃い。", "explanation": "ここは〈味〉の意味。利便に濃淡はなく、味の濃さは表さない。"}, {"text": "このシャツは利便が鮮やかだ。", "explanation": "ここは〈色〉の意味。利便は使いやすさの性質で、色の鮮やかさは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37235, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は、どこへ行くにも利便をよい。", "corrected_sentence": "この店は、どこへ行くにも利便がよい。", "error_description": "助詞の誤り。形容詞「よい」は主語として「利便が」を取る。「利便を」は目的語用で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37235, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地区は、学校も病院も近くて利便が広い。", "corrected_sentence": "この地区は、学校も病院も近くて利便がよい。", "error_description": "語の誤用。利便の良し悪しは「よい」「悪い」で表す。「広い」は場所や面積に使い、利便の性質には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
