INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37236, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "小さくまとまったこと。", "primary_collocate": null, "pronunciation": "こんぱくと", "ipa": "kompakɯto", "syllable_count": 5, "sentences": [{"text": "このカメラはコンパクトで、かばんに入れやすいです。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "このカメラはコンパクトで、かばんに入[い]れやすいです。", "sentence_source": "generated"}, {"text": "コンパクトな車は、せまい道でも運転しやすいです。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "コンパクトな車[くるま]は、せまい道[みち]でも運転[うんてん]しやすいです。", "sentence_source": "generated"}, {"text": "小さな部屋なので、コンパクトな家具を選びました。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "小[ちい]さな部屋[へや]なので、コンパクトな家具[かぐ]を選[えら]びました。", "sentence_source": "generated"}, {"text": "旅行用に、コンパクトにたためるかさを買いました。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "旅行用[りょこうよう]に、コンパクトにたためるかさを買[か]いました。", "sentence_source": "generated"}, {"text": "このバッグはコンパクトで、電車の中でも場所をとりません。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "このバッグはコンパクトで、電車[でんしゃ]の中[なか]でも場所[ばしょ]をとりません。", "sentence_source": "generated"}, {"text": "コンパクトなパソコンは、持ち歩くのに便利です。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "コンパクトなパソコンは、持[も]ち歩[ある]くのに便利[べんり]です。", "sentence_source": "generated"}, {"text": "新しい事務所はコンパクトですが、使いやすいです。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "新[あたら]しい事務所[じむしょ]はコンパクトですが、使[つか]いやすいです。", "sentence_source": "generated"}, {"text": "この辞書はコンパクトなので、毎日持ち歩けます。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "この辞書[じしょ]はコンパクトなので、毎日[まいにち]持[も]ち歩[ある]けます。", "sentence_source": "generated"}, {"text": "台所がせまいので、コンパクトな冷蔵庫にしました。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "台所[だいどころ]がせまいので、コンパクトな冷蔵庫[れいぞうこ]にしました。", "sentence_source": "generated"}, {"text": "町がコンパクトにまとまっていて、どこへでも歩いて行けます。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "町[まち]がコンパクトにまとまっていて、どこへでも歩[ある]いて行[い]けます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コンパクト", "label": "基本形"}, {"form": "コンパクトな", "label": "連体形"}, {"form": "コンパクトに", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "小さくまとまっていて扱いやすいようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ac41b1-bf6a-4b52-9986-43adaca85130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37236, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コンパクト", "is_correct": true, "explanation": "カメラを小さくまとまったものとして説明し、かばんに入れやすいという内容に合う。"}, {"text": "派手", "is_correct": false, "explanation": "派手は見た目が目立つことで、かばんに入れやすさとは結びつかない。"}, {"text": "不便", "is_correct": false, "explanation": "「不便で、かばんに入れやすい」は前後の意味が逆になり、文脈に合わない。"}, {"text": "豪華", "is_correct": false, "explanation": "豪華は贅沢な見た目を表し、持ち運びやすさの説明には合わない。"}], "explanations": {"コンパクト": "カメラを小さくまとまったものとして説明し、かばんに入れやすいという内容に合う。", "派手": "派手は見た目が目立つことで、かばんに入れやすさとは結びつかない。", "不便": "「不便で、かばんに入れやすい」は前後の意味が逆になり、文脈に合わない。", "豪華": "豪華は贅沢な見た目を表し、持ち運びやすさの説明には合わない。"}, "sentence_index": 0, "correct_answer": "コンパクト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "たくさん食べて、もうコンパクトです。", "explanation": "ここは〈満腹〉の意味。コンパクトは小さくまとまったようすで、お腹がいっぱいの状態には使わない。"}, {"text": "この箱のコンパクトは、一メートルです。", "explanation": "ここは〈大きさ〉の意味。コンパクトは小さくまとまった状態で、数値で測る大きさは表せない。"}, {"text": "野菜はコンパクトが多いです。", "explanation": "ここは〈水分〉の意味。コンパクトは小さくまとまったようすで、中に含まれる水の量には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37236, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コンパクト", "is_correct": true, "explanation": "事務所の規模を表し、「ですが、使いやすい」という内容として自然に続く。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は人や雰囲気の明るさを表し、事務所の大きさの説明には合わない。"}, {"text": "大胆", "is_correct": false, "explanation": "大胆は行動の思い切りを表し、事務所の性質として使うと不自然。"}, {"text": "乱暴", "is_correct": false, "explanation": "乱暴は扱いの荒さを表し、「使いやすい」との対比として成り立たない。"}], "explanations": {"コンパクト": "事務所の規模を表し、「ですが、使いやすい」という内容として自然に続く。", "陽気": "陽気は人や雰囲気の明るさを表し、事務所の大きさの説明には合わない。", "大胆": "大胆は行動の思い切りを表し、事務所の性質として使うと不自然。", "乱暴": "乱暴は扱いの荒さを表し、「使いやすい」との対比として成り立たない。"}, "sentence_index": 6, "correct_answer": "コンパクト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪をひいてから、体のぐあいがコンパクトです。", "explanation": "ここは〈体調〉の意味。コンパクトは小さくまとまったようすで、体の調子の良し悪しは表せない。"}, {"text": "冷え込みがコンパクトで、外に出られません。", "explanation": "ここは〈寒さ〉の意味。コンパクトは小さくまとまったようすで、気温の厳しさは表せない。"}, {"text": "明日は空模様がコンパクトなので、遠足は中止になりました。", "explanation": "ここは〈天気〉の意味。コンパクトは小さくまとまったようすで、天候の状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37236, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この傘はコンパクトな折りたためます。", "corrected_sentence": "この傘はコンパクトに折りたためます。", "error_description": "活用形の誤り。正しくは「コンパクトに」（連用形）。「な」は名詞に続く形なので、動詞「たためます」を修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "コンパクト", "is_correct": true, "explanation": "形状詞の基本形で、「な車」と続けて名詞を修飾できる。"}, {"text": "コンパクトに", "is_correct": false, "explanation": "連用形で、「な車」の形に合わず名詞を直接修飾できない。"}, {"text": "コンパクトで", "is_correct": false, "explanation": "て形で、「で」のあとに「な車」は続かず文が成り立たない。"}, {"text": "コンパクトだ", "is_correct": false, "explanation": "断定の形で、「だ」のあとに「な車」は続かず名詞を修飾できない。"}], "correct_form": "コンパクト", "base_form": "コンパクト", "form_label": "基本形", "sentence_index": 1, "explanations": {"コンパクト": "形状詞の基本形で、「な車」と続けて名詞を修飾できる。", "コンパクトに": "連用形で、「な車」の形に合わず名詞を直接修飾できない。", "コンパクトで": "て形で、「で」のあとに「な車」は続かず文が成り立たない。", "コンパクトだ": "断定の形で、「だ」のあとに「な車」は続かず名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37236, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅の近くのアパートは、コンパクトのに家賃が安いです。", "corrected_sentence": "駅の近くのアパートは、コンパクトなのに家賃が安いです。", "error_description": "活用形の誤り。「コンパクト」は形状詞なので、「な」を付けて「なのに」とする必要がある。「の」では文法的に成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "コンパクト", "is_correct": true, "explanation": "形状詞の基本形で、「なので」と続いて理由を表す。"}, {"text": "コンパクトだった", "is_correct": false, "explanation": "過去の断定形で、「だった」のあとに「なので」は続かない。"}, {"text": "コンパクトくて", "is_correct": false, "explanation": "形容詞の活用形で、形状詞には付かないので「くて」は使えない。"}, {"text": "コンパクトらしく", "is_correct": false, "explanation": "様態の連用形で、「なので」の前には続かず理由を表せない。"}], "correct_form": "コンパクト", "base_form": "コンパクト", "form_label": "基本形", "sentence_index": 7, "explanations": {"コンパクト": "形状詞の基本形で、「なので」と続いて理由を表す。", "コンパクトだった": "過去の断定形で、「だった」のあとに「なので」は続かない。", "コンパクトくて": "形容詞の活用形で、形状詞には付かないので「くて」は使えない。", "コンパクトらしく": "様態の連用形で、「なので」の前には続かず理由を表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
