INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37237, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "場所をとらず、機能や部品が効率よく詰まっていて、まとまりがよい様子。", "primary_collocate": null, "pronunciation": "こんぱくと", "ipa": "kompakɯto", "syllable_count": 5, "sentences": [{"text": "このコンパクトな掃除機は、小さいのに力が強いです。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "このコンパクトな掃除機[そうじき]は、小[ちい]さいのに力[ちから]が強[つよ]いです。", "sentence_source": "generated"}, {"text": "コンパクトなキッチンですが、使いやすくて便利です。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "コンパクトなキッチンですが、使[つか]いやすくて便利[べんり]です。", "sentence_source": "generated"}, {"text": "コンパクトな設計なので、家具を置いても部屋が広いです。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "コンパクトな設計[せっけい]なので、家具[かぐ]を置[お]いても部屋[へや]が広[ひろ]いです。", "sentence_source": "generated"}, {"text": "この携帯電話は、多くの機能がコンパクトに入っています。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "この携帯電話[けいたいでんわ]は、多[おお]くの機能[きのう]がコンパクトに入[はい]っています。", "sentence_source": "generated"}, {"text": "弟の部屋はコンパクトですが、必要な物は全部そろっています。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "弟[おとうと]の部屋[へや]はコンパクトですが、必要[ひつよう]な物[もの]は全部[ぜんぶ]そろっています。", "sentence_source": "generated"}, {"text": "コンパクトなスピーカーなのに、音がとても大きいです。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "コンパクトなスピーカーなのに、音[おと]がとても大[おお]きいです。", "sentence_source": "generated"}, {"text": "この工具セットはコンパクトで、車の中でも場所をとりません。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "この工具[こうぐ]セットはコンパクトで、車[くるま]の中[なか]でも場所[ばしょ]をとりません。", "sentence_source": "generated"}, {"text": "コンパクトなデザインのおかげで、机の上が広く使えます。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "コンパクトなデザインのおかげで、机[つくえ]の上[うえ]が広[ひろ]く使[つか]えます。", "sentence_source": "generated"}, {"text": "新しいプリンターはコンパクトになり、棚にもしまえます。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "新[あたら]しいプリンターはコンパクトになり、棚[たな]にもしまえます。", "sentence_source": "generated"}, {"text": "コンパクトな家でも、収納が多ければ暮らしやすいです。", "target_word": "コンパクト", "complexity_tier": "T3", "furigana": "コンパクトな家[いえ]でも、収納[しゅうのう]が多[おお]ければ暮[く]らしやすいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コンパクトだ", "label": "終止形"}, {"form": "コンパクトな", "label": "連体形"}, {"form": "コンパクトに", "label": "連用形"}], "register": "丁寧", "sense_fingerprint": "場所をとらず機能が効率よく詰まっている様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a7c10f-7617-45e5-a3d0-bcfe1bdfc1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37237, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コンパクト", "is_correct": true, "explanation": "「コンパクトな掃除機」として、場所をとらず力が詰まっている様子を表す正解。"}, {"text": "平和", "is_correct": false, "explanation": "「平和な掃除機」は意味が通らず、空欄に入らない。"}, {"text": "正直", "is_correct": false, "explanation": "「正直な掃除機」は成り立たず、文脈に合わない。"}, {"text": "明確", "is_correct": false, "explanation": "「明確な掃除機」は意味が通らず、空欄に入らない。"}], "explanations": {"コンパクト": "「コンパクトな掃除機」として、場所をとらず力が詰まっている様子を表す正解。", "平和": "「平和な掃除機」は意味が通らず、空欄に入らない。", "正直": "「正直な掃除機」は成り立たず、文脈に合わない。", "明確": "「明確な掃除機」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "コンパクト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女はコンパクトに優しくて、みんなに好かれた。", "explanation": "ここは〈優しい〉の意味。コンパクトは場所をとらない様子で、人柄の温かさは表さない。"}, {"text": "彼はコンパクトに大笑いして、みんなを驚かせた。", "explanation": "ここは〈豪快〉の意味。コンパクトは場所をとらない様子で、勢いのある笑い方には使わない。"}, {"text": "この携帯電話はコンパクトな値段で買えた。", "explanation": "ここは〈格安〉の意味。コンパクトは機能の詰まり方を表し、価格の安さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37237, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コンパクト", "is_correct": true, "explanation": "「この工具セットはコンパクトで」と述語になり、場所をとらない様子を表す正解。"}, {"text": "親切", "is_correct": false, "explanation": "「親切で、車の中でも場所をとりません」は意味が通らず、空欄に入らない。"}, {"text": "神秘", "is_correct": false, "explanation": "「神秘で、場所をとりません」は文として成り立たない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気で、場所をとりません」は意味が通らず、文脈に合わない。"}], "explanations": {"コンパクト": "「この工具セットはコンパクトで」と述語になり、場所をとらない様子を表す正解。", "親切": "「親切で、車の中でも場所をとりません」は意味が通らず、空欄に入らない。", "神秘": "「神秘で、場所をとりません」は文として成り立たない。", "陽気": "「陽気で、場所をとりません」は意味が通らず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "コンパクト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女はコンパクトな表情で、答えを考えていた。", "explanation": "ここは〈真剣〉の意味。コンパクトは場所をとらない様子で、表情の真剣さは表さない。"}, {"text": "映画のラストで、彼女はコンパクトに心が動いた。", "explanation": "ここは〈感動〉の意味。コンパクトは場所をとらない様子で、心の動きの大きさは表さない。"}, {"text": "このパーティーにはコンパクトな色の服を着ていった。", "explanation": "ここは〈派手〉の意味。コンパクトは機能や場所の効率を表し、色の目立ち方には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37237, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "機能が多いのに場所をとらないコンパクトの設計です。", "corrected_sentence": "機能が多いのに場所をとらないコンパクトな設計です。", "error_description": "形状詞の「コンパクト」は名詞を修飾するとき「な」を付ける。「の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "コンパクト", "is_correct": true, "explanation": "正解。「コンパクトなキッチン」の「な」を外した語幹で、名詞の前に「な」を付けて修飾する。"}, {"text": "コンパクトだ", "is_correct": false, "explanation": "終止形なので名詞「キッチン」の前に直接置けず、「コンパクトだキッチン」は成り立たない。"}, {"text": "コンパクトに", "is_correct": false, "explanation": "連用形は名詞を修飾できず、「コンパクトにキッチン」は文の形に合わない。"}, {"text": "コンパクトだった", "is_correct": false, "explanation": "「な」が後に続くため、「コンパクトだったなキッチン」となり成り立たない。"}], "correct_form": "コンパクト", "base_form": "コンパクト", "form_label": "語幹", "sentence_index": 1, "explanations": {"コンパクト": "正解。「コンパクトなキッチン」の「な」を外した語幹で、名詞の前に「な」を付けて修飾する。", "コンパクトだ": "終止形なので名詞「キッチン」の前に直接置けず、「コンパクトだキッチン」は成り立たない。", "コンパクトに": "連用形は名詞を修飾できず、「コンパクトにキッチン」は文の形に合わない。", "コンパクトだった": "「な」が後に続くため、「コンパクトだったなキッチン」となり成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37237, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家の中が狭くても、コンパクトに収納棚なら物がたくさん入ります。", "corrected_sentence": "家の中が狭くても、コンパクトな収納棚なら物がたくさん入ります。", "error_description": "「コンパクトな収納棚」と形状詞の「な」で名詞を修飾する。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "コンパクト", "is_correct": true, "explanation": "正解。「コンパクトなデザイン」の「な」を外した語幹で、名詞の前に「な」を付けて修飾する形の基になる。"}, {"text": "コンパクトで", "is_correct": false, "explanation": "中止形・て形なので、名詞「デザイン」に直接続けられず、「コンパクトでデザイン」は成り立たない。"}, {"text": "コンパクトなら", "is_correct": false, "explanation": "仮定の形なので名詞の前に置けず、「コンパクトならデザイン」は文の形に合わない。"}, {"text": "コンパクトだから", "is_correct": false, "explanation": "理由を表す形なので名詞を修飾できず、「コンパクトだからデザイン」は成り立たない。"}], "correct_form": "コンパクト", "base_form": "コンパクト", "form_label": "語幹", "sentence_index": 7, "explanations": {"コンパクト": "正解。「コンパクトなデザイン」の「な」を外した語幹で、名詞の前に「な」を付けて修飾する形の基になる。", "コンパクトで": "中止形・て形なので、名詞「デザイン」に直接続けられず、「コンパクトでデザイン」は成り立たない。", "コンパクトなら": "仮定の形なので名詞の前に置けず、「コンパクトならデザイン」は文の形に合わない。", "コンパクトだから": "理由を表す形なので名詞を修飾できず、「コンパクトだからデザイン」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37238, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〈には〉で、この市に毎週市場があるという場所の前提を示す。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示すが、ここは場所について述べる文なので合わない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、後ろの〈は〉と重なり〈シティーがは〉と不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ〈の〉は、〈シティーのは〉と続くと文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "〈には〉で、この市に毎週市場があるという場所の前提を示す。", "を": "動作の対象を示すが、ここは場所について述べる文なので合わない。", "が": "主語を示すが、後ろの〈は〉と重なり〈シティーがは〉と不自然になる。", "の": "名詞をつなぐ〈の〉は、〈シティーのは〉と続くと文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37238, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "到達点や終点を示す〈まで〉で、〈となりのシティーまで〉の距離を表す。"}, {"text": "と", "is_correct": false, "explanation": "並べる相手を示すが、〈となりのシティーと、バスで〉は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比べる対象を示すが、距離の終点を表さず文が合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す〈を〉は、〈となりのシティーを〉では移動の終点にならず、文が成り立たない。"}], "correct_answer": "まで", "explanations": {"まで": "到達点や終点を示す〈まで〉で、〈となりのシティーまで〉の距離を表す。", "と": "並べる相手を示すが、〈となりのシティーと、バスで〉は意味が通らない。", "より": "比べる対象を示すが、距離の終点を表さず文が合わない。", "を": "目的語を示す〈を〉は、〈となりのシティーを〉では移動の終点にならず、文が成り立たない。"}, "error_tags": {"と": "並列・相手", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37238, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人がそこで生活し、暮らしている地域としての、まち。", "primary_collocate": null, "pronunciation": "してぃー", "ipa": "ɕitiː", "syllable_count": 3, "sentences": [{"text": "私はこのシティーで生まれて、今も住んでいます。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "私[わたし]はこのシティーで生[う]まれて、今[いま]も住[す]んでいます。", "sentence_source": "generated"}, {"text": "このシティーには、毎週土曜日に大きな市場が開かれます。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "このシティーには、毎週[まいしゅう]土曜日[どようび]に大[おお]きな市場[いちば]が開[ひら]かれます。", "sentence_source": "generated"}, {"text": "夏休みに、海の近くのシティーへ行きました。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、海[うみ]の近[ちか]くのシティーへ行[い]きました。", "sentence_source": "generated"}, {"text": "そのシティーは静かで、夜は星がよく見えます。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "そのシティーは静[しず]かで、夜[よる]は星[ほし]がよく見[み]えます。", "sentence_source": "generated"}, {"text": "シティーの真ん中に、古い図書館があります。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "シティーの真[ま]ん中[なか]に、古[ふる]い図書館[としょかん]があります。", "sentence_source": "generated"}, {"text": "私たちのシティーでは、毎年春に祭りがあります。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "私[わたし]たちのシティーでは、毎年[まいとし]春[はる]に祭[まつ]りがあります。", "sentence_source": "generated"}, {"text": "駅から歩いて、シティーの中を見て回りました。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "駅[えき]から歩[ある]いて、シティーの中[なか]を見[み]て回[まわ]りました。", "sentence_source": "generated"}, {"text": "となりのシティーまで、バスで三十分かかります。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "となりのシティーまで、バスで三十分[さんじゅっぷん]かかります。", "sentence_source": "generated"}, {"text": "このシティーの人はみんな親切で、道を教えてくれました。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "このシティーの人[ひと]はみんな親切[しんせつ]で、道[みち]を教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "友達が住むシティーは、川がきれいなことで有名です。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "友達[ともだち]が住[す]むシティーは、川[かわ]がきれいなことで有名[ゆうめい]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シティー", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "人が住むまち、という意味のシティー", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a7c10f-7617-45e5-a3d0-bcfe1bdfc1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37238, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スープ", "is_correct": false, "explanation": "食べ物で、人が生まれて住む場所にはならない。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "布製品で、生まれて住む場所を表さない。"}, {"text": "シティー", "is_correct": true, "explanation": "生まれて今も住んでいる「まち」を指すので、この文の場所に入る。"}, {"text": "ボタン", "is_correct": false, "explanation": "服の部品で、人が生まれて住む場所にならない。"}], "explanations": {"スープ": "食べ物で、人が生まれて住む場所にはならない。", "ハンカチ": "布製品で、生まれて住む場所を表さない。", "シティー": "生まれて今も住んでいる「まち」を指すので、この文の場所に入る。", "ボタン": "服の部品で、人が生まれて住む場所にならない。"}, "sentence_index": 0, "correct_answer": "シティー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の試合は、シティーが後半に二点を取って勝ちました。", "explanation": "ここはサッカーなどの〈チーム〉の意味。まちを指すシティーは試合で点を取る主体にはならないので合わない。"}, {"text": "週末は、新しいシティーで海へドライブに行きました。", "explanation": "ここは車種名の意味。まちを指すシティーとは別の語として使われている。"}, {"text": "週末に、シティーハンターのアニメを一気に見ました。", "explanation": "ここは作品名の意味。まちを指すシティーとは別の固有名詞として使われている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37238, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ケーキ", "is_correct": false, "explanation": "食べ物で、歩いて中を見て回る場所にはならない。"}, {"text": "シティー", "is_correct": true, "explanation": "歩いて見て回れる「まちの中」を表すので、ここに入る。"}, {"text": "ラケット", "is_correct": false, "explanation": "スポーツの道具で、中を見て回れる場所ではない。"}, {"text": "ゴム", "is_correct": false, "explanation": "材料で、人が歩いて見て回る場所ではない。"}], "explanations": {"ケーキ": "食べ物で、歩いて中を見て回る場所にはならない。", "シティー": "歩いて見て回れる「まちの中」を表すので、ここに入る。", "ラケット": "スポーツの道具で、中を見て回れる場所ではない。", "ゴム": "材料で、人が歩いて見て回る場所ではない。"}, "sentence_index": 6, "correct_answer": "シティー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山あいのシティーには、家が三軒しかなく、畑が広がっています。", "explanation": "ここは〈村〉の意味。家が三軒の集落は、まちを指すシティーとは言えないので合わない。"}, {"text": "来年は、シティー納税に申し込もうと思います。", "explanation": "ここは〈ふるさと〉の意味。〈ふるさと納税〉は決まった言い方で、シティーとは組み合わせない。"}, {"text": "週末は、シティーポップのライブに行きました。", "explanation": "ここは音楽のジャンル名の意味。まちを指すシティーの意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37238, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このシティーを、毎週土曜日に大きな市場が開かれます。", "corrected_sentence": "このシティーでは、毎週土曜日に大きな市場が開かれます。", "error_description": "〈シティー〉に続く助詞が誤り。市場が開かれる場所は〈で〉（〜では）で示す。〈を〉は目的語を示すので、ここでは文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37238, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達はシティーが住んでいます。", "corrected_sentence": "友達はシティーに住んでいます。", "error_description": "〈住む〉の場所は〈に〉で示す。〈が〉にするとシティーが主語になり、住む人がいない文になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37239, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〈には〉で、この市に大きな会社や美術館があるという所在を示す。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示すが、ここは存在を述べる文なので合わない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、後ろの〈は〉と重なり〈シティーがは〉と不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ〈の〉は、〈シティーのは〉と続くと文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "〈には〉で、この市に大きな会社や美術館があるという所在を示す。", "を": "動作の対象を示すが、ここは存在を述べる文なので合わない。", "が": "主語を示すが、後ろの〈は〉と重なり〈シティーがは〉と不自然になる。", "の": "名詞をつなぐ〈の〉は、〈シティーのは〉と続くと文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37239, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "〈シティーの中心〉と名詞をつなぐ〈の〉が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、名詞をつなぐ位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、〈シティーで中心には〉と続くと意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、ここには動作の対象がなく〈中心には〉と続かないので合わない。"}], "correct_answer": "の", "explanations": {"の": "〈シティーの中心〉と名詞をつなぐ〈の〉が正しい。", "へ": "方向を示すが、名詞をつなぐ位置には合わない。", "で": "場所や手段を示すが、〈シティーで中心には〉と続くと意味が通らない。", "を": "目的語を示すが、ここには動作の対象がなく〈中心には〉と続かないので合わない。"}, "error_tags": {"へ": "方向", "で": "場所・手段", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37239, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "都市。大きな町。特に、たくさんの人が住んでいて、商業や文化が発展している地域を指します。", "primary_collocate": null, "pronunciation": "してぃー", "ipa": "ɕitiː", "syllable_count": 3, "sentences": [{"text": "東京は人が多く、商業も文化も発展したシティーです。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "東京[とうきょう]は人[ひと]が多[おお]く、商業[しょうぎょう]も文化[ぶんか]も発展[はってん]したシティーです。", "sentence_source": "generated"}, {"text": "このシティーには、大きな会社や美術館がたくさんあります。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "このシティーには、大[おお]きな会社[かいしゃ]や美術館[びじゅつかん]がたくさんあります。", "sentence_source": "generated"}, {"text": "田舎からシティーに出て、新しい仕事を始めました。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "田舎[いなか]からシティーに出[で]て、新[あたら]しい仕事[しごと]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "世界中から観光客が集まる大きなシティーを旅しました。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "世界中[せかいじゅう]から観光客[かんこうきゃく]が集[あつ]まる大[おお]きなシティーを旅[たび]しました。", "sentence_source": "generated"}, {"text": "シティーの夜は明るく、遅くまで店が開いています。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "シティーの夜[よる]は明[あか]るく、遅[おそ]くまで店[みせ]が開[あ]いています。", "sentence_source": "generated"}, {"text": "そのシティーは港で栄え、今は多くの国の人が働いています。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "そのシティーは港[みなと]で栄[さか]え、今[いま]は多[おお]くの国[くに]の人[ひと]が働[はたら]いています。", "sentence_source": "generated"}, {"text": "シティーで暮らすと便利ですが、家賃が高いのが困ります。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "シティーで暮[く]らすと便利[べんり]ですが、家賃[やちん]が高[たか]いのが困[こま]ります。", "sentence_source": "generated"}, {"text": "大きなシティーの中心には、高いビルが並んでいます。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "大[おお]きなシティーの中心[ちゅうしん]には、高[たか]いビルが並[なら]んでいます。", "sentence_source": "generated"}, {"text": "このシティーは音楽の文化が盛んで、毎晩どこかで演奏があります。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "このシティーは音楽[おんがく]の文化[ぶんか]が盛[さか]んで、毎晩[まいばん]どこかで演奏[えんそう]があります。", "sentence_source": "generated"}, {"text": "人口が増えて、小さな町が大きなシティーに変わりました。", "target_word": "シティー", "complexity_tier": "T3", "furigana": "人口[じんこう]が増[ふ]えて、小[ちい]さな町[まち]が大[おお]きなシティーに変[か]わりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シティー", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "人口が多く商業や文化が発展した大きな都市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a7c10f-7617-45e5-a3d0-bcfe1bdfc1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37239, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ペン", "is_correct": false, "explanation": "筆記用具で、商業や文化が発展した地域を表さない。"}, {"text": "シティー", "is_correct": true, "explanation": "商業や文化が発展した大きなまちを表すので、ここに入る。"}, {"text": "ドア", "is_correct": false, "explanation": "建物の部品で、地域の性質を表す語として合わない。"}, {"text": "ケーキ", "is_correct": false, "explanation": "食べ物で、商業や文化が発展した大きな町の意味にならない。"}], "explanations": {"ペン": "筆記用具で、商業や文化が発展した地域を表さない。", "シティー": "商業や文化が発展した大きなまちを表すので、ここに入る。", "ドア": "建物の部品で、地域の性質を表す語として合わない。", "ケーキ": "食べ物で、商業や文化が発展した大きな町の意味にならない。"}, "sentence_index": 0, "correct_answer": "シティー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海辺のシティーには、漁船が三隻しかなく、住む人は五十人ほどです。", "explanation": "ここは〈漁村〉の意味。住む人が五十人ほどの集落は、大勢が住み商業も発展したシティーとは言えないので合わない。"}, {"text": "新しいシティーを買って、週末に海へ行きました。", "explanation": "ここは車種名の意味。都市を指すシティーとは別の語として使われている。"}, {"text": "山奥のシティーで、ひとりで暮らしています。", "explanation": "ここは〈山奥〉の意味。人里離れた場所は、大勢が住み商業が発展したシティーとは合わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37239, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ワイン", "is_correct": false, "explanation": "飲み物で、暮らす場所として使えない。"}, {"text": "ラケット", "is_correct": false, "explanation": "スポーツの道具で、暮らす場所にはならない。"}, {"text": "シティー", "is_correct": true, "explanation": "暮らす場所を表し、便利さや家賃の話につながるので、ここに入る。"}, {"text": "ゴム", "is_correct": false, "explanation": "材料で、暮らす場所を表さない。"}], "explanations": {"ワイン": "飲み物で、暮らす場所として使えない。", "ラケット": "スポーツの道具で、暮らす場所にはならない。", "シティー": "暮らす場所を表し、便利さや家賃の話につながるので、ここに入る。", "ゴム": "材料で、暮らす場所を表さない。"}, "sentence_index": 6, "correct_answer": "シティー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大学の友達と、シティーポップの音楽を聴きながら帰りました。", "explanation": "ここは音楽のジャンル名の意味。まちを指すシティーの意味では使わない。"}, {"text": "このシティーには人がほとんど住んでおらず、空き地と畑が広がっています。", "explanation": "人がほとんど住まず畑が広がる土地は、人口が多く商業が発展したシティーとは言えないので合わない。"}, {"text": "ペットのシティーは、毎朝公園で元気に走ります。", "explanation": "ここは犬の名前の意味。都市を指すシティーとは別の語として使われている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37239, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きなシティーが、新しい仕事を探しています。", "corrected_sentence": "大きなシティーで、新しい仕事を探しています。", "error_description": "仕事を探す場所は〈で〉で示す。〈が〉にすると、まちが主語になり、仕事を探す人がいなくなる文になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37239, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "シティーを住む人は、電車で通勤します。", "corrected_sentence": "シティーに住む人は、電車で通勤します。", "error_description": "〈住む〉の場所は〈に〉で示す。〈を〉は目的語を示すので、〈シティーを住む〉は不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37240, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「島を目指して」で、目指す対象である目的地を示す「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「島が目指して進んでいる」は島が主体になってしまい、目指す対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「島で目指して」は場所を示す「で」で、目指す対象にならない。"}, {"text": "と", "is_correct": false, "explanation": "「島と目指して」は並列の「と」で、目指す対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「島を目指して」で、目指す対象である目的地を示す「を」が正しい。", "が": "「島が目指して進んでいる」は島が主体になってしまい、目指す対象を示せない。", "で": "「島で目指して」は場所を示す「で」で、目指す対象にならない。", "と": "「島と目指して」は並列の「と」で、目指す対象を示せない。"}, "error_tags": {"が": "主語", "で": "場所", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37240, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37240, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「目指す」は、どこかに行きたいところを決めて、そこに向かって行くことです。", "primary_collocate": null, "pronunciation": "めざす", "ipa": "medzasɯ", "syllable_count": 3, "sentences": [{"text": "私たちは、山の頂上を目指して歩き始めた。", "target_word": "目指して", "complexity_tier": "T3", "furigana": "私[わたし]たちは、山[やま]の頂上[ちょうじょう]を目指[めざ]して歩[ある]き始[はじ]めた。", "sentence_source": "generated"}, {"text": "船は、小さな島を目指して進んでいる。", "target_word": "目指して", "complexity_tier": "T3", "furigana": "船[ふね]は、小[ちい]さな島[しま]を目指[めざ]して進[すす]んでいる。", "sentence_source": "generated"}, {"text": "彼は、一番近い駅を目指して走った。", "target_word": "目指して", "complexity_tier": "T3", "furigana": "彼[かれ]は、一番[いちばん]近[ちか]い駅[えき]を目指[めざ]して走[はし]った。", "sentence_source": "generated"}, {"text": "日が暮れる前に、山小屋を目指そう。", "target_word": "目指そう", "complexity_tier": "T3", "furigana": "日[ひ]が暮[く]れる前[まえ]に、山小屋[やまごや]を目指[めざ]そう。", "sentence_source": "generated"}, {"text": "道に迷ったが、遠くの明かりを目指して歩いた。", "target_word": "目指して", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]ったが、遠[とお]くの明[あ]かりを目指[めざ]して歩[ある]いた。", "sentence_source": "generated"}, {"text": "鳥の群れが、南の国を目指して飛んでいく。", "target_word": "目指して", "complexity_tier": "T3", "furigana": "鳥[とり]の群[む]れが、南[みなみ]の国[くに]を目指[めざ]して飛[と]んでいく。", "sentence_source": "generated"}, {"text": "雨の中、ゴールを目指す選手たちが走っている。", "target_word": "目指す", "complexity_tier": "T3", "furigana": "雨[あめ]の中[なか]、ゴールを目指[めざ]す選手[せんしゅ]たちが走[はし]っている。", "sentence_source": "generated"}, {"text": "地図を見ながら、公園の入り口を目指した。", "target_word": "目指した", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ながら、公園[こうえん]の入[い]り口[ぐち]を目指[めざ]した。", "sentence_source": "generated"}, {"text": "登山者は、朝早く出発して、次の宿を目指す。", "target_word": "目指す", "complexity_tier": "T3", "furigana": "登山者[とざんしゃ]は、朝[あさ]早[はや]く出発[しゅっぱつ]して、次[つぎ]の宿[やど]を目指[めざ]す。", "sentence_source": "generated"}, {"text": "嵐が来る前に、港を目指して急いで帰った。", "target_word": "目指して", "complexity_tier": "T3", "furigana": "嵐[あらし]が来[く]る前[まえ]に、港[みなと]を目指[めざ]して急[いそ]いで帰[かえ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "目指す", "label": "辞書形"}, {"form": "目指し", "label": "連用形"}, {"form": "目指して", "label": "て形"}, {"form": "目指した", "label": "過去形"}, {"form": "目指さ", "label": "未然形"}, {"form": "目指そう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "行き先を決めてそこへ向かって進む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f48066bd-2190-4cb8-bbf1-f08443cd7da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37240, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目指して", "is_correct": true, "explanation": "「山の頂上を目指して歩き始めた」で、行き先に向かう動作を表し、文の意味に合う。"}, {"text": "洗って", "is_correct": false, "explanation": "「山の頂上を洗って歩き始めた」は意味が通らない。洗う動作は行き先に向かわない。"}, {"text": "包んで", "is_correct": false, "explanation": "「山の頂上を包んで歩き始めた」は意味が通らない。包む動作は行き先を表さない。"}, {"text": "縛って", "is_correct": false, "explanation": "「山の頂上を縛って歩き始めた」は合わない。縛る動作は行き先を表さない。"}], "explanations": {"目指して": "「山の頂上を目指して歩き始めた」で、行き先に向かう動作を表し、文の意味に合う。", "洗って": "「山の頂上を洗って歩き始めた」は意味が通らない。洗う動作は行き先に向かわない。", "包んで": "「山の頂上を包んで歩き始めた」は意味が通らない。包む動作は行き先を表さない。", "縛って": "「山の頂上を縛って歩き始めた」は合わない。縛る動作は行き先を表さない。"}, "sentence_index": 0, "correct_answer": "目指して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は隙を目指して、相手の財布を盗んだ。", "explanation": "ここは〈狙う〉の意味。目指すは向かう先へ進む動きで、機会をうかがって狙う意味にはならない。隙は目指す対象ではなく、狙うものだ。"}, {"text": "その赤い服は、人混みの中でとても目指す。", "explanation": "ここは〈目立つ〉の意味。目指すは向かう目標を表し、人の目を引く様子は表さない。"}, {"text": "彼は窓辺に座り、夕焼けの景色を目指した。", "explanation": "ここは〈眺める〉の意味。目指すは行き先に向かうことで、景色を見て楽しむ意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37240, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目指す", "is_correct": true, "explanation": "「ゴールを目指す選手たち」で、目的地に向かう選手を表し、名詞を修飾する形として合う。"}, {"text": "磨く", "is_correct": false, "explanation": "「ゴールを磨く選手たち」は意味が通らない。磨く動作は目的地を表さない。"}, {"text": "敷く", "is_correct": false, "explanation": "「ゴールを敷く選手たち」は意味が通らない。敷く動作は行き先を表さない。"}, {"text": "塗る", "is_correct": false, "explanation": "「ゴールを塗る選手たち」は意味が通らない。塗る動作は行き先を表さない。"}], "explanations": {"目指す": "「ゴールを目指す選手たち」で、目的地に向かう選手を表し、名詞を修飾する形として合う。", "磨く": "「ゴールを磨く選手たち」は意味が通らない。磨く動作は目的地を表さない。", "敷く": "「ゴールを敷く選手たち」は意味が通らない。敷く動作は行き先を表さない。", "塗る": "「ゴールを塗る選手たち」は意味が通らない。塗る動作は行き先を表さない。"}, "sentence_index": 6, "correct_answer": "目指す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "嵐から急いで目指した。", "explanation": "ここは〈逃げる〉の意味。目指すは向かう先を示す動きで、危険から離れる動きには使わない。"}, {"text": "その事故の重さを目指した。", "explanation": "ここは〈量る〉の意味。目指すは向かう目標を表し、重さを測る意味にはならない。"}, {"text": "彼女は夜に手紙を目指した。", "explanation": "ここは〈書く〉の意味。目指すは行き先に向かう動きで、文字を書く行為は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37240, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私たちは、湖が目指して自転車で走った。", "corrected_sentence": "私たちは、湖を目指して自転車で走った。", "error_description": "助詞の誤り。「目指す」は目的地を目的語として取るので「湖を」が正しい。「湖が」は主語になってしまい誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "目指して", "is_correct": true, "explanation": "「進んでいる」へ続けるための「て形」で、「目指して進んでいる」の形として文法的に正しい。"}, {"text": "目指す", "is_correct": false, "explanation": "辞書形のため、「進んでいる」へ続けると文法が崩れる。"}, {"text": "目指した", "is_correct": false, "explanation": "過去形のため、「進んでいる」という現在の動作とは続かない。"}, {"text": "目指そう", "is_correct": false, "explanation": "意志形で、勧誘や決意の文になり、ここでは使えない。"}], "correct_form": "目指して", "base_form": "目指す", "form_label": "て形", "sentence_index": 1, "explanations": {"目指して": "「進んでいる」へ続けるための「て形」で、「目指して進んでいる」の形として文法的に正しい。", "目指す": "辞書形のため、「進んでいる」へ続けると文法が崩れる。", "目指した": "過去形のため、「進んでいる」という現在の動作とは続かない。", "目指そう": "意志形で、勧誘や決意の文になり、ここでは使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37240, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の上の村を目指で、一日中歩いた。", "corrected_sentence": "山の上の村を目指して、一日中歩いた。", "error_description": "活用の誤り。す行五段動詞のて形は「して」で、濁らせた「目指で」は誤り。正しくは「目指して」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "目指した", "is_correct": true, "explanation": "「公園の入り口を目指した」で、過去の出来事を述べる文末の過去形として合う。"}, {"text": "目指し", "is_correct": false, "explanation": "連用形のため文を終えられず、「公園の入り口を目指し。」では文末として成り立たない。"}, {"text": "目指さ", "is_correct": false, "explanation": "未然形のため単独で文を終えられず、「公園の入り口を目指さ。」は文として成り立たない。"}, {"text": "目指して", "is_correct": false, "explanation": "て形のため文が終わらず、「公園の入り口を目指して。」では文末として成り立たない。"}], "correct_form": "目指した", "base_form": "目指す", "form_label": "過去形", "sentence_index": 7, "explanations": {"目指した": "「公園の入り口を目指した」で、過去の出来事を述べる文末の過去形として合う。", "目指し": "連用形のため文を終えられず、「公園の入り口を目指し。」では文末として成り立たない。", "目指さ": "未然形のため単独で文を終えられず、「公園の入り口を目指さ。」は文として成り立たない。", "目指して": "て形のため文が終わらず、「公園の入り口を目指して。」では文末として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7505afc-c00a-40e5-b353-810c9c45a552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37242, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "〈ラッシュの電車〉と名詞をつなぐ〈の〉が正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、ラッシュが主語になると電車との関係が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、ここは電車を修飾する文なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、ラッシュを目的地にする文にはならない。"}], "correct_answer": "の", "explanations": {"の": "〈ラッシュの電車〉と名詞をつなぐ〈の〉が正しい。", "が": "主語を示すが、ラッシュが主語になると電車との関係が通らない。", "を": "目的語を示すが、ここは電車を修飾する文なので合わない。", "へ": "方向を示すが、ラッシュを目的地にする文にはならない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37242, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "〈ラッシュの中〉と名詞をつなぐ〈の〉が正しい。"}, {"text": "に", "is_correct": false, "explanation": "場所や時を示すが、〈ラッシュに中〉は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並べる相手を示すが、〈ラッシュと中〉では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比べる対象を示すが、〈ラッシュより中〉では文が合わない。"}], "correct_answer": "の", "explanations": {"の": "〈ラッシュの中〉と名詞をつなぐ〈の〉が正しい。", "に": "場所や時を示すが、〈ラッシュに中〉は文として成り立たない。", "と": "並べる相手を示すが、〈ラッシュと中〉では意味が通らない。", "より": "比べる対象を示すが、〈ラッシュより中〉では文が合わない。"}, "error_tags": {"に": "場所・時", "と": "並列・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37242, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの人がいっしょにのったり、おりたりする、いそがしいじかんのことです。", "primary_collocate": null, "pronunciation": "らっしゅ", "ipa": "raɕɕɯ", "syllable_count": 3, "sentences": [{"text": "朝のラッシュで、駅のホームは人でいっぱいでした。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "朝[あさ]のラッシュで、駅[えき]のホームは人[ひと]でいっぱいでした。", "sentence_source": "generated"}, {"text": "ラッシュの電車は、座るどころか立つ場所もありません。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "ラッシュの電車[でんしゃ]は、座[すわ]るどころか立[た]つ場所[ばしょ]もありません。", "sentence_source": "generated"}, {"text": "ラッシュを避けるために、一時間早く家を出ました。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "ラッシュを避[さ]けるために、一時間[いちじかん]早[はや]く家[いえ]を出[で]ました。", "sentence_source": "generated"}, {"text": "夕方のラッシュに会って、帰りが遅くなりました。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]のラッシュに会[あ]って、帰[かえ]りが遅[おそ]くなりました。", "sentence_source": "generated"}, {"text": "ラッシュの時間は、乗る人も降りる人も急いでいます。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "ラッシュの時間[じかん]は、乗[の]る人[ひと]も降[お]りる人[ひと]も急[いそ]いでいます。", "sentence_source": "generated"}, {"text": "毎朝のラッシュは、会社へ行く人でとても混んでいます。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]のラッシュは、会社[かいしゃ]へ行[い]く人[ひと]でとても混[こ]んでいます。", "sentence_source": "generated"}, {"text": "ラッシュが終わると、電車の中は静かになりました。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "ラッシュが終[お]わると、電車[でんしゃ]の中[なか]は静[しず]かになりました。", "sentence_source": "generated"}, {"text": "ラッシュの中、ベビーカーで電車に乗るのは大変です。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "ラッシュの中[なか]、ベビーカーで電車[でんしゃ]に乗[の]るのは大変[たいへん]です。", "sentence_source": "generated"}, {"text": "バスもラッシュの時間は、遅れることが多いです。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "バスもラッシュの時間[じかん]は、遅[おく]れることが多[おお]いです。", "sentence_source": "generated"}, {"text": "ラッシュに巻き込まれないよう、昼に出かけます。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "ラッシュに巻[ま]き込[こ]まれないよう、昼[ひる]に出[で]かけます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ラッシュ", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "乗り降りする人で混み合う朝夕の通勤通学の時間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a7c10f-7617-45e5-a3d0-bcfe1bdfc1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37242, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ラーメン", "is_correct": false, "explanation": "食べ物で、駅の混み方を表す語にならない。"}, {"text": "ラッシュ", "is_correct": true, "explanation": "朝の混み合う時間を表し、駅が人でいっぱいになる理由に合う。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓の布で、人が集まる混雑を表さない。"}, {"text": "ピアノ", "is_correct": false, "explanation": "楽器で、朝の混み具合を表す語にならない。"}], "explanations": {"ラーメン": "食べ物で、駅の混み方を表す語にならない。", "ラッシュ": "朝の混み合う時間を表し、駅が人でいっぱいになる理由に合う。", "カーテン": "窓の布で、人が集まる混雑を表さない。", "ピアノ": "楽器で、朝の混み具合を表す語にならない。"}, "sentence_index": 0, "correct_answer": "ラッシュ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "監督は、撮影したラッシュを見て、もう一度撮り直すことにしました。", "explanation": "ここは映画の未編集の映像の意味。通勤の混む時間とは別の語。"}, {"text": "ジェットコースターを降りると、アドレナリンのラッシュで体が熱くなりました。", "explanation": "ここは〈どっと押し寄せる強い感覚〉の意味。通勤の混雑とは別の語。"}, {"text": "昔のゴールドラッシュの時代、この町には人が集まりました。", "explanation": "ここは〈金の採掘地への殺到〉の意味。通勤の混み合う時間とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37242, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "クッキー", "is_correct": false, "explanation": "食べ物で、終わって電車の中が静かになる出来事ではない。"}, {"text": "ボタン", "is_correct": false, "explanation": "服の部品で、時間として終わる対象にならない。"}, {"text": "ラッシュ", "is_correct": true, "explanation": "混み合う時間帯を表し、終わると電車が静かになる文に合う。"}, {"text": "ゴム", "is_correct": false, "explanation": "材料で、時間として終わる対象にならない。"}], "explanations": {"クッキー": "食べ物で、終わって電車の中が静かになる出来事ではない。", "ボタン": "服の部品で、時間として終わる対象にならない。", "ラッシュ": "混み合う時間帯を表し、終わると電車が静かになる文に合う。", "ゴム": "材料で、時間として終わる対象にならない。"}, "sentence_index": 6, "correct_answer": "ラッシュ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の海では、ラッシュガードを着て日焼けを防ぎました。", "explanation": "ここは水着の名前の意味。混む時間帯の意味とは別の語。"}, {"text": "週末は、ラッシュのアルバムを聴きながら勉強しました。", "explanation": "ここはバンド名の意味。混む時間帯の意味とは別の語。"}, {"text": "試合の後半、ラッシュをかけて同点に追いつきました。", "explanation": "ここは一気に攻め込む攻撃の意味。通勤の混雑とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37242, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ラッシュを巻き込まれて、遅刻しました。", "corrected_sentence": "ラッシュに巻き込まれて、遅刻しました。", "error_description": "〈巻き込まれる〉は〈に〉で相手を示す。〈を〉にすると目的語になり、この文では成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37242, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ラッシュに避けて、昼に出かけました。", "corrected_sentence": "ラッシュを避けて、昼に出かけました。", "error_description": "〈避ける〉の対象は〈を〉で示す。〈に〉にすると避ける動作が成り立たず、文として不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
