INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37243, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "多くの人が集中して移動する時間帯や、混雑した状態を指す言葉。", "primary_collocate": null, "pronunciation": "らっしゅ", "ipa": "raɕɕɯ", "syllable_count": 3, "sentences": [{"text": "連休の初日は、高速道路がラッシュで全く動きません。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "連休[れんきゅう]の初日[しょにち]は、高速道路[こうそくどうろ]がラッシュで全[まった]く動[うご]きません。", "sentence_source": "generated"}, {"text": "通勤のラッシュが始まる前に、会社に着きました。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "通勤[つうきん]のラッシュが始[はじ]まる前[まえ]に、会社[かいしゃ]に着[つ]きました。", "sentence_source": "generated"}, {"text": "ラッシュの時間を過ぎると、道は一気にすきます。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "ラッシュの時間[じかん]を過[す]ぎると、道[みち]は一気[いっき]にすきます。", "sentence_source": "generated"}, {"text": "駅の出口は、ラッシュで人が流れず危険でした。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "駅[えき]の出口[でぐち]は、ラッシュで人[ひと]が流[なが]れず危険[きけん]でした。", "sentence_source": "generated"}, {"text": "夏休みの最後の日は、空港もラッシュになります。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの最後[さいご]の日[ひ]は、空港[くうこう]もラッシュになります。", "sentence_source": "generated"}, {"text": "朝のラッシュが長く続き、バスが三十分も遅れました。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "朝[あさ]のラッシュが長[なが]く続[つづ]き、バスが三十分[さんじゅっぷん]も遅[おく]れました。", "sentence_source": "generated"}, {"text": "ラッシュのころは、道を渡るだけでも時間がかかります。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "ラッシュのころは、道[みち]を渡[わた]るだけでも時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "ラッシュを避けて、夜遅くに出発しました。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "ラッシュを避[さ]けて、夜遅[よるおそ]くに出発[しゅっぱつ]しました。", "sentence_source": "generated"}, {"text": "毎日のラッシュに疲れて、自転車で通うことにしました。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "毎日[まいにち]のラッシュに疲[つか]れて、自転車[じてんしゃ]で通[かよ]うことにしました。", "sentence_source": "generated"}, {"text": "ラッシュが終わったので、やっと車が楽に走れます。", "target_word": "ラッシュ", "complexity_tier": "T3", "furigana": "ラッシュが終[お]わったので、やっと車[くるま]が楽[らく]に走[はし]れます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ラッシュ", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "人や車が一度に集中して動く時間帯とその混雑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a7c10f-7617-45e5-a3d0-bcfe1bdfc1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37243, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ピクニック", "is_correct": false, "explanation": "野外で食べる行事で、道路が動かない原因にならない。"}, {"text": "ハンガー", "is_correct": false, "explanation": "服を掛ける道具で、道路が動かない状態にはならない。"}, {"text": "ラッシュ", "is_correct": true, "explanation": "車が一度に集中して混み、動かなくなる状態を表すので、ここに入る。"}, {"text": "ミルク", "is_correct": false, "explanation": "飲み物で、道路の状態を表さない。"}], "explanations": {"ピクニック": "野外で食べる行事で、道路が動かない原因にならない。", "ハンガー": "服を掛ける道具で、道路が動かない状態にはならない。", "ラッシュ": "車が一度に集中して混み、動かなくなる状態を表すので、ここに入る。", "ミルク": "飲み物で、道路の状態を表さない。"}, "sentence_index": 0, "correct_answer": "ラッシュ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ライブで、ラッシュの曲が流れて盛り上がりました。", "explanation": "ここはバンド名の意味。混み合う時間帯の意味では使わない。"}, {"text": "ライブのあと、興奮のラッシュで眠れませんでした。", "explanation": "ここは〈どっと押し寄せる強い感覚〉の意味。通勤や道路の混雑とは別の語。"}, {"text": "試合の終わりに、一気にラッシュをかけて追いつきました。", "explanation": "ここは一気に攻め込む攻撃の意味。道路が混む状態とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37243, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カーテン", "is_correct": false, "explanation": "窓の布で、時間の区切りにならない。"}, {"text": "ラーメン", "is_correct": false, "explanation": "食べ物で、道路の混む時期を表さない。"}, {"text": "ラッシュ", "is_correct": true, "explanation": "混み合う時間帯を表し、道を渡るのに時間がかかる理由になる。"}, {"text": "ゴム", "is_correct": false, "explanation": "材料で、時間の区切りとして使えない。"}], "explanations": {"カーテン": "窓の布で、時間の区切りにならない。", "ラーメン": "食べ物で、道路の混む時期を表さない。", "ラッシュ": "混み合う時間帯を表し、道を渡るのに時間がかかる理由になる。", "ゴム": "材料で、時間の区切りとして使えない。"}, "sentence_index": 6, "correct_answer": "ラッシュ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海に行くので、ラッシュガードを一枚買いました。", "explanation": "ここは水着の名前の意味。混み合う道路の状態を表す語ではない。"}, {"text": "試写会の前に、編集前のラッシュを確認しました。", "explanation": "ここは映画の未編集の映像の意味。道路や時間帯の意味では使わない。"}, {"text": "昔のゴールドラッシュの時代、この町は一攫千金を夢見る人で賑わいました。", "explanation": "ここは〈金の採掘地への殺到〉の意味。通勤や道路の混雑を表す語とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37243, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "通勤のラッシュを、電車はいつも混んでいます。", "corrected_sentence": "通勤のラッシュで、電車はいつも混んでいます。", "error_description": "混む原因は〈で〉で示す。〈を〉にするとラッシュが目的語になり、電車が混む文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37243, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ラッシュに抜けたら、道はすいていました。", "corrected_sentence": "ラッシュを抜けたら、道はすいていました。", "error_description": "〈抜ける〉の対象は〈を〉で示す。〈に〉にすると、ラッシュの中から出る動作が表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37244, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「役立つ」の対象を示す正しい格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「緩和へ役立つ」は方向の意味になり、役立つの対象としては不自然。"}, {"text": "の", "is_correct": false, "explanation": "「緩和の役立つ」は文として成り立たず、「の」は動詞に続かない。"}, {"text": "を", "is_correct": false, "explanation": "「緩和を役立つ」は目的語にならず、誤り。"}], "correct_answer": "に", "explanations": {"に": "「役立つ」の対象を示す正しい格助詞。", "へ": "「緩和へ役立つ」は方向の意味になり、役立つの対象としては不自然。", "の": "「緩和の役立つ」は文として成り立たず、「の」は動詞に続かない。", "を": "「緩和を役立つ」は目的語にならず、誤り。"}, "error_tags": {"へ": "方向", "の": "連体修飾", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37244, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「緊張を緩和する」の目的語を示す正しい格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「緊張に緩和した」は対象を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「緊張へ緩和した」は方向の意味になり、成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「緊張の緩和した」は文として成り立たず、名詞どうしを結ぶだけになる。"}], "correct_answer": "を", "explanations": {"を": "「緊張を緩和する」の目的語を示す正しい格助詞。", "に": "「緊張に緩和した」は対象を示せず、不自然。", "へ": "「緊張へ緩和した」は方向の意味になり、成り立たない。", "の": "「緊張の緩和した」は文として成り立たず、名詞どうしを結ぶだけになる。"}, "error_tags": {"に": "相手・到達点", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37244, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "きびしさやくるしさを、やわらげること。", "primary_collocate": null, "pronunciation": "かんわ", "ipa": "kaɴwa", "syllable_count": 3, "sentences": [{"text": "政府は、入国のきびしい制限を緩和すると発表した。", "target_word": "緩和する", "complexity_tier": "T3", "furigana": "政府[せいふ]は、入国[にゅうこく]のきびしい制限[せいげん]を緩和[かんわ]すると発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "温かいお茶を飲むと、緊張の緩和に役立つ。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "温[あたた]かいお茶[ちゃ]を飲[の]むと、緊張[きんちょう]の緩和[かんわ]に役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "薬のおかげで、痛みが少し緩和された。", "target_word": "緩和された", "complexity_tier": "T3", "furigana": "薬[くすり]のおかげで、痛[いた]みが少[すこ]し緩和[かんわ]された。", "sentence_source": "generated"}, {"text": "規制の緩和によって、新しい店が増えた。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "規制[きせい]の緩和[かんわ]によって、新[あたら]しい店[みせ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "試験の条件が緩和されて、多くの人が受けられる。", "target_word": "緩和されて", "complexity_tier": "T3", "furigana": "試験[しけん]の条件[じょうけん]が緩和[かんわ]されて、多[おお]くの人[ひと]が受[う]けられる。", "sentence_source": "generated"}, {"text": "ストレッチは、肩のこりの緩和に効果がある。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "ストレッチは、肩[かた]のこりの緩和[かんわ]に効果[こうか]がある。", "sentence_source": "generated"}, {"text": "町は、渋滞を緩和するために新しい道を作った。", "target_word": "緩和する", "complexity_tier": "T3", "furigana": "町[まち]は、渋滞[じゅうたい]を緩和[かんわ]するために新[あたら]しい道[みち]を作[つく]った。", "sentence_source": "generated"}, {"text": "先生の冗談が、教室の緊張を緩和した。", "target_word": "緩和した", "complexity_tier": "T3", "furigana": "先生[せんせい]の冗談[じょうだん]が、教室[きょうしつ]の緊張[きんちょう]を緩和[かんわ]した。", "sentence_source": "generated"}, {"text": "働き方のルールを緩和して、会社は在宅勤務を認めた。", "target_word": "緩和して", "complexity_tier": "T3", "furigana": "働[はたら]き方[かた]のルールを緩和[かんわ]して、会社[かいしゃ]は在宅勤務[ざいたくきんむ]を認[みと]めた。", "sentence_source": "generated"}, {"text": "扇風機の風が、夏の暑さの緩和に役立った。", "target_word": "緩和", "complexity_tier": "T3", "furigana": "扇風機[せんぷうき]の風[かぜ]が、夏[なつ]の暑[あつ]さの緩和[かんわ]に役立[やくだ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緩和する", "label": "サ変動詞"}, {"form": "緩和した", "label": "過去形"}, {"form": "緩和して", "label": "て形"}, {"form": "緩和された", "label": "受身の過去形"}], "register": "標準・常体", "sense_fingerprint": "規制・痛み・緊張などの厳しさや苦しさを弱めてやわらげる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37244, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緩和する", "is_correct": true, "explanation": "「制限を緩和する」は、きびしさをやわらげる意味で自然に続く。"}, {"text": "達成する", "is_correct": false, "explanation": "「制限を達成する」は意味が通らない。達成は目標に対して使う。"}, {"text": "発行する", "is_correct": false, "explanation": "「制限を発行する」は不自然。発行は証明書などに使う。"}, {"text": "所有する", "is_correct": false, "explanation": "「制限を所有する」は成り立たない。制限は持つものではない。"}], "explanations": {"緩和する": "「制限を緩和する」は、きびしさをやわらげる意味で自然に続く。", "達成する": "「制限を達成する」は意味が通らない。達成は目標に対して使う。", "発行する": "「制限を発行する」は不自然。発行は証明書などに使う。", "所有する": "「制限を所有する」は成り立たない。制限は持つものではない。"}, "sentence_index": 0, "correct_answer": "緩和する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "締めていたネジが緩和して、机がぐらついた。", "explanation": "ここは〈緩む〉の意味。緩和は苦しさや厳しさをやわらげることで、物理的にネジがゆるむことには使わない。"}, {"text": "試験の日を緩和して、一週間後に延ばした。", "explanation": "ここは〈延期〉の意味。緩和は苦しさや厳しさをやわらげることで、日時を後ろに延ばすという意味では使わない。"}, {"text": "規制の緩和で、ルールがいっそう厳しくなった。", "explanation": "ここは〈強化〉の意味。緩和は厳しさをやわらげることで、厳しくする意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37244, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緩和する", "is_correct": true, "explanation": "「渋滞を緩和する」は、混雑をやわらげる意味で自然に続く。"}, {"text": "完成する", "is_correct": false, "explanation": "「渋滞を完成する」は意味が通らない。完成はものに使う。"}, {"text": "登録する", "is_correct": false, "explanation": "「渋滞を登録する」は不自然。登録は名簿や制度に使う。"}, {"text": "公開する", "is_correct": false, "explanation": "「渋滞を公開する」は意味が合わない。公開は情報に使う。"}], "explanations": {"緩和する": "「渋滞を緩和する」は、混雑をやわらげる意味で自然に続く。", "完成する": "「渋滞を完成する」は意味が通らない。完成はものに使う。", "登録する": "「渋滞を登録する」は不自然。登録は名簿や制度に使う。", "公開する": "「渋滞を公開する」は意味が合わない。公開は情報に使う。"}, "sentence_index": 6, "correct_answer": "緩和する"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この薬は酸性の液を緩和して、水と同じにする。", "explanation": "ここは〈中和〉の意味。緩和は苦しさや厳しさをやわらげることで、酸とアルカリを打ち消して性質を変える化学的な変化には使わない。"}, {"text": "世界の緩和を願う式典が開かれた。", "explanation": "ここは〈平和〉の意味。緩和は厳しさをやわらげることで、争いのない状態を指す語ではない。"}, {"text": "機械を緩和して、熱を下げた。", "explanation": "ここは〈冷却〉の意味。緩和は苦しさをやわらげることで、機械の温度を下げる行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37244, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この薬は、痛みの緩和を役立つ。", "corrected_sentence": "この薬は、痛みの緩和に役立つ。", "error_description": "「役立つ」は「に」で対象を示す。「を」は誤りで、正しくは「緩和に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37244, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "税金の負担を緩和さると、家計が楽になる。", "corrected_sentence": "税金の負担を緩和すると、家計が楽になる。", "error_description": "サ変動詞「緩和する」に「さる」は付かない。正しくは「緩和すると」の形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37246, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "〈郊外〉を話題に出して「は」で続ける形で、「郊外は静かなので」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「静かだ」の目的語にはならないため、「郊外を静かなので」は不自然で文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「静かなので」の理由を述べる文には合わず、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「郊外と静かなので」は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "〈郊外〉を話題に出して「は」で続ける形で、「郊外は静かなので」と自然に続く。", "を": "「静かだ」の目的語にはならないため、「郊外を静かなので」は不自然で文が成立しない。", "へ": "方向を示す「へ」は「静かなので」の理由を述べる文には合わず、意味が通らない。", "と": "「と」は並列や相手を示すが、「郊外と静かなので」は意味が通らない。"}, "error_tags": {"は": "主題", "を": "対象", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37246, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "〈郊外〉と〈店〉をつないで「郊外の店」と名詞を修飾し、「郊外にある店」の意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「郊外が店は」と主語にすると意味が通らず、後ろの「駐車場が広い」とも続かない。"}, {"text": "を", "is_correct": false, "explanation": "「郊外を店は」と目的語にできず、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「郊外へ店は」は方向を示すだけで、店の所在を表す名詞修飾にはならない。"}], "correct_answer": "の", "explanations": {"の": "〈郊外〉と〈店〉をつないで「郊外の店」と名詞を修飾し、「郊外にある店」の意味になる。", "が": "「郊外が店は」と主語にすると意味が通らず、後ろの「駐車場が広い」とも続かない。", "を": "「郊外を店は」と目的語にできず、文が成立しない。", "へ": "「郊外へ店は」は方向を示すだけで、店の所在を表す名詞修飾にはならない。"}, "error_tags": {"の": "連体修飾", "が": "主格", "を": "対象", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37246, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まちの真ん中ではなく、はずれの方にある場所のことです。", "primary_collocate": null, "pronunciation": "こうがい", "ipa": "koːɡai", "syllable_count": 4, "sentences": [{"text": "私は町の中心ではなく、郊外に住んでいます。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "私[わたし]は町[まち]の中心[ちゅうしん]ではなく、郊外[こうがい]に住[す]んでいます。", "sentence_source": "generated"}, {"text": "郊外は静かなので、夜よく眠れます。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "郊外[こうがい]は静[しず]かなので、夜[よる]よく眠[ねむ]れます。", "sentence_source": "generated"}, {"text": "駅から遠い郊外の家は、値段が安いです。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "駅[えき]から遠[とお]い郊外[こうがい]の家[いえ]は、値段[ねだん]が安[やす]いです。", "sentence_source": "generated"}, {"text": "毎朝、郊外から電車で会社へ通っています。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、郊外[こうがい]から電車[でんしゃ]で会社[かいしゃ]へ通[かよ]っています。", "sentence_source": "generated"}, {"text": "週末は家族で郊外の大きな公園へ行きました。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]は家族[かぞく]で郊外[こうがい]の大[おお]きな公園[こうえん]へ行[い]きました。", "sentence_source": "generated"}, {"text": "郊外には畑が多く、空気もきれいです。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "郊外[こうがい]には畑[はたけ]が多[おお]く、空気[くうき]もきれいです。", "sentence_source": "generated"}, {"text": "都心は便利ですが、郊外のほうが広い部屋に住めます。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "都心[としん]は便利[べんり]ですが、郊外[こうがい]のほうが広[ひろ]い部屋[へや]に住[す]めます。", "sentence_source": "generated"}, {"text": "郊外の店は駐車場が広いので、車で買い物しやすいです。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "郊外[こうがい]の店[みせ]は駐車場[ちゅうしゃじょう]が広[ひろ]いので、車[くるま]で買[か]い物[もの]しやすいです。", "sentence_source": "generated"}, {"text": "来年は、子どもが生まれるので郊外に引っ越します。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "来年[らいねん]は、子[こ]どもが生[う]まれるので郊外[こうがい]に引[ひ]っ越[こ]します。", "sentence_source": "generated"}, {"text": "郊外に新しい学校ができて、子どもが増えました。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "郊外[こうがい]に新[あたら]しい学校[がっこう]ができて、子[こ]どもが増[ふ]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "郊外", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "町の中心から離れたはずれの場所。日常会話で住む場所として使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37246, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "郊外", "is_correct": true, "explanation": "〈郊外〉は町の中心から離れた外れの地域を指し、「町の中心ではなく」と対になって住む場所として合う。"}, {"text": "時計", "is_correct": false, "explanation": "人が住める場所ではないため、「〜に住んでいます」の場所として成り立たない。"}, {"text": "電話", "is_correct": false, "explanation": "住む場所を表さない道具の名前なので、空欄に入れると文が通らない。"}, {"text": "野菜", "is_correct": false, "explanation": "食べ物を表す語で、人が住む場所にはならないため、この文脈に合わない。"}], "explanations": {"郊外": "〈郊外〉は町の中心から離れた外れの地域を指し、「町の中心ではなく」と対になって住む場所として合う。", "時計": "人が住める場所ではないため、「〜に住んでいます」の場所として成り立たない。", "電話": "住む場所を表さない道具の名前なので、空欄に入れると文が通らない。", "野菜": "食べ物を表す語で、人が住む場所にはならないため、この文脈に合わない。"}, "sentence_index": 0, "correct_answer": "郊外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアの郊外で待っていてください。", "explanation": "ここは〈外〉の意味。郊外は都市の周辺の地域を指すので、ドアの外側の位置には使えない。"}, {"text": "指の郊外にささくれができて、痛い。", "explanation": "ここは〈先端〉の意味。郊外は地域を表す語なので、指の先の位置には使えない。"}, {"text": "事務所は、ビルの郊外の階にあります。", "explanation": "ここは〈上の階〉の意味。郊外は地域を表す語なので、建物の階の位置には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37246, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "郊外", "is_correct": true, "explanation": "〈郊外〉は都心と比べる対象の地域で、「郊外のほうが広い部屋に住める」に合う。"}, {"text": "値段", "is_correct": false, "explanation": "「〜のほうが広い部屋に住める」の主語になれず、文の対比が成り立たない。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物を表す語で、広い部屋に住めるものとして比べる文には入らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電で、住める場所ではないため、「広い部屋に住める」の比較対象にならない。"}], "explanations": {"郊外": "〈郊外〉は都心と比べる対象の地域で、「郊外のほうが広い部屋に住める」に合う。", "値段": "「〜のほうが広い部屋に住める」の主語になれず、文の対比が成り立たない。", "電車": "乗り物を表す語で、広い部屋に住めるものとして比べる文には入らない。", "冷蔵庫": "家電で、住める場所ではないため、「広い部屋に住める」の比較対象にならない。"}, "sentence_index": 6, "correct_answer": "郊外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その大木の郊外に柵を作った。", "explanation": "ここは〈周囲〉の意味。郊外は都市の周辺地域なので、木の周りの位置には使えない。"}, {"text": "坂道の郊外で車が止まった。", "explanation": "ここは〈途中〉の意味。郊外は地域を表す語なので、道の途中の位置には使えない。"}, {"text": "建物の郊外は、思ったより広かった。", "explanation": "ここは〈内部〉の意味。郊外は都市の周辺地域で、建物の内側の空間には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37246, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は郊外を出かけて、キャンプをしました。", "corrected_sentence": "週末は郊外に出かけて、キャンプをしました。", "error_description": "「出かける」は行き先を「に」で示す。「郊外を」は誤りで、正しくは「郊外に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37246, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は郊外を住んでいました。", "corrected_sentence": "祖父は郊外に住んでいました。", "error_description": "「住む」は住む場所を「に」で示す。「郊外を」は誤りで、正しくは「郊外に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37247, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〈郊外〉を「探す」の行き先として示し、「郊外に家を探す」と自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "「郊外が家を探す」では主語が合わず、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「郊外と家を探す」では並列の相手にならず、不自然で文が成立しない。"}, {"text": "を", "is_correct": false, "explanation": "「郊外を家を探す」と目的語が重なり、文として成立しない。"}], "correct_answer": "に", "explanations": {"に": "〈郊外〉を「探す」の行き先として示し、「郊外に家を探す」と自然に続く。", "が": "「郊外が家を探す」では主語が合わず、意味が通らない。", "と": "「郊外と家を探す」では並列の相手にならず、不自然で文が成立しない。", "を": "「郊外を家を探す」と目的語が重なり、文として成立しない。"}, "error_tags": {"に": "場所・行き先", "が": "主格", "と": "並列・相手", "を": "対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37247, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37247, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "都市の中心部から離れた、周辺の地域。", "primary_collocate": null, "pronunciation": "こうがい", "ipa": "koːɡai", "syllable_count": 4, "sentences": [{"text": "この都市の郊外には、大きな住宅地が広がっている。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "この都市[とし]の郊外[こうがい]には、大[おお]きな住宅地[じゅうたくち]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "都心の家賃が高いため、郊外に家を探す人が増えている。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "都心[としん]の家賃[やちん]が高[たか]いため、郊外[こうがい]に家[いえ]を探[さが]す人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "郊外の駅の前に、新しい図書館が建てられた。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "郊外[こうがい]の駅[えき]の前[まえ]に、新[あたら]しい図書館[としょかん]が建[た]てられた。", "sentence_source": "generated"}, {"text": "彼は郊外から二時間かけて都心の大学に通っている。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "彼[かれ]は郊外[こうがい]から二時間[にじかん]かけて都心[としん]の大学[だいがく]に通[かよ]っている。", "sentence_source": "generated"}, {"text": "郊外の大型店は、車で来る客を中心に商売をしている。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "郊外[こうがい]の大型店[おおがたてん]は、車[くるま]で来[く]る客[きゃく]を中心[ちゅうしん]に商売[しょうばい]をしている。", "sentence_source": "generated"}, {"text": "郊外では、バスの本数が少なく、車がないと不便だ。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "郊外[こうがい]では、バスの本数[ほんすう]が少[すく]なく、車[くるま]がないと不便[ふべん]だ。", "sentence_source": "generated"}, {"text": "市は郊外の森を守るため、開発を禁止した。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "市[し]は郊外[こうがい]の森[もり]を守[まも]るため、開発[かいはつ]を禁止[きんし]した。", "sentence_source": "generated"}, {"text": "都心では高いビルが多いが、郊外では低い家が並んでいる。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "都心[としん]では高[たか]いビルが多[おお]いが、郊外[こうがい]では低[ひく]い家[いえ]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "大雪の日、郊外の道路は車が動かなくなった。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "大雪[おおゆき]の日[ひ]、郊外[こうがい]の道路[どうろ]は車[くるま]が動[うご]かなくなった。", "sentence_source": "generated"}, {"text": "郊外に工場が移ったので、中心部の騒音は減った。", "target_word": "郊外", "complexity_tier": "T3", "furigana": "郊外[こうがい]に工場[こうじょう]が移[うつ]ったので、中心部[ちゅうしんぶ]の騒音[そうおん]は減[へ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "郊外", "label": "基本形"}], "register": "書き言葉", "sense_fingerprint": "都市の周辺に広がる地域。住宅地・開発・交通など都市の話題で使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37247, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "郊外", "is_correct": true, "explanation": "〈郊外〉は都市の周辺地域を指し、「住宅地が広がっている」場所として文脈に合う。"}, {"text": "図書館", "is_correct": false, "explanation": "施設であって一帯の地域ではないため、「住宅地が広がっている」場所として成り立たない。"}, {"text": "工場", "is_correct": false, "explanation": "工場は住宅地が広がる場所を指さないので、「住宅地が広がっている」と合わない。"}, {"text": "河川", "is_correct": false, "explanation": "川は住宅地が広がる場所にならず、この文の空欄に入ると意味が通らない。"}], "explanations": {"郊外": "〈郊外〉は都市の周辺地域を指し、「住宅地が広がっている」場所として文脈に合う。", "図書館": "施設であって一帯の地域ではないため、「住宅地が広がっている」場所として成り立たない。", "工場": "工場は住宅地が広がる場所を指さないので、「住宅地が広がっている」と合わない。", "河川": "川は住宅地が広がる場所にならず、この文の空欄に入ると意味が通らない。"}, "sentence_index": 0, "correct_answer": "郊外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は毎朝、海の郊外へ船を出して漁をしている。", "explanation": "ここは〈沖〉の意味。郊外は陸地の周辺地域を指すので、海上の位置を表す「沖」の代わりには使えない。"}, {"text": "新聞の紙面の郊外に、小さな記事が載っていた。", "explanation": "ここは〈隅〉の意味。郊外は都市の周辺を指すので、紙面の位置には使えない。"}, {"text": "鍵はポケットの郊外に入っていた。", "explanation": "ここは〈奥〉の意味。郊外は地域を表す語なので、ポケットの中の位置には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37247, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "郊外", "is_correct": true, "explanation": "〈郊外〉は市の周辺地域で、「市は郊外の森を守る」という文の流れに合う。"}, {"text": "教室", "is_correct": false, "explanation": "教室に森はないため、「教室の森を守る」という文は成り立たない。"}, {"text": "本棚", "is_correct": false, "explanation": "本棚は森を持たないものなので、保護の対象として文に入れると意味が通らない。"}, {"text": "食卓", "is_correct": false, "explanation": "食卓には森がなく、「食卓の森を守る」は文脈として成立しない。"}], "explanations": {"郊外": "〈郊外〉は市の周辺地域で、「市は郊外の森を守る」という文の流れに合う。", "教室": "教室に森はないため、「教室の森を守る」という文は成り立たない。", "本棚": "本棚は森を持たないものなので、保護の対象として文に入れると意味が通らない。", "食卓": "食卓には森がなく、「食卓の森を守る」は文脈として成立しない。"}, "sentence_index": 6, "correct_answer": "郊外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "紙の郊外に、薄い傷がついていた。", "explanation": "ここは〈表面〉の意味。郊外は都市の周辺地域なので、紙の表面の位置には使えない。"}, {"text": "床の郊外に小さな虫がいた。", "explanation": "ここは〈床下〉の意味。郊外は地域を指すので、床の下の空間には合わない。"}, {"text": "箱の郊外に、小さな鈴が入っていた。", "explanation": "ここは〈中央〉の意味。郊外は都市の周辺を指すので、箱の中の真ん中の位置には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37247, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "郊外を引っ越す人が増えている。", "corrected_sentence": "郊外に引っ越す人が増えている。", "error_description": "「引っ越す」は移る先を「に」で示す。「郊外を」は誤りで、正しくは「郊外に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37247, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "郊外を駅前に、新しい住宅が建ち並んだ。", "corrected_sentence": "郊外の駅前に、新しい住宅が建ち並んだ。", "error_description": "「郊外」は「駅前」を修飾する語なので「の」で続ける。「を」は名詞修飾の形にならず誤り。正しくは「郊外の駅前」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37248, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〈部屋〉を流れ込む先として示し、「部屋に流入しました」と空気が入る文として自然。"}, {"text": "が", "is_correct": false, "explanation": "「部屋が流入しました」では部屋が流れ込む主体になり、意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「部屋を流入」は目的語を取れず、「流入」の使い方と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「部屋と流入」では並列の相手にならず、文が成立しない。"}], "correct_answer": "に", "explanations": {"に": "〈部屋〉を流れ込む先として示し、「部屋に流入しました」と空気が入る文として自然。", "が": "「部屋が流入しました」では部屋が流れ込む主体になり、意味が通らない。", "を": "「部屋を流入」は目的語を取れず、「流入」の使い方と合わない。", "と": "「部屋と流入」では並列の相手にならず、文が成立しない。"}, "error_tags": {"に": "着点・場所", "が": "主格", "を": "対象", "と": "相手・並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流出", "is_correct": true, "explanation": "〈流入〉の反対で、内から外へ流れ出ることを表し、辞書で対義語として挙がる。"}, {"text": "侵入", "is_correct": false, "explanation": "内へ入る点で流入に近く、反対の意味ではないため、対義語にはならない。"}, {"text": "沈殿", "is_correct": false, "explanation": "粒が底に沈むことを表し、流れ込みの反対を表す語ではない。"}, {"text": "停滞", "is_correct": false, "explanation": "流れが滞ってとどまることで、流れ込みの反対を表す語ではない。"}], "correct_answer": "流出", "explanations": {"流出": "〈流入〉の反対で、内から外へ流れ出ることを表し、辞書で対義語として挙がる。", "侵入": "内へ入る点で流入に近く、反対の意味ではないため、対義語にはならない。", "沈殿": "粒が底に沈むことを表し、流れ込みの反対を表す語ではない。", "停滞": "流れが滞ってとどまることで、流れ込みの反対を表す語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37248, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "〈流入〉を主語にして「流入が止まり」と続け、「止まる」と自然に結びつく。"}, {"text": "を", "is_correct": false, "explanation": "「流入を止まり」と目的語にすると、自動詞「止まる」と合わず文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「流入に止まり」では着点にならず、「止まる」と結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "「流入へ止まり」は方向を示すが、止まる先として意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "〈流入〉を主語にして「流入が止まり」と続け、「止まる」と自然に結びつく。", "を": "「流入を止まり」と目的語にすると、自動詞「止まる」と合わず文が崩れる。", "に": "「流入に止まり」では着点にならず、「止まる」と結びつかない。", "へ": "「流入へ止まり」は方向を示すが、止まる先として意味が通らない。"}, "error_tags": {"が": "主格", "を": "対象", "に": "着点", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流出", "is_correct": true, "explanation": "〈流入〉の反対で、外へ流れ出ることを表し、辞書で対義語として挙がる。"}, {"text": "凍結", "is_correct": false, "explanation": "水が固まることを表し、流れ込みの反対を表す語ではない。"}, {"text": "凝縮", "is_correct": false, "explanation": "気体が液体に変わることを表し、流れ込みの反対を表す語ではない。"}, {"text": "滞留", "is_correct": false, "explanation": "同じ場所にとどまることで、流れ込みの反対とは言えない。"}], "correct_answer": "流出", "explanations": {"流出": "〈流入〉の反対で、外へ流れ出ることを表し、辞書で対義語として挙がる。", "凍結": "水が固まることを表し、流れ込みの反対を表す語ではない。", "凝縮": "気体が液体に変わることを表し、流れ込みの反対を表す語ではない。", "滞留": "同じ場所にとどまることで、流れ込みの反対とは言えない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37248, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水や空気のように、外から中に入ってくること。", "primary_collocate": null, "pronunciation": "りゅうにゅう", "ipa": "ɾʲɯːɲɯː", "syllable_count": 4, "sentences": [{"text": "大雨で、川の水が地下室に流入しました。", "target_word": "流入", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で、川[かわ]の水[みず]が地下室[ちかしつ]に流入[りゅうにゅう]しました。", "sentence_source": "generated"}, {"text": "窓が開いていたため、冷たい空気が部屋に流入しました。", "target_word": "流入", "complexity_tier": "T3", "furigana": "窓[まど]が開[あ]いていたため、冷[つめ]たい空気[くうき]が部屋[へや]に流入[りゅうにゅう]しました。", "sentence_source": "generated"}, {"text": "海水の流入を防ぐために、入り口に壁を作りました。", "target_word": "流入", "complexity_tier": "T3", "furigana": "海水[かいすい]の流入[りゅうにゅう]を防[ふせ]ぐために、入[い]り口[ぐち]に壁[かべ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "割れた窓から雨水が流入して、床がぬれました。", "target_word": "流入", "complexity_tier": "T3", "furigana": "割[わ]れた窓[まど]から雨水[あまみず]が流入[りゅうにゅう]して、床[ゆか]がぬれました。", "sentence_source": "generated"}, {"text": "工場の排水が湖に流入し、魚が減りました。", "target_word": "流入", "complexity_tier": "T3", "furigana": "工場[こうじょう]の排水[はいすい]が湖[みずうみ]に流入[りゅうにゅう]し、魚[さかな]が減[へ]りました。", "sentence_source": "generated"}, {"text": "トンネルへの水の流入は、ポンプで止めました。", "target_word": "流入", "complexity_tier": "T3", "furigana": "トンネルへの水[みず]の流入[りゅうにゅう]は、ポンプで止[と]めました。", "sentence_source": "generated"}, {"text": "煙の流入を止めるため、ドアをしっかり閉めました。", "target_word": "流入", "complexity_tier": "T3", "furigana": "煙[けむり]の流入[りゅうにゅう]を止[と]めるため、ドアをしっかり閉[し]めました。", "sentence_source": "generated"}, {"text": "川から池への水の流入が止まり、池は小さくなりました。", "target_word": "流入", "complexity_tier": "T3", "furigana": "川[かわ]から池[いけ]への水[みず]の流入[りゅうにゅう]が止[と]まり、池[いけ]は小[ちい]さくなりました。", "sentence_source": "generated"}, {"text": "古い船に水が流入して、船が少しずつ沈みました。", "target_word": "流入", "complexity_tier": "T3", "furigana": "古[ふる]い船[ふね]に水[みず]が流入[りゅうにゅう]して、船[ふね]が少[すこ]しずつ沈[しず]みました。", "sentence_source": "generated"}, {"text": "外から土砂が流入し、水路がふさがれました。", "target_word": "流入", "complexity_tier": "T3", "furigana": "外[そと]から土砂[どしゃ]が流入[りゅうにゅう]し、水路[すいろ]がふさがれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流入", "label": "基本形"}, {"form": "流入する", "label": "終止形"}, {"form": "流入した", "label": "過去形"}, {"form": "流入して", "label": "て形"}], "register": "丁寧", "sense_fingerprint": "水・空気・煙など流れるものが外から中へ入ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37248, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流入", "is_correct": true, "explanation": "水が外から中へ流れ込む意味で、「地下室に流入しました」として文脈に合う。"}, {"text": "停止", "is_correct": false, "explanation": "止まることを表し、水が地下室へ入るという文には合わないため、成り立たない。"}, {"text": "拡大", "is_correct": false, "explanation": "範囲が広がることを表すので、地下室に入るという文脈とは合わない。"}, {"text": "増加", "is_correct": false, "explanation": "数量が増えることを表し、水が地下室へ流れ込む文の動きに合わない。"}], "explanations": {"流入": "水が外から中へ流れ込む意味で、「地下室に流入しました」として文脈に合う。", "停止": "止まることを表し、水が地下室へ入るという文には合わないため、成り立たない。", "拡大": "範囲が広がることを表すので、地下室に入るという文脈とは合わない。", "増加": "数量が増えることを表し、水が地下室へ流れ込む文の動きに合わない。"}, "sentence_index": 0, "correct_answer": "流入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "泥棒が窓から家に流入した。", "explanation": "ここは〈侵入〉の意味。流入は水や空気などが流れ込むことに使い、人が忍び込む場合には使わない。"}, {"text": "一文が文章の途中に流入した。", "explanation": "ここは〈挿入〉の意味。流入は流れ込む現象に使うので、文章の中に一文を差し込む場合には合わない。"}, {"text": "台風が港に流入した。", "explanation": "ここは〈上陸〉の意味。流入は水や空気などが流れ込む現象に使うので、台風が陸に上がる場合には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37248, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流入", "is_correct": true, "explanation": "煙が外から入ってくることを表し、「煙の流入を止める」として文脈に合う。"}, {"text": "運転", "is_correct": false, "explanation": "機械を動かすことを表し、煙を止める対象として合わないため、文が成り立たない。"}, {"text": "注文", "is_correct": false, "explanation": "品物を頼む行為で、煙を止める対象にはならないため、意味が通らない。"}, {"text": "契約", "is_correct": false, "explanation": "取り決めを結ぶ行為で、煙を対象として止める文には入らない。"}], "explanations": {"流入": "煙が外から入ってくることを表し、「煙の流入を止める」として文脈に合う。", "運転": "機械を動かすことを表し、煙を止める対象として合わないため、文が成り立たない。", "注文": "品物を頼む行為で、煙を止める対象にはならないため、意味が通らない。", "契約": "取り決めを結ぶ行為で、煙を対象として止める文には入らない。"}, "sentence_index": 6, "correct_answer": "流入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父が毎晩遅くに家に流入した。", "explanation": "ここは〈帰宅〉の意味。流入は水や空気などの流れに使い、人が家に戻る場合には合わない。"}, {"text": "選手が大会に流入した。", "explanation": "ここは〈参加〉の意味。流入は流れ込みを表すので、選手が大会に加わる場合には使わない。"}, {"text": "囚人が牢屋の外に流入した。", "explanation": "ここは〈脱出〉の意味。流入は外から中へ入ることで、中から外へ逃げ出す場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37248, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台風の影響で、海水が港の倉庫を流入した。", "corrected_sentence": "台風の影響で、海水が港の倉庫に流入した。", "error_description": "「流入」は流れ込む先を「に」で示す。「倉庫を流入」は誤りで、正しくは「倉庫に流入」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37248, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強風で砂が家の中を流入した。", "corrected_sentence": "強風で砂が家の中に流入した。", "error_description": "「流入」は入る先を「に」で示す。「家の中を」は誤りで、正しくは「家の中に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37249, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流出", "is_correct": true, "explanation": "〈流入〉の反対で、内から外へ出ていくことを表し、辞書で対義語として挙がる。"}, {"text": "移動", "is_correct": false, "explanation": "場所を変えることを表すが、外から入る流れの反対にはならない。"}, {"text": "滞在", "is_correct": false, "explanation": "一定の場所にとどまることで、流れ込みの反対語には当たらない。"}, {"text": "来訪", "is_correct": false, "explanation": "人が訪れることで、流れ込みと同じ向きの動きを表し、反対ではない。"}], "correct_answer": "流出", "explanations": {"流出": "〈流入〉の反対で、内から外へ出ていくことを表し、辞書で対義語として挙がる。", "移動": "場所を変えることを表すが、外から入る流れの反対にはならない。", "滞在": "一定の場所にとどまることで、流れ込みの反対語には当たらない。", "来訪": "人が訪れることで、流れ込みと同じ向きの動きを表し、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37249, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流出", "is_correct": true, "explanation": "〈流入〉の反対で、外へ流れ出ることを表し、辞書で対義語として挙がる。"}, {"text": "流通", "is_correct": false, "explanation": "商品などが広く行き渡ることを表し、流入の反対にはならない。"}, {"text": "定住", "is_correct": false, "explanation": "人が一か所に住み着くことで、流れ込みの反対を表す語ではない。"}, {"text": "出張", "is_correct": false, "explanation": "一時的に他の場所へ出向くことで、流入の反対語ではない。"}], "correct_answer": "流出", "explanations": {"流出": "〈流入〉の反対で、外へ流れ出ることを表し、辞書で対義語として挙がる。", "流通": "商品などが広く行き渡ることを表し、流入の反対にはならない。", "定住": "人が一か所に住み着くことで、流れ込みの反対を表す語ではない。", "出張": "一時的に他の場所へ出向くことで、流入の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37249, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "外部から内部へ、人や物が流れ込むこと。特に、人の移動やお金などの資源が他地域から入ってくる場合に使う。", "primary_collocate": null, "pronunciation": "りゅうにゅう", "ipa": "ɾʲɯːɲɯː", "syllable_count": 4, "sentences": [{"text": "都市部への人口の流入が続き、住宅が足りなくなっている。", "target_word": "流入", "complexity_tier": "T3", "furigana": "都市部[としぶ]への人口[じんこう]の流入[りゅうにゅう]が続[つづ]き、住宅[じゅうたく]が足[た]りなくなっている。", "sentence_source": "generated"}, {"text": "海外からの資金の流入で、国の経済が大きく成長した。", "target_word": "流入", "complexity_tier": "T3", "furigana": "海外[かいがい]からの資金[しきん]の流入[りゅうにゅう]で、国[くに]の経済[けいざい]が大[おお]きく成長[せいちょう]した。", "sentence_source": "generated"}, {"text": "仕事を求める若者の流入により、町の人口が増えた。", "target_word": "流入", "complexity_tier": "T3", "furigana": "仕事[しごと]を求[もと]める若者[わかもの]の流入[りゅうにゅう]により、町[まち]の人口[じんこう]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "外国人観光客の流入が増え、店の売り上げが上がった。", "target_word": "流入", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]観光客[かんこうきゃく]の流入[りゅうにゅう]が増[ふ]え、店[みせ]の売[う]り上[あ]げが上[あ]がった。", "sentence_source": "generated"}, {"text": "大都市への人の流入を抑えるため、政府は地方に仕事を作った。", "target_word": "流入", "complexity_tier": "T3", "furigana": "大都市[だいとし]への人[ひと]の流入[りゅうにゅう]を抑[おさ]えるため、政府[せいふ]は地方[ちほう]に仕事[しごと]を作[つく]った。", "sentence_source": "generated"}, {"text": "投資家のお金の流入が止まると、株価は下がるだろう。", "target_word": "流入", "complexity_tier": "T3", "furigana": "投資家[とうしか]のお金[かね]の流入[りゅうにゅう]が止[と]まると、株価[かぶか]は下[さ]がるだろう。", "sentence_source": "generated"}, {"text": "難民の流入に対応するため、市は新しい施設を開いた。", "target_word": "流入", "complexity_tier": "T3", "furigana": "難民[なんみん]の流入[りゅうにゅう]に対応[たいおう]するため、市[し]は新[あたら]しい施設[しせつ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "地方では若者の流出が多いが、都市では流入が多い。", "target_word": "流入", "complexity_tier": "T3", "furigana": "地方[ちほう]では若者[わかもの]の流出[りゅうしゅつ]が多[おお]いが、都市[とし]では流入[りゅうにゅう]が多[おお]い。", "sentence_source": "generated"}, {"text": "外国からの安い商品の流入は、国内の工場に影響を与えた。", "target_word": "流入", "complexity_tier": "T3", "furigana": "外国[がいこく]からの安[やす]い商品[しょうひん]の流入[りゅうにゅう]は、国内[こくない]の工場[こうじょう]に影響[えいきょう]を与[あた]えた。", "sentence_source": "generated"}, {"text": "人口の流入が急に増えたため、学校の教室が足りなくなった。", "target_word": "流入", "complexity_tier": "T3", "furigana": "人口[じんこう]の流入[りゅうにゅう]が急[きゅう]に増[ふ]えたため、学校[がっこう]の教室[きょうしつ]が足[た]りなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流入", "label": "基本形"}, {"form": "流入する", "label": "終止形"}, {"form": "流入した", "label": "過去形"}, {"form": "流入して", "label": "て形"}], "register": "書き言葉", "sense_fingerprint": "人・お金・商品などが他の地域や国から入ってくること。社会・経済の話題で使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37249, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流入", "is_correct": true, "explanation": "人口が外から集まってくる現象を指し、「続き、住宅が足りなくなっている」という文脈に合う。"}, {"text": "手続き", "is_correct": false, "explanation": "人口に対して続く行為としては成り立たず、「人口の手続き」は文として通らない。"}, {"text": "契約", "is_correct": false, "explanation": "人口と結びつく語ではなく、住宅が足りないという文脈に合わない。"}, {"text": "建設", "is_correct": false, "explanation": "人口を建設するという表現はなく、空欄に入ると意味が通らない。"}], "explanations": {"流入": "人口が外から集まってくる現象を指し、「続き、住宅が足りなくなっている」という文脈に合う。", "手続き": "人口に対して続く行為としては成り立たず、「人口の手続き」は文として通らない。", "契約": "人口と結びつく語ではなく、住宅が足りないという文脈に合わない。", "建設": "人口を建設するという表現はなく、空欄に入ると意味が通らない。"}, "sentence_index": 0, "correct_answer": "流入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "息子は隣の市の学校に流入した。", "explanation": "ここは〈転校〉の意味。流入は多くの人や資源が流れ込むことで、一人の生徒が学校を移る場合には使わない。"}, {"text": "町の人が自治会に流入した。", "explanation": "ここは〈加入〉の意味。流入は外から多く入ってくることで、一人が団体に入る場合には合わない。"}, {"text": "地元の企業が図書館に流入した。", "explanation": "ここは〈寄贈〉の意味。流入は自然に流れ込むことで、企業が本などを寄付する場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37249, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流入", "is_correct": true, "explanation": "難民が外から多く入ってくる事態を指し、「それに対応するため施設を開いた」という文脈に合う。"}, {"text": "大会", "is_correct": false, "explanation": "難民に対応する対象にならず、「難民の大会に対応する」は文として成立しない。"}, {"text": "税金", "is_correct": false, "explanation": "対応すべき事態を表す語ではなく、施設を開く文脈に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "施設を開いて対応する対象にはならず、「難民の天気に対応する」は意味が通らない。"}], "explanations": {"流入": "難民が外から多く入ってくる事態を指し、「それに対応するため施設を開いた」という文脈に合う。", "大会": "難民に対応する対象にならず、「難民の大会に対応する」は文として成立しない。", "税金": "対応すべき事態を表す語ではなく、施設を開く文脈に合わない。", "天気": "施設を開いて対応する対象にはならず、「難民の天気に対応する」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "流入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新入社員が営業部に流入した。", "explanation": "ここは〈配属〉の意味。流入は多くの人や物が流れ込むことで、一人を部署に割り当てる場合には使わない。"}, {"text": "俳優がドラマに流入した。", "explanation": "ここは〈出演〉の意味。流入は外から入る流れを指すので、俳優が作品に出る場合には合わない。"}, {"text": "学生が寮に流入した。", "explanation": "ここは〈寄宿〉の意味。流入は多数が流れ込むことを表し、一人が寮に泊まる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37249, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海外の資金が国内を流入し、株価が上がった。", "corrected_sentence": "海外の資金が国内に流入し、株価が上がった。", "error_description": "「流入」は入る先を「に」で示す。「国内を流入」は誤りで、正しくは「国内に流入」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37249, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人口が都市に流入ないで、住宅が足りなくなった。", "corrected_sentence": "人口が都市に流入して、住宅が足りなくなった。", "error_description": "「流入」はサ変動詞なので「流入して」と続ける。「流入ないで」は活用の誤りで、文として成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37250, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「多い」の主語は「人口」なので「人口が多い」となる。"}, {"text": "を", "is_correct": false, "explanation": "「多い」は目的語を取らないので「人口を多い」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「人口に多い」では「多い」の主語関係が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や範囲を表し、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「多い」の主語は「人口」なので「人口が多い」となる。", "を": "「多い」は目的語を取らないので「人口を多い」は不自然。", "に": "「人口に多い」では「多い」の主語関係が成り立たない。", "で": "「で」は手段や範囲を表し、主語にはならない。"}, "error_tags": {"を": "目的語（「多い」には不要）", "に": "帰着・相手（主語関係にならない）", "で": "手段・範囲（主語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37250, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「多く」の主語は「人口」なので「人口が多く」となる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「多く」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「人口と多く」では並列になってしまい、主語関係が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を表し、「人口」を主語として示さない。"}], "correct_answer": "が", "explanations": {"が": "「多く」の主語は「人口」なので「人口が多く」となる。", "へ": "「へ」は方向を表し、「多く」の主語にはならない。", "と": "「人口と多く」では並列になってしまい、主語関係が成り立たない。", "から": "「から」は起点や理由を表し、「人口」を主語として示さない。"}, "error_tags": {"へ": "方向（主語にならない）", "と": "並列・相手（主語関係にならない）", "から": "起点・理由（主語にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37250, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある場所に住んでいる人の数。", "primary_collocate": null, "pronunciation": "じんこう", "ipa": "dʑiŋkoː", "syllable_count": 4, "sentences": [{"text": "この町の人口は、約三万人です。", "target_word": "人口", "complexity_tier": "T3", "furigana": "この町[まち]の人口[じんこう]は、約[やく]三万人[さんまんにん]です。", "sentence_source": "generated"}, {"text": "東京は日本でいちばん人口が多い都市です。", "target_word": "人口", "complexity_tier": "T3", "furigana": "東京[とうきょう]は日本[にほん]でいちばん人口[じんこう]が多[おお]い都市[とし]です。", "sentence_source": "generated"}, {"text": "人口が少ない村では、店が閉まってしまいました。", "target_word": "人口", "complexity_tier": "T3", "furigana": "人口[じんこう]が少[すく]ない村[むら]では、店[みせ]が閉[し]まってしまいました。", "sentence_source": "generated"}, {"text": "若い人が出ていくので、この島の人口は年々減っています。", "target_word": "人口", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]が出[で]ていくので、この島[しま]の人口[じんこう]は年々[ねんねん]減[へ]っています。", "sentence_source": "generated"}, {"text": "人口が増えたため、新しい小学校ができました。", "target_word": "人口", "complexity_tier": "T3", "furigana": "人口[じんこう]が増[ふ]えたため、新[あたら]しい小学校[しょうがっこう]ができました。", "sentence_source": "generated"}, {"text": "私の町は人口が少ないですが、みんな仲がいいです。", "target_word": "人口", "complexity_tier": "T3", "furigana": "私[わたし]の町[まち]は人口[じんこう]が少[すく]ないですが、みんな仲[なか]がいいです。", "sentence_source": "generated"}, {"text": "世界の人口は、八十億人をこえました。", "target_word": "人口", "complexity_tier": "T3", "furigana": "世界[せかい]の人口[じんこう]は、八十億人[はちじゅうおくにん]をこえました。", "sentence_source": "generated"}, {"text": "駅の近くは人口が多く、いつもにぎやかです。", "target_word": "人口", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くは人口[じんこう]が多[おお]く、いつもにぎやかです。", "sentence_source": "generated"}, {"text": "この市の人口は、十年前より二千人増えました。", "target_word": "人口", "complexity_tier": "T3", "furigana": "この市[し]の人口[じんこう]は、十年前[じゅうねんまえ]より二千人[にせんにん]増[ふ]えました。", "sentence_source": "generated"}, {"text": "人口の少ない町には、大きな病院がありません。", "target_word": "人口", "complexity_tier": "T3", "furigana": "人口[じんこう]の少[すく]ない町[まち]には、大[おお]きな病院[びょういん]がありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人口", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "町や国など、ある場所に住む人の数。日常会話で多い・少ないと言う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37250, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人口", "is_correct": true, "explanation": "住んでいる人の数を表すので、「この町の〜は約三万人」に入る。"}, {"text": "面積", "is_correct": false, "explanation": "土地の広さを表す語で、人の数を示す文には合わない。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度を表す語で、人数の文脈には入らない。"}, {"text": "予算", "is_correct": false, "explanation": "お金の計画額を表す語で、「約三万人」とはつながらない。"}], "explanations": {"人口": "住んでいる人の数を表すので、「この町の〜は約三万人」に入る。", "面積": "土地の広さを表す語で、人の数を示す文には合わない。", "気温": "空気の温度を表す語で、人数の文脈には入らない。", "予算": "お金の計画額を表す語で、「約三万人」とはつながらない。"}, "sentence_index": 0, "correct_answer": "人口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この池は人口の湖で、夏には観光客が集まる。", "explanation": "ここは〈人工〉（人の手で作った）の意味。人口（住民の数）とは同音異義語。"}, {"text": "この番組では人口知能が司会を務めている。", "explanation": "ここは〈人工〉（人の手で作った）の意味。人工知能のことで、人口（住民の数）とは同音異義語。"}, {"text": "駅前に人口の滝を作る計画が進んでいる。", "explanation": "ここは〈人工〉（人の手で作った）の意味。人工の滝のことで、人口（住民の数）とは同音異義語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37250, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人口", "is_correct": true, "explanation": "地球に住む人の数を表すので、八十億人を超えるという文に入る。"}, {"text": "寿命", "is_correct": false, "explanation": "生きる年数を表すので、人の数が超えるという文には合わない。"}, {"text": "収入", "is_correct": false, "explanation": "お金の額を表すので、人数の文には使えない。"}, {"text": "体重", "is_correct": false, "explanation": "人の重さを表すので、人数を述べる文には合わない。"}], "explanations": {"人口": "地球に住む人の数を表すので、八十億人を超えるという文に入る。", "寿命": "生きる年数を表すので、人の数が超えるという文には合わない。", "収入": "お金の額を表すので、人数の文には使えない。", "体重": "人の重さを表すので、人数を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "人口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "救急隊員は倒れた人に人口呼吸をした。", "explanation": "ここは〈人工呼吸〉（人の手で行う呼吸の補助）の意味。人口（住民の数）とは別の語で、同じ読みでも意味が違う。"}, {"text": "研究所では人口の筋肉を開発している。", "explanation": "ここは〈人工〉（人の手で作った）の意味。人工筋肉のことで、人口（住民の数）とは同音異義語。"}, {"text": "この箱は人口の素材で作られている。", "explanation": "ここは〈人工〉（人の手で作った）の意味。人工素材のことで、人口（住民の数）とは同音異義語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37250, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人口を減ったのは、どの地域ですか。", "corrected_sentence": "人口が減ったのは、どの地域ですか。", "error_description": "誤: 人口を（を）／正: 人口が（が）。「減る」は自動詞で、人口が主語になるので「が」を使う。「を」は「人口を減らす」のような他動詞の場合に使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37250, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町は人口が減らして、学校が一つ閉まった。", "corrected_sentence": "この町は人口が減って、学校が一つ閉まった。", "error_description": "誤: 減らして（他動詞）／正: 減って（自動詞）。「人口が」が主語で人口自体が変化するので「減る」を使う。「減らす」は人が人口を減らす場合に使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37251, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この国の人口は」と話題を示し、後に予測を述べる文になる。"}, {"text": "を", "is_correct": false, "explanation": "「人口を、半分になる」では目的語の関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「人口に、半分になる」では帰着や相手の関係にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や範囲を表し、この文の話題にはならない。"}], "correct_answer": "は", "explanations": {"は": "「この国の人口は」と話題を示し、後に予測を述べる文になる。", "を": "「人口を、半分になる」では目的語の関係が成り立たない。", "に": "「人口に、半分になる」では帰着や相手の関係にならず不自然。", "で": "「で」は手段や範囲を表し、この文の話題にはならない。"}, "error_tags": {"を": "目的語（他動詞用）", "に": "帰着・相手（文の話題にならない）", "で": "手段・範囲（文の話題にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37251, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「人口の増加」と名詞を修飾する形になり、文の流れに合う。"}, {"text": "へ", "is_correct": false, "explanation": "「人口へ増加が止まっている」では方向の関係になり、意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「止まっている」は目的語を取らないので「を」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、「人口」と「増加」をつなぐ働きをしない。"}], "correct_answer": "の", "explanations": {"の": "「人口の増加」と名詞を修飾する形になり、文の流れに合う。", "へ": "「人口へ増加が止まっている」では方向の関係になり、意味が通らない。", "を": "「止まっている」は目的語を取らないので「を」は不自然。", "から": "「から」は起点を表し、「人口」と「増加」をつなぐ働きをしない。"}, "error_tags": {"を": "目的語（「止まっている」は目的語を取らない）", "へ": "方向（主語にならない）", "から": "起点・理由（修飾関係にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37251, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある地域に住んでいる人の数のこと。特に、国や都市などの人口統計で使われる。", "primary_collocate": null, "pronunciation": "じんこう", "ipa": "dʑiŋkoː", "syllable_count": 4, "sentences": [{"text": "国勢調査では、五年ごとに日本の人口が調べられる。", "target_word": "人口", "complexity_tier": "T3", "furigana": "国勢調査[こくせいちょうさ]では、五年[ごねん]ごとに日本[にほん]の人口[じんこう]が調[しら]べられる。", "sentence_source": "generated"}, {"text": "この国の人口は、今世紀の終わりには半分になると予測されている。", "target_word": "人口", "complexity_tier": "T3", "furigana": "この国[くに]の人口[じんこう]は、今世紀[こんせいき]の終[お]わりには半分[はんぶん]になると予測[よそく]されている。", "sentence_source": "generated"}, {"text": "人口が集中する都市ほど、土地の値段が上がりやすい。", "target_word": "人口", "complexity_tier": "T3", "furigana": "人口[じんこう]が集中[しゅうちゅう]する都市[とし]ほど、土地[とち]の値段[ねだん]が上[あ]がりやすい。", "sentence_source": "generated"}, {"text": "高齢化が進み、日本の人口に占める六十五歳以上の割合は高くなった。", "target_word": "人口", "complexity_tier": "T3", "furigana": "高齢化[こうれいか]が進[すす]み、日本[にほん]の人口[じんこう]に占[し]める六十五歳[ろくじゅうごさい]以上[いじょう]の割合[わりあい]は高[たか]くなった。", "sentence_source": "generated"}, {"text": "統計によると、この県の人口は去年より約千人減った。", "target_word": "人口", "complexity_tier": "T3", "furigana": "統計[とうけい]によると、この県[けん]の人口[じんこう]は去年[きょねん]より約[やく]千人[せんにん]減[へ]った。", "sentence_source": "generated"}, {"text": "人口が増えた国では、食料の確保が大きな課題となる。", "target_word": "人口", "complexity_tier": "T3", "furigana": "人口[じんこう]が増[ふ]えた国[くに]では、食料[しょくりょう]の確保[かくほ]が大[おお]きな課題[かだい]となる。", "sentence_source": "generated"}, {"text": "市の人口は、昨年の調査で五十万人を超えた。", "target_word": "人口", "complexity_tier": "T3", "furigana": "市[し]の人口[じんこう]は、昨年[さくねん]の調査[ちょうさ]で五十万人[ごじゅうまんにん]を超[こ]えた。", "sentence_source": "generated"}, {"text": "先進国では出生率が下がり、人口の増加が止まっている。", "target_word": "人口", "complexity_tier": "T3", "furigana": "先進国[せんしんこく]では出生率[しゅっしょうりつ]が下[さ]がり、人口[じんこう]の増加[ぞうか]が止[と]まっている。", "sentence_source": "generated"}, {"text": "人口の変化は、国の将来の計画を立てる際の大切な資料だ。", "target_word": "人口", "complexity_tier": "T3", "furigana": "人口[じんこう]の変化[へんか]は、国[くに]の将来[しょうらい]の計画[けいかく]を立[た]てる際[さい]の大切[たいせつ]な資料[しりょう]だ。", "sentence_source": "generated"}, {"text": "都市と農村の人口を比べると、都市のほうが三倍多い。", "target_word": "人口", "complexity_tier": "T3", "furigana": "都市[とし]と農村[のうそん]の人口[じんこう]を比[くら]べると、都市[とし]のほうが三倍[さんばい]多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人口", "label": "基本形"}], "register": "書き言葉", "sense_fingerprint": "国や都市の住民数を表す統計上の数。調査・予測・増減の話題で使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37251, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人口", "is_correct": true, "explanation": "国ごとの住民数は国勢調査の調査対象なので、「日本の人口が調べられる」に入る。"}, {"text": "夢", "is_correct": false, "explanation": "人の見る夢は統計の調査対象にならず、この文には合わない。"}, {"text": "冗談", "is_correct": false, "explanation": "話の内容であり、国勢調査で数える対象ではない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝ている間の発言で、国勢調査の対象にはならない。"}], "explanations": {"人口": "国ごとの住民数は国勢調査の調査対象なので、「日本の人口が調べられる」に入る。", "夢": "人の見る夢は統計の調査対象にならず、この文には合わない。", "冗談": "話の内容であり、国勢調査で数える対象ではない。", "寝言": "寝ている間の発言で、国勢調査の対象にはならない。"}, "sentence_index": 0, "correct_answer": "人口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議室の床に人口の芝生を敷いた。", "explanation": "ここは〈人工〉（人の手で作った）の意味。人工芝のことで、人口（住民の数）とは同音異義語。"}, {"text": "この建物は人口の素材を使って作られた。", "explanation": "ここは〈人工〉（人の手で作った）の意味。人工素材のことで、人口（住民の数）とは同音異義語。"}, {"text": "夜空に人口の光が広がっていた。", "explanation": "ここは〈人工〉（人の手で作った）の意味。人工の光のことで、人口（住民の数）とは同音異義語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37251, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人口", "is_correct": true, "explanation": "市に住む人の数で、昨年の調査で五十万人を超えたという文に入る。"}, {"text": "予算", "is_correct": false, "explanation": "お金の計画額で、人数が五十万人を超えたという文には合わない。"}, {"text": "税収", "is_correct": false, "explanation": "税金の収入額で、人数の文には使えない。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度で、人の数を述べる文には合わない。"}], "explanations": {"人口": "市に住む人の数で、昨年の調査で五十万人を超えたという文に入る。", "予算": "お金の計画額で、人数が五十万人を超えたという文には合わない。", "税収": "税金の収入額で、人数の文には使えない。", "気温": "空気の温度で、人の数を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "人口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "故障した人口衛星の修理を依頼した。", "explanation": "ここは〈人工衛星〉（人が作った衛星）の意味。人口（住民の数）とは別の語で、書き言葉でも取り違えやすい。"}, {"text": "工場では人口の部品を大量に作っている。", "explanation": "ここは〈人工〉（人の手で作った）の意味。人工部品のことで、人口（住民の数）とは同音異義語。"}, {"text": "この店は人口の甘味料を使っている。", "explanation": "ここは〈人工〉（人の手で作った）の意味。人工甘味料のことで、人口（住民の数）とは同音異義語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37251, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この国の人口を三年間で三%増えた。", "corrected_sentence": "この国の人口は三年間で三%増えた。", "error_description": "誤: 人口を（を）／正: 人口は（は）。「増える」は自動詞なので目的語の「を」は使えない。主題の「は」で人口の変化を述べる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37251, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府は人口が増やす政策を進めている。", "corrected_sentence": "政府は人口を増やす政策を進めている。", "error_description": "誤: 人口が（が）／正: 人口を（を）。「増やす」は他動詞で、人口を目的語として取るので「を」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37252, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「対応が」と主語を示し、「わからなくて」につながる。"}, {"text": "に", "is_correct": false, "explanation": "「対応にわからなくて」では「わからない」の対象として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表し、「わからない」の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「わからない」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「対応が」と主語を示し、「わからなくて」につながる。", "に": "「対応にわからなくて」では「わからない」の対象として成り立たない。", "で": "「で」は手段や場所を表し、「わからない」の主語にはならない。", "へ": "「へ」は方向を表し、「わからない」の主語にはならない。"}, "error_tags": {"に": "帰着・対象（主語にならない）", "で": "手段・場所（主語にならない）", "へ": "方向（主語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37252, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「対応を調べる」と目的語を示し、「調べると」につながる。"}, {"text": "と", "is_correct": false, "explanation": "「対応と調べると」では並列になり、目的語の関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を表し、「調べる」の目的語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「対応の調べると」では「の」が続く語がなく、文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「対応を調べる」と目的語を示し、「調べると」につながる。", "と": "「対応と調べると」では並列になり、目的語の関係が成り立たない。", "より": "「より」は比較や起点を表し、「調べる」の目的語にはならない。", "の": "「対応の調べると」では「の」が続く語がなく、文として成り立たない。"}, "error_tags": {"と": "並列・相手（目的語にならない）", "より": "比較・起点（目的語にならない）", "の": "連体修飾（目的語にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37252, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つの物事が、互いに一対一で結びついていること。またその結びつき。", "primary_collocate": null, "pronunciation": "たいおう", "ipa": "taioː", "syllable_count": 4, "sentences": [{"text": "この表は日本語と英語の言葉の対応を示している。", "target_word": "対応", "complexity_tier": "T3", "furigana": "この表(ひょう)は日本語(にほんご)と英語(えいご)の言葉(ことば)の対応(たいおう)を示(しめ)している。", "sentence_source": "generated"}, {"text": "地図の記号と実際の建物の対応がわからなくて、道に迷った。", "target_word": "対応", "complexity_tier": "T3", "furigana": "地図(ちず)の記号(きごう)と実際(じっさい)の建物(たてもの)の対応(たいおう)がわからなくて、道(みち)に迷(まよ)った。", "sentence_source": "generated"}, {"text": "左の列と右の列の対応を、線で結ぶ問題が出た。", "target_word": "対応", "complexity_tier": "T3", "furigana": "左(ひだり)の列(れつ)と右(みぎ)の列(れつ)の対応(たいおう)を、線(せん)で結(むす)ぶ問題(もんだい)が出(で)た。", "sentence_source": "generated"}, {"text": "注文番号と商品の対応を確認してから、箱に詰めた。", "target_word": "対応", "complexity_tier": "T3", "furigana": "注文(ちゅうもん)番号(ばんごう)と商品(しょうひん)の対応(たいおう)を確認(かくにん)してから、箱(はこ)に詰(つ)めた。", "sentence_source": "generated"}, {"text": "音符と音名の対応を覚えるまで、楽譜が読めなかった。", "target_word": "対応", "complexity_tier": "T3", "furigana": "音符(おんぷ)と音名(おんめい)の対応(たいおう)を覚(おぼ)えるまで、楽譜(がくふ)が読(よ)めなかった。", "sentence_source": "generated"}, {"text": "地図の色と国名の対応は、右の説明に書いてある。", "target_word": "対応", "complexity_tier": "T3", "furigana": "地図(ちず)の色(いろ)と国名(こくめい)の対応(たいおう)は、右(みぎ)の説明(せつめい)に書(か)いてある。", "sentence_source": "generated"}, {"text": "名前と顔の対応を覚えられず、紹介に時間がかかった。", "target_word": "対応", "complexity_tier": "T3", "furigana": "名前(なまえ)と顔(かお)の対応(たいおう)を覚(おぼ)えられず、紹介(しょうかい)に時間(じかん)がかかった。", "sentence_source": "generated"}, {"text": "二つのグラフの点の対応を調べると、変化の原因が見えてくる。", "target_word": "対応", "complexity_tier": "T3", "furigana": "二(ふた)つのグラフの点(てん)の対応(たいおう)を調(しら)べると、変化(へんか)の原因(げんいん)が見(み)えてくる。", "sentence_source": "generated"}, {"text": "数字と文字の対応を決めて、簡単な暗号を作った。", "target_word": "対応", "complexity_tier": "T3", "furigana": "数字(すうじ)と文字(もじ)の対応(たいおう)を決(き)めて、簡単(かんたん)な暗号(あんごう)を作(つく)った。", "sentence_source": "generated"}, {"text": "図の番号と説明文の対応が間違っていて、読者が混乱した。", "target_word": "対応", "complexity_tier": "T3", "furigana": "図(ず)の番号(ばんごう)と説明文(せつめいぶん)の対応(たいおう)が間違(まちが)っていて、読者(どくしゃ)が混乱(こんらん)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対応", "label": "基本形"}, {"form": "対応する", "label": "サ変動詞形"}, {"form": "対応した", "label": "過去形"}, {"form": "対応している", "label": "継続形"}], "register": "中立（常体）", "sense_fingerprint": "二つの物事が互いに結びつく関係。対応表・対応関係の意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37252, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対応", "is_correct": true, "explanation": "二つのものの結びつきを示す語で、言葉どうしの関係を表す文に入る。"}, {"text": "速度", "is_correct": false, "explanation": "物事の進む速さを表す語で、言葉の関係を示す文には合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "物の重量を表す語で、言葉の対応関係の文には合わない。"}, {"text": "音量", "is_correct": false, "explanation": "声や音の大きさを表す語で、この文脈では成り立たない。"}], "explanations": {"対応": "二つのものの結びつきを示す語で、言葉どうしの関係を表す文に入る。", "速度": "物事の進む速さを表す語で、言葉の関係を示す文には合わない。", "重さ": "物の重量を表す語で、言葉の対応関係の文には合わない。", "音量": "声や音の大きさを表す語で、この文脈では成り立たない。"}, "sentence_index": 0, "correct_answer": "対応"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部長の対応が遅れたので、取引先を待たせてしまった。", "explanation": "ここは〈処置・応答〉（相手に応じて処置すること）の意味。二つの物事の結びつきを表す〈対応〉とは別の意味。"}, {"text": "事故の後、会社は素早く対応を取った。", "explanation": "ここは〈処置・応答〉（相手に応じて処置すること）の意味。二つの物事の結びつきを表す〈対応〉とは別の意味。"}, {"text": "緊急時の対応を、社員全員で話し合った。", "explanation": "ここは〈処置・応答〉（相手に応じて処置すること）の意味。二つの物事の結びつきを表す〈対応〉とは別の意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37252, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対応", "is_correct": true, "explanation": "名前と顔の結びつきを表す語で、覚えるべき対応関係の文に入る。"}, {"text": "温度", "is_correct": false, "explanation": "物の熱さの度合いを表し、名前と顔の関係には合わない。"}, {"text": "香り", "is_correct": false, "explanation": "匂いを表す語で、名前と顔の関係を述べる文には合わない。"}, {"text": "厚さ", "is_correct": false, "explanation": "物の厚みを表し、この文脈では成り立たない。"}], "explanations": {"対応": "名前と顔の結びつきを表す語で、覚えるべき対応関係の文に入る。", "温度": "物の熱さの度合いを表し、名前と顔の関係には合わない。", "香り": "匂いを表す語で、名前と顔の関係を述べる文には合わない。", "厚さ": "物の厚みを表し、この文脈では成り立たない。"}, "sentence_index": 6, "correct_answer": "対応"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故の対応を、警察と一緒に進めた。", "explanation": "ここは〈処置・応答〉（相手に応じて処置すること）の意味。二つの物事の結びつきを表す〈対応〉とは別の意味。"}, {"text": "新しい窓口の対応を、来月から始める。", "explanation": "ここは〈処置・応答〉（相手に応じて処置すること）の意味。二つの物事の結びつきを表す〈対応〉とは別の意味。"}, {"text": "初めての対応に、みんな戸惑っていた。", "explanation": "ここは〈処置・応答〉（相手に応じて処置すること）の意味。二つの物事の結びつきを表す〈対応〉とは別の意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37252, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この資料は英語と日本語の単語の対応に示している。", "corrected_sentence": "この資料は英語と日本語の単語の対応を示している。", "error_description": "誤: 対応に（に）／正: 対応を（を）。「示す」は目的語に「を」を取るので、「対応を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37252, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "図の番号と説明文の対応に一つずつ確認した。", "corrected_sentence": "図の番号と説明文の対応を一つずつ確認した。", "error_description": "誤: 対応に（に）／正: 対応を（を）。「確認する」は目的語に「を」を取るので、「対応を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37253, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「対応を発表した」と目的語を示し、市役所が発表する対象になる。"}, {"text": "へ", "is_correct": false, "explanation": "「対応へ発表した」では方向の関係になり、発表の対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する働きで、「発表した」の目的語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、発表の目的語を示さない。"}], "correct_answer": "を", "explanations": {"を": "「対応を発表した」と目的語を示し、市役所が発表する対象になる。", "へ": "「対応へ発表した」では方向の関係になり、発表の対象にならない。", "の": "「の」は名詞を修飾する働きで、「発表した」の目的語にはならない。", "から": "「から」は起点を表し、発表の目的語を示さない。"}, "error_tags": {"へ": "方向（目的語にならない）", "の": "連体修飾（目的語にならない）", "から": "起点・理由（目的語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37253, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「対応が」と主語を示し、「できる職員」につながる。"}, {"text": "に", "is_correct": false, "explanation": "「英語での対応にできる」では、主語と述語の関係が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「対応とできる」では並列になり、主語関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、「できる」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「対応が」と主語を示し、「できる職員」につながる。", "に": "「英語での対応にできる」では、主語と述語の関係が成り立たない。", "と": "「対応とできる」では並列になり、主語関係が成り立たない。", "より": "「より」は比較を表し、「できる」の主語にはならない。"}, "error_tags": {"に": "帰着・対象（主語にならない）", "と": "並列・相手（主語にならない）", "より": "比較（主語にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37253, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "相手(あいて)の動きや状況(じょうきょう)に合わせて、適切(てきせつ)な方法(ほうほう)をとること。", "primary_collocate": null, "pronunciation": "たいおう", "ipa": "taioː", "syllable_count": 4, "sentences": [{"text": "客のクレームへの対応が早かったので、問題はすぐ解決した。", "target_word": "対応", "complexity_tier": "T3", "furigana": "客(きゃく)のクレームへの対応(たいおう)が早(はや)かったので、問題(もんだい)はすぐ解決(かいけつ)した。", "sentence_source": "generated"}, {"text": "台風の接近に合わせた対応を、市役所が発表した。", "target_word": "対応", "complexity_tier": "T3", "furigana": "台風(たいふう)の接近(せっきん)に合(あ)わせた対応(たいおう)を、市役所(しやくしょ)が発表(はっぴょう)した。", "sentence_source": "generated"}, {"text": "店員の丁寧な対応のおかげで、気持ちよく買い物ができた。", "target_word": "対応", "complexity_tier": "T3", "furigana": "店員(てんいん)の丁寧(ていねい)な対応(たいおう)のおかげで、気持(きも)ちよく買(か)い物(もの)ができた。", "sentence_source": "generated"}, {"text": "電話の対応が悪くて、客を怒らせてしまった。", "target_word": "対応", "complexity_tier": "T3", "furigana": "電話(でんわ)の対応(たいおう)が悪(わる)くて、客(きゃく)を怒(おこ)らせてしまった。", "sentence_source": "generated"}, {"text": "地震の直後、学校の対応は迅速だった。", "target_word": "対応", "complexity_tier": "T3", "furigana": "地震(じしん)の直後(ちょくご)、学校(がっこう)の対応(たいおう)は迅速(じんそく)だった。", "sentence_source": "generated"}, {"text": "相手の出方を見てから対応を決める。", "target_word": "対応", "complexity_tier": "T3", "furigana": "相手(あいて)の出方(でかた)を見(み)てから対応(たいおう)を決(き)める。", "sentence_source": "generated"}, {"text": "苦情の対応に追われて、昼ご飯を食べる時間がなかった。", "target_word": "対応", "complexity_tier": "T3", "furigana": "苦情(くじょう)の対応(たいおう)に追(お)われて、昼(ひる)ご飯(はん)を食(た)べる時間(じかん)がなかった。", "sentence_source": "generated"}, {"text": "英語での対応ができる職員が足りない。", "target_word": "対応", "complexity_tier": "T3", "furigana": "英語(えいご)での対応(たいおう)ができる職員(しょくいん)が足(た)りない。", "sentence_source": "generated"}, {"text": "事故後の対応を間違えて、会社は信用を失った。", "target_word": "対応", "complexity_tier": "T3", "furigana": "事故後(じこご)の対応(たいおう)を間違(まちが)えて、会社(かいしゃ)は信用(しんよう)を失(うしな)った。", "sentence_source": "generated"}, {"text": "状況が変わったら、すぐに別の対応を考えるべきだ。", "target_word": "対応", "complexity_tier": "T3", "furigana": "状況(じょうきょう)が変(か)わったら、すぐに別(べつ)の対応(たいおう)を考(かんが)えるべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対応", "label": "基本形"}, {"form": "対応する", "label": "サ変動詞形"}, {"form": "対応した", "label": "過去形"}, {"form": "対応して", "label": "て形"}], "register": "中立（常体）", "sense_fingerprint": "相手や出来事に合わせて適切に処置・応答すること。客対応・事故対応の意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37253, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対応", "is_correct": true, "explanation": "相手の要望に応じて処置することを表し、クレームへの処置の文に入る。"}, {"text": "予約", "is_correct": false, "explanation": "前もって日時を決めることで、クレームに対する処置の文には合わない。"}, {"text": "出版", "is_correct": false, "explanation": "本などを世に出すことで、クレームへの処置の文には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつけることで、この文脈では成り立たない。"}], "explanations": {"対応": "相手の要望に応じて処置することを表し、クレームへの処置の文に入る。", "予約": "前もって日時を決めることで、クレームに対する処置の文には合わない。", "出版": "本などを世に出すことで、クレームへの処置の文には合わない。", "採点": "答案などに点数をつけることで、この文脈では成り立たない。"}, "sentence_index": 0, "correct_answer": "対応"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "表の番号と説明文の対応が正しい。", "explanation": "ここは〈結びつき〉（二つの物事の対応関係）の意味。相手に応じて処置する〈対応〉とは別の意味。"}, {"text": "二つの表の対応を一つずつ確かめた。", "explanation": "ここは〈結びつき〉（二つの物事の対応関係）の意味。相手に応じて処置する〈対応〉とは別の意味。"}, {"text": "言葉と図の対応が、きれいに一致した。", "explanation": "ここは〈結びつき〉（二つの物事の対応関係）の意味。相手に応じて処置する〈対応〉とは別の意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37253, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対応", "is_correct": true, "explanation": "苦情に応じて処置することを表し、追われる仕事の内容として入る。"}, {"text": "出荷", "is_correct": false, "explanation": "商品を送り出すことで、苦情に追われる文には合わない。"}, {"text": "製造", "is_correct": false, "explanation": "物を作ることで、苦情に追われる文脈では成り立たない。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮ることで、苦情に追われる文には合わない。"}], "explanations": {"対応": "苦情に応じて処置することを表し、追われる仕事の内容として入る。", "出荷": "商品を送り出すことで、苦情に追われる文には合わない。", "製造": "物を作ることで、苦情に追われる文脈では成り立たない。", "撮影": "写真や映像を撮ることで、苦情に追われる文には合わない。"}, "sentence_index": 6, "correct_answer": "対応"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "左の列と右の列の対応を線で結んだ。", "explanation": "ここは〈結びつき〉（二つの物事の対応関係）の意味。相手に応じて処置する〈対応〉とは別の意味。"}, {"text": "地図の色と国名の対応が分からない。", "explanation": "ここは〈結びつき〉（二つの物事の対応関係）の意味。相手に応じて処置する〈対応〉とは別の意味。"}, {"text": "音符と音名の対応表を作った。", "explanation": "ここは〈結びつき〉（二つの物事の対応関係）の意味。相手に応じて処置する〈対応〉とは別の意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37253, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店員の対応を丁寧で、もう一度来た。", "corrected_sentence": "店員の対応が丁寧で、もう一度来た。", "error_description": "誤: 対応を（を）／正: 対応が（が）。「丁寧だ」は状態を表し、主語に「が」を使う。「を」は目的語のため不適。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37253, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客からの苦情を対応するのは、係長の仕事だ。", "corrected_sentence": "客からの苦情に対応するのは、係長の仕事だ。", "error_description": "誤: 苦情を（を）／正: 苦情に（に）。「対応する」は「〜に対応する」の形で、相手や事柄に「に」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37254, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "出どころを示す。地下から冷たい水がわき出てくるという意味で正しい。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す。わき出るは対象をとらないので、地下を置くと文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。地下が冷たい水をわき出すことになり、流れに合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。わき出る動きは外へ出ることなので、「へ」では文が成り立たない。"}], "correct_answer": "から", "explanations": {"から": "出どころを示す。地下から冷たい水がわき出てくるという意味で正しい。", "を": "動作の対象を示す。わき出るは対象をとらないので、地下を置くと文が成り立たない。", "が": "主語を示す。地下が冷たい水をわき出すことになり、流れに合わない。", "へ": "方向を示す。わき出る動きは外へ出ることなので、「へ」では文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37254, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "場所を示す。地下に長いトンネルを掘るという、掘る先の場所を表していて正しい。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。地下から掘るという意味になり、掘る場所を示せない。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す。「地下を」と「トンネルを」が二つ続き、文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並べる相手を示す。地下と長いトンネルを並べる意味になり、掘る場所の説明にならない。"}], "correct_answer": "に", "explanations": {"に": "場所を示す。地下に長いトンネルを掘るという、掘る先の場所を表していて正しい。", "から": "起点を示す。地下から掘るという意味になり、掘る場所を示せない。", "を": "動作の対象を示す。「地下を」と「トンネルを」が二つ続き、文として成り立たない。", "と": "並べる相手を示す。地下と長いトンネルを並べる意味になり、掘る場所の説明にならない。"}, "error_tags": {"から": "起点", "と": "並列", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37254, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面の下にある場所や空間。", "primary_collocate": null, "pronunciation": "ちか", "ipa": "t͡ɕika", "syllable_count": 2, "sentences": [{"text": "地下に水道管が通っているので、工事の前に調べる必要がある。", "target_word": "地下", "complexity_tier": "T3", "furigana": "地下(ちか)に水道管(すいどうかん)が通(とお)っているので、工事(こうじ)の前(まえ)に調(しら)べる必要(ひつよう)がある。", "sentence_source": "generated"}, {"text": "地下から冷たい水がわき出て、小さな池になっていた。", "target_word": "地下", "complexity_tier": "T3", "furigana": "地下(ちか)から冷(つめ)たい水(みず)がわき出(で)て、小(ちい)さな池(いけ)になっていた。", "sentence_source": "generated"}, {"text": "古いお寺の地下から、昔の壺が見つかった。", "target_word": "地下", "complexity_tier": "T3", "furigana": "古(ふる)いお寺(てら)の地下(ちか)から、昔(むかし)の壺(つぼ)が見(み)つかった。", "sentence_source": "generated"}, {"text": "木の根は、地下に広く伸びて水を吸い上げる。", "target_word": "地下", "complexity_tier": "T3", "furigana": "木(き)の根(ね)は、地下(ちか)に広(ひろ)く伸(の)びて水(みず)を吸(す)い上(あ)げる。", "sentence_source": "generated"}, {"text": "工事で地下を深く掘ったら、大きな岩が出てきた。", "target_word": "地下", "complexity_tier": "T3", "furigana": "工事(こうじ)で地下(ちか)を深(ふか)く掘(ほ)ったら、大(おお)きな岩(いわ)が出(で)てきた。", "sentence_source": "generated"}, {"text": "戦争に備えて、庭の地下にシェルターを作った。", "target_word": "地下", "complexity_tier": "T3", "furigana": "戦争(せんそう)に備(そな)えて、庭(にわ)の地下(ちか)にシェルターを作(つく)った。", "sentence_source": "generated"}, {"text": "地震のとき、地下は地上より揺れが小さいと言われる。", "target_word": "地下", "complexity_tier": "T3", "furigana": "地震(じしん)のとき、地下(ちか)は地上(ちじょう)より揺(ゆ)れが小(ちい)さいと言(い)われる。", "sentence_source": "generated"}, {"text": "モグラは地下に長いトンネルを掘って暮らしている。", "target_word": "地下", "complexity_tier": "T3", "furigana": "モグラは地下(ちか)に長(なが)いトンネルを掘(ほ)って暮(く)らしている。", "sentence_source": "generated"}, {"text": "地下の温度は一年中ほとんど変わらない。", "target_word": "地下", "complexity_tier": "T3", "furigana": "地下(ちか)の温度(おんど)は一年中(いちねんじゅう)ほとんど変(か)わらない。", "sentence_source": "generated"}, {"text": "雨水は地面にしみこんで、ゆっくり地下へ流れていく。", "target_word": "地下", "complexity_tier": "T3", "furigana": "雨水(あまみず)は地面(じめん)にしみこんで、ゆっくり地下(ちか)へ流(なが)れていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地下", "label": "基本形"}, {"form": "地下の", "label": "連体形（の）"}, {"form": "地下に", "label": "位置（に）"}, {"form": "地下へ", "label": "方向（へ）"}], "register": "中立（常体）", "sense_fingerprint": "地面の下という場所・空間そのもの。地上の反対", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 木の根 (Zipf 2.45)','sentence 9 above tier T2: contains vocabulary far above tier T2: しみこん (Zipf 1.79)']::text[], 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37254, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地下", "is_correct": true, "explanation": "地面の下の場所を指す。水道管は地下に通っていて、工事の前に調べる必要があるという文脈に合う。"}, {"text": "夜空", "is_correct": false, "explanation": "空の一部を指すので、水道管が通る場所としては成り立たない。"}, {"text": "雲", "is_correct": false, "explanation": "空に浮かぶものなので、水道管が通る場所にはならない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空に現れる現象で、水道管の通る場所を表せない。"}], "explanations": {"地下": "地面の下の場所を指す。水道管は地下に通っていて、工事の前に調べる必要があるという文脈に合う。", "夜空": "空の一部を指すので、水道管が通る場所としては成り立たない。", "雲": "空に浮かぶものなので、水道管が通る場所にはならない。", "夕焼け": "空に現れる現象で、水道管の通る場所を表せない。"}, "sentence_index": 0, "correct_answer": "地下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、地下に乗って会社へ行く。", "explanation": "ここは〈地下鉄〉の意味。地下は場所を指すので、乗り物としての電車は表せず、「乗る」と合わない。"}, {"text": "雪が降って、地下が白くなった。", "explanation": "ここは〈地表〉の意味。雪で白くなるのは地面の表面（地表）で、地下の空間は雪に覆われないので合わない。"}, {"text": "子どもたちは地下にチョークで絵を描いて遊んだ。", "explanation": "ここは〈地面〉の意味。地下は地面の下の空間で、表面に絵を描くことはできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37254, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地下", "is_correct": true, "explanation": "地面の下の場所を指す。地上より揺れが小さいと言われる場所として自然。"}, {"text": "地震", "is_correct": false, "explanation": "揺れの原因で場所ではない。「地震は地上より揺れが小さい」とは言えない。"}, {"text": "津波", "is_correct": false, "explanation": "海から来る水の現象で、場所を主語にする文には合わない。"}, {"text": "雷", "is_correct": false, "explanation": "空で起こる現象で、地上と比べる揺れの話には合わない。"}], "explanations": {"地下": "地面の下の場所を指す。地上より揺れが小さいと言われる場所として自然。", "地震": "揺れの原因で場所ではない。「地震は地上より揺れが小さい」とは言えない。", "津波": "海から来る水の現象で、場所を主語にする文には合わない。", "雷": "空で起こる現象で、地上と比べる揺れの話には合わない。"}, "sentence_index": 6, "correct_answer": "地下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕日が沈むころ、地下の空がオレンジ色に染まった。", "explanation": "ここは〈空〉の意味。地下は地面の下の場所なので、夕焼けに染まる空を指せない。"}, {"text": "夏休みは、地下の砂浜で貝殻を拾って遊んだ。", "explanation": "ここは〈海辺〉の意味。地下には砂浜がなく、貝殻を拾える場所としては合わない。"}, {"text": "台風の夜、地下の屋根が吹き飛ばされて、強風が入り込んだ。", "explanation": "ここは〈屋根〉の意味。屋根は地上の建物に付くもので、地面の下の空間には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37254, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨のあと、地下にから水が流れ出して、道路が冠水した。", "corrected_sentence": "大雨のあと、地下から水が流れ出して、道路が冠水した。", "error_description": "「に」と「から」が重なっていて不正。出どころは「から」だけで示す。正しくは「地下から」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37254, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地下に貯蔵庫で、ワインを寝かせている。", "corrected_sentence": "地下の貯蔵庫で、ワインを寝かせている。", "error_description": "正しくは「地下の貯蔵庫」で、「の」が「地下」と「貯蔵庫」をつなぐ。「に」は場所を示す助詞なので、名詞の前に置くと文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37255, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在する場所を示す。地下に駐車場があるという意味で正しい。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す。ある（存在）は対象をとらないので、地下を置くと文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "移動の方向を示す。存在を表す「ある」とは結びつかず不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体を示す。「地下の」は名詞に続く形で、「は」が続くと文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "存在する場所を示す。地下に駐車場があるという意味で正しい。", "を": "動作の対象を示す。ある（存在）は対象をとらないので、地下を置くと文が成り立たない。", "へ": "移動の方向を示す。存在を表す「ある」とは結びつかず不自然。", "の": "連体を示す。「地下の」は名詞に続く形で、「は」が続くと文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37255, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「地下」と「広い通り」をつなぐ。「地下の広い通り」という名詞の修飾で正しい。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す。「地下を」と「広い通りには」が続き、並ぶ場所の説明として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "場所を示す。「地下に広い」は形容詞に「に」が続き、文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。地下から通りが並ぶという意味になり、場所の説明として不自然。"}], "correct_answer": "の", "explanations": {"の": "「地下」と「広い通り」をつなぐ。「地下の広い通り」という名詞の修飾で正しい。", "を": "動作の対象を示す。「地下を」と「広い通りには」が続き、並ぶ場所の説明として成り立たない。", "に": "場所を示す。「地下に広い」は形容詞に「に」が続き、文として成り立たない。", "から": "起点を示す。地下から通りが並ぶという意味になり、場所の説明として不自然。"}, "error_tags": {"から": "起点", "を": "目的語", "に": "場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37255, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地表よりも下にある空間や構造物。特に、地下鉄などの地下を利用した施設を指すことが多い。", "primary_collocate": null, "pronunciation": "ちか", "ipa": "t͡ɕika", "syllable_count": 2, "sentences": [{"text": "雨の日は、地下を通れば濡れずに駅まで行ける。", "target_word": "地下", "complexity_tier": "T3", "furigana": "雨(あめ)の日(ひ)は、地下(ちか)を通(とお)れば濡(ぬ)れずに駅(えき)まで行(い)ける。", "sentence_source": "generated"}, {"text": "このビルの地下には、大きな駐車場がある。", "target_word": "地下", "complexity_tier": "T3", "furigana": "このビルの地下(ちか)には、大(おお)きな駐車場(ちゅうしゃじょう)がある。", "sentence_source": "generated"}, {"text": "デパートの地下で、夕食のお弁当を買った。", "target_word": "地下", "complexity_tier": "T3", "furigana": "デパートの地下(ちか)で、夕食(ゆうしょく)のお弁当(べんとう)を買(か)った。", "sentence_source": "generated"}, {"text": "地下のホームへ続く階段は、朝は人でいっぱいだ。", "target_word": "地下", "complexity_tier": "T3", "furigana": "地下(ちか)のホームへ続(つづ)く階段(かいだん)は、朝(あさ)は人(ひと)でいっぱいだ。", "sentence_source": "generated"}, {"text": "新しい路線は、都心ではほとんどの区間が地下を走る。", "target_word": "地下", "complexity_tier": "T3", "furigana": "新(あたら)しい路線(ろせん)は、都心(としん)ではほとんどの区間(くかん)が地下(ちか)を走(はし)る。", "sentence_source": "generated"}, {"text": "二つの駅は地下の通路でつながっている。", "target_word": "地下", "complexity_tier": "T3", "furigana": "二(ふた)つの駅(えき)は地下(ちか)の通路(つうろ)でつながっている。", "sentence_source": "generated"}, {"text": "地下の改札で、友達と待ち合わせた。", "target_word": "地下", "complexity_tier": "T3", "furigana": "地下(ちか)の改札(かいさつ)で、友達(ともだち)と待(ま)ち合(あ)わせた。", "sentence_source": "generated"}, {"text": "地下の広い通りには、喫茶店や本屋が並んでいる。", "target_word": "地下", "complexity_tier": "T3", "furigana": "地下(ちか)の広(ひろ)い通(とお)りには、喫茶店(きっさてん)や本屋(ほんや)が並(なら)んでいる。", "sentence_source": "generated"}, {"text": "工事のため、地下の入り口は今日だけ閉まっている。", "target_word": "地下", "complexity_tier": "T3", "furigana": "工事(こうじ)のため、地下(ちか)の入(い)り口(ぐち)は今日(きょう)だけ閉(し)まっている。", "sentence_source": "generated"}, {"text": "荷物が多かったので、地下のエレベーターで地上に上がった。", "target_word": "地下", "complexity_tier": "T3", "furigana": "荷物(にもつ)が多(おお)かったので、地下(ちか)のエレベーターで地上(ちじょう)に上(あ)がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地下", "label": "基本形"}, {"form": "地下の", "label": "連体形（の）"}, {"form": "地下に", "label": "位置（に）"}, {"form": "地下を", "label": "経路（を）"}], "register": "中立（常体）", "sense_fingerprint": "地下鉄・地下通路・地下駐車場など、地面の下に作られた施設や構造物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37255, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地下", "is_correct": true, "explanation": "建物の下に作られた通路を指す。雨に濡れずに駅へ行けるという続く文に合う。"}, {"text": "空", "is_correct": false, "explanation": "空は通り抜ける場所ではないので、通ればという文に合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "上にかぶせるもので、通る場所にはならない。"}, {"text": "地上", "is_correct": false, "explanation": "外の地面を指し、雨に濡れてしまうので、濡れずに行けるという文と逆になる。"}], "explanations": {"地下": "建物の下に作られた通路を指す。雨に濡れずに駅へ行けるという続く文に合う。", "空": "空は通り抜ける場所ではないので、通ればという文に合わない。", "屋根": "上にかぶせるもので、通る場所にはならない。", "地上": "外の地面を指し、雨に濡れてしまうので、濡れずに行けるという文と逆になる。"}, "sentence_index": 0, "correct_answer": "地下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもたちは地下にチョークで絵を描いて遊んだ。", "explanation": "ここは〈地面〉の意味。地下は地面の下の空間で、表面に絵を描くことはできないので合わない。"}, {"text": "地下の屋上で、子どもたちが花火を見上げた。", "explanation": "ここは〈屋上〉の意味。屋上は建物の一番上を指し、地下とは両立しないので合わない。"}, {"text": "地下の港に、大型の船が着いた。", "explanation": "ここは〈港〉の意味。港は海や川に面した場所で、地下の施設には船が着けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37255, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地下", "is_correct": true, "explanation": "地下にある改札の意味。地下の改札で待ち合わせるという文に合う。"}, {"text": "会議室", "is_correct": false, "explanation": "会議をする部屋で、改札はない。"}, {"text": "海辺", "is_correct": false, "explanation": "海のそばの場所で、改札とは結びつかない。"}, {"text": "体育館", "is_correct": false, "explanation": "運動をする建物で、改札とは合わない。"}], "explanations": {"地下": "地下にある改札の意味。地下の改札で待ち合わせるという文に合う。", "会議室": "会議をする部屋で、改札はない。", "海辺": "海のそばの場所で、改札とは結びつかない。", "体育館": "運動をする建物で、改札とは合わない。"}, "sentence_index": 6, "correct_answer": "地下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪が降って、地下が白くなった。", "explanation": "ここは〈地表〉の意味。雪で白くなるのは地面の表面（地表）で、地下の施設は雪に覆われないので合わない。"}, {"text": "夕日が沈むころ、地下が赤く染まって、街全体がきれいに見えた。", "explanation": "ここは〈空〉の意味で、夕焼けが広がる場所を指す。地下は地面の下の施設なので、夕焼けの空として使えない。"}, {"text": "夏休みに地下へ行って、砂浜で貝殻を拾った。", "explanation": "ここは〈海辺〉の意味。地下の施設には砂浜がないので、貝殻を拾う場所として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37255, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このビルの地下が、大きな駐車場が造られた。", "corrected_sentence": "このビルの地下に、大きな駐車場が造られた。", "error_description": "正しくは「地下に」（場所を示す「に」）。「が」は主語を示すので、場所の「地下」が主語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37255, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地下を売店で、新聞と飲み物を買った。", "corrected_sentence": "地下の売店で、新聞と飲み物を買った。", "error_description": "正しくは「地下の売店」で、「の」が「地下」と「売店」をつなぐ。「を」は動作の対象を示すので、名詞の「売店」に続けると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37256, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "「町まで」で到達点を示し、そこに受身の「延長される」がつながる。ここに入る正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「町を延長される」となり、受身の文で目的語が重なって成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「町の延長される」は名詞修飾の形になり、動詞「延長される」の前に置けない。"}, {"text": "と", "is_correct": false, "explanation": "「町と延長される」は相手や並列を示す形で、受身の動作の行き先を表せない。"}], "correct_answer": "まで", "explanations": {"まで": "「町まで」で到達点を示し、そこに受身の「延長される」がつながる。ここに入る正しい助詞。", "を": "「町を延長される」となり、受身の文で目的語が重なって成り立たない。", "の": "「町の延長される」は名詞修飾の形になり、動詞「延長される」の前に置けない。", "と": "「町と延長される」は相手や並列を示す形で、受身の動作の行き先を表せない。"}, "error_tags": {"を": "対象の重複", "の": "名詞修飾", "と": "相手・並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短縮", "is_correct": true, "explanation": "〈延長〉の対義語。長さを縮める意味で、道を延ばす〈延長〉と反対の関係にある。"}, {"text": "中断", "is_correct": false, "explanation": "途中でやめることで、長さを変える意味の対義語にはならない。"}, {"text": "開始", "is_correct": false, "explanation": "始めることで、長さの増減とは対義関係にない。"}, {"text": "撤去", "is_correct": false, "explanation": "取り除くことで、長くする意味の反対とは言えない。"}], "correct_answer": "短縮", "explanations": {"短縮": "〈延長〉の対義語。長さを縮める意味で、道を延ばす〈延長〉と反対の関係にある。", "中断": "途中でやめることで、長さを変える意味の対義語にはならない。", "開始": "始めることで、長さの増減とは対義関係にない。", "撤去": "取り除くことで、長くする意味の反対とは言えない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37256, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「橋の延長」で、「橋」と「延長」を結ぶ所有・修飾の「の」。ここに入る正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「が」を二つ続けることになり、「橋」と「延長」をつなげられない。"}, {"text": "を", "is_correct": false, "explanation": "「橋を延長」の形になり、後ろの「決まり」の主語として文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「橋へ延長」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「橋の延長」で、「橋」と「延長」を結ぶ所有・修飾の「の」。ここに入る正しい助詞。", "が": "「が」を二つ続けることになり、「橋」と「延長」をつなげられない。", "を": "「橋を延長」の形になり、後ろの「決まり」の主語として文が成り立たない。", "へ": "「へ」は方向を示すので、「橋へ延長」は成り立たない。"}, "error_tags": {"が": "主格の重複", "を": "目的語の誤用", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短縮", "is_correct": true, "explanation": "〈延長〉の対義語。長さを縮める意味で、路線を延ばす〈延長〉と反対の関係。"}, {"text": "完成", "is_correct": false, "explanation": "仕上がることで、長さを変える意味の対義語にはならない。"}, {"text": "設置", "is_correct": false, "explanation": "備え付けることで、長さの増減とは対義関係にない。"}, {"text": "廃棄", "is_correct": false, "explanation": "捨てることで、長くする意味の反対とは言えない。"}], "correct_answer": "短縮", "explanations": {"短縮": "〈延長〉の対義語。長さを縮める意味で、路線を延ばす〈延長〉と反対の関係。", "完成": "仕上がることで、長さを変える意味の対義語にはならない。", "設置": "備え付けることで、長さの増減とは対義関係にない。", "廃棄": "捨てることで、長くする意味の反対とは言えない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37256, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを長くすること。", "primary_collocate": null, "pronunciation": "えんちょう", "ipa": "eɲtɕoː", "syllable_count": 4, "sentences": [{"text": "電話のコードを延長して、ベッドまで届くようにした。", "target_word": "延長して", "complexity_tier": "T3", "furigana": "電話[でんわ]のコードを延長[えんちょう]して、ベッドまで届[とど]くようにした。", "sentence_source": "generated"}, {"text": "この線路は、隣の町まで延長される予定だ。", "target_word": "延長される", "complexity_tier": "T3", "furigana": "この線路[せんろ]は、隣[となり]の町[まち]まで延長[えんちょう]される予定[よてい]だ。", "sentence_source": "generated"}, {"text": "地下鉄の延長工事が始まり、駅の前が工事中だ。", "target_word": "延長", "complexity_tier": "T3", "furigana": "地下鉄[ちかてつ]の延長工事[えんちょうこうじ]が始[はじ]まり、駅[えき]の前[まえ]が工事中[こうじちゅう]だ。", "sentence_source": "generated"}, {"text": "道が短かったので、公園の入口まで延長した。", "target_word": "延長した", "complexity_tier": "T3", "furigana": "道[みち]が短[みじか]かったので、公園[こうえん]の入口[いりぐち]まで延長[えんちょう]した。", "sentence_source": "generated"}, {"text": "ホースを延長すれば、庭のすみまで水が届く。", "target_word": "延長すれば", "complexity_tier": "T3", "furigana": "ホースを延長[えんちょう]すれば、庭[にわ]のすみまで水[みず]が届[とど]く。", "sentence_source": "generated"}, {"text": "川に沿って、散歩道を二キロ延長した。", "target_word": "延長した", "complexity_tier": "T3", "furigana": "川[かわ]に沿[そ]って、散歩道[さんぽみち]を二[に]キロ延長[えんちょう]した。", "sentence_source": "generated"}, {"text": "この電線は、家の裏まで延長してある。", "target_word": "延長して", "complexity_tier": "T3", "furigana": "この電線[でんせん]は、家[いえ]の裏[うら]まで延長[えんちょう]してある。", "sentence_source": "generated"}, {"text": "橋の延長が決まり、町の人たちは喜んだ。", "target_word": "延長", "complexity_tier": "T3", "furigana": "橋[はし]の延長[えんちょう]が決[き]まり、町[まち]の人[ひと]たちは喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "滑走路を延長すれば、大きな飛行機も着陸できる。", "target_word": "延長すれば", "complexity_tier": "T3", "furigana": "滑走路[かっそうろ]を延長[えんちょう]すれば、大[おお]きな飛行機[ひこうき]も着陸[ちゃくりく]できる。", "sentence_source": "generated"}, {"text": "バスの路線は、駅の北口まで延長された。", "target_word": "延長された", "complexity_tier": "T3", "furigana": "バスの路線[ろせん]は、駅[えき]の北口[きたぐち]まで延長[えんちょう]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "延長する", "label": "サ変動詞"}, {"form": "延長した", "label": "過去形"}, {"form": "延長して", "label": "て形"}, {"form": "延長される", "label": "受身形"}], "register": "標準・常体", "sense_fingerprint": "道・線路・コードなど物の長さをのばして長くする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37256, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "延長して", "is_correct": true, "explanation": "て形で、後ろの「届くようにした」と一文につながる。ここに入る正しい形。"}, {"text": "延長する", "is_correct": false, "explanation": "辞書形は文を終える形で、「、」の前に置くと文が成り立たない。"}, {"text": "延長される", "is_correct": false, "explanation": "受身形だと「コードを」と合わず、「コードが延長される」になってしまうので入らない。"}, {"text": "延長しよう", "is_correct": false, "explanation": "意志形は「〜しよう」で文を終える形なので、後ろに続けられず不自然。"}], "explanations": {"延長して": "て形で、後ろの「届くようにした」と一文につながる。ここに入る正しい形。", "延長する": "辞書形は文を終える形で、「、」の前に置くと文が成り立たない。", "延長される": "受身形だと「コードを」と合わず、「コードが延長される」になってしまうので入らない。", "延長しよう": "意志形は「〜しよう」で文を終える形なので、後ろに続けられず不自然。"}, "sentence_index": 0, "correct_answer": "延長して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋を延長して、幅を広くした。", "explanation": "ここは〈拡張〉の意味。〈延長〉は長さを伸ばすことで、幅を広げるなら〈拡張〉を使う。"}, {"text": "子どもの背が延長した。", "explanation": "ここは〈伸長〉の意味。背が伸びることを〈延長〉とは言わず、〈伸長〉や「伸びる」を使う。"}, {"text": "火事が隣の家まで延長した。", "explanation": "ここは〈延焼〉の意味。火が燃え広がることは〈延長〉では言わず、〈延焼〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37256, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延長して", "is_correct": true, "explanation": "て形に「ある」が続き、状態を表す文が成り立つ。ここに入る正しい形。"}, {"text": "延長した", "is_correct": false, "explanation": "た形は「ある」に直接つながらず、「延長したある」は不自然で成り立たない。"}, {"text": "延長しない", "is_correct": false, "explanation": "否定形は「ある」につながらず、「延長しないある」は文として不自然。"}, {"text": "延長させ", "is_correct": false, "explanation": "使役の連用形は「ある」に続かず、「延長させある」は成り立たない。"}], "explanations": {"延長して": "て形に「ある」が続き、状態を表す文が成り立つ。ここに入る正しい形。", "延長した": "た形は「ある」に直接つながらず、「延長したある」は不自然で成り立たない。", "延長しない": "否定形は「ある」につながらず、「延長しないある」は文として不自然。", "延長させ": "使役の連用形は「ある」に続かず、「延長させある」は成り立たない。"}, "sentence_index": 6, "correct_answer": "延長して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場の規模を延長した。", "explanation": "ここは〈拡大〉の意味。〈延長〉は長さを伸ばす語で、規模を大きくする場合は〈拡大〉を使う。"}, {"text": "部屋いっぱいに香りが延長した。", "explanation": "ここは〈拡散〉の意味。香りなどが広がることは〈延長〉では言わず、〈拡散〉を使う。"}, {"text": "細菌が延長した。", "explanation": "ここは〈増殖〉の意味。数が増えることは〈延長〉ではなく〈増殖〉を使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37256, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭のホースを延長で、物置まで水を届けた。", "corrected_sentence": "庭のホースを延長して、物置まで水を届けた。", "error_description": "誤りは「延長して」の「して」が「で」になっている点。正しくは「延長して」（て形）で、後ろの「届けた」につながる。「延長で」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37256, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "バスの路線が延長されで、駅が一つ増えた。", "corrected_sentence": "バスの路線が延長されて、駅が一つ増えた。", "error_description": "誤りは「延長されて」の「て」が「で」になっている点。正しくは「延長されて」（て形）で、後ろの「駅が一つ増えた」につながる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37257, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「期間を延長する」の目的語を示す「を」で、「延長できる」の対象になる。ここに入る正しい助詞。"}, {"text": "の", "is_correct": false, "explanation": "「期間の延長」の形は名詞修飾になり、「延長できる」の目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、「期間と延長できる」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「期間へ延長」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「期間を延長する」の目的語を示す「を」で、「延長できる」の対象になる。ここに入る正しい助詞。", "の": "「期間の延長」の形は名詞修飾になり、「延長できる」の目的語にならない。", "と": "「と」は相手や並列を示すので、「期間と延長できる」は意味が通らない。", "へ": "「へ」は方向を示すので、「期間へ延長」は成り立たない。"}, "error_tags": {"の": "名詞修飾", "と": "相手・並列", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短縮", "is_correct": true, "explanation": "〈延長〉の対義語。期間を縮める意味で、期間を延ばす〈延長〉と反対の関係。"}, {"text": "完了", "is_correct": false, "explanation": "終わることで、期間を長くする意味の対義語にはならない。"}, {"text": "撤去", "is_correct": false, "explanation": "取り除くことで、期間を長くする意味の反対とは言えない。"}, {"text": "設置", "is_correct": false, "explanation": "備え付けることで、期間の増減とは対義関係にない。"}], "correct_answer": "短縮", "explanations": {"短縮": "〈延長〉の対義語。期間を縮める意味で、期間を延ばす〈延長〉と反対の関係。", "完了": "終わることで、期間を長くする意味の対義語にはならない。", "撤去": "取り除くことで、期間を長くする意味の反対とは言えない。", "設置": "備え付けることで、期間の増減とは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37257, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「期間が延長される」の主語を示す「が」で、受身の文として成り立つ。ここに入る正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "受身の「延長される」は「期間を」と合わず、目的語が重なって成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「期間の延長」は名詞の形で、「延長されて」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、「期間と延長されて」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「期間が延長される」の主語を示す「が」で、受身の文として成り立つ。ここに入る正しい助詞。", "を": "受身の「延長される」は「期間を」と合わず、目的語が重なって成り立たない。", "の": "「期間の延長」は名詞の形で、「延長されて」の主語にはならない。", "と": "「と」は相手や並列を示すので、「期間と延長されて」は意味が通らない。"}, "error_tags": {"を": "受身と目的語の衝突", "の": "名詞修飾", "と": "相手・並列"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短縮", "is_correct": true, "explanation": "〈延長〉の対義語。期限を縮める意味で、期限を延ばす〈延長〉と反対の関係。"}, {"text": "中断", "is_correct": false, "explanation": "途中でやめることで、期限を延ばす・縮める関係にはならない。"}, {"text": "開始", "is_correct": false, "explanation": "始めることで、期限の長さの変化と対義関係にない。"}, {"text": "廃棄", "is_correct": false, "explanation": "捨てることで、期限を長くする意味の反対とは言えない。"}], "correct_answer": "短縮", "explanations": {"短縮": "〈延長〉の対義語。期限を縮める意味で、期限を延ばす〈延長〉と反対の関係。", "中断": "途中でやめることで、期限を延ばす・縮める関係にはならない。", "開始": "始めることで、期限の長さの変化と対義関係にない。", "廃棄": "捨てることで、期限を長くする意味の反対とは言えない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37257, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるものの長さや期間を、もとの状態よりも長くすること。", "primary_collocate": null, "pronunciation": "えんちょう", "ipa": "eɲtɕoː", "syllable_count": 4, "sentences": [{"text": "工事が遅れたため、完成までの期間が延長された。", "target_word": "延長", "complexity_tier": "T3", "furigana": "工事[こうじ]が遅[おく]れたため、完成[かんせい]までの期間[きかん]が延長[えんちょう]された。", "sentence_source": "generated"}, {"text": "図書館の本は、電話で貸出期間を延長できる。", "target_word": "延長できる", "complexity_tier": "T3", "furigana": "図書館[としょかん]の本[ほん]は、電話[でんわ]で貸出期間[かしだしきかん]を延長[えんちょう]できる。", "sentence_source": "generated"}, {"text": "人気の展示会は、会期を一週間延長することにした。", "target_word": "延長", "complexity_tier": "T3", "furigana": "人気[にんき]の展示会[てんじかい]は、会期[かいき]を一週間[いっしゅうかん]延長[えんちょう]することにした。", "sentence_source": "generated"}, {"text": "会議が長引いて、終了時間を三十分延長した。", "target_word": "延長した", "complexity_tier": "T3", "furigana": "会議[かいぎ]が長引[ながび]いて、終了時間[しゅうりょうじかん]を三十分[さんじゅっぷん]延長[えんちょう]した。", "sentence_source": "generated"}, {"text": "ビザの期限を延長するために、役所へ行った。", "target_word": "延長する", "complexity_tier": "T3", "furigana": "ビザの期限[きげん]を延長[えんちょう]するために、役所[やくしょ]へ行[い]った。", "sentence_source": "generated"}, {"text": "店は人気が高く、営業時間を夜十時まで延長している。", "target_word": "延長している", "complexity_tier": "T3", "furigana": "店[みせ]は人気[にんき]が高[たか]く、営業時間[えいぎょうじかん]を夜[よる]十時[じゅうじ]まで延長[えんちょう]している。", "sentence_source": "generated"}, {"text": "契約を一年延長するかどうか、社長が決める。", "target_word": "延長する", "complexity_tier": "T3", "furigana": "契約[けいやく]を一年[いちねん]延長[えんちょう]するかどうか、社長[しゃちょう]が決[き]める。", "sentence_source": "generated"}, {"text": "セールの期間が延長されて、買い物客が増えた。", "target_word": "延長されて", "complexity_tier": "T3", "furigana": "セールの期間[きかん]が延長[えんちょう]されて、買[か]い物客[ものきゃく]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "授業が延長されると、部活に遅れてしまう。", "target_word": "延長される", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が延長[えんちょう]されると、部活[ぶかつ]に遅[おく]れてしまう。", "sentence_source": "generated"}, {"text": "提出の期限が延長されたので、ゆっくり書ける。", "target_word": "延長された", "complexity_tier": "T3", "furigana": "提出[ていしゅつ]の期限[きげん]が延長[えんちょう]されたので、ゆっくり書[か]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "延長する", "label": "サ変動詞"}, {"form": "延長した", "label": "過去形"}, {"form": "延長して", "label": "て形"}, {"form": "延長される", "label": "受身形"}], "register": "標準・常体", "sense_fingerprint": "期限・時間・期間を予定より長くのばす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37257, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "延長", "is_correct": true, "explanation": "名詞の「延長」に「された」が続き、受身の文として成り立つ。ここに入る正しい形。"}, {"text": "延長する", "is_correct": false, "explanation": "辞書形に「された」は続かず、「延長するされた」は成り立たない。"}, {"text": "延長して", "is_correct": false, "explanation": "て形に「された」は続かず、「延長してされた」は不自然。"}, {"text": "延長でき", "is_correct": false, "explanation": "可能形の連用形は「された」につながらず、文が成り立たない。"}], "explanations": {"延長": "名詞の「延長」に「された」が続き、受身の文として成り立つ。ここに入る正しい形。", "延長する": "辞書形に「された」は続かず、「延長するされた」は成り立たない。", "延長して": "て形に「された」は続かず、「延長してされた」は不自然。", "延長でき": "可能形の連用形は「された」につながらず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "延長"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風で、出発を一時間延長した。", "explanation": "ここは〈延期〉の意味。予定の日時を後ろにずらすなら〈延期〉を使い、〈延長〉は期間を長くする語。"}, {"text": "火の手が隣の建物まで延長した。", "explanation": "ここは〈延焼〉の意味。火が燃え広がることは〈延長〉では言わず、〈延焼〉を使う。"}, {"text": "語学力が延長した。", "explanation": "ここは〈伸長〉の意味。能力が伸びることは〈伸長〉で言い、〈延長〉は期間や長さに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37257, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延長する", "is_correct": true, "explanation": "辞書形に「かどうか」が続き、決める内容を表す文が成り立つ。ここに入る正しい形。"}, {"text": "延長して", "is_correct": false, "explanation": "て形に「かどうか」は続かず、「延長してかどうか」は成り立たない。"}, {"text": "延長させ", "is_correct": false, "explanation": "使役の連用形は「かどうか」につながらず、文が成り立たない。"}, {"text": "延長され", "is_correct": false, "explanation": "受身の連用形は「かどうか」につながらず、「延長されかどうか」は不自然。"}], "explanations": {"延長する": "辞書形に「かどうか」が続き、決める内容を表す文が成り立つ。ここに入る正しい形。", "延長して": "て形に「かどうか」は続かず、「延長してかどうか」は成り立たない。", "延長させ": "使役の連用形は「かどうか」につながらず、文が成り立たない。", "延長され": "受身の連用形は「かどうか」につながらず、「延長されかどうか」は不自然。"}, "sentence_index": 6, "correct_answer": "延長する"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "町の人口が延長した。", "explanation": "ここは〈増加〉の意味。数が増えることは〈増加〉を使い、〈延長〉は期間や長さに使う。"}, {"text": "物価が延長した。", "explanation": "ここは〈上昇〉の意味。数値が上がることは〈上昇〉で言い、〈延長〉では言わない。"}, {"text": "技術が延長した。", "explanation": "ここは〈普及〉の意味。広く行き渡ることは〈普及〉で言い、〈延長〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37257, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "レンタルの期間を延長すため、店に相談した。", "corrected_sentence": "レンタルの期間を延長するため、店に相談した。", "error_description": "誤りは「延長する」の「する」が「す」になっている点。正しくは「延長するため」（辞書形＋ため）で、理由を表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37257, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試合が延長されたで、帰りが遅くなった。", "corrected_sentence": "試合が延長されたので、帰りが遅くなった。", "error_description": "誤りは「延長された」の後の「ので」が「で」になっている点。正しくは「ので」（理由）で、後ろの文につながる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
