INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37258, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "バスが専用の道を走って、たくさんの人を早く運ぶしくみのことです。", "primary_collocate": null, "pronunciation": "びーあーるてぃー", "ipa": "biːaːɾɯtiː", "syllable_count": 7, "sentences": [{"text": "BRT は、バスが専用の道を走るので、道がこんでいても早く着きます。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "BRT は、バスが専用(せんよう)の道(みち)を走(はし)るので、道(みち)がこんでいても早(はや)く着(つ)きます。", "sentence_source": "generated"}, {"text": "わたしの町の BRT は、朝、たくさんの人がのっています。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "わたしの町(まち)の BRT は、朝(あさ)、たくさんの人(ひと)がのっています。", "sentence_source": "generated"}, {"text": "BRT のバスは、大きくて、ドアがいくつもあります。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "BRT のバスは、大(おお)きくて、ドアがいくつもあります。", "sentence_source": "generated"}, {"text": "おじいちゃんは、BRT に乗って病院へ行きます。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "おじいちゃんは、BRT に乗(の)って病院(びょういん)へ行(い)きます。", "sentence_source": "generated"}, {"text": "BRT は、ふつうのバスより、早く着くことが多いです。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "BRT は、ふつうのバスより、早(はや)く着(つ)くことが多(おお)いです。", "sentence_source": "generated"}, {"text": "車が多い道でも、BRT は止まらずに進めます。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "車(くるま)が多(おお)い道(みち)でも、BRT は止(と)まらずに進(すす)めます。", "sentence_source": "generated"}, {"text": "BRT には、一度にたくさんの人がのれる長いバスもあります。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "BRT には、一度(いちど)にたくさんの人(ひと)がのれる長(なが)いバスもあります。", "sentence_source": "generated"}, {"text": "学校が終わったあと、BRT で友だちの家に行きました。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "学校(がっこう)が終(お)わったあと、BRT で友(とも)だちの家(いえ)に行(い)きました。", "sentence_source": "generated"}, {"text": "BRT の専用の道には、ふつうの車は入れません。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "BRT の専用(せんよう)の道(みち)には、ふつうの車(くるま)は入(はい)れません。", "sentence_source": "generated"}, {"text": "雨の日でも、BRT の乗り場には屋根があるので、ぬれません。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "雨(あめ)の日(ひ)でも、BRT の乗(の)り場(ば)には屋根(やね)があるので、ぬれません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "BRT", "label": "基本形"}, {"form": "BRTの", "label": "連体形（の）"}, {"form": "BRTで", "label": "手段（で）"}], "register": "やさしい丁寧体（です・ます）", "sense_fingerprint": "専用の道を走り、たくさんの人を早く運ぶバスの仕組み（子ども向けの説明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37258, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "BRT", "is_correct": true, "explanation": "バスが専用の道を走る仕組みの名前。主語にぴったりで、続く文の説明と合う。"}, {"text": "飛行機", "is_correct": false, "explanation": "空を飛ぶ乗り物で、専用の道を走るバスの話の主語にはならない。"}, {"text": "船", "is_correct": false, "explanation": "水の上を進む乗り物で、道を走るバスの話には合わない。"}, {"text": "自転車", "is_correct": false, "explanation": "人がこぐ乗り物で、バスが専用の道を走るという文の主語としては合わない。"}], "explanations": {"BRT": "バスが専用の道を走る仕組みの名前。主語にぴったりで、続く文の説明と合う。", "飛行機": "空を飛ぶ乗り物で、専用の道を走るバスの話の主語にはならない。", "船": "水の上を進む乗り物で、道を走るバスの話には合わない。", "自転車": "人がこぐ乗り物で、バスが専用の道を走るという文の主語としては合わない。"}, "sentence_index": 0, "correct_answer": "BRT"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "BRT は、川を通って海へ行きます。", "explanation": "ここは〈船〉の意味。BRT は道路を走るバスなので、川や海は通りません。"}, {"text": "BRT は、空を飛んで遠くの町へ行きます。", "explanation": "ここは〈飛行機〉の意味。BRT は地面の道を走るので、空は飛べません。"}, {"text": "BRT は、線路の上を走って町と町をつなぎます。", "explanation": "ここは〈電車〉の意味。BRT は線路ではなく、専用の道を走るバスの仕組みです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37258, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "BRT", "is_correct": true, "explanation": "バスの仕組みの名前。長いバスもあると続けるのに合う。"}, {"text": "ヘリコプター", "is_correct": false, "explanation": "空を飛ぶ乗り物で、長いバスの話の主語にはならない。"}, {"text": "ロケット", "is_correct": false, "explanation": "宇宙へ行く乗り物で、バスの話には合わない。"}, {"text": "新幹線", "is_correct": false, "explanation": "列車で、バスの話には合わない。"}], "explanations": {"BRT": "バスの仕組みの名前。長いバスもあると続けるのに合う。", "ヘリコプター": "空を飛ぶ乗り物で、長いバスの話の主語にはならない。", "ロケット": "宇宙へ行く乗り物で、バスの話には合わない。", "新幹線": "列車で、バスの話には合わない。"}, "sentence_index": 6, "correct_answer": "BRT"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "BRT は、人が引いて町の中を回ります。", "explanation": "ここは〈人力車〉の意味。BRT は人が引く乗り物ではなく、道を走るバスです。"}, {"text": "BRT は、宇宙へ飛び立ちます。", "explanation": "ここは〈ロケット〉の意味。BRT は地上の専用の道を走るので、宇宙へは行きません。"}, {"text": "BRT は、坂道をワイヤーで引っぱって登ります。", "explanation": "ここは〈ケーブルカー〉の意味。BRT はワイヤーで引く仕組みではなく、バスが道を走ります。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37258, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "BRT を乗るときは、乗り場で切符を買います。", "corrected_sentence": "BRT に乗るときは、乗り場で切符を買います。", "error_description": "正しくは「BRT に乗る」。乗り物に乗るときは「に」を使い、「を」は動作の対象を示すので「乗る」と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37258, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "BRT を運転手さんは、いつもやさしく声をかけてくれます。", "corrected_sentence": "BRT の運転手さんは、いつもやさしく声をかけてくれます。", "error_description": "正しくは「BRT の運転手さん」。「の」で所属を示す。「を」は動作の対象を示すが、この文には対象をとる動詞がないので、「BRT を運転手さんは」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
