INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37259, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "バス高速輸送システム。専用の道路や停留所を使って、たくさんの人を速く運ぶ公共交通機関のことだ。", "primary_collocate": null, "pronunciation": "びーあーるてぃー", "ipa": "biːaːɾɯtiː", "syllable_count": 7, "sentences": [{"text": "BRT は、専用の走行路を使うことで、渋滞の影響を受けにくい。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "BRT は、専用(せんよう)の走行路(そうこうろ)を使(つか)うことで、渋滞(じゅうたい)の影響(えいきょう)を受(う)けにくい。", "sentence_source": "generated"}, {"text": "市は新しい交通手段として BRT の導入を決めた。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "市(し)は新(あたら)しい交通(こうつう)手段(しゅだん)として BRT の導入(どうにゅう)を決(き)めた。", "sentence_source": "generated"}, {"text": "鉄道を引くより費用が少ないため、BRT を選ぶ地域が増えている。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "鉄道(てつどう)を引(ひ)くより費用(ひよう)が少(すく)ないため、BRT を選(えら)ぶ地域(ちいき)が増(ふ)えている。", "sentence_source": "generated"}, {"text": "BRT の停留所には、乗る前に料金を払う方式を採る所もある。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "BRT の停留所(ていりゅうじょ)には、乗(の)る前(まえ)に料金(りょうきん)を払(はら)う方式(ほうしき)を採(と)る所(ところ)もある。", "sentence_source": "generated"}, {"text": "震災で壊れた鉄道の代わりに、BRT が運行を始めた。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "震災(しんさい)で壊(こわ)れた鉄道(てつどう)の代(か)わりに、BRT が運行(うんこう)を始(はじ)めた。", "sentence_source": "generated"}, {"text": "連節バスを使った BRT は、一度に多くの乗客を運べる。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "連節(れんせつ)バスを使(つか)った BRT は、一度(いちど)に多(おお)くの乗客(じょうきゃく)を運(はこ)べる。", "sentence_source": "generated"}, {"text": "BRT は優先信号のおかげで、交差点で待つ時間も短くなる。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "BRT は優先(ゆうせん)信号(しんごう)のおかげで、交差点(こうさてん)で待(ま)つ時間(じかん)も短(みじか)くなる。", "sentence_source": "generated"}, {"text": "路線の建設が早く終わり、BRT は計画から数年で開業した。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "路線(ろせん)の建設(けんせつ)が早(はや)く終(お)わり、BRT は計画(けいかく)から数年(すうねん)で開業(かいぎょう)した。", "sentence_source": "generated"}, {"text": "バス高速輸送システムを略して BRT と呼ぶ。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "バス高速(こうそく)輸送(ゆそう)システムを略(りゃく)して BRT と呼(よ)ぶ。", "sentence_source": "generated"}, {"text": "通勤時間帯には、BRT が五分おきに発着する。", "target_word": "BRT", "complexity_tier": "T3", "furigana": "通勤時間帯(つうきんじかんたい)には、BRT(びーあーるてぃー) が五分(ごふん)おきに発着(はっちゃく)する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "BRT", "label": "基本形"}, {"form": "BRTの", "label": "連体形（の）"}, {"form": "BRTを", "label": "目的語（を）"}], "register": "中立（常体・書き言葉）", "sense_fingerprint": "専用道路・専用停留所を用い大量の乗客を速く運ぶ公共交通システム。導入・運行・開業の文脈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd59781f0-782c-443d-b7d9-60f66a94d2c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37259, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "BRT", "is_correct": true, "explanation": "バス高速輸送の仕組み。専用の走行路を使う主語として合う。"}, {"text": "歩道", "is_correct": false, "explanation": "人が歩く道で、専用の走行路を使うバスの話には合わない。"}, {"text": "信号機", "is_correct": false, "explanation": "道路の信号の装置で、交通の仕組みの主語にはならない。"}, {"text": "交差点", "is_correct": false, "explanation": "道が交わる場所で、専用の走行路を使うという文の主語としては合わない。"}], "explanations": {"BRT": "バス高速輸送の仕組み。専用の走行路を使う主語として合う。", "歩道": "人が歩く道で、専用の走行路を使うバスの話には合わない。", "信号機": "道路の信号の装置で、交通の仕組みの主語にはならない。", "交差点": "道が交わる場所で、専用の走行路を使うという文の主語としては合わない。"}, "sentence_index": 0, "correct_answer": "BRT"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "BRT は、線路の上を走って大量の人を運ぶ。", "explanation": "ここは〈鉄道〉の意味。BRT は道路の専用走行路を使うバスの仕組みで、線路は使わない。"}, {"text": "BRT が、次々と空港から離陸していく。", "explanation": "ここは〈航空機〉の意味。BRT は地上の道を走るので、空港から離陸することはない。"}, {"text": "BRT は、夜になるとお客さんを泊める。", "explanation": "ここは〈ホテル〉の意味。BRT は乗客を運ぶバスの仕組みで、泊まらせる施設ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37259, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "BRT", "is_correct": true, "explanation": "バス高速輸送の仕組み。優先信号のおかげで待つ時間が短くなる主語に合う。"}, {"text": "渋滞", "is_correct": false, "explanation": "車が進まない状態で、優先信号で待ち時間が短くなる主語にはならない。"}, {"text": "運賃", "is_correct": false, "explanation": "乗るときに払うお金で、待つ時間の主語にはならない。"}, {"text": "駐車場", "is_correct": false, "explanation": "車を止める場所で、優先信号で待つ時間が短くなる主語としては合わない。"}], "explanations": {"BRT": "バス高速輸送の仕組み。優先信号のおかげで待つ時間が短くなる主語に合う。", "渋滞": "車が進まない状態で、優先信号で待ち時間が短くなる主語にはならない。", "運賃": "乗るときに払うお金で、待つ時間の主語にはならない。", "駐車場": "車を止める場所で、優先信号で待つ時間が短くなる主語としては合わない。"}, "sentence_index": 6, "correct_answer": "BRT"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "BRT は、一日に二回、港から海へ出ていく。", "explanation": "ここは〈フェリー〉の意味。BRT は道路を走るバスなので、港や海へは出ない。"}, {"text": "BRT は、ふわふわと空に上がっていく。", "explanation": "ここは〈風船〉の意味。BRT は地上の専用走行路を走るので、空へ上がることはない。"}, {"text": "BRT が、夜空に大きく広がって消えていく。", "explanation": "ここは〈花火〉の意味。BRT は乗客を運ぶ仕組みで、夜空に広がる光を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37259, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "BRT を運行が始まり、通勤の時間が短くなった。", "corrected_sentence": "BRT の運行が始まり、通勤の時間が短くなった。", "error_description": "正しくは「BRT の運行」。「の」が名詞同士をつなぐ。「を」は動作の対象を示すので、「運行が始まる」の前に置くと文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37259, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅の掲示板で、BRT に路線図を見た。", "corrected_sentence": "駅の掲示板で、BRT の路線図を見た。", "error_description": "正しくは「BRT の路線図」。「の」が名詞同士をつなぐ。「に」は場所や相手を示すので、路線図につながらず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41643f5c-166c-43b7-88ce-8ea19edb827b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
