INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37260, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ものがとても速く動くこと。", "primary_collocate": null, "pronunciation": "こうそく", "ipa": "koːsokɯ", "syllable_count": 4, "sentences": [{"text": "高速で回るコマは、止まっているように見える。", "target_word": "高速", "complexity_tier": "T3", "furigana": "高速[こうそく]で回[まわ]るコマは、止[と]まっているように見[み]える。", "sentence_source": "generated"}, {"text": "この電車は高速で走るので、目的地までとても早く着く。", "target_word": "高速", "complexity_tier": "T3", "furigana": "この電車[でんしゃ]は高速[こうそく]で走[はし]るので、目的地[もくてきち]までとても早[はや]く着[つ]く。", "sentence_source": "generated"}, {"text": "雨が強くなったので、ワイパーを高速に切り替えた。", "target_word": "高速", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]くなったので、ワイパーを高速[こうそく]に切[き]り替[か]えた。", "sentence_source": "generated"}, {"text": "ハチドリは高速で羽を動かして、空中で止まることができる。", "target_word": "高速", "complexity_tier": "T3", "furigana": "ハチドリは高速[こうそく]で羽[はね]を動[うご]かして、空中[くうちゅう]で止[と]まることができる。", "sentence_source": "generated"}, {"text": "高速で飛ぶボールを、彼は簡単に打ち返した。", "target_word": "高速", "complexity_tier": "T3", "furigana": "高速[こうそく]で飛[と]ぶボールを、彼[かれ]は簡単[かんたん]に打[う]ち返[かえ]した。", "sentence_source": "generated"}, {"text": "映画の中の車は高速で動いていて、目で追うのが大変だった。", "target_word": "高速", "complexity_tier": "T3", "furigana": "映画[えいが]の中[なか]の車[くるま]は高速[こうそく]で動[うご]いていて、目[め]で追[お]うのが大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "機械が高速で動くときは、手を近づけてはいけない。", "target_word": "高速", "complexity_tier": "T3", "furigana": "機械[きかい]が高速[こうそく]で動[うご]くときは、手[て]を近[ちか]づけてはいけない。", "sentence_source": "generated"}, {"text": "高速で動くものは、写真にぶれて写りやすい。", "target_word": "高速", "complexity_tier": "T3", "furigana": "高速[こうそく]で動[うご]くものは、写真[しゃしん]にぶれて写[うつ]りやすい。", "sentence_source": "generated"}, {"text": "洗濯機が高速で回転して、水をしっかり切る。", "target_word": "高速", "complexity_tier": "T3", "furigana": "洗濯機[せんたくき]が高速[こうそく]で回転[かいてん]して、水[みず]をしっかり切[き]る。", "sentence_source": "generated"}, {"text": "新幹線は高速で走るが、中はとても静かだ。", "target_word": "高速", "complexity_tier": "T3", "furigana": "新幹線[しんかんせん]は高速[こうそく]で走[はし]るが、中[なか]はとても静[しず]かだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高速", "label": "基本形"}, {"form": "高速で", "label": "連用形（で）"}, {"form": "高速の", "label": "連体形（の）"}], "register": "neutral", "sense_fingerprint": "物が非常に速く動く・回る・走ること。速さが大きい状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ハチドリ (Zipf 2.34)','sentence 4 above tier T2: contains vocabulary far above tier T2: 打ち返し (Zipf 2.18)']::text[], '8135be4b-f00d-40ac-8845-1284b6ffb713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37260, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高速", "is_correct": true, "explanation": "ものの動く速さを表す。『高速で回る』として文に合う。"}, {"text": "高価", "is_correct": false, "explanation": "値段が高いという意味。回るコマの速さの説明には合わない。"}, {"text": "高齢", "is_correct": false, "explanation": "年齢が高いという意味。コマの回転には使えない。"}, {"text": "高利", "is_correct": false, "explanation": "利息が高いという意味。回転の様子とは結びつかない。"}], "explanations": {"高速": "ものの動く速さを表す。『高速で回る』として文に合う。", "高価": "値段が高いという意味。回るコマの速さの説明には合わない。", "高齢": "年齢が高いという意味。コマの回転には使えない。", "高利": "利息が高いという意味。回転の様子とは結びつかない。"}, "sentence_index": 0, "correct_answer": "高速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "景気が高速に回復した。", "explanation": "ここは〈急速〉の意味。景気の立ち直りの速さには急速を使い、高速は物の動きの速さに限られる。"}, {"text": "会議で、彼は議題を高速に決めた。", "explanation": "ここは〈瞬時〉の意味。決める速さを表すなら瞬時を使い、高速は物の動きの速さに限られる。"}, {"text": "体重が高速に増えた。", "explanation": "ここは〈急激〉の意味。体重の変化の速さには高速を使わず、急激を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37260, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高速", "is_correct": true, "explanation": "動きの速さを表す。機械の動作の説明に合う。"}, {"text": "高額", "is_correct": false, "explanation": "金額が大きいという意味。機械の動きには使えない。"}, {"text": "高層", "is_correct": false, "explanation": "建物が高いという意味。動作の速さとは関係ない。"}, {"text": "高原", "is_correct": false, "explanation": "標高の高い土地を指す。機械の動作の文脈に合わない。"}], "explanations": {"高速": "動きの速さを表す。機械の動作の説明に合う。", "高額": "金額が大きいという意味。機械の動きには使えない。", "高層": "建物が高いという意味。動作の速さとは関係ない。", "高原": "標高の高い土地を指す。機械の動作の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "高速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火災の知らせに、消防隊は高速に出動した。", "explanation": "ここは〈速やか〉の意味。出動の素早さを表すなら速やかを使い、高速は物の動きの速さに限られる。"}, {"text": "店員は客の注文に高速に応じた。", "explanation": "ここは〈迅速〉の意味。注文への対応の素早さには迅速を使い、高速は合わない。"}, {"text": "彼は質問に高速に答えた。", "explanation": "ここは〈即座〉の意味。すぐに答える様子には即座を使い、高速は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37260, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "高速を飛ぶ鳥は、目で追うのが難しい。", "corrected_sentence": "高速で飛ぶ鳥は、目で追うのが難しい。", "error_description": "『高速で飛ぶ』と、飛び方の様子を示す『で』が正しい。『を』は場所や経路を表すため、『高速を飛ぶ』は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37260, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "扇風機が高速で止まるので、近くに物を置かないでください。", "corrected_sentence": "扇風機が高速で回るので、近くに物を置かないでください。", "error_description": "『高速で』が修飾する動詞は、速く動き続ける状態を表す『回る』が正しい。『止まる』は動きがなくなる意味で、高速と矛盾する。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37261, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低速", "is_correct": true, "explanation": "高速の対義語。速さの大小が反対になる関係。"}, {"text": "低俗", "is_correct": false, "explanation": "高尚の対義語で、品位の話。速さとは関係がない。"}, {"text": "低地", "is_correct": false, "explanation": "高地の対義語で、土地の高さの話。速度とは無関係。"}, {"text": "低温", "is_correct": false, "explanation": "高温の対義語で、温度の話。速度の反対語ではない。"}], "correct_answer": "低速", "explanations": {"低速": "高速の対義語。速さの大小が反対になる関係。", "低俗": "高尚の対義語で、品位の話。速さとは関係がない。", "低地": "高地の対義語で、土地の高さの話。速度とは無関係。", "低温": "高温の対義語で、温度の話。速度の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37261, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低速", "is_correct": true, "explanation": "高速の対義語。速さの大小が反対になる関係。"}, {"text": "低姿勢", "is_correct": false, "explanation": "態度が控えめなことを表す。速さの反対ではない。"}, {"text": "低年齢", "is_correct": false, "explanation": "年齢の若さを表す語。速度の対義語ではない。"}, {"text": "低額", "is_correct": false, "explanation": "高額の対義語で、金額の話。速さとは関係がない。"}], "correct_answer": "低速", "explanations": {"低速": "高速の対義語。速さの大小が反対になる関係。", "低姿勢": "態度が控えめなことを表す。速さの反対ではない。", "低年齢": "年齢の若さを表す語。速度の対義語ではない。", "低額": "高額の対義語で、金額の話。速さとは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37261, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "速度が非常に大きいこと。また、そのさま。", "primary_collocate": null, "pronunciation": "こうそく", "ipa": "koːsokɯ", "syllable_count": 4, "sentences": [{"text": "高速の通信が使えるので、大きなファイルもすぐ送れる。", "target_word": "高速", "complexity_tier": "T3", "furigana": "高速[こうそく]の通信[つうしん]が使[つか]えるので、大[おお]きなファイルもすぐ送[おく]れる。", "sentence_source": "generated"}, {"text": "このコンピューターは高速な処理が特長で、計算が一瞬で終わる。", "target_word": "高速", "complexity_tier": "T3", "furigana": "このコンピューターは高速[こうそく]な処理[しょり]が特長[とくちょう]で、計算[けいさん]が一瞬[いっしゅん]で終[お]わる。", "sentence_source": "generated"}, {"text": "高速で移動する物体を、特別なカメラで撮影した。", "target_word": "高速", "complexity_tier": "T3", "furigana": "高速[こうそく]で移動[いどう]する物体[ぶったい]を、特別[とくべつ]なカメラで撮影[さつえい]した。", "sentence_source": "generated"}, {"text": "彼は高速のサーブを武器に、試合に勝った。", "target_word": "高速", "complexity_tier": "T3", "furigana": "彼[かれ]は高速[こうそく]のサーブを武器[ぶき]に、試合[しあい]に勝[か]った。", "sentence_source": "generated"}, {"text": "戦闘機は高速で飛ぶため、操縦には高い技術が必要だ。", "target_word": "高速", "complexity_tier": "T3", "furigana": "戦闘機[せんとうき]は高速[こうそく]で飛[と]ぶため、操縦[そうじゅう]には高[たか]い技術[ぎじゅつ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "高速で進む列車の窓から見ると、景色が流れるように変わる。", "target_word": "高速", "complexity_tier": "T3", "furigana": "高速[こうそく]で進[すす]む列車[れっしゃ]の窓[まど]から見[み]ると、景色[けしき]が流[なが]れるように変[か]わる。", "sentence_source": "generated"}, {"text": "高速の水の流れは、岩さえ削ってしまう。", "target_word": "高速", "complexity_tier": "T3", "furigana": "高速[こうそく]の水[みず]の流[なが]れは、岩[いわ]さえ削[けず]ってしまう。", "sentence_source": "generated"}, {"text": "高速で作業できるロボットが、工場の生産を支えている。", "target_word": "高速", "complexity_tier": "T3", "furigana": "高速[こうそく]で作業[さぎょう]できるロボットが、工場[こうじょう]の生産[せいさん]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "この機械は高速での連続運転には向いていない。", "target_word": "高速", "complexity_tier": "T3", "furigana": "この機械[きかい]は高速[こうそく]での連続[れんぞく]運転[うんてん]には向[む]いていない。", "sentence_source": "generated"}, {"text": "高速な動きについていけず、目が疲れてしまった。", "target_word": "高速", "complexity_tier": "T3", "furigana": "高速[こうそく]な動[うご]きについていけず、目[め]が疲[つか]れてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高速", "label": "基本形"}, {"form": "高速な", "label": "連体形（な）"}, {"form": "高速の", "label": "連体形（の）"}, {"form": "高速で", "label": "連用形（で）"}], "register": "neutral", "sense_fingerprint": "速度が非常に大きい状態やそのさま。通信・処理・動きなどの速さにも使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8135be4b-f00d-40ac-8845-1284b6ffb713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37261, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高速", "is_correct": true, "explanation": "通信の速さを表す。『高速の通信』として文に合う。"}, {"text": "高齢", "is_correct": false, "explanation": "年齢が高いという意味。通信には使えない。"}, {"text": "高利", "is_correct": false, "explanation": "利息が高いという意味。通信の性能とは結びつかない。"}, {"text": "高価", "is_correct": false, "explanation": "値段が高いという意味。『高価の通信』は不自然で、速さの説明にならない。"}], "explanations": {"高速": "通信の速さを表す。『高速の通信』として文に合う。", "高齢": "年齢が高いという意味。通信には使えない。", "高利": "利息が高いという意味。通信の性能とは結びつかない。", "高価": "値段が高いという意味。『高価の通信』は不自然で、速さの説明にならない。"}, "sentence_index": 0, "correct_answer": "高速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合は高速に決着した。", "explanation": "ここは〈瞬時〉の意味。一瞬で決まる様子には瞬時を使い、高速は速度の大きさを表す語で、決着の速さには合わない。"}, {"text": "物価が高速に上がった。", "explanation": "ここは〈急速〉の意味。物価の変化の速さには高速を使わず、急速を使う。"}, {"text": "気温が高速に下がった。", "explanation": "ここは〈急激〉の意味。気温の変化の速さには高速ではなく、急激を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37261, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高速", "is_correct": true, "explanation": "水の流れの速さを表す。『高速の水の流れ』として文に合う。"}, {"text": "高額", "is_correct": false, "explanation": "金額の大きさを表す。水の流れの説明には使えない。"}, {"text": "高層", "is_correct": false, "explanation": "建物が高いことを表す。水流の速さとは関係がない。"}, {"text": "高慢", "is_correct": false, "explanation": "態度が偉そうなことを表す。流れの説明にはならない。"}], "explanations": {"高速": "水の流れの速さを表す。『高速の水の流れ』として文に合う。", "高額": "金額の大きさを表す。水の流れの説明には使えない。", "高層": "建物が高いことを表す。水流の速さとは関係がない。", "高慢": "態度が偉そうなことを表す。流れの説明にはならない。"}, "sentence_index": 6, "correct_answer": "高速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火災の知らせに、消防隊は高速に出動した。", "explanation": "ここは〈速やか〉の意味。出動の素早さには速やかを使い、高速は物の動きの速さに限られる。"}, {"text": "店員は客の注文に高速に応じた。", "explanation": "ここは〈迅速〉の意味。注文への対応の素早さには迅速を使い、高速は合わない。"}, {"text": "彼は質問に高速に答えた。", "explanation": "ここは〈即座〉の意味。すぐに答える様子には即座を使い、高速は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37261, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "高速だ回線を使えば、大容量のデータも一瞬で送れる。", "corrected_sentence": "高速な回線を使えば、大容量のデータも一瞬で送れる。", "error_description": "名詞の前では連体形『高速な』を使う。『高速だ』は名詞の前に置けない形なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37261, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "高速だデータ転送は、ケーブルの種類で変わる。", "corrected_sentence": "高速なデータ転送は、ケーブルの種類で変わる。", "error_description": "名詞の前では連体形『高速な』を使う。『高速だ』は名詞の前に置けないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37262, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『走行に注意』の『に』。注意の対象を示すので文に合う。"}, {"text": "を", "is_correct": false, "explanation": "『注意が必要』の前に対象として『を』を取るのは不自然。"}, {"text": "の", "is_correct": false, "explanation": "『走行の』の後に『は』は続かず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "『走行が注意が必要』と『が』が続き、文の構造が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "『走行に注意』の『に』。注意の対象を示すので文に合う。", "を": "『注意が必要』の前に対象として『を』を取るのは不自然。", "の": "『走行の』の後に『は』は続かず、文が成り立たない。", "が": "『走行が注意が必要』と『が』が続き、文の構造が成り立たない。"}, "error_tags": {"を": "object", "が": "subject", "の": "linker"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
