INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37262, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "くるまや電車が道を進むことです。", "primary_collocate": null, "pronunciation": "そうこう", "ipa": "soːkoː", "syllable_count": 4, "sentences": [{"text": "車の走行が静かで、中で話しやすい。", "target_word": "走行", "complexity_tier": "T3", "furigana": "車[くるま]の走行[そうこう]が静[しず]かで、中[なか]で話[はな]しやすい。", "sentence_source": "generated"}, {"text": "雪の日は道がすべるので、走行には注意が必要だ。", "target_word": "走行", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は道[みち]がすべるので、走行[そうこう]には注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "この電車は、走行する音がとても小さい。", "target_word": "走行", "complexity_tier": "T3", "furigana": "この電車[でんしゃ]は、走行[そうこう]する音[おと]がとても小[ちい]さい。", "sentence_source": "generated"}, {"text": "工事のため、この道では走行できない。", "target_word": "走行", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、この道[みち]では走行[そうこう]できない。", "sentence_source": "generated"}, {"text": "新しい車で走行してみると、思ったより乗り心地がよかった。", "target_word": "走行", "complexity_tier": "T3", "furigana": "新[あたら]しい車[くるま]で走行[そうこう]してみると、思[おも]ったより乗[の]り心地[ごこち]がよかった。", "sentence_source": "generated"}, {"text": "夜の走行では、ライトをつけなければならない。", "target_word": "走行", "complexity_tier": "T3", "furigana": "夜[よる]の走行[そうこう]では、ライトをつけなければならない。", "sentence_source": "generated"}, {"text": "バスは決まった道を走行して、駅と学校を結んでいる。", "target_word": "走行", "complexity_tier": "T3", "furigana": "バスは決[き]まった道[みち]を走行[そうこう]して、駅[えき]と学校[がっこう]を結[むす]んでいる。", "sentence_source": "generated"}, {"text": "大雨の中、車は速度を落として走行した。", "target_word": "走行", "complexity_tier": "T3", "furigana": "大雨[おおあめ]の中[なか]、車[くるま]は速度[そくど]を落[お]として走行[そうこう]した。", "sentence_source": "generated"}, {"text": "事故のあと、電車は一時間ほど走行を止めていた。", "target_word": "走行", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、電車[でんしゃ]は一時間[いちじかん]ほど走行[そうこう]を止[と]めていた。", "sentence_source": "generated"}, {"text": "山道の走行は、カーブが多くて疲れる。", "target_word": "走行", "complexity_tier": "T3", "furigana": "山道[やまみち]の走行[そうこう]は、カーブが多[おお]くて疲[つか]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "走行", "label": "基本形"}, {"form": "走行する", "label": "終止形（する）"}, {"form": "走行した", "label": "過去形"}, {"form": "走行して", "label": "て形"}], "register": "formal", "sense_fingerprint": "車や電車などの乗り物が道や線路を進むこと。する動詞としても使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8135be4b-f00d-40ac-8845-1284b6ffb713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37262, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走行", "is_correct": true, "explanation": "車が進むことを表す。『車の走行が静かで』として文に合う。"}, {"text": "色彩", "is_correct": false, "explanation": "色の様子を表す。車の静けさの説明には合わない。"}, {"text": "容量", "is_correct": false, "explanation": "中に入る量を表す。静かさとは関係がない。"}, {"text": "年齢", "is_correct": false, "explanation": "使用してからの年数を表す。静かさの話には合わない。"}], "explanations": {"走行": "車が進むことを表す。『車の走行が静かで』として文に合う。", "色彩": "色の様子を表す。車の静けさの説明には合わない。", "容量": "中に入る量を表す。静かさとは関係がない。", "年齢": "使用してからの年数を表す。静かさの話には合わない。"}, "sentence_index": 0, "correct_answer": "走行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猫は屋根の上を走行して、追いかけてきた。", "explanation": "ここは〈走る〉の意味。動物の動きには走行を使わず、走行は乗り物の進行を指す。"}, {"text": "歩行者は横断歩道を走行して渡った。", "explanation": "ここは〈歩行〉の意味。人が歩いて渡る行為には走行を使わない。"}, {"text": "駅までは走行で十分だ。", "explanation": "ここは〈徒歩〉の意味。歩いて移動することを言うときは徒歩を使い、走行は乗り物の進行に限る。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37262, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走行", "is_correct": true, "explanation": "車や電車が進むことを表す。『道を走行して』として文に合う。"}, {"text": "停止", "is_correct": false, "explanation": "止まることを表す。道を進む文脈に合わない。"}, {"text": "撮影", "is_correct": false, "explanation": "写真を撮る意味。道を結ぶ説明には合わない。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつける意味。道を結ぶ文脈には合わない。"}], "explanations": {"走行": "車や電車が進むことを表す。『道を走行して』として文に合う。", "停止": "止まることを表す。道を進む文脈に合わない。", "撮影": "写真を撮る意味。道を結ぶ説明には合わない。", "点灯": "明かりをつける意味。道を結ぶ文脈には合わない。"}, "sentence_index": 6, "correct_answer": "走行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は去年、走行免許を取った。", "explanation": "ここは〈運転〉の意味。免許は運転に対して与えられるもので、走行免許とは言わない。"}, {"text": "この道は工事のため走行止めになっている。", "explanation": "ここは〈通行〉の意味。道を通れなくする表現は通行止めで、走行止めとは言わない。"}, {"text": "休日は公園を走行した。", "explanation": "ここは〈散歩〉の意味。人がのんびり歩く行為には走行を使わず、乗り物の進行を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37262, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この車は走行を安定していて、高速道路でも安心だ。", "corrected_sentence": "この車は走行が安定していて、高速道路でも安心だ。", "error_description": "『安定している』は『走行が』と主語に『が』を取る。ここで『を』を使うのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37262, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その車は道路を安定して走行されている。", "corrected_sentence": "その車は道路を安定して走行している。", "error_description": "走行は自動詞なので、受け身の『れる』は付かない。『走行している』が正しい形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
