INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37263, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自動車や電車などが走ること。移動すること。", "primary_collocate": null, "pronunciation": "そうこう", "ipa": "soːkoː", "syllable_count": 4, "sentences": [{"text": "この車は電気で走行するので、排気ガスが出ない。", "target_word": "走行", "complexity_tier": "T3", "furigana": "この車[くるま]は電気[でんき]で走行[そうこう]するので、排気[はいき]ガスが出[で]ない。", "sentence_source": "generated"}, {"text": "新型の電車が、試験のために線路を走行した。", "target_word": "走行", "complexity_tier": "T3", "furigana": "新型[しんがた]の電車[でんしゃ]が、試験[しけん]のために線路[せんろ]を走行[そうこう]した。", "sentence_source": "generated"}, {"text": "自動運転の車が、運転手なしで道路を走行している。", "target_word": "走行", "complexity_tier": "T3", "furigana": "自動[じどう]運転[うんてん]の車[くるま]が、運転手[うんてんしゅ]なしで道路[どうろ]を走行[そうこう]している。", "sentence_source": "generated"}, {"text": "タイヤがすり減ると、安全に走行できなくなる。", "target_word": "走行", "complexity_tier": "T3", "furigana": "タイヤがすり減[へ]ると、安全[あんぜん]に走行[そうこう]できなくなる。", "sentence_source": "generated"}, {"text": "雪の中を走行する列車の写真を撮った。", "target_word": "走行", "complexity_tier": "T3", "furigana": "雪[ゆき]の中[なか]を走行[そうこう]する列車[れっしゃ]の写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "最新の車は、燃料が少なくても長く走行できる。", "target_word": "走行", "complexity_tier": "T3", "furigana": "最新[さいしん]の車[くるま]は、燃料[ねんりょう]が少[すく]なくても長[なが]く走行[そうこう]できる。", "sentence_source": "generated"}, {"text": "台風の影響で、電車は速度を落として走行している。", "target_word": "走行", "complexity_tier": "T3", "furigana": "台風[たいふう]の影響[えいきょう]で、電車[でんしゃ]は速度[そくど]を落[お]として走行[そうこう]している。", "sentence_source": "generated"}, {"text": "この車は一日で三百キロを走行した。", "target_word": "走行", "complexity_tier": "T3", "furigana": "この車[くるま]は一日[いちにち]で三百[さんびゃく]キロを走行[そうこう]した。", "sentence_source": "generated"}, {"text": "走行した道のデータは、車の中に記録される。", "target_word": "走行", "complexity_tier": "T3", "furigana": "走行[そうこう]した道[みち]のデータは、車[くるま]の中[なか]に記録[きろく]される。", "sentence_source": "generated"}, {"text": "月の表面を走行する探査車が、新しい石を見つけた。", "target_word": "走行", "complexity_tier": "T3", "furigana": "月[つき]の表面[ひょうめん]を走行[そうこう]する探査車[たんさしゃ]が、新[あたら]しい石[いし]を見[み]つけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "走行", "label": "基本形"}, {"form": "走行する", "label": "終止形（する）"}, {"form": "走行した", "label": "過去形"}, {"form": "走行できる", "label": "可能形"}], "register": "formal", "sense_fingerprint": "自動車・電車・探査車などが走って移動すること。する動詞としても使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: すり減る (Zipf 2.1)']::text[], '8135be4b-f00d-40ac-8845-1284b6ffb713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37263, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走行", "is_correct": true, "explanation": "車が進むことを表す。『電気で走行する』として文に合う。"}, {"text": "排出", "is_correct": false, "explanation": "外へ出すという意味。電気で動く説明にはならない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分をなくすという意味。車の動きの説明には合わない。"}, {"text": "停止", "is_correct": false, "explanation": "止まるという意味。電気で動くという文脈と矛盾する。"}], "explanations": {"走行": "車が進むことを表す。『電気で走行する』として文に合う。", "排出": "外へ出すという意味。電気で動く説明にはならない。", "乾燥": "水分をなくすという意味。車の動きの説明には合わない。", "停止": "止まるという意味。電気で動くという文脈と矛盾する。"}, "sentence_index": 0, "correct_answer": "走行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この道は工事のため走行止めになっている。", "explanation": "ここは〈通行止め〉の意味。道を通れなくする表現であり、走行止めとは言わない。"}, {"text": "飛行機が空を走行して、遠い国へ向かった。", "explanation": "ここは〈飛行〉の意味。空を飛ぶ航空機の動きには走行を使わない。"}, {"text": "子どもが公園を走行して、ボールを追いかけた。", "explanation": "ここは〈走る〉の意味。人が走る動きには走行を使わず、乗り物の進行を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37263, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走行", "is_correct": true, "explanation": "電車が進むことを表す。『速度を落として走行している』として文に合う。"}, {"text": "集計", "is_correct": false, "explanation": "数をまとめる意味。速度を落とす文脈と結びつかない。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつける意味。電車の速度の説明には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける意味。電車の様子には使えない。"}], "explanations": {"走行": "電車が進むことを表す。『速度を落として走行している』として文に合う。", "集計": "数をまとめる意味。速度を落とす文脈と結びつかない。", "点灯": "明かりをつける意味。電車の速度の説明には合わない。", "採点": "点数をつける意味。電車の様子には使えない。"}, "sentence_index": 6, "correct_answer": "走行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "引っ越しで家具を走行した。", "explanation": "ここは〈移動〉の意味。物を別の場所へ動かす意味には走行を使わない。"}, {"text": "この会社は新しいシステムを走行している。", "explanation": "ここは〈運用〉の意味。システムの稼働には運用を使い、走行は合わない。"}, {"text": "彼は毎朝、公園を走行する。", "explanation": "ここは〈散歩〉の意味。人がのんびり歩く行為には走行を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
