INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37264, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "減少", "is_correct": true, "explanation": "げんしょう。正解の語です。"}, {"text": "現状", "is_correct": false, "explanation": "げんじょう。「しょ」が「じょ」になり、1音だけ違います。"}, {"text": "検証", "is_correct": false, "explanation": "けんしょう。「げ」が「け」になり、1音だけ違います。"}, {"text": "現職", "is_correct": false, "explanation": "げんしょく。最後の「う」が「く」になり、1音だけ違います。"}], "explanations": {"減少": "げんしょう。正解の語です。", "現状": "げんじょう。「しょ」が「じょ」になり、1音だけ違います。", "検証": "けんしょう。「げ」が「け」になり、1音だけ違います。", "現職": "げんしょく。最後の「う」が「く」になり、1音だけ違います。"}, "sentence_index": null, "correct_answer": "減少"}, "level_3": {"options": [{"text": "減少しました", "is_correct": true, "explanation": "生徒の数が少なくなったという意味に合います。"}, {"text": "到着しました", "is_correct": false, "explanation": "形は合うが、生徒の数が「到着した」では意味が合わない。"}, {"text": "結婚しました", "is_correct": false, "explanation": "形は合うが、生徒の数が「結婚した」では意味が合わない。"}, {"text": "出発しました", "is_correct": false, "explanation": "形は合うが、生徒の数が「出発した」では意味が合わない。"}], "explanations": {"減少しました": "生徒の数が少なくなったという意味に合います。", "到着しました": "形は合うが、生徒の数が「到着した」では意味が合わない。", "結婚しました": "形は合うが、生徒の数が「結婚した」では意味が合わない。", "出発しました": "形は合うが、生徒の数が「出発した」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "減少しました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姉は毎日、駅で電車の減少をしている。", "explanation": "「減少」は数が減ることで、電車に関する動作には使えません。"}, {"text": "このカバンは減少が大きくて、たくさん入る。", "explanation": "「減少」は大きさを表さないので、意味が合いません。"}, {"text": "子どもたちが公園で楽しく減少している。", "explanation": "「減少」は遊ぶ動作ではなく、意味が合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37264, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "減少", "is_correct": true, "explanation": "げんしょう。正解の語です。"}, {"text": "幻想", "is_correct": false, "explanation": "げんそう。「しょ」が「そ」になり、1音だけ違います。"}, {"text": "減収", "is_correct": false, "explanation": "げんしゅう。「しょ」が「しゅ」になり、1音だけ違います。"}, {"text": "現像", "is_correct": false, "explanation": "げんぞう。「しょ」が「ぞ」になり、1音だけ違います。"}], "explanations": {"減少": "げんしょう。正解の語です。", "幻想": "げんそう。「しょ」が「そ」になり、1音だけ違います。", "減収": "げんしゅう。「しょ」が「しゅ」になり、1音だけ違います。", "現像": "げんぞう。「しょ」が「ぞ」になり、1音だけ違います。"}, "sentence_index": null, "correct_answer": "減少"}, "level_3": {"options": [{"text": "減少した", "is_correct": true, "explanation": "数が少なくなった客を呼び戻したい、と意味が合います。"}, {"text": "完成した", "is_correct": false, "explanation": "形は合うが、客が「完成した」では意味が合わない。"}, {"text": "爆発した", "is_correct": false, "explanation": "形は合うが、客が「爆発した」では意味が合わない。"}, {"text": "発表した", "is_correct": false, "explanation": "形は合うが、客が「発表した」では意味が合わない。"}], "explanations": {"減少した": "数が少なくなった客を呼び戻したい、と意味が合います。", "完成した": "形は合うが、客が「完成した」では意味が合わない。", "爆発した": "形は合うが、客が「爆発した」では意味が合わない。", "発表した": "形は合うが、客が「発表した」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "減少した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は黒板に大きく減少を書いた。", "explanation": "「減少」は変化を表す語で、黒板に書く物としては意味が合いません。"}, {"text": "母と一緒に、晩ご飯の減少を作った。", "explanation": "「減少」は作る料理を表さないので、意味が合いません。"}, {"text": "先生は参加者の減少を温めて食べた。", "explanation": "「減少」は食べ物ではなく、意味が合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37264, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "川の魚の数が減少くなりました。", "corrected_sentence": "川の魚の数が減少しました。", "error_description": "「減少」は形容詞ではないので「減少くなる」とは言いません。「減少しました」が正しい形です。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37264, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客の数が減少なって、店が困っている。", "corrected_sentence": "客の数が減少して、店が困っている。", "error_description": "「減少」は「減少して」と言います。「減少なって」は誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37265, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「人口が減少する」で、人口が主語になります。"}, {"text": "へ", "is_correct": false, "explanation": "「人口へ減少している」は文として成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「人口に減少している」は文として成り立ちません。"}, {"text": "で", "is_correct": false, "explanation": "「人口で減少している」は文として成り立ちません。"}], "correct_answer": "が", "explanations": {"が": "「人口が減少する」で、人口が主語になります。", "へ": "「人口へ減少している」は文として成り立ちません。", "に": "「人口に減少している」は文として成り立ちません。", "で": "「人口で減少している」は文として成り立ちません。"}, "error_tags": {"へ": "direction", "に": "wrong_case", "で": "wrong_case"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増加", "is_correct": true, "explanation": "数量が増えることで、「減少」の反対です。"}, {"text": "低下", "is_correct": false, "explanation": "下がることで、反対ではなく近い意味です。"}, {"text": "削減", "is_correct": false, "explanation": "減らすことで、反対ではなく近い意味です。"}, {"text": "縮小", "is_correct": false, "explanation": "小さくなることで、反対ではなく近い意味です。"}], "correct_answer": "増加", "explanations": {"増加": "数量が増えることで、「減少」の反対です。", "低下": "下がることで、反対ではなく近い意味です。", "削減": "減らすことで、反対ではなく近い意味です。", "縮小": "小さくなることで、反対ではなく近い意味です。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37265, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「客の減少を防ぐ」で、防ぐ対象を示します。"}, {"text": "に", "is_correct": false, "explanation": "「減少に防ぐ」は文として成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「減少と防ぐ」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「減少へ防ぐ」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「客の減少を防ぐ」で、防ぐ対象を示します。", "に": "「減少に防ぐ」は文として成り立ちません。", "と": "「減少と防ぐ」は文として成り立ちません。", "へ": "「減少へ防ぐ」は文として成り立ちません。"}, "error_tags": {"に": "wrong_case", "と": "wrong_case", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増大", "is_correct": true, "explanation": "程度が大きくなることで、「減少」の反対です。"}, {"text": "軽減", "is_correct": false, "explanation": "負担などを減らすことで、反対ではなく近い意味です。"}, {"text": "緩和", "is_correct": false, "explanation": "和らぐことで、反対の関係ではありません。"}, {"text": "消失", "is_correct": false, "explanation": "なくなることで、反対ではなく近い意味です。"}], "correct_answer": "増大", "explanations": {"増大": "程度が大きくなることで、「減少」の反対です。", "軽減": "負担などを減らすことで、反対ではなく近い意味です。", "緩和": "和らぐことで、反対の関係ではありません。", "消失": "なくなることで、反対ではなく近い意味です。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37265, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の数量や程度が、以前より少なくなること。", "primary_collocate": null, "pronunciation": "げんしょう", "ipa": "ɡeɴɕoː", "syllable_count": 4, "sentences": [{"text": "従来の肉体労働は減少しますが、機械を操作する専門知識を持つ人材の確保が、新たな課題として浮上しているのです。", "target_word": "減少します", "complexity_tier": "T6", "furigana": "従来[じゅうらい]の肉体労働[にくたいろうどう]は減少[げんしょう]しますが、機械[きかい]を操作[そうさ]する専門知識[せんもんちしき]を持[も]つ人材[じんざい]の確保[かくほ]が、新[あら]たな課題[かだい]として浮上[ふじょう]しているのです。", "sentence_source": "mined"}, {"text": "人口が減少している。", "target_word": "減少している", "complexity_tier": "T3", "furigana": "人口[じんこう]が減少[げんしょう]している。", "sentence_source": "generated"}, {"text": "魚の数が年々減少しています。", "target_word": "減少しています", "complexity_tier": "T2", "furigana": "魚[さかな]の数[かず]が年々[ねんねん]減少[げんしょう]しています。", "sentence_source": "generated"}, {"text": "売り上げが前年より減少した。", "target_word": "減少した", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが前年[ぜんねん]より減少[げんしょう]した。", "sentence_source": "generated"}, {"text": "事故は減少する傾向にある。", "target_word": "減少する", "complexity_tier": "T3", "furigana": "事故[じこ]は減少[げんしょう]する傾向[けいこう]にある。", "sentence_source": "generated"}, {"text": "収入の減少で、生活が苦しくなった。", "target_word": "減少", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]の減少[げんしょう]で、生活[せいかつ]が苦[くる]しくなった。", "sentence_source": "generated"}, {"text": "雨の量が減少したため、川の水が少ない。", "target_word": "減少した", "complexity_tier": "T3", "furigana": "雨[あめ]の量[りょう]が減少[げんしょう]したため、川[かわ]の水[みず]が少[すく]ない。", "sentence_source": "generated"}, {"text": "客の減少を防ぐ方法を考えたい。", "target_word": "減少", "complexity_tier": "T3", "furigana": "客[きゃく]の減少[げんしょう]を防[ふせ]ぐ方法[ほうほう]を考[かんが]えたい。", "sentence_source": "generated"}, {"text": "減少した利益を取り戻したい。", "target_word": "減少した", "complexity_tier": "T3", "furigana": "減少[げんしょう]した利益[りえき]を取[と]り戻[もど]したい。", "sentence_source": "generated"}, {"text": "痛みが少しずつ減少してきた。", "target_word": "減少してきた", "complexity_tier": "T3", "furigana": "痛[いた]みが少[すこ]しずつ減少[げんしょう]してきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "減少する", "label": "活用"}, {"form": "減少した", "label": "活用"}, {"form": "減少傾向", "label": "派生"}, {"form": "減少率", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 数量や程度が以前より少なくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa10040-79ce-478c-8cf8-7b3b9938243e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37265, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "減少", "is_correct": true, "explanation": "げんしょう。正解の語です。"}, {"text": "現状", "is_correct": false, "explanation": "げんじょう。「しょ」が「じょ」になり、1音だけ違います。"}, {"text": "検証", "is_correct": false, "explanation": "けんしょう。「げ」が「け」になり、1音だけ違います。"}, {"text": "現職", "is_correct": false, "explanation": "げんしょく。最後の「う」が「く」になり、1音だけ違います。"}], "explanations": {"減少": "げんしょう。正解の語です。", "現状": "げんじょう。「しょ」が「じょ」になり、1音だけ違います。", "検証": "けんしょう。「げ」が「け」になり、1音だけ違います。", "現職": "げんしょく。最後の「う」が「く」になり、1音だけ違います。"}, "sentence_index": null, "correct_answer": "減少"}, "level_3": {"options": [{"text": "減少します", "is_correct": true, "explanation": "肉体労働が少なくなるという文脈に合います。"}, {"text": "到着します", "is_correct": false, "explanation": "形は合うが、肉体労働が「到着する」では意味が合わない。"}, {"text": "出発します", "is_correct": false, "explanation": "形は合うが、肉体労働が「出発する」では意味が合わない。"}, {"text": "卒業します", "is_correct": false, "explanation": "形は合うが、肉体労働が「卒業する」では意味が合わない。"}], "explanations": {"減少します": "肉体労働が少なくなるという文脈に合います。", "到着します": "形は合うが、肉体労働が「到着する」では意味が合わない。", "出発します": "形は合うが、肉体労働が「出発する」では意味が合わない。", "卒業します": "形は合うが、肉体労働が「卒業する」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "減少します"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、公園の周りを減少しています。", "explanation": "「減少」は数量が減ることで、場所の周りを動く意味では使えません。"}, {"text": "友だちが私に誕生日の減少をくれた。", "explanation": "「減少」は物ではなく変化を表すので、贈り物の意味では使えません。"}, {"text": "新しい服が減少して、とてもきれいに見える。", "explanation": "「減少」は数量が減ることで、服の見た目の変化には使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37265, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "減少", "is_correct": true, "explanation": "げんしょう。正解の語です。"}, {"text": "幻想", "is_correct": false, "explanation": "げんそう。「しょ」が「そ」になり、1音だけ違います。"}, {"text": "減収", "is_correct": false, "explanation": "げんしゅう。「しょ」が「しゅ」になり、1音だけ違います。"}, {"text": "現像", "is_correct": false, "explanation": "げんぞう。「しょ」が「ぞ」になり、1音だけ違います。"}], "explanations": {"減少": "げんしょう。正解の語です。", "幻想": "げんそう。「しょ」が「そ」になり、1音だけ違います。", "減収": "げんしゅう。「しょ」が「しゅ」になり、1音だけ違います。", "現像": "げんぞう。「しょ」が「ぞ」になり、1音だけ違います。"}, "sentence_index": null, "correct_answer": "減少"}, "level_3": {"options": [{"text": "減少した", "is_correct": true, "explanation": "雨が少なくなったので川の水が少ない、と意味が合います。"}, {"text": "発表した", "is_correct": false, "explanation": "形は合うが、雨の量が「発表した」では意味が合わない。"}, {"text": "結婚した", "is_correct": false, "explanation": "形は合うが、雨の量が「結婚した」では意味が合わない。"}, {"text": "出発した", "is_correct": false, "explanation": "形は合うが、雨の量が「出発した」では意味が合わない。"}], "explanations": {"減少した": "雨が少なくなったので川の水が少ない、と意味が合います。", "発表した": "形は合うが、雨の量が「発表した」では意味が合わない。", "結婚した": "形は合うが、雨の量が「結婚した」では意味が合わない。", "出発した": "形は合うが、雨の量が「出発した」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "減少した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は会社で部長に減少された。", "explanation": "「減少」は人を対象にする動作ではなく、受け身で使えません。"}, {"text": "この料理は減少してから食べるとおいしい。", "explanation": "「減少」は調理の動作を表さないので、意味が合いません。"}, {"text": "彼女は大きな声で減少して、みんなを笑わせた。", "explanation": "「減少」は人が声を出す動作ではなく、意味が合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
