INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37266, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『答えを確認する』の目的語を示す『を』。"}, {"text": "に", "is_correct": false, "explanation": "確認の目的語には『に』を付けない。『答えに確認する』は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表す。確認の対象には使えない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を表す。『答えから確認する』は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "『答えを確認する』の目的語を示す『を』。", "に": "確認の目的語には『に』を付けない。『答えに確認する』は不自然。", "へ": "『へ』は方向を表す。確認の対象には使えない。", "から": "『から』は起点を表す。『答えから確認する』は意味が通らない。"}, "error_tags": {"に": "対象ではない", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37266, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『無事を確認した』の目的語を示す『を』。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表す。無事の状態を確かめる文には使えない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を表す。『無事から確認』は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を表す。ここでは比べる文脈がない。"}], "correct_answer": "を", "explanations": {"を": "『無事を確認した』の目的語を示す『を』。", "へ": "『へ』は方向を表す。無事の状態を確かめる文には使えない。", "から": "『から』は起点を表す。『無事から確認』は意味が通らない。", "より": "『より』は比較を表す。ここでは比べる文脈がない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37266, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ほんとうかどうかをしらべること。", "primary_collocate": null, "pronunciation": "かくにん", "ipa": "kakɯniɴ", "syllable_count": 4, "sentences": [{"text": "出かける前に、かぎを閉めたか確認しました。", "target_word": "確認", "complexity_tier": "T3", "furigana": "出[で]かける前[まえ]に、かぎを閉[し]めたか確認[かくにん]しました。", "sentence_source": "generated"}, {"text": "先生に宿題の答えを確認してもらいました。", "target_word": "確認", "complexity_tier": "T3", "furigana": "先生[せんせい]に宿題[しゅくだい]の答[こた]えを確認[かくにん]してもらいました。", "sentence_source": "generated"}, {"text": "予約の日時をメールで確認します。", "target_word": "確認", "complexity_tier": "T3", "furigana": "予約[よやく]の日時[にちじ]をメールで確認[かくにん]します。", "sentence_source": "generated"}, {"text": "荷物が届いたことを確認してから、連絡してください。", "target_word": "確認", "complexity_tier": "T3", "furigana": "荷物[にもつ]が届[とど]いたことを確認[かくにん]してから、連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "内容をよく確認しないで、サインしてはいけません。", "target_word": "確認", "complexity_tier": "T3", "furigana": "内容[ないよう]をよく確認[かくにん]しないで、サインしてはいけません。", "sentence_source": "generated"}, {"text": "電車の時間を確認したので、遅れずに着きました。", "target_word": "確認", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の時間[じかん]を確認[かくにん]したので、遅[おく]れずに着[つ]きました。", "sentence_source": "generated"}, {"text": "住所が正しいかどうか、もう一度確認をお願いします。", "target_word": "確認", "complexity_tier": "T3", "furigana": "住所[じゅうしょ]が正[ただ]しいかどうか、もう一度[いちど]確認[かくにん]をお願[ねが]いします。", "sentence_source": "generated"}, {"text": "地震のあと、家族みんなの無事を確認した。", "target_word": "確認", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、家族[かぞく]みんなの無事[ぶじ]を確認[かくにん]した。", "sentence_source": "generated"}, {"text": "数字に間違いがないか、二人で確認しながら計算した。", "target_word": "確認", "complexity_tier": "T3", "furigana": "数字[すうじ]に間違[まちが]いがないか、二人[ふたり]で確認[かくにん]しながら計算[けいさん]した。", "sentence_source": "generated"}, {"text": "目で見て確認すると、安心できます。", "target_word": "確認", "complexity_tier": "T3", "furigana": "目[め]で見[み]て確認[かくにん]すると、安心[あんしん]できます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "確認する", "label": "dictionary form"}, {"form": "確認します", "label": "polite form"}, {"form": "確認して", "label": "te-form"}, {"form": "確認した", "label": "past form"}, {"form": "確認しない", "label": "negative form"}], "register": "neutral", "sense_fingerprint": "事実や状態が正しいかどうかを調べて確かめること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 出かける (Zipf 3.95), かぎ (Zipf 3.22), 閉め (Zipf 3.87)']::text[], 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37266, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "確認", "is_correct": true, "explanation": "ここでは『鍵を閉めたかどうかを調べた』の意味で文に合う。"}, {"text": "確保", "is_correct": false, "explanation": "確保は手に入れて守ること。過去の行動を確かめる文脈には合わない。"}, {"text": "予約", "is_correct": false, "explanation": "予約は前もって決めること。『閉めたか予約しました』とは言わない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物を頼むこと。鍵の状態は注文の対象にならず、文として不自然になる。"}], "explanations": {"確認": "ここでは『鍵を閉めたかどうかを調べた』の意味で文に合う。", "確保": "確保は手に入れて守ること。過去の行動を確かめる文脈には合わない。", "予約": "予約は前もって決めること。『閉めたか予約しました』とは言わない。", "注文": "注文は品物を頼むこと。鍵の状態は注文の対象にならず、文として不自然になる。"}, "sentence_index": 0, "correct_answer": "確認"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店で昼ご飯を確認した。", "explanation": "ここは〈注文〉の意味。確認は事実を調べることで、料理を頼む意味では使わない。"}, {"text": "旅行の楽しかった日々を確認して、笑った。", "explanation": "ここは〈思い出す〉の意味。確認は事実を調べることで、記憶をたどる意味では使わない。"}, {"text": "ケーキを確認して、焼いた。", "explanation": "ここは〈焼く〉の意味。確認は事実を調べることで、材料を加熱して作る動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37266, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "確認", "is_correct": true, "explanation": "『もう一度確認をお願いします』の形で、依頼の文に合う。"}, {"text": "出発", "is_correct": false, "explanation": "出発は場所を離れること。『もう一度出発をお願い』とは言わない。"}, {"text": "販売", "is_correct": false, "explanation": "販売は商品を売ること。依頼の文脈に合わない。"}, {"text": "乗車", "is_correct": false, "explanation": "乗車は乗り物に乗ること。ここでは意味が通らない。"}], "explanations": {"確認": "『もう一度確認をお願いします』の形で、依頼の文に合う。", "出発": "出発は場所を離れること。『もう一度出発をお願い』とは言わない。", "販売": "販売は商品を売ること。依頼の文脈に合わない。", "乗車": "乗車は乗り物に乗ること。ここでは意味が通らない。"}, "sentence_index": 6, "correct_answer": "確認"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "舞台に上がると、大きな拍手を確認した。", "explanation": "ここは〈受ける〉の意味。確認は事実を調べることで、拍手を受けて感じ取る意味では使わない。"}, {"text": "試合のあと、選手は大きなため息を確認した。", "explanation": "ここは〈吐く〉の意味。確認は事実を調べることで、息を外に出す動作には使わない。"}, {"text": "ボールを蹴る前に、ゴールの歓声を確認した。", "explanation": "ここは〈聞く〉の意味。確認は事実を調べることで、音を耳で聞き取る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37266, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "書類の内容に確認して、サインしました。", "corrected_sentence": "書類の内容を確認して、サインしました。", "error_description": "『確認』は『〜を確認する』と目的語に『を』をとる。『に』は誤りで、『を』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37266, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "資料の数字に確認しながら、計算した。", "corrected_sentence": "資料の数字を確認しながら、計算した。", "error_description": "『確認』は目的語に『を』をとる。『に』は誤りで、『を』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
