INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37268, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物を育てるための、温度を暖かく保つガラスやプラスチックの部屋。", "primary_collocate": null, "pronunciation": "おんしつ", "ipa": "onɕitsɯ", "syllable_count": 4, "sentences": [{"text": "学校の裏に、生徒たちが野菜を育てる温室がある。", "target_word": "温室", "complexity_tier": "T3", "furigana": "学校[がっこう]の裏[うら]に、生徒[せいと]たちが野菜[やさい]を育[そだ]てる温室[おんしつ]がある。", "sentence_source": "generated"}, {"text": "温室の中は湿度が高く、眼鏡がすぐに曇った。", "target_word": "温室", "complexity_tier": "T3", "furigana": "温室[おんしつ]の中[なか]は湿度[しつど]が高[たか]く、眼鏡[めがね]がすぐに曇[くも]った。", "sentence_source": "generated"}, {"text": "寒い地方では、温室がなければ冬に花を売ることはできない。", "target_word": "温室", "complexity_tier": "T3", "furigana": "寒[さむ]い地方[ちほう]では、温室[おんしつ]がなければ冬[ふゆ]に花[はな]を売[う]ることはできない。", "sentence_source": "generated"}, {"text": "母は小さなプラスチックの温室を買って、ベランダで苗を育て始めた。", "target_word": "温室", "complexity_tier": "T3", "furigana": "母[はは]は小[ちい]さなプラスチックの温室[おんしつ]を買[か]って、ベランダで苗[なえ]を育[そだ]て始[はじ]めた。", "sentence_source": "generated"}, {"text": "夜は温度が下がりすぎないよう、温室のヒーターをつける。", "target_word": "温室", "complexity_tier": "T3", "furigana": "夜[よる]は温度[おんど]が下[さ]がりすぎないよう、温室[おんしつ]のヒーターをつける。", "sentence_source": "generated"}, {"text": "この花は寒さに弱いので、春まで温室に置いておきます。", "target_word": "温室", "complexity_tier": "T3", "furigana": "この花[はな]は寒[さむ]さに弱[よわ]いので、春[はる]まで温室[おんしつ]に置[お]いておきます。", "sentence_source": "generated"}, {"text": "温室で育てたキュウリは、畑で育てたものより早く収穫できた。", "target_word": "温室", "complexity_tier": "T3", "furigana": "温室[おんしつ]で育[そだ]てたキュウリは、畑[はたけ]で育[そだ]てたものより早[はや]く収穫[しゅうかく]できた。", "sentence_source": "generated"}, {"text": "見学の日、私たちは大きな温室の中でバナナの木を見た。", "target_word": "温室", "complexity_tier": "T3", "furigana": "見学[けんがく]の日[ひ]、私[わたし]たちは大[おお]きな温室[おんしつ]の中[なか]でバナナの木[き]を見[み]た。", "sentence_source": "generated"}, {"text": "温室のおかげで、雪の日でも新鮮なレタスが食べられる。", "target_word": "温室", "complexity_tier": "T3", "furigana": "温室[おんしつ]のおかげで、雪[ゆき]の日[ひ]でも新鮮[しんせん]なレタスが食[た]べられる。", "sentence_source": "generated"}, {"text": "温室は暖かいが、夏は暑すぎて、窓を全部開けなければならない。", "target_word": "温室", "complexity_tier": "T3", "furigana": "温室[おんしつ]は暖[あたた]かいが、夏[なつ]は暑[あつ]すぎて、窓[まど]を全部[ぜんぶ]開[あ]けなければならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "温室", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "greenhouse as a warm glass or plastic room for raising plants", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37268, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温室", "is_correct": true, "explanation": "正解。野菜を育てる、暖かく保たれた部屋を指す。"}, {"text": "温泉", "is_correct": false, "explanation": "湯がわく場所で、野菜を育てる場所ではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、野菜を育てる場所にはならない。"}, {"text": "金庫", "is_correct": false, "explanation": "貴重品を保管する箱で、育てる場所にはならない。"}], "explanations": {"温室": "正解。野菜を育てる、暖かく保たれた部屋を指す。", "温泉": "湯がわく場所で、野菜を育てる場所ではない。", "冷蔵庫": "食品を冷やす家電で、野菜を育てる場所にはならない。", "金庫": "貴重品を保管する箱で、育てる場所にはならない。"}, "sentence_index": 0, "correct_answer": "温室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "かき氷用の氷は、温室で保存する。", "explanation": "ここは〈氷室〉（氷を保存する部屋）の意味。温室は中を暖める部屋で、氷を保存する場所としては合わない。"}, {"text": "お風呂の前に、温室で服を脱いでおく。", "explanation": "ここは〈脱衣所〉の意味。温室は植物を育てる部屋で、服を脱ぐ場所としては合わない。"}, {"text": "牛乳は温室に入れて、冷やしておく。", "explanation": "ここは〈冷蔵庫〉の意味。温室は中を暖める部屋なので、牛乳を冷やす用途には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37268, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温室", "is_correct": true, "explanation": "正解。キュウリを育てた施設を指し、「温室で育てた」と続く。"}, {"text": "浴槽", "is_correct": false, "explanation": "湯をためる容器で、キュウリを育てる場所としては合わない。"}, {"text": "冷凍庫", "is_correct": false, "explanation": "食品を凍らせる家電で、育てる場所にはならない。"}, {"text": "物置", "is_correct": false, "explanation": "物を収納する小屋で、キュウリを育てる環境としては合わない。"}], "explanations": {"温室": "正解。キュウリを育てた施設を指し、「温室で育てた」と続く。", "浴槽": "湯をためる容器で、キュウリを育てる場所としては合わない。", "冷凍庫": "食品を凍らせる家電で、育てる場所にはならない。", "物置": "物を収納する小屋で、キュウリを育てる環境としては合わない。"}, "sentence_index": 6, "correct_answer": "温室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パン生地は温室に入れて、ふくらませる。", "explanation": "ここは〈ホイロ〉（生地を発酵させる装置）の意味。温室は植物を育てる部屋で、生地をふくらませる場所としては合わない。"}, {"text": "早産の赤ちゃんは温室で体温を保つ。", "explanation": "ここは〈保育器〉の意味。温室は植物用の施設で、赤ちゃんを入れる医療機器の用途には合わない。"}, {"text": "寒い夜は温室でじっくり汗を流す。", "explanation": "ここは〈サウナ〉の意味。温室は植物を育てる施設で、人が汗を流す場所としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37268, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は庭の温室に、蘭を育てている。", "corrected_sentence": "祖父は庭の温室で、蘭を育てている。", "error_description": "「温室に」の「に」が誤り。育てる場所を示すには「で」が必要で、「に」では到着点の意味になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37268, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬は温室を冷やして、苗を寒さから守る。", "corrected_sentence": "冬は温室を暖めて、苗を寒さから守る。", "error_description": "「冷やして」が誤り。寒さから苗を守るには温室を「暖める」必要があり、「冷やす」は目的と逆になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37269, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37269, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「温室で育てる」と行為が行われる場所を示す「で」。ここが正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」なので、「温室が育てると」は場所を表せない。"}, {"text": "と", "is_correct": false, "explanation": "共同や相手を示す「と」は、「温室と育てると」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す「より」は、場所を表す文脈に合わない。"}], "correct_answer": "で", "explanations": {"で": "「温室で育てる」と行為が行われる場所を示す「で」。ここが正解。", "が": "主語を示す「が」なので、「温室が育てると」は場所を表せない。", "と": "共同や相手を示す「と」は、「温室と育てると」では意味が通らない。", "より": "比較の基準を示す「より」は、場所を表す文脈に合わない。"}, "error_tags": {"が": "主語の格", "と": "共同・相手の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37269, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の生育に適した温度を保つために作られた施設。主にガラスや透明な屋根で覆われ、太陽光を利用して内部を暖める。", "primary_collocate": null, "pronunciation": "おんしつ", "ipa": "onɕitsɯ", "syllable_count": 4, "sentences": [{"text": "冬の朝、父は庭の温室で、イチゴの苗に水をやった。", "target_word": "温室", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]、父[ちち]は庭[にわ]の温室[おんしつ]で、イチゴの苗[なえ]に水[みず]をやった。", "sentence_source": "generated"}, {"text": "冬でもトマトを育てられるのは、温室の中がいつも暖かいからだ。", "target_word": "温室", "complexity_tier": "T3", "furigana": "冬[ふゆ]でもトマトを育[そだ]てられるのは、温室[おんしつ]の中[なか]がいつも暖[あたた]かいからだ。", "sentence_source": "generated"}, {"text": "祖父は庭に小さな温室を作って、蘭を育てている。", "target_word": "温室", "complexity_tier": "T3", "furigana": "祖父[そふ]は庭[にわ]に小[ちい]さな温室[おんしつ]を作[つく]って、蘭[らん]を育[そだ]てている。", "sentence_source": "generated"}, {"text": "温室のガラスが割れたので、中の苗が寒さで枯れてしまった。", "target_word": "温室", "complexity_tier": "T3", "furigana": "温室[おんしつ]のガラスが割[わ]れたので、中[なか]の苗[なえ]が寒[さむ]さで枯[か]れてしまった。", "sentence_source": "generated"}, {"text": "この植物園の温室には、熱帯の花がたくさん咲いている。", "target_word": "温室", "complexity_tier": "T3", "furigana": "この植物園[しょくぶつえん]の温室[おんしつ]には、熱帯[ねったい]の花[はな]がたくさん咲[さ]いている。", "sentence_source": "generated"}, {"text": "外は雪だが、温室に入ると汗が出るほど暑い。", "target_word": "温室", "complexity_tier": "T3", "furigana": "外[そと]は雪[ゆき]だが、温室[おんしつ]に入[はい]ると汗[あせ]が出[で]るほど暑[あつ]い。", "sentence_source": "generated"}, {"text": "農家の人は朝、温室の窓を開けて、中の熱を逃がす。", "target_word": "温室", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は朝[あさ]、温室[おんしつ]の窓[まど]を開[あ]けて、中[なか]の熱[ねつ]を逃[に]がす。", "sentence_source": "generated"}, {"text": "イチゴは温室で育てると、真冬でも甘い実がなる。", "target_word": "温室", "complexity_tier": "T3", "furigana": "イチゴは温室[おんしつ]で育[そだ]てると、真冬[まふゆ]でも甘[あま]い実[み]がなる。", "sentence_source": "generated"}, {"text": "温室は太陽の光で中を暖めるので、暖房費が少なくて済む。", "target_word": "温室", "complexity_tier": "T4", "furigana": "温室[おんしつ]は太陽[たいよう]の光[ひかり]で中[なか]を暖[あたた]めるので、暖房費[だんぼうひ]が少[すく]なくて済[す]む。", "sentence_source": "generated"}, {"text": "台風が近づいているため、温室のビニールを補強した。", "target_word": "温室", "complexity_tier": "T4", "furigana": "台風[たいふう]が近[ちか]づいているため、温室[おんしつ]のビニールを補強[ほきょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "温室", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "greenhouse as a heated facility for growing plants, covered with glass or transparent roof using sunlight", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37269, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温室", "is_correct": true, "explanation": "正解。植物を育てるために暖かく保たれた、庭の施設を指す。"}, {"text": "温泉", "is_correct": false, "explanation": "湯がわく場所で、苗に水をやる場所ではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、苗を育てる場所にはならない。"}, {"text": "金庫", "is_correct": false, "explanation": "貴重品を保管する箱で、苗を育てる場所にはならない。"}], "explanations": {"温室": "正解。植物を育てるために暖かく保たれた、庭の施設を指す。", "温泉": "湯がわく場所で、苗に水をやる場所ではない。", "冷蔵庫": "食品を冷やす家電で、苗を育てる場所にはならない。", "金庫": "貴重品を保管する箱で、苗を育てる場所にはならない。"}, "sentence_index": 0, "correct_answer": "温室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暑い日は、温室で涼んでから出かけた。", "explanation": "ここは〈冷房の効いた部屋で涼む〉の意味。温室は中を暖める施設なので、涼む場所としては合わない。"}, {"text": "週末は山奥の温室で、足湯につかってのんびりした。", "explanation": "ここは〈温泉〉の意味。温室は植物を育てる施設で、人が足湯につかる場所ではないので合わない。"}, {"text": "食材を余らせないよう、温室の中で凍らせて保存した。", "explanation": "ここは〈冷凍庫〉の意味。温室は中を暖める施設なので、食材を凍らせて保存する場所としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37269, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温室", "is_correct": true, "explanation": "正解。窓を開けて中の熱を逃がす農業用の施設を指す。"}, {"text": "金魚鉢", "is_correct": false, "explanation": "金魚を飼う水の入った容器で、窓を開けて熱を逃がす農家の施設ではない。"}, {"text": "書棚", "is_correct": false, "explanation": "本を並べる家具で、熱を逃がすために窓を開ける施設ではない。"}, {"text": "浴槽", "is_correct": false, "explanation": "湯をためる容器で、窓を開けて熱を逃がす農家の施設ではない。"}], "explanations": {"温室": "正解。窓を開けて中の熱を逃がす農業用の施設を指す。", "金魚鉢": "金魚を飼う水の入った容器で、窓を開けて熱を逃がす農家の施設ではない。", "書棚": "本を並べる家具で、熱を逃がすために窓を開ける施設ではない。", "浴槽": "湯をためる容器で、窓を開けて熱を逃がす農家の施設ではない。"}, "sentence_index": 6, "correct_answer": "温室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疲れた日は温室で汗を流して、体をほぐす。", "explanation": "ここは〈サウナ〉の意味。温室は植物のための施設で、人が汗を流す場所としては使わない。"}, {"text": "未熟児は温室の中で、体温を保って育てられる。", "explanation": "ここは〈保育器〉の意味。温室は植物用の施設で、未熟児を入れる医療機器の用途には合わない。"}, {"text": "ふかし芋は、温室で二十分ふかして作る。", "explanation": "ここは〈蒸し器〉の意味。温室は食べ物を加熱する器具ではなく、芋をふかす場所としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37269, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "温室を冬野菜を育てると、寒さに当てずに済む。", "corrected_sentence": "温室で冬野菜を育てると、寒さに当てずに済む。", "error_description": "「温室を」の「を」が誤り。場所を示す「で」が正しい（温室は育てる対象ではなく、育てる場所）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37269, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年、祖父は庭に温室を建てる。", "corrected_sentence": "去年、祖父は庭に温室を建てた。", "error_description": "「建てる」は非過去形で、過去を表す「去年」と合わない。過去形の「建てた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37270, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37270, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「歩行でも」の「で」。「長時間歩いても」の意味で、状態・場面を表す「でも」の一部。"}, {"text": "を", "is_correct": false, "explanation": "「歩行を」は目的語になり、「〜も疲れにくい」とつながらず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。歩行は行き先ではないので、「歩行へも」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。歩行と並べる対象がなく、「歩行とも」は意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「歩行でも」の「で」。「長時間歩いても」の意味で、状態・場面を表す「でも」の一部。", "を": "「歩行を」は目的語になり、「〜も疲れにくい」とつながらず文が成り立たない。", "へ": "方向を表す「へ」。歩行は行き先ではないので、「歩行へも」は意味が通らない。", "と": "並列の「と」。歩行と並べる対象がなく、「歩行とも」は意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37270, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "歩くという意味の言葉です。", "primary_collocate": null, "pronunciation": "ほこう", "ipa": "hokoː", "syllable_count": 3, "sentences": [{"text": "足をけがして、歩行が難しくなった。", "target_word": "歩行", "complexity_tier": "T3", "furigana": "足[あし]をけがして、歩行[ほこう]が難[むずか]しくなった。", "sentence_source": "generated"}, {"text": "おじいさんは杖を使って、ゆっくり歩行している。", "target_word": "歩行", "complexity_tier": "T3", "furigana": "おじいさんは杖[つえ]を使[つか]って、ゆっくり歩行[ほこう]している。", "sentence_source": "generated"}, {"text": "赤ちゃんは一歳ごろに歩行を始める。", "target_word": "歩行", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは一歳[いっさい]ごろに歩行[ほこう]を始[はじ]める。", "sentence_source": "generated"}, {"text": "歩行が安定するように、毎日少し運動している。", "target_word": "歩行", "complexity_tier": "T3", "furigana": "歩行[ほこう]が安定[あんてい]するように、毎日[まいにち]少[すこ]し運動[うんどう]している。", "sentence_source": "generated"}, {"text": "雨の日は道がすべるので、歩行に気をつけなければならない。", "target_word": "歩行", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は道[みち]がすべるので、歩行[ほこう]に気[き]をつけなければならない。", "sentence_source": "generated"}, {"text": "長い入院のあと、彼女は歩行の練習を始めた。", "target_word": "歩行", "complexity_tier": "T3", "furigana": "長[なが]い入院[にゅういん]のあと、彼女[かのじょ]は歩行[ほこう]の練習[れんしゅう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "暗い道で歩行しながらスマホを見るのは危ない。", "target_word": "歩行", "complexity_tier": "T3", "furigana": "暗[くら]い道[みち]で歩行[ほこう]しながらスマホを見[み]るのは危[あぶ]ない。", "sentence_source": "generated"}, {"text": "この靴は軽いので、長時間の歩行でも疲れにくい。", "target_word": "歩行", "complexity_tier": "T3", "furigana": "この靴[くつ]は軽[かる]いので、長時間[ちょうじかん]の歩行[ほこう]でも疲[つか]れにくい。", "sentence_source": "generated"}, {"text": "先生は、歩行のときの姿勢を直してくれた。", "target_word": "歩行", "complexity_tier": "T3", "furigana": "先生[せんせい]は、歩行[ほこう]のときの姿勢[しせい]を直[なお]してくれた。", "sentence_source": "generated"}, {"text": "二本足での歩行は、人間の大きな特徴だ。", "target_word": "歩行", "complexity_tier": "T3", "furigana": "二本足[にほんあし]での歩行[ほこう]は、人間[にんげん]の大[おお]きな特徴[とくちょう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歩行", "label": "基本形"}, {"form": "歩行する", "label": "終止形（する）"}, {"form": "歩行した", "label": "過去形"}, {"form": "歩行して", "label": "て形"}], "register": "formal", "sense_fingerprint": "人や動物が足で歩くこと。する動詞としても使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8135be4b-f00d-40ac-8845-1284b6ffb713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37270, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歩行", "is_correct": true, "explanation": "足をけがして難しくなるのは、足で歩くこと。ここに歩行が入る。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は足のけがの影響を受けない作業で、「足をけがして」という原因の文脈に合わない。"}, {"text": "会計", "is_correct": false, "explanation": "会計はけがで体が不自由になっても直接難しくなる作業ではなく、この文の流れに合わない。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は足のけがと結びつかず、「足をけがして、作曲が難しくなった」は文脈が成り立たない。"}], "explanations": {"歩行": "足をけがして難しくなるのは、足で歩くこと。ここに歩行が入る。", "翻訳": "翻訳は足のけがの影響を受けない作業で、「足をけがして」という原因の文脈に合わない。", "会計": "会計はけがで体が不自由になっても直接難しくなる作業ではなく、この文の流れに合わない。", "作曲": "作曲は足のけがと結びつかず、「足をけがして、作曲が難しくなった」は文脈が成り立たない。"}, "sentence_index": 0, "correct_answer": "歩行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "トラックは山道をゆっくり歩行した。", "explanation": "ここは〈走行〉の意味。歩行は足で歩く動きを指すので、車両が進むことには使わない。"}, {"text": "台風の影響で、電車の歩行がすべて止まった。", "explanation": "ここは〈運行〉の意味。電車やバスのダイヤどおりの運転には、足で歩く歩行は使わない。"}, {"text": "鳥は羽を広げて、空を歩行した。", "explanation": "ここは〈飛行〉の意味。空を飛ぶ動きには、地面を足で歩くことを表す歩行は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37270, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歩行", "is_correct": true, "explanation": "暗い道を歩きながらスマホを見る、という意味になり、歩行が入る。"}, {"text": "会議", "is_correct": false, "explanation": "会議は道を歩きながら行うものではなく、「暗い道で会議しながら」は成り立たない。"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯は道を歩きながらする家事ではなく、この文の場面に合わない。"}, {"text": "採点", "is_correct": false, "explanation": "採点は道で歩きながら行う作業ではなく、文の意味が通らない。"}], "explanations": {"歩行": "暗い道を歩きながらスマホを見る、という意味になり、歩行が入る。", "会議": "会議は道を歩きながら行うものではなく、「暗い道で会議しながら」は成り立たない。", "洗濯": "洗濯は道を歩きながらする家事ではなく、この文の場面に合わない。", "採点": "採点は道で歩きながら行う作業ではなく、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "歩行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議は予定どおり歩行した。", "explanation": "ここは〈進行〉の意味。会議や行事の進み具合を表すのに、足で歩く歩行は使わない。"}, {"text": "会社は来期、海外市場へ歩行する計画だ。", "explanation": "ここは〈進出〉の意味。市場や分野へ広げる動きには、足で歩く歩行は使わない。"}, {"text": "景気は一年で歩行した。", "explanation": "ここは〈推移〉の意味。景気や状態の移り変わりには、歩行は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37270, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は道がすべるので、歩行を特に気をつけてください。", "corrected_sentence": "雨の日は道がすべるので、歩行に特に気をつけてください。", "error_description": "「気をつける」は「〜に」を取るので、「歩行を」は誤り。正しくは「歩行に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37270, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "赤ちゃんがそろそろ歩行を始まる時期だ。", "corrected_sentence": "赤ちゃんがそろそろ歩行を始める時期だ。", "error_description": "「始める」は「歩行を」を目的語に取る他動詞。「始まる」は自動詞なので「歩行を」と合わない。正しくは「始める」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37272, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「自転が」の「が」。「ある」の主語を示し、自転の存在を述べる。"}, {"text": "を", "is_correct": false, "explanation": "「自転を」は目的語になり、「ある」と結びつかず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。自転は行き先ではないので、「自転へ」は文脈に合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。自転と並べる対象がなく、「自転と、ある」は文の流れに合わない。"}], "correct_answer": "が", "explanations": {"が": "「自転が」の「が」。「ある」の主語を示し、自転の存在を述べる。", "を": "「自転を」は目的語になり、「ある」と結びつかず文が成り立たない。", "へ": "方向を表す「へ」。自転は行き先ではないので、「自転へ」は文脈に合わない。", "と": "並列の「と」。自転と並べる対象がなく、「自転と、ある」は文の流れに合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37272, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37272, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ちきゅうなどが じぶんで くるくる まわる こと。", "primary_collocate": null, "pronunciation": "じてん", "ipa": "dʑiteɴ", "syllable_count": 3, "sentences": [{"text": "地球は一日に一回、自転している。", "target_word": "自転", "complexity_tier": "T3", "furigana": "地球(ちきゅう)は一日(いちにち)に一回(いっかい)、自転(じてん)している。", "sentence_source": "generated"}, {"text": "自転があるから、朝と夜が来る。", "target_word": "自転", "complexity_tier": "T3", "furigana": "自転(じてん)があるから、朝(あさ)と夜(よる)が来(く)る。", "sentence_source": "generated"}, {"text": "地球の自転は速いのに、私たちは動きを感じない。", "target_word": "自転", "complexity_tier": "T3", "furigana": "地球(ちきゅう)の自転(じてん)は速(はや)いのに、私(わたし)たちは動(うご)きを感(かん)じない。", "sentence_source": "generated"}, {"text": "月の自転はとても遅く、一周に約一か月かかる。", "target_word": "自転", "complexity_tier": "T3", "furigana": "月(つき)の自転(じてん)はとても遅(おそ)く、一周(いっしゅう)に約(やく)一(いっ)か月(げつ)かかる。", "sentence_source": "generated"}, {"text": "自転が止まったら、昼だけの場所と夜だけの場所ができる。", "target_word": "自転", "complexity_tier": "T3", "furigana": "自転(じてん)が止(と)まったら、昼(ひる)だけの場所(ばしょ)と夜(よる)だけの場所(ばしょ)ができる。", "sentence_source": "generated"}, {"text": "先生は地球儀を回して、自転のしかたを見せた。", "target_word": "自転", "complexity_tier": "T3", "furigana": "先生(せんせい)は地球儀(ちきゅうぎ)を回(まわ)して、自転(じてん)のしかたを見(み)せた。", "sentence_source": "generated"}, {"text": "地球が自転するので、太陽は東からのぼる。", "target_word": "自転", "complexity_tier": "T3", "furigana": "地球(ちきゅう)が自転(じてん)するので、太陽(たいよう)は東(ひがし)からのぼる。", "sentence_source": "generated"}, {"text": "木星も自転していて、一日が十時間ほどしかない。", "target_word": "自転", "complexity_tier": "T3", "furigana": "木星(もくせい)も自転(じてん)していて、一日(いちにち)が十時間(じゅうじかん)ほどしかない。", "sentence_source": "generated"}, {"text": "自転の向きは、北極の上から見ると反時計回りだ。", "target_word": "自転", "complexity_tier": "T3", "furigana": "自転(じてん)の向(む)きは、北極(ほっきょく)の上(うえ)から見(み)ると反時計回(はんとけいまわ)りだ。", "sentence_source": "generated"}, {"text": "昔の人は、空が動くと思い、地球の自転を知らなかった。", "target_word": "自転", "complexity_tier": "T3", "furigana": "昔(むかし)の人(ひと)は、空(そら)が動(うご)くと思(おも)い、地球(ちきゅう)の自転(じてん)を知(し)らなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自転する", "label": "する形"}, {"form": "自転している", "label": "ている形"}, {"form": "自転した", "label": "た形"}, {"form": "自転しない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "地球などが自分で回ること(やさしい説明)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8135be4b-f00d-40ac-8845-1284b6ffb713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37272, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自転", "is_correct": true, "explanation": "地球が自分で一日に一回回る、という意味で「自転」が入る。"}, {"text": "散歩", "is_correct": false, "explanation": "地球は散歩しないので、「地球は一日に一回、散歩している」は文の内容に合わない。"}, {"text": "料理", "is_correct": false, "explanation": "地球は料理をしないので、一日一回の動きを表す語として文が成り立たない。"}, {"text": "会議", "is_correct": false, "explanation": "地球は会議をしないので、一日に一回の周期的な動きを表す語として合わない。"}], "explanations": {"自転": "地球が自分で一日に一回回る、という意味で「自転」が入る。", "散歩": "地球は散歩しないので、「地球は一日に一回、散歩している」は文の内容に合わない。", "料理": "地球は料理をしないので、一日一回の動きを表す語として文が成り立たない。", "会議": "地球は会議をしないので、一日に一回の周期的な動きを表す語として合わない。"}, "sentence_index": 0, "correct_answer": "自転"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地球は太陽のまわりを自転している。", "explanation": "ここは〈公転〉の意味。太陽のまわりを回る動きは自転ではなく公転と言う。"}, {"text": "人口が十年で自転して、二倍に増えた。", "explanation": "ここは〈増加〉の意味。人口の増加には、軸まわりの回転を表す自転は使わない。"}, {"text": "ランナーは公園の池のまわりを自転した。", "explanation": "ここは〈周回〉の意味。池のまわりを外側から回る動きには、自転は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37272, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自転", "is_correct": true, "explanation": "地球が自分の軸で回るので太陽が東から昇る、という理由になり、「自転する」の形で入る。"}, {"text": "点滅", "is_correct": false, "explanation": "点滅は光が明滅することで、地球が東から太陽が昇る理由にならず、文の意味が通らない。"}, {"text": "発熱", "is_correct": false, "explanation": "発熱は地球の状態を表す語ではなく、太陽が東から昇る理由として成り立たない。"}, {"text": "入浴", "is_correct": false, "explanation": "地球は入浴しないので、太陽が東から昇る理由として文が成り立たない。"}], "explanations": {"自転": "地球が自分の軸で回るので太陽が東から昇る、という理由になり、「自転する」の形で入る。", "点滅": "点滅は光が明滅することで、地球が東から太陽が昇る理由にならず、文の意味が通らない。", "発熱": "発熱は地球の状態を表す語ではなく、太陽が東から昇る理由として成り立たない。", "入浴": "地球は入浴しないので、太陽が東から昇る理由として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "自転"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "血液は心臓から全身を自転して、また心臓に戻る。", "explanation": "ここは〈循環〉の意味。血液が体の中を巡ることには、自分の軸で回る自転は使わない。"}, {"text": "バスが交差点で自転して、反対方向を向いた。", "explanation": "ここは〈転回〉の意味。進む向きを反対にする動きには、軸まわりの自転は使わない。"}, {"text": "飛行機は空港の上空を自転して、着陸の順番を待った。", "explanation": "ここは〈旋回〉の意味。空中で円を描いて回る動きには、自転は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37272, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地球の自転を遅くなると、一日が長くなる。", "corrected_sentence": "地球の自転が遅くなると、一日が長くなる。", "error_description": "「遅くなる」の主語は「自転が」。「自転を」は誤りで、正しくは「自転が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37272, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地球の自転が止めると、一日の区別がなくなる。", "corrected_sentence": "地球の自転が止まると、一日の区別がなくなる。", "error_description": "主語「自転が」には自動詞「止まる」が合う。「止める」は他動詞で行為者を必要とするので誤り。正しくは「止まる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37273, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「自転は」の「は」。金星の自転について述べる主題を示す。"}, {"text": "を", "is_correct": false, "explanation": "「自転を」は目的語になり、「逆向きで、とても遅い」の主題にならず文が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。自転は行き先ではないので、文脈に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」。自転を起点とする文脈がなく、文の流れに合わない。"}], "correct_answer": "は", "explanations": {"は": "「自転は」の「は」。金星の自転について述べる主題を示す。", "を": "「自転を」は目的語になり、「逆向きで、とても遅い」の主題にならず文が崩れる。", "へ": "方向を表す「へ」。自転は行き先ではないので、文脈に合わない。", "から": "起点を表す「から」。自転を起点とする文脈がなく、文の流れに合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37273, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37273, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "天体が、自分の軸を中心として回ること。", "primary_collocate": null, "pronunciation": "じてん", "ipa": "dʑiteɴ", "syllable_count": 3, "sentences": [{"text": "惑星は自分の軸を中心に自転しながら、太陽のまわりを公転する。", "target_word": "自転", "complexity_tier": "T4", "furigana": "惑星(わくせい)は自分(じぶん)の軸(じく)を中心(ちゅうしん)に自転(じてん)しながら、太陽(たいよう)のまわりを公転(こうてん)する。", "sentence_source": "generated"}, {"text": "金星の自転は、ほかの惑星と逆向きで、とても遅い。", "target_word": "自転", "complexity_tier": "T3", "furigana": "金星(きんせい)の自転(じてん)は、ほかの惑星(わくせい)と逆向(ぎゃくむ)きで、とても遅(おそ)い。", "sentence_source": "generated"}, {"text": "地球の自転の軸は、少し傾いている。", "target_word": "自転", "complexity_tier": "T3", "furigana": "地球(ちきゅう)の自転(じてん)の軸(じく)は、少(すこ)し傾(かたむ)いている。", "sentence_source": "generated"}, {"text": "自転の速さは、天体によって大きく違う。", "target_word": "自転", "complexity_tier": "T3", "furigana": "自転(じてん)の速(はや)さは、天体(てんたい)によって大(おお)きく違(ちが)う。", "sentence_source": "generated"}, {"text": "木星は自転が速いため、形が少し平たい。", "target_word": "自転", "complexity_tier": "T3", "furigana": "木星(もくせい)は自転(じてん)が速(はや)いため、形(かたち)が少(すこ)し平(ひら)たい。", "sentence_source": "generated"}, {"text": "自転が速い星ほど、一日の長さが短くなる。", "target_word": "自転", "complexity_tier": "T3", "furigana": "自転(じてん)が速(はや)い星(ほし)ほど、一日(いちにち)の長(なが)さが短(みじか)くなる。", "sentence_source": "generated"}, {"text": "天文学者は、望遠鏡で星の自転を観測した。", "target_word": "自転", "complexity_tier": "T3", "furigana": "天文学者(てんもんがくしゃ)は、望遠鏡(ぼうえんきょう)で星(ほし)の自転(じてん)を観測(かんそく)した。", "sentence_source": "generated"}, {"text": "太陽も自転していて、場所によって回る速さが違う。", "target_word": "自転", "complexity_tier": "T3", "furigana": "太陽(たいよう)も自転(じてん)していて、場所(ばしょ)によって回(まわ)る速(はや)さが違(ちが)う。", "sentence_source": "generated"}, {"text": "自転する地球の上では、風がまっすぐ進まず曲がる。", "target_word": "自転", "complexity_tier": "T3", "furigana": "自転(じてん)する地球(ちきゅう)の上(うえ)では、風(かぜ)がまっすぐ進(すす)まず曲(ま)がる。", "sentence_source": "generated"}, {"text": "月は自転と公転の時間が同じなので、いつも同じ面を地球に向ける。", "target_word": "自転", "complexity_tier": "T4", "furigana": "月(つき)は自転(じてん)と公転(こうてん)の時間(じかん)が同(おな)じなので、いつも同(おな)じ面(めん)を地球(ちきゅう)に向(む)ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自転する", "label": "する形"}, {"form": "自転している", "label": "ている形"}, {"form": "自転した", "label": "た形"}, {"form": "自転しない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "天体が自分の軸を中心に回ること(天文・理科の説明)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8135be4b-f00d-40ac-8845-1284b6ffb713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37273, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自転", "is_correct": true, "explanation": "惑星が自分の軸を中心に回るという意味を表し、「自転しながら」の形で入る。"}, {"text": "散歩", "is_correct": false, "explanation": "惑星は散歩しないので、軸まわりの回転を表す語として合わない。"}, {"text": "会話", "is_correct": false, "explanation": "惑星は会話をしないので、この文の天体の動きの説明に合わない。"}, {"text": "料理", "is_correct": false, "explanation": "惑星は料理をしないので、「料理しながら、太陽のまわりを公転する」は文の内容が成り立たない。"}], "explanations": {"自転": "惑星が自分の軸を中心に回るという意味を表し、「自転しながら」の形で入る。", "散歩": "惑星は散歩しないので、軸まわりの回転を表す語として合わない。", "会話": "惑星は会話をしないので、この文の天体の動きの説明に合わない。", "料理": "惑星は料理をしないので、「料理しながら、太陽のまわりを公転する」は文の内容が成り立たない。"}, "sentence_index": 0, "correct_answer": "自転"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "惑星は太陽のまわりを自転しながら、一年かけて回る。", "explanation": "ここは〈公転〉の意味。太陽のまわりを回る動きには、自転ではなく公転を使う。"}, {"text": "物価が一年で自転して、二割上がった。", "explanation": "ここは〈上昇〉の意味。物価の上がり方には、軸まわりの回転を表す自転は使わない。"}, {"text": "飛行機が空港の上空で自転した。", "explanation": "ここは〈旋回〉の意味。空中で円を描いて回る動きには、軸まわりの自転は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37273, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自転", "is_correct": true, "explanation": "望遠鏡で星が軸まわりに回る様子を観測する、という意味になり、「星の自転」の形で入る。"}, {"text": "翻訳", "is_correct": false, "explanation": "星の翻訳を観測するのは成り立たず、この文の観測対象に合わない。"}, {"text": "採点", "is_correct": false, "explanation": "星の採点を観測するのは意味が通らず、天文学の観測対象として合わない。"}, {"text": "入浴", "is_correct": false, "explanation": "星の入浴を観測するのは意味が通らず、文の内容に合わない。"}], "explanations": {"自転": "望遠鏡で星が軸まわりに回る様子を観測する、という意味になり、「星の自転」の形で入る。", "翻訳": "星の翻訳を観測するのは成り立たず、この文の観測対象に合わない。", "採点": "星の採点を観測するのは意味が通らず、天文学の観測対象として合わない。", "入浴": "星の入浴を観測するのは意味が通らず、文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "自転"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "血液は心臓から全身を自転して、また心臓に戻る。", "explanation": "ここは〈循環〉の意味。血液が体の中を巡ることには、自分の軸で回る自転は使わない。"}, {"text": "バスが交差点で自転して、反対方向を向いた。", "explanation": "ここは〈転回〉の意味。進む向きを反対にする動きには、軸まわりの自転は使わない。"}, {"text": "選手たちは競技場を何周も自転した。", "explanation": "ここは〈周回〉の意味。競技場の外側を何周も回る動きには、自転は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37273, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "土星は自転を速く、一日が短い。", "corrected_sentence": "土星は自転が速く、一日が短い。", "error_description": "「速い」は「〜が速い」の形を取るので、「自転を」は誤り。正しくは「自転が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37273, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、望遠鏡で星の自転を測定された。", "corrected_sentence": "研究者は、望遠鏡で星の自転を測定した。", "error_description": "「測定する」の行為者は「研究者は」。能動態の「測定した」が正しく、「測定された」は受け身で主語と行為者が合わないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37274, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「連携」が主語になり、「大切だ」が続く形。「料理は、みんなの連携が大切だ」で正しい。"}, {"text": "を", "is_correct": false, "explanation": "を は他動詞の目的語を示すが、「大切だ」は目的語を取らないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "に は帰着点や相手を示す。「連携に大切だ」は「大切だ」と結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "で は場所や手段を示す。「連携で大切だ」では、連携が大切だという意味が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「連携」が主語になり、「大切だ」が続く形。「料理は、みんなの連携が大切だ」で正しい。", "を": "を は他動詞の目的語を示すが、「大切だ」は目的語を取らないので合わない。", "に": "に は帰着点や相手を示す。「連携に大切だ」は「大切だ」と結びつかない。", "で": "で は場所や手段を示す。「連携で大切だ」では、連携が大切だという意味が成り立たない。"}, "error_tags": {"を": "目的語", "に": "帰着点・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37274, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「連携」が主語になり、「よく」と続く形。「彼らは連携がよく、言葉がなくても動ける」で正しい。"}, {"text": "へ", "is_correct": false, "explanation": "へ は方向を示す。「連携へよく」は、よい状態を表す形として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "から は起点や理由を示す。ここでは連携の状態を示す働きがなく合わない。"}, {"text": "の", "is_correct": false, "explanation": "の は名詞を修飾する。「連携のよく」は続かず、主語と述語の関係が作れない。"}], "correct_answer": "が", "explanations": {"が": "「連携」が主語になり、「よく」と続く形。「彼らは連携がよく、言葉がなくても動ける」で正しい。", "へ": "へ は方向を示す。「連携へよく」は、よい状態を表す形として成り立たない。", "から": "から は起点や理由を示す。ここでは連携の状態を示す働きがなく合わない。", "の": "の は名詞を修飾する。「連携のよく」は続かず、主語と述語の関係が作れない。"}, "error_tags": {"へ": "方向", "から": "起点・理由", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37274, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人と人がいっしょに動くこと。", "primary_collocate": null, "pronunciation": "れんけい", "ipa": "ɾeŋkeː", "syllable_count": 4, "sentences": [{"text": "二人の連携がよくて、試合に勝てた。", "target_word": "連携", "complexity_tier": "T3", "furigana": "二人(ふたり)の連携(れんけい)がよくて、試合(しあい)に勝(か)てた。", "sentence_source": "generated"}, {"text": "料理は、みんなの連携が大切だ。", "target_word": "連携", "complexity_tier": "T3", "furigana": "料理(りょうり)は、みんなの連携(れんけい)が大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "連携がとれていないと、仕事が進まない。", "target_word": "連携", "complexity_tier": "T3", "furigana": "連携(れんけい)がとれていないと、仕事(しごと)が進(すす)まない。", "sentence_source": "generated"}, {"text": "サッカーでは、パスの連携が上手なチームが強い。", "target_word": "連携", "complexity_tier": "T3", "furigana": "サッカーでは、パスの連携(れんけい)が上手(じょうず)なチームが強(つよ)い。", "sentence_source": "generated"}, {"text": "引っ越しの日は、家族の連携で一日で終わった。", "target_word": "連携", "complexity_tier": "T3", "furigana": "引(ひ)っ越(こ)しの日(ひ)は、家族(かぞく)の連携(れんけい)で一日(いちにち)で終(お)わった。", "sentence_source": "generated"}, {"text": "連携が悪かったため、二人は同じ荷物を二回運んだ。", "target_word": "連携", "complexity_tier": "T3", "furigana": "連携(れんけい)が悪(わる)かったため、二人(ふたり)は同(おな)じ荷物(にもつ)を二回(にかい)運(はこ)んだ。", "sentence_source": "generated"}, {"text": "先生と親が連携して、子どもを見守っている。", "target_word": "連携", "complexity_tier": "T3", "furigana": "先生(せんせい)と親(おや)が連携(れんけい)して、子(こ)どもを見守(みまも)っている。", "sentence_source": "generated"}, {"text": "彼らは連携がよく、言葉がなくても動ける。", "target_word": "連携", "complexity_tier": "T3", "furigana": "彼(かれ)らは連携(れんけい)がよく、言葉(ことば)がなくても動(うご)ける。", "sentence_source": "generated"}, {"text": "劇の本番前に、みんなで連携の練習をした。", "target_word": "連携", "complexity_tier": "T3", "furigana": "劇(げき)の本番前(ほんばんまえ)に、みんなで連携(れんけい)の練習(れんしゅう)をした。", "sentence_source": "generated"}, {"text": "連携が足りず、私たちは別々の場所で待っていた。", "target_word": "連携", "complexity_tier": "T3", "furigana": "連携(れんけい)が足(た)りず、私(わたし)たちは別々(べつべつ)の場所(ばしょ)で待(ま)っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連携する", "label": "する形"}, {"form": "連携して", "label": "て形"}, {"form": "連携した", "label": "た形"}, {"form": "連携しない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "人どうしが息を合わせていっしょに動くこと(身近な場面)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8135be4b-f00d-40ac-8845-1284b6ffb713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37274, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連携", "is_correct": true, "explanation": "人どうしが息を合わせて動くことを表し、「二人の連携がよくて、試合に勝てた」の空欄に合う。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す語で、二人が息を合わせて動く様子は表せない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るときに使う道具のことで、試合での二人の動きの良さとは結びつかない。"}, {"text": "食器", "is_correct": false, "explanation": "料理を盛る道具のことで、二人が試合でどう動いたかを表せない。"}], "explanations": {"連携": "人どうしが息を合わせて動くことを表し、「二人の連携がよくて、試合に勝てた」の空欄に合う。", "体重": "体の重さを表す語で、二人が息を合わせて動く様子は表せない。", "寝具": "寝るときに使う道具のことで、試合での二人の動きの良さとは結びつかない。", "食器": "料理を盛る道具のことで、二人が試合でどう動いたかを表せない。"}, "sentence_index": 0, "correct_answer": "連携"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人の関係が連携した。", "explanation": "ここは〈断絶〉の意味。関係が途切れることは、いっしょに動く連携とは反対なので合わない。"}, {"text": "雨で試合が中止になり、私は連携を取り消した。", "explanation": "ここは〈取り消し〉の意味。予定をなくすことは、いっしょに動く連携とは反対なので合わない。"}, {"text": "明日休むときは、先生に連携してください。", "explanation": "ここは〈連絡〉の意味。知らせるだけの行為には連携を使わず、一緒に動く関係を表す語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37274, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連携", "is_correct": true, "explanation": "先生と親が協力して見守る様子を表し、「先生と親が連携して、子どもを見守っている」に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、先生と親の動きには当てはまらない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちを表す語で、子どもを見守る行動には合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を表す語で、先生と親が一緒に何かをする意味にはならない。"}], "explanations": {"連携": "先生と親が協力して見守る様子を表し、「先生と親が連携して、子どもを見守っている」に合う。", "天気": "空模様を表す語で、先生と親の動きには当てはまらない。", "食欲": "食べたい気持ちを表す語で、子どもを見守る行動には合わない。", "体温": "体の温度を表す語で、先生と親が一緒に何かをする意味にはならない。"}, "sentence_index": 6, "correct_answer": "連携"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その店は三日連携で休んだ。", "explanation": "ここは〈連続〉の意味。連携は人が息を合わせて動くことで、回数が続く意味には使わないので合わない。"}, {"text": "大雨で試合が連携した。", "explanation": "ここは〈中断〉の意味。試合が途中でやむことは、息を合わせて動く連携とは別なので合わない。"}, {"text": "私は大会に連携した。", "explanation": "ここは〈参加〉の意味。一人で加わる行為には連携を使わず、複数の人が協力して動くことを表す語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37274, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試合中、二人は連携に攻めた。", "corrected_sentence": "試合中、二人は連携して攻めた。", "error_description": "「連携に攻めた」は誤り。「連携して」（て形）で後ろの動詞「攻める」につなぐのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37274, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三人は連携が取って、重い荷物を運んだ。", "corrected_sentence": "三人は連携を取って、重い荷物を運んだ。", "error_description": "「連携が取る」は誤り。「連携を取る」の「を」が正しく、「取る」は目的語に「を」を取る。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37275, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「により」の「に」で、連携を理由や手段として示し、後ろの結果につなぐ。「会社と大学の連携により、新しい薬が生まれた」で正しい。"}, {"text": "を", "is_correct": false, "explanation": "を は目的語を示すが、「生まれた」は目的語を取らないので、ここでは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "へ は方向を示す。「連携へ、新しい薬が生まれた」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "と は並列や相手を示す。連携と薬の間に理由の関係を作れず、合わない。"}], "correct_answer": "に", "explanations": {"に": "「により」の「に」で、連携を理由や手段として示し、後ろの結果につなぐ。「会社と大学の連携により、新しい薬が生まれた」で正しい。", "を": "を は目的語を示すが、「生まれた」は目的語を取らないので、ここでは合わない。", "へ": "へ は方向を示す。「連携へ、新しい薬が生まれた」は成り立たない。", "と": "と は並列や相手を示す。連携と薬の間に理由の関係を作れず、合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37275, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「連携のおかげで」の「の」で、連携を名詞として示し、「おかげで」につなぐ。「学校と地域の連携のおかげで、通学路が安全になった」で正しい。"}, {"text": "が", "is_correct": false, "explanation": "が は主語を示す。「連携がおかげで」は、連携を名詞句として続けられない。"}, {"text": "に", "is_correct": false, "explanation": "に は帰着点や時を示す。「連携におかげで」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "から は起点や理由を示すが、「連携からおかげで」は名詞句として続かない。"}], "correct_answer": "の", "explanations": {"の": "「連携のおかげで」の「の」で、連携を名詞として示し、「おかげで」につなぐ。「学校と地域の連携のおかげで、通学路が安全になった」で正しい。", "が": "が は主語を示す。「連携がおかげで」は、連携を名詞句として続けられない。", "に": "に は帰着点や時を示す。「連携におかげで」は成り立たない。", "から": "から は起点や理由を示すが、「連携からおかげで」は名詞句として続かない。"}, "error_tags": {"が": "主語", "に": "帰着点・時", "から": "起点・理由"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37275, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の人や組織が互いに協力して、目的を達成するために行動を合わせること。", "primary_collocate": null, "pronunciation": "れんけい", "ipa": "ɾeŋkeː", "syllable_count": 4, "sentences": [{"text": "警察と消防が連携して、災害の被害を減らした。", "target_word": "連携", "complexity_tier": "T3", "furigana": "警察(けいさつ)と消防(しょうぼう)が連携(れんけい)して、災害(さいがい)の被害(ひがい)を減(へ)らした。", "sentence_source": "generated"}, {"text": "会社と大学の連携により、新しい薬が生まれた。", "target_word": "連携", "complexity_tier": "T3", "furigana": "会社(かいしゃ)と大学(だいがく)の連携(れんけい)により、新(あたら)しい薬(くすり)が生(う)まれた。", "sentence_source": "generated"}, {"text": "部署間の連携が弱く、情報が共有されなかった。", "target_word": "連携", "complexity_tier": "T3", "furigana": "部署間(ぶしょかん)の連携(れんけい)が弱(よわ)く、情報(じょうほう)が共有(きょうゆう)されなかった。", "sentence_source": "generated"}, {"text": "市は地元の店と連携し、観光客を増やす計画だ。", "target_word": "連携", "complexity_tier": "T3", "furigana": "市(し)は地元(じもと)の店(みせ)と連携(れんけい)し、観光客(かんこうきゃく)を増(ふ)やす計画(けいかく)だ。", "sentence_source": "generated"}, {"text": "病院どうしの連携が進み、患者はどこでも同じ治療を受けられる。", "target_word": "連携", "complexity_tier": "T4", "furigana": "病院(びょういん)どうしの連携(れんけい)が進(すす)み、患者(かんじゃ)はどこでも同(おな)じ治療(ちりょう)を受(う)けられる。", "sentence_source": "generated"}, {"text": "各国の連携を強めなければ、この問題は解決できない。", "target_word": "連携", "complexity_tier": "T3", "furigana": "各国(かっこく)の連携(れんけい)を強(つよ)めなければ、この問題(もんだい)は解決(かいけつ)できない。", "sentence_source": "generated"}, {"text": "連携を深めるため、二つの団体は毎月会議を開く。", "target_word": "連携", "complexity_tier": "T3", "furigana": "連携(れんけい)を深(ふか)めるため、二(ふた)つの団体(だんたい)は毎月(まいつき)会議(かいぎ)を開(ひら)く。", "sentence_source": "generated"}, {"text": "学校と地域の連携のおかげで、通学路が安全になった。", "target_word": "連携", "complexity_tier": "T3", "furigana": "学校(がっこう)と地域(ちいき)の連携(れんけい)のおかげで、通学路(つうがくろ)が安全(あんぜん)になった。", "sentence_source": "generated"}, {"text": "銀行がアプリ会社と連携して、新しいサービスを始めた。", "target_word": "連携", "complexity_tier": "T3", "furigana": "銀行(ぎんこう)がアプリ会社(がいしゃ)と連携(れんけい)して、新(あたら)しいサービスを始(はじ)めた。", "sentence_source": "generated"}, {"text": "連携が不十分だと、同じ作業を別々の組織が行ってしまう。", "target_word": "連携", "complexity_tier": "T4", "furigana": "連携(れんけい)が不十分(ふじゅうぶん)だと、同(おな)じ作業(さぎょう)を別々(べつべつ)の組織(そしき)が行(おこな)ってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連携する", "label": "する形"}, {"form": "連携して", "label": "て形"}, {"form": "連携した", "label": "た形"}, {"form": "連携しない", "label": "ない形"}], "register": "formal", "sense_fingerprint": "複数の人や組織が目的のために協力して行動を合わせること(組織・社会の場面)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8135be4b-f00d-40ac-8845-1284b6ffb713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37275, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連携", "is_correct": true, "explanation": "組織どうしが協力して行動を合わせることを表し、「警察と消防が連携して、災害の被害を減らした」に合う。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を表す語で、警察と消防の協力は表せない。"}, {"text": "食卓", "is_correct": false, "explanation": "食事をする台のことで、組織の協力や災害対策には当てはまらない。"}, {"text": "通帳", "is_correct": false, "explanation": "預金の記録帳のことで、災害対策の協力とは結びつかない。"}], "explanations": {"連携": "組織どうしが協力して行動を合わせることを表し、「警察と消防が連携して、災害の被害を減らした」に合う。", "体温": "体の温度を表す語で、警察と消防の協力は表せない。", "食卓": "食事をする台のことで、組織の協力や災害対策には当てはまらない。", "通帳": "預金の記録帳のことで、災害対策の協力とは結びつかない。"}, "sentence_index": 0, "correct_answer": "連携"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町は雨が連携で三日降った。", "explanation": "ここは〈連続〉の意味。連携は組織や人が協力して動くことで、雨が続く回数の表現には使わないので合わない。"}, {"text": "二国の友好関係が連携した。", "explanation": "ここは〈崩壊〉の意味。関係が壊れることは、協力して動く連携とは反対なので合わない。"}, {"text": "私は単独で連携した。", "explanation": "ここは〈単独〉の意味。一人で行うことは、複数の組織が行動を合わせる連携とは矛盾するので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37275, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連携", "is_correct": true, "explanation": "団体どうしが協力する意味を表し、「連携を深めるため、二つの団体は毎月会議を開く」に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、「天気を深める」とは言えないので合わない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るための道具で、団体どうしの関係を深める意味とは結びつかない。"}, {"text": "食器", "is_correct": false, "explanation": "料理を盛る道具のことで、「食器を深める」は成り立たない。"}], "explanations": {"連携": "団体どうしが協力する意味を表し、「連携を深めるため、二つの団体は毎月会議を開く」に合う。", "天気": "空模様を表す語で、「天気を深める」とは言えないので合わない。", "寝具": "寝るための道具で、団体どうしの関係を深める意味とは結びつかない。", "食器": "料理を盛る道具のことで、「食器を深める」は成り立たない。"}, "sentence_index": 6, "correct_answer": "連携"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その団体は三月に連携した。", "explanation": "ここは〈解散〉の意味。組織が活動をやめることは、協力して動く連携とは反対なので合わない。"}, {"text": "その記事は来月号に連携した。", "explanation": "ここは〈掲載〉の意味。記事を誌面にのせることは、協力して動く連携とは別なので合わない。"}, {"text": "細胞が二つに連携した。", "explanation": "ここは〈分裂〉の意味。一つのものが分かれる意味で、協力して動く連携とは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37275, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市と大学は連携を取り組んでいる。", "corrected_sentence": "市と大学は連携に取り組んでいる。", "error_description": "「連携を取り組んでいる」は誤り。「取り組む」は「〜に取り組む」の形をとるので、「連携を」ではなく「連携に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37275, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の団体は、連携ずに防災訓練を開いた。", "corrected_sentence": "町の団体は、連携せずに防災訓練を開いた。", "error_description": "「連携ずに」は誤り。「連携」はサ変動詞なので「連携せず」の形になり、「せずに」で続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37276, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37276, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す「が」で、トランジットが全部止まっているという事実を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」だが、止まる主体にはならないので誤り。"}, {"text": "に", "is_correct": false, "explanation": "場所を示す「に」だが、止まる対象の場所にはならず文が不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、止まっている状態には合わない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す「が」で、トランジットが全部止まっているという事実を表す。", "を": "目的語を示す「を」だが、止まる主体にはならないので誤り。", "に": "場所を示す「に」だが、止まる対象の場所にはならず文が不自然。", "へ": "方向を示すが、止まっている状態には合わない。"}, "error_tags": {"を": "目的語", "に": "場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37276, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人がのる乗り物が、ある場所から別の場所へ行くこと。", "primary_collocate": null, "pronunciation": "とらんじっと", "ipa": "to̞ɾa̠ɲd͡ʑitto̞", "syllable_count": 6, "sentences": [{"text": "この町はトランジットが便利なので、車がなくても困らない。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "この町[まち]はトランジットが便利[べんり]なので、車[くるま]がなくても困[こま]らない。", "sentence_source": "generated"}, {"text": "朝のトランジットはいつも通勤する人でいっぱいだ。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "朝[あさ]のトランジットはいつも通勤[つうきん]する人[ひと]でいっぱいだ。", "sentence_source": "generated"}, {"text": "雪の日は、トランジットが遅れることが多い。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、トランジットが遅[おく]れることが多[おお]い。", "sentence_source": "generated"}, {"text": "新しい駅ができて、トランジットがさらに便利になった。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "新[あたら]しい駅[えき]ができて、トランジットがさらに便利[べんり]になった。", "sentence_source": "generated"}, {"text": "市は高齢者のために、トランジットの料金を安くした。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "市[し]は高齢者[こうれいしゃ]のために、トランジットの料金[りょうきん]を安[やす]くした。", "sentence_source": "generated"}, {"text": "都会ではトランジットを使う人が多く、道もすいている。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "都会[とかい]ではトランジットを使[つか]う人[ひと]が多[おお]く、道[みち]もすいている。", "sentence_source": "generated"}, {"text": "夜遅くはトランジットが少ないので、帰りが心配だ。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "夜遅[よるおそ]くはトランジットが少[すく]ないので、帰[かえ]りが心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "大雨のため、今日はトランジットが全部止まっている。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のため、今日[きょう]はトランジットが全部[ぜんぶ]止[と]まっている。", "sentence_source": "generated"}, {"text": "この国のトランジットは時間に正確だと言われている。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "この国[くに]のトランジットは時間[じかん]に正確[せいかく]だと言[い]われている。", "sentence_source": "generated"}, {"text": "旅行者はトランジットのおかげで、安く町を回れた。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "旅行者[りょこうしゃ]はトランジットのおかげで、安[やす]く町[まち]を回[まわ]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トランジット", "label": "基本形（名詞）"}, {"form": "トランジットの", "label": "連体形"}], "register": "中立", "sense_fingerprint": "バスや電車など人を乗せる乗り物の運行・公共の移動手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90fa4bdf-c71d-489f-bb70-e9e1151b79b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37276, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トランジット", "is_correct": true, "explanation": "交通機関の移動を指し、町の交通が便利だという文脈に合う。"}, {"text": "犬", "is_correct": false, "explanation": "生き物で、町の便利さを表す語として合わない。"}, {"text": "月謝", "is_correct": false, "explanation": "習いごとなどの料金で、町の便利さには使えない。"}, {"text": "手袋", "is_correct": false, "explanation": "身につける物で、町の便利さを表さない。"}], "explanations": {"トランジット": "交通機関の移動を指し、町の交通が便利だという文脈に合う。", "犬": "生き物で、町の便利さを表す語として合わない。", "月謝": "習いごとなどの料金で、町の便利さには使えない。", "手袋": "身につける物で、町の便利さを表さない。"}, "sentence_index": 0, "correct_answer": "トランジット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅のトランジットが複雑で、いつも迷ってしまう。", "explanation": "ここは〈乗り換え〉の意味（電車などを乗り替えること）。トランジットは乗り物が場所から場所へ行く移動そのものを指すので、駅の中の乗り換えの複雑さは表せない。"}, {"text": "百年以上ぶりの金星のトランジットを、望遠鏡で観察した。", "explanation": "ここは〈天体の通過〉の意味（金星が太陽の前を横切って見える現象）。トランジットは乗り物の移動を指すので、天体の現象には使わない。"}, {"text": "電車はトランジットになり、乗客を乗せずに車庫へ向かった。", "explanation": "ここは〈回送〉の意味（客を乗せず車庫などへ走る運転）。トランジットは人がのる乗り物の移動を指すので、客を乗せない運転には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37276, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トランジット", "is_correct": true, "explanation": "夜遅く交通機関が少ないという文脈に合い、空欄に入る。"}, {"text": "富士山", "is_correct": false, "explanation": "山の名で、交通機関の本数には使えない。"}, {"text": "春風", "is_correct": false, "explanation": "季節の風で、交通機関の話には合わない。"}, {"text": "北極星", "is_correct": false, "explanation": "夜空の星で、交通機関の本数の話には合わない。"}], "explanations": {"トランジット": "夜遅く交通機関が少ないという文脈に合い、空欄に入る。", "富士山": "山の名で、交通機関の本数には使えない。", "春風": "季節の風で、交通機関の話には合わない。", "北極星": "夜空の星で、交通機関の本数の話には合わない。"}, "sentence_index": 6, "correct_answer": "トランジット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "運転士は一日のトランジットを終えて、やっと帰った。", "explanation": "ここは〈乗務〉の意味（乗り物の運転や担当として勤務すること）。トランジットは乗り物が移動すること自体を指すので、勤務の意味では使わない。"}, {"text": "帰りにトランジットをして、本屋に入った。", "explanation": "ここは〈寄り道〉の意味（目的地へ行く途中で別の場所に立ち寄ること）。トランジットは乗り物の移動を指すので、人が立ち寄る行為には使わない。"}, {"text": "休日は公園でトランジットをして過ごした。", "explanation": "ここは〈散歩〉の意味（目的なくぶらぶら歩くこと）。トランジットは乗り物での移動を指すので、徒歩で楽しむ行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37276, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜は、トランジットが使わずに帰る人も多い。", "corrected_sentence": "夜は、トランジットを使わずに帰る人も多い。", "error_description": "「使う」の目的語は「を」で示す。「が」は主語の助詞なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37276, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台風のため、トランジットは全部止まってしまうなかった。", "corrected_sentence": "台風のため、トランジットは全部止まってしまった。", "error_description": "「止まってしまった」の部分に「なかった」の否定を重ねており、動詞の活用が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
