INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37277, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や物をある地点から別の地点へ運ぶこと。特に、交通機関による移動や輸送を指す。", "primary_collocate": null, "pronunciation": "とらんじっと", "ipa": "to̞ɾa̠ɲd͡ʑitto̞", "syllable_count": 6, "sentences": [{"text": "輸入した部品のトランジットに、港で一週間かかった。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "{輸入|ゆにゅう}した{部品|ぶひん}の{トランジット|とらんじっと}に、{港|みなと}で{一週間|いっしゅうかん}かかった。", "sentence_source": "generated"}, {"text": "荷物のトランジットに、港から工場まで二日かかった。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "荷物[にもつ]のトランジットに、港[みなと]から工場[こうじょう]まで二日[ふつか]かかった。", "sentence_source": "generated"}, {"text": "海外から来た荷物は、ここでトランジットされて各地へ送られる。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "海外[かいがい]から来[き]た荷物[にもつ]は、ここでトランジットされて各地[かくち]へ送[おく]られる。", "sentence_source": "generated"}, {"text": "人のトランジットが増えて、駅は毎日混雑している。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "人[ひと]のトランジットが増[ふ]えて、駅[えき]は毎日[まいにち]混雑[こんざつ]している。", "sentence_source": "generated"}, {"text": "この会社は、食品のトランジットを専門にしている。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、食品[しょくひん]のトランジットを専門[せんもん]にしている。", "sentence_source": "generated"}, {"text": "雪のため、トランジットに予定より時間がかかった。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "雪[ゆき]のため、トランジットに予定[よてい]より時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "災害の後、避難者のトランジットを助けるため、臨時の案内所ができた。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "{災害|さいがい}の{後|あと}、{避難者|ひなんしゃ}の{トランジット|とらんじっと}を{助|たす}けるため、{臨時|りんじ}の{案内所|あんないじょ}ができた。", "sentence_source": "generated"}, {"text": "国をまたぐトランジットには、特別な書類が必要だ。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "国[くに]をまたぐトランジットには、特別[とくべつ]な書類[しょるい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "この港は世界中の荷物のトランジットの中心になっている。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "この港[みなと]は世界中[せかいじゅう]の荷物[にもつ]のトランジットの中心[ちゅうしん]になっている。", "sentence_source": "generated"}, {"text": "長いトランジットのあと、やっと目的地に着いた。", "target_word": "トランジット", "complexity_tier": "T3", "furigana": "長[なが]いトランジットのあと、やっと目的地[もくてきち]に着[つ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トランジット", "label": "基本形（名詞）"}, {"form": "トランジットする", "label": "する動詞"}, {"form": "トランジットされる", "label": "受身"}], "register": "中立", "sense_fingerprint": "交通機関で人や荷物を途中の地点を通して運ぶ・移動させること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90fa4bdf-c71d-489f-bb70-e9e1151b79b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37277, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トランジット", "is_correct": true, "explanation": "輸入した部品を港で経由させて運ぶ過程を指し、空欄に入る。"}, {"text": "洗顔", "is_correct": false, "explanation": "顔を洗う行為で、部品の輸送には使えない。"}, {"text": "三味線", "is_correct": false, "explanation": "楽器の名で、部品の輸送には合わない。"}, {"text": "富士山", "is_correct": false, "explanation": "山の名で、部品の輸送の話には使えない。"}], "explanations": {"トランジット": "輸入した部品を港で経由させて運ぶ過程を指し、空欄に入る。", "洗顔": "顔を洗う行為で、部品の輸送には使えない。", "三味線": "楽器の名で、部品の輸送には合わない。", "富士山": "山の名で、部品の輸送の話には使えない。"}, "sentence_index": 0, "correct_answer": "トランジット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ピザのトランジットに三十分かかった。", "explanation": "ここは〈配達〉の意味（注文品を届け先へ届けること）。トランジットは荷物を中継・経由させる意味で、注文品を届け先へ届ける行為そのものは表さない。"}, {"text": "店員はトランジットに追われて、昼食を取れなかった。", "explanation": "ここは〈接客〉の意味（客の応対をすること）。トランジットは人や物を移す意味で、客への応対には使わない。"}, {"text": "アンケート用紙をトランジットした。", "explanation": "ここは〈回収〉の意味（配ったものを集めること）。トランジットは運んで中継する意味で、集める行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37277, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トランジット", "is_correct": true, "explanation": "避難者が移動の途中で経由する過程を指し、空欄に入る。"}, {"text": "陶器", "is_correct": false, "explanation": "焼き物の器で、避難者の移動には合わない。"}, {"text": "天体", "is_correct": false, "explanation": "星などの天の物体で、避難者の支援の文脈には合わない。"}, {"text": "盆栽", "is_correct": false, "explanation": "小さな植木の鉢で、避難者の支援には使えない。"}], "explanations": {"トランジット": "避難者が移動の途中で経由する過程を指し、空欄に入る。", "陶器": "焼き物の器で、避難者の移動には合わない。", "天体": "星などの天の物体で、避難者の支援の文脈には合わない。", "盆栽": "小さな植木の鉢で、避難者の支援には使えない。"}, "sentence_index": 6, "correct_answer": "トランジット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月、実家へ生活費をトランジットした。", "explanation": "ここは〈送金〉の意味（お金を相手へ送り届けること）。トランジットは人や物を運ぶ語義で、お金の送付には使わない。"}, {"text": "十年ぶりの水星のトランジットを、学校の屋上から観察した。", "explanation": "ここは〈天体の通過〉の意味（水星が太陽の前を横切って見える現象）。トランジットは人や物を運ぶ意味なので、天体の現象には使わない。"}, {"text": "出発前に、車をトランジットに出した。", "explanation": "ここは〈点検〉の意味（機械や車の状態を調べること）。トランジットは運搬や中継の語義で、状態を調べる行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37277, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "輸入した機械のトランジットを、港で三日かかった。", "corrected_sentence": "輸入した機械のトランジットに、港で三日かかった。", "error_description": "「かかる」は時間を示す「に」を取る。「を」は文法的に誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37277, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台風の後、トランジットは時間通りに再開させた。", "corrected_sentence": "台風の後、トランジットは時間通りに再開した。", "error_description": "「再開させた」は動作主を必要とする使役だが、主語のトランジットは動かす側になれない。「再開した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
