INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37278, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "「オリエンテッド」は「〜の方向に向いている」という意味です。", "primary_collocate": null, "pronunciation": "おりえんてっど", "ipa": "oɾienteddo", "syllable_count": 7, "sentences": [{"text": "「オリエンテッド」は、「〜の方向に向いている」という意味の言葉だ。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」は、「〜の方向[ほうこう]に向[む]いている」という意味[いみ]の言葉[ことば]だ。", "sentence_source": "generated"}, {"text": "「オリエンテッド」の「〜の方向に向いている」という部分が、この言葉の中心的な意味だ。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」の「〜の方向[ほうこう]に向[む]いている」という部分[ぶぶん]が、この言葉[ことば]の中心[ちゅうしん]的[てき]な意味[いみ]だ。", "sentence_source": "generated"}, {"text": "英語の oriented から来た言葉で、「オリエンテッド」は「〜の方向に向いている」という意味だ。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "英語[えいご]の oriented から来[き]た言葉[ことば]で、「オリエンテッド」は「〜の方向[ほうこう]に向[む]いている」という意味[いみ]だ。", "sentence_source": "generated"}, {"text": "「オリエンテッド」は、目的や方向を表す言葉と組み合わせて使われることが多い。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」は、目的[もくてき]や方向[ほうこう]を表[あらわ]す言葉[ことば]と組[く]み合[あ]わせて使[つか]われることが多[おお]い。", "sentence_source": "generated"}, {"text": "「オリエンテッド」は、気持ちや行動がある方向へ向かっている様子を表す言葉だ。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」は、気持[きも]ちや行動[こうどう]がある方向[ほうこう]へ向[む]かっている様子[ようす]を表[あらわ]す言葉[ことば]だ。", "sentence_source": "generated"}, {"text": "辞書で「オリエンテッド」を引くと、「〜の方向に向いている」という説明が出てくる。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "辞書[じしょ]で「オリエンテッド」を引[ひ]くと、「〜の方向[ほうこう]に向[む]いている」という説明[せつめい]が出[で]てくる。", "sentence_source": "generated"}, {"text": "英語で「オリエンテッド」は「向いている」の意味で使われる。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "英語[えいご]で「オリエンテッド」は「向[む]いている」の意味[いみ]で使[つか]われる。", "sentence_source": "generated"}, {"text": "「オリエンテッド」の意味を一言で言えば、「〜の方向に向いている」ということだ。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」の意味[いみ]を一言[ひとこと]で言[い]えば、「〜の方向[ほうこう]に向[む]いている」ということだ。", "sentence_source": "generated"}, {"text": "「オリエンテッド」という言葉は、目を向けている先を示すときに使われる。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」という言葉[ことば]は、目[め]を向[む]けている先[さき]を示[しめ]すときに使[つか]われる。", "sentence_source": "generated"}, {"text": "「オリエンテッド」は英語からきた言葉で、向いている方向を示すときに使われる。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」は英語[えいご]から来[き]た言葉[ことば]で、向[む]いている方向[ほうこう]を示[しめ]すときに使[つか]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "オリエンテッドだ", "label": "断定形"}, {"form": "オリエンテッドな", "label": "連体形"}, {"form": "オリエンテッドに", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "ある方向や対象に向いているさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37278, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オリエンテッド", "is_correct": true, "explanation": "「〜の方向に向いている」という定義を述べる語で、空欄に入るのはこの語だけ。"}, {"text": "ポジティブ", "is_correct": false, "explanation": "物事のよい面や前向きさを表す語で、「〜の方向に向いている」という定義とは合わない。"}, {"text": "ネガティブ", "is_correct": false, "explanation": "悪い面や後ろ向きさを表す語で、方向の意味を定義する文には合わない。"}, {"text": "デリケート", "is_correct": false, "explanation": "繊細で扱いにくいさまを表し、方向を示す定義とは意味が合わない。"}], "explanations": {"オリエンテッド": "「〜の方向に向いている」という定義を述べる語で、空欄に入るのはこの語だけ。", "ポジティブ": "物事のよい面や前向きさを表す語で、「〜の方向に向いている」という定義とは合わない。", "ネガティブ": "悪い面や後ろ向きさを表す語で、方向の意味を定義する文には合わない。", "デリケート": "繊細で扱いにくいさまを表し、方向を示す定義とは意味が合わない。"}, "sentence_index": 0, "correct_answer": "オリエンテッド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新入生は、大学のオリエンテッドに参加した。", "explanation": "ここは〈オリエンテーション（新入生向けの説明会）〉の意味。オリエンテッドは「〜の方向に向いている」の意味で、説明会は表さない。"}, {"text": "夕方、海辺でオリエンテッドの色を眺めた。", "explanation": "ここは〈オレンジ（橙色）〉の意味。オリエンテッドは方向に向いている様子を表す語で、色の名前ではない。"}, {"text": "週末は山でオリエンテッドを楽しんだ。", "explanation": "ここは〈オリエンテーリング（地図とコンパスで競う競技）〉の意味。オリエンテッドは方向に向いている様子を表す語で、競技の名前ではないので、この文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37278, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "オリエンテッド", "is_correct": true, "explanation": "「向いている」の意味で使われる語で、英語での用法を説明する文に入る。"}, {"text": "シンプル", "is_correct": false, "explanation": "簡素なさまを表す語で、「向いている」の意味を説明する文には合わない。"}, {"text": "ダイナミック", "is_correct": false, "explanation": "力強く躍動的なさまを表し、「向いている」の意味とは一致しない。"}, {"text": "エレガント", "is_correct": false, "explanation": "上品で優雅なさまを表し、方向を示す意味の説明には合わない。"}], "explanations": {"オリエンテッド": "「向いている」の意味で使われる語で、英語での用法を説明する文に入る。", "シンプル": "簡素なさまを表す語で、「向いている」の意味を説明する文には合わない。", "ダイナミック": "力強く躍動的なさまを表し、「向いている」の意味とは一致しない。", "エレガント": "上品で優雅なさまを表し、方向を示す意味の説明には合わない。"}, "sentence_index": 6, "correct_answer": "オリエンテッド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は、オリエンテッドな雰囲気の内装で、落ち着いた空間だ。", "explanation": "ここは〈オリエンタル（東洋風）〉の意味。オリエンテッドは方向を表す語で、雰囲気や地域の意味にはならない。"}, {"text": "シルクロードの研究では、オリエンテッドの文明が重要な位置を占めている。", "explanation": "ここは〈オリエント（東方の地域）〉の意味。オリエンテッドは地域名ではなく、方向に向いている様子を表す。"}, {"text": "新しく発売された掃除機のオリエンテッドを分析した。", "explanation": "ここは〈吸引力〉の意味。オリエンテッドは方向に向いている様子を表す語で、吸引の強さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37278, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "「オリエンテッド」を、〜の方向に向いている意味の言葉だ。", "corrected_sentence": "「オリエンテッド」は、〜の方向に向いている意味の言葉だ。", "error_description": "誤りは主題の「を」。定義文では語を主題として「は」で示すのが正しく、「を」は動作の対象を示すため述語のないこの文には合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "オリエンテッド", "is_correct": true, "explanation": "文中では引用された語として活用させず、そのままの形で使われている。"}, {"text": "オリエンテッドだ", "is_correct": false, "explanation": "断定形で、引用された語をそのまま示す文脈には用いない。"}, {"text": "オリエンテッドな", "is_correct": false, "explanation": "連体形で、後ろに名詞が続く形。ここでは名詞が続いていない。"}, {"text": "オリエンテッドに", "is_correct": false, "explanation": "連用形で、用言を修飾する形。引用語として示す文脈とは合わない。"}], "correct_form": "オリエンテッド", "base_form": "オリエンテッド", "form_label": "語幹のまま（活用なし）", "sentence_index": 1, "explanations": {"オリエンテッド": "文中では引用された語として活用させず、そのままの形で使われている。", "オリエンテッドだ": "断定形で、引用された語をそのまま示す文脈には用いない。", "オリエンテッドな": "連体形で、後ろに名詞が続く形。ここでは名詞が続いていない。", "オリエンテッドに": "連用形で、用言を修飾する形。引用語として示す文脈とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37278, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この言葉は、オリエンテッドの方向性を表す。", "corrected_sentence": "この言葉は、オリエンテッドな方向性を表す。", "error_description": "誤りは「オリエンテッドの」の「の」。形状詞は名詞の前で連体形「な」になるので「オリエンテッドな方向性」が正しく、格助詞「の」は使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "オリエンテッド", "is_correct": true, "explanation": "「の意味」の前に置かれ、引用された語として活用させずに示されている。"}, {"text": "オリエンテッドで", "is_correct": false, "explanation": "連用形の「で」の形で、ここでは語を引用して示す文脈に合わない。"}, {"text": "オリエンテッドだった", "is_correct": false, "explanation": "過去の断定形で、語を示す文脈には用いない。"}, {"text": "オリエンテッドではない", "is_correct": false, "explanation": "否定形で、語の意味を述べる文の形としては合わない。"}], "correct_form": "オリエンテッド", "base_form": "オリエンテッド", "form_label": "語幹のまま（活用なし）", "sentence_index": 7, "explanations": {"オリエンテッド": "「の意味」の前に置かれ、引用された語として活用させずに示されている。", "オリエンテッドで": "連用形の「で」の形で、ここでは語を引用して示す文脈に合わない。", "オリエンテッドだった": "過去の断定形で、語を示す文脈には用いない。", "オリエンテッドではない": "否定形で、語の意味を述べる文の形としては合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
