INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37279, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "「オリエンテッド」は「〜志向の」「〜を重視した」という意味で、特定の目的や方向性に焦点を当てていることを表します。", "primary_collocate": null, "pronunciation": "おりえんてっど", "ipa": "oɾienteddo", "syllable_count": 7, "sentences": [{"text": "「オリエンテッド」は、英語の oriented に由来する言葉で、目的や方向性に焦点を当てる意味で用いられる。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」は、英語[えいご]の oriented に由来[ゆらい]する言葉[ことば]で、目的[もくてき]や方向性[ほうこうせい]に焦点[しょうてん]を当[あ]てる意味[いみ]で用[もち]いられる。", "sentence_source": "generated"}, {"text": "企業の文書では、「オリエンテッド」を、特定の目的に重きを置く姿勢を示す語として用いることがある。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "企業[きぎょう]の文書[ぶんしょ]では、「オリエンテッド」を、特定[とくてい]の目的[もくてき]に重[おも]きを置[お]く姿勢[しせい]を示[しめ]す語[ご]として用[もち]いることがある。", "sentence_source": "generated"}, {"text": "報告書において「オリエンテッド」の語は、対象への志向性を示す要素として扱われる。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "報告書[ほうこくしょ]において「オリエンテッド」の語[ご]は、対象[たいしょう]への志向性[しこうせい]を示[しめ]す要素[ようそ]として扱[あつか]われる。", "sentence_source": "generated"}, {"text": "「オリエンテッド」は、ほかの語の後ろに付けて「〜志向の」という意味を表す要素として理解される。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」は、ほかの語[ご]の後[うし]ろに付[つ]けて「〜志向[しこう]の」という意味[いみ]を表[あらわ]す要素[ようそ]として理解[りかい]される。", "sentence_source": "generated"}, {"text": "「オリエンテッド」は「〜志向の」という意味で、目的を重視する姿勢を表す。", "target_word": "オリエンテッド", "complexity_tier": "T4", "furigana": "「オリエンテッド」は「〜志向[しこう]の」という意味[いみ]で、目的[もくてき]を重視[じゅうし]する姿勢[しせい]を表[あらわ]す。", "sentence_source": "generated"}, {"text": "辞書では、「オリエンテッド」の項目に「〜志向の」「〜を重視した」という説明が並んでいる。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "辞書[じしょ]では、「オリエンテッド」の項目[こうもく]に「〜志向[しこう]の」「〜を重視[じゅうし]した」という説明[せつめい]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "「オリエンテッド」が示すのは、特定の目的や方向に軸足を置く姿勢である。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」が示[しめ]すのは、特定[とくてい]の目的[もくてき]や方向[ほうこう]に軸足[じくあし]を置[お]く姿勢[しせい]である。", "sentence_source": "generated"}, {"text": "「オリエンテッド」は、英語 oriented の訳語として、目的や方向への志向を表すのが一般的である。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」は、英語[えいご] oriented の訳語[やくご]として、目的[もくてき]や方向[ほうこう]への志向[しこう]を表[あらわ]すのが一般的[いっぱんてき]である。", "sentence_source": "generated"}, {"text": "「オリエンテッド」の意味は、〜志向の、つまり特定の方向性に焦点を当てることである。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "「オリエンテッド」の意味[いみ]は、〜志向[しこう]の、つまり特定[とくてい]の方向性[ほうこうせい]に焦点[しょうてん]を当[あ]てることである。", "sentence_source": "generated"}, {"text": "文章中で「オリエンテッド」と書くとき、その語は目的や方向性への焦点を表す。", "target_word": "オリエンテッド", "complexity_tier": "T3", "furigana": "文章中[ぶんしょうちゅう]で「オリエンテッド」と書[か]くとき、その語[ご]は目的[もくてき]や方向性[ほうこうせい]への焦点[しょうてん]を表[あらわ]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "オリエンテッドだ", "label": "断定形"}, {"form": "オリエンテッドな", "label": "連体形"}, {"form": "オリエンテッドに", "label": "連用形"}], "register": "formal", "sense_fingerprint": "特定の目的や価値を重視する志向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37279, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オリエンテッド", "is_correct": true, "explanation": "英語の oriented に由来し、目的や方向性に焦点を当てる意味を持つ語。"}, {"text": "合理的", "is_correct": false, "explanation": "筋道が通っているさまを表し、英語の語源を説明する文には合わない。"}, {"text": "普遍的", "is_correct": false, "explanation": "すべてに当てはまるさまを表し、語の由来を述べる文と噛み合わない。"}, {"text": "不可欠", "is_correct": false, "explanation": "欠かせないさまを表し、語源の説明には意味が合わない。"}], "explanations": {"オリエンテッド": "英語の oriented に由来し、目的や方向性に焦点を当てる意味を持つ語。", "合理的": "筋道が通っているさまを表し、英語の語源を説明する文には合わない。", "普遍的": "すべてに当てはまるさまを表し、語の由来を述べる文と噛み合わない。", "不可欠": "欠かせないさまを表し、語源の説明には意味が合わない。"}, "sentence_index": 0, "correct_answer": "オリエンテッド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新入社員は、入社初日のオリエンテッドで会社の歴史を学んだ。", "explanation": "ここは〈オリエンテーション（説明会）〉の意味。オリエンテッドは「〜志向の」の意味で、説明会の意味は持たない。"}, {"text": "景気のオリエンテッドを分析して、来期の計画を立てた。", "explanation": "ここは〈傾向〉の意味。オリエンテッドは志向を表す形容語で、名詞の傾向の代わりにはならない。"}, {"text": "南オリエンテッドの部屋は明るく、日当たりがよい。", "explanation": "ここは〈向き〉の意味。オリエンテッドは志向や重視の姿勢を表し、方角の向きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37279, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "オリエンテッド", "is_correct": true, "explanation": "特定の目的や方向に軸足を置く姿勢を示す語で、文の主語に入る。"}, {"text": "保守的", "is_correct": false, "explanation": "変化を避けるさまを表し、目的や方向に軸足を置く姿勢の説明とは合わない。"}, {"text": "革新的", "is_correct": false, "explanation": "新しいことを取り入れるさまを表し、方向性に焦点を当てる意味とは一致しない。"}, {"text": "画一的", "is_correct": false, "explanation": "個性がなく一様なさまを表し、姿勢を示す文脈には合わない。"}], "explanations": {"オリエンテッド": "特定の目的や方向に軸足を置く姿勢を示す語で、文の主語に入る。", "保守的": "変化を避けるさまを表し、目的や方向に軸足を置く姿勢の説明とは合わない。", "革新的": "新しいことを取り入れるさまを表し、方向性に焦点を当てる意味とは一致しない。", "画一的": "個性がなく一様なさまを表し、姿勢を示す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "オリエンテッド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新商品は、オリエンテッドに味付けされ、評判になった。", "explanation": "ここは〈オリジナル（独自の）〉の意味。オリエンテッドは志向を表す語で、独自性の意味にはならない。"}, {"text": "港のオリエンテッドを確かめて、船を進めた。", "explanation": "ここは〈方角〉の意味。オリエンテッドは志向や重視の姿勢を表し、方角の名詞には使わない。"}, {"text": "物体の速さとオリエンテッドを計算する。", "explanation": "ここは〈ベクトル（向きと大きさをもつ量）〉の意味。オリエンテッドは方向への志向を表す語で、数学の量を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37279, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "プロジェクトは、顧客オリエンテッドの姿勢で進められた。", "corrected_sentence": "プロジェクトは、顧客オリエンテッドな姿勢で進められた。", "error_description": "誤りは「顧客オリエンテッドの」の「の」。形状詞は名詞を修飾するとき連体形「な」を取るので「顧客オリエンテッドな姿勢」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "オリエンテッド", "is_correct": true, "explanation": "「企業の文書では」の後、語をそのまま示す形で用いられている。"}, {"text": "オリエンテッドだ", "is_correct": false, "explanation": "断定形で、語を用語として示す文脈には合わない。"}, {"text": "オリエンテッドな", "is_correct": false, "explanation": "連体形で、後ろに名詞が続く形。ここでは名詞が続いていない。"}, {"text": "オリエンテッドに", "is_correct": false, "explanation": "連用形で、用言を修飾する形。語を示す文脈とは合わない。"}], "correct_form": "オリエンテッド", "base_form": "オリエンテッド", "form_label": "語幹のまま（活用なし）", "sentence_index": 1, "explanations": {"オリエンテッド": "「企業の文書では」の後、語をそのまま示す形で用いられている。", "オリエンテッドだ": "断定形で、語を用語として示す文脈には合わない。", "オリエンテッドな": "連体形で、後ろに名詞が続く形。ここでは名詞が続いていない。", "オリエンテッドに": "連用形で、用言を修飾する形。語を示す文脈とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37279, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この団体は、地域オリエンテッドへ活動を続けている。", "corrected_sentence": "この団体は、地域オリエンテッドな活動を続けている。", "error_description": "誤りは「地域オリエンテッドへ」の「へ」。方向の格助詞「へ」は形状詞に付かず、連体形「な」で「活動」を修飾するのが正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "オリエンテッド", "is_correct": true, "explanation": "「の意味」の前に置かれ、語をそのまま示す形で用いられている。"}, {"text": "オリエンテッドで", "is_correct": false, "explanation": "連用形の「で」の形で、語を示す文脈には合わない。"}, {"text": "オリエンテッドだった", "is_correct": false, "explanation": "過去の断定形で、語の意味を述べる文の形には合わない。"}, {"text": "オリエンテッドではない", "is_correct": false, "explanation": "否定形で、語を示す文脈には合わない。"}], "correct_form": "オリエンテッド", "base_form": "オリエンテッド", "form_label": "語幹のまま（活用なし）", "sentence_index": 7, "explanations": {"オリエンテッド": "「の意味」の前に置かれ、語をそのまま示す形で用いられている。", "オリエンテッドで": "連用形の「で」の形で、語を示す文脈には合わない。", "オリエンテッドだった": "過去の断定形で、語の意味を述べる文の形には合わない。", "オリエンテッドではない": "否定形で、語を示す文脈には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37281, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37281, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37281, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "公共交通機関を中心とした都市開発。駅周辺に商業施設や住宅、行政機関を集約し、歩行者や自転車の利用を促進することで、車に頼らない持続可能な都市構造を実現する手法。", "primary_collocate": null, "pronunciation": "てぃーおーでぃー", "ipa": "tiːoːdiː", "syllable_count": 6, "sentences": [{"text": "TOD は公共交通を中心に、都市を開発する手法である。", "target_word": "TOD", "complexity_tier": "T4", "furigana": "TOD は公共交通(こうきょうこうつう)を中心(ちゅうしん)に、都市(とし)を開発(かいはつ)する手法(しゅほう)である。", "sentence_source": "generated"}, {"text": "駅周辺に住宅と商業施設を集約するのが TOD の特徴だ。", "target_word": "TOD", "complexity_tier": "T4", "furigana": "駅周辺(えきしゅうへん)に住宅(じゅうたく)と商業施設(しょうぎょうしせつ)を集約(しゅうやく)するのが TOD の特徴(とくちょう)だ。", "sentence_source": "generated"}, {"text": "TOD を導入した都市では、自動車の利用が減った。", "target_word": "TOD", "complexity_tier": "T4", "furigana": "TOD を導入(どうにゅう)した都市(とし)では、自動車(じどうしゃ)の利用(りよう)が減(へ)った。", "sentence_source": "generated"}, {"text": "行政は持続可能な都市を目指して、TOD を推進している。", "target_word": "TOD", "complexity_tier": "T4", "furigana": "行政(ぎょうせい)は持続可能(じぞくかのう)な都市(とし)を目指(めざ)して、TOD を推進(すいしん)している。", "sentence_source": "generated"}, {"text": "TOD により、歩行者や自転車が使いやすい街ができる。", "target_word": "TOD", "complexity_tier": "T4", "furigana": "TOD により、歩行者(ほこうしゃ)や自転車(じてんしゃ)が使(つか)いやすい街(まち)ができる。", "sentence_source": "generated"}, {"text": "人口が減る地方でも、TOD は街のにぎわいを保つ方法になる。", "target_word": "TOD", "complexity_tier": "T4", "furigana": "人口(じんこう)が減(へ)る地方(ちほう)でも、TOD は街(まち)のにぎわいを保(たも)つ方法(ほうほう)になる。", "sentence_source": "generated"}, {"text": "TOD の計画では、駅から徒歩圏に行政機関を置く。", "target_word": "TOD", "complexity_tier": "T4", "furigana": "TOD の計画(けいかく)では、駅(えき)から徒歩圏(とほけん)に行政機関(ぎょうせいきかん)を置(お)く。", "sentence_source": "generated"}, {"text": "開発業者は、TOD に合わせて駅前に高層住宅を建てた。", "target_word": "TOD", "complexity_tier": "T4", "furigana": "開発業者(かいはつぎょうしゃ)は、TOD に合(あ)わせて駅前(えきまえ)に高層住宅(こうそうじゅうたく)を建(た)てた。", "sentence_source": "generated"}, {"text": "TOD が進まない理由の一つは、土地の所有者が多いことだ。", "target_word": "TOD", "complexity_tier": "T4", "furigana": "TOD が進(すす)まない理由(りゆう)の一(ひと)つは、土地(とち)の所有者(しょゆうしゃ)が多(おお)いことだ。", "sentence_source": "generated"}, {"text": "専門家は TOD を、環境への負担を減らす都市構造だと評価する。", "target_word": "TOD", "complexity_tier": "T4", "furigana": "専門家(せんもんか)は TOD を、環境(かんきょう)への負担(ふたん)を減(へ)らす都市構造(としこうぞう)だと評価(ひょうか)する。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "公共交通中心の都市開発手法(駅周辺への機能集約・車に頼らない都市構造)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8135be4b-f00d-40ac-8845-1284b6ffb713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37281, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "TOD", "is_correct": true, "explanation": "公共交通を中心にした都市開発の手法を指し、「TOD は公共交通を中心に、都市を開発する手法である」に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、都市開発の手法の説明には合わない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちを表す語で、都市開発の手法とは結びつかない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るための道具のことで、都市開発の手法の説明には合わない。"}], "explanations": {"TOD": "公共交通を中心にした都市開発の手法を指し、「TOD は公共交通を中心に、都市を開発する手法である」に合う。", "天気": "空模様を表す語で、都市開発の手法の説明には合わない。", "食欲": "食べたい気持ちを表す語で、都市開発の手法とは結びつかない。", "寝具": "寝るための道具のことで、都市開発の手法の説明には合わない。"}, "sentence_index": 0, "correct_answer": "TOD"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市は、センサーで交通量を測る TOD を進めている。", "explanation": "ここは〈スマートシティ〉の意味。ICT で街を管理する考えで、公共交通の周辺に機能を集める TOD とは違うので合わない。"}, {"text": "車を駅前に停めて電車に乗る、TOD を利用する人が増えた。", "explanation": "ここは〈パークアンドライド〉の意味。車を駅前に置いて乗り換える方式で、駅周辺に機能を集める TOD とは違う。"}, {"text": "無計画に郊外へ家が広がる、TOD が進んでいる。", "explanation": "ここは〈スプロール〉の意味。郊外へ無計画に広がる現象で、駅周辺に機能を集める TOD とは逆なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37281, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "TOD", "is_correct": true, "explanation": "行政機関を駅から徒歩圏に置く都市計画の名前として、「TOD の計画では、駅から徒歩圏に行政機関を置く」に合う。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を表す語で、都市計画の説明には合わない。"}, {"text": "食器", "is_correct": false, "explanation": "料理を盛る道具のことで、都市計画とは結びつかない。"}, {"text": "通帳", "is_correct": false, "explanation": "預金の記録帳のことで、都市計画の説明には合わない。"}], "explanations": {"TOD": "行政機関を駅から徒歩圏に置く都市計画の名前として、「TOD の計画では、駅から徒歩圏に行政機関を置く」に合う。", "体温": "体の温度を表す語で、都市計画の説明には合わない。", "食器": "料理を盛る道具のことで、都市計画とは結びつかない。", "通帳": "預金の記録帳のことで、都市計画の説明には合わない。"}, "sentence_index": 6, "correct_answer": "TOD"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アプリで電車とバスを一度に予約できる、TOD が広がっている。", "explanation": "ここは〈MaaS〉の意味。移動サービスを一つにまとめる仕組みで、駅周辺に機能を集める TOD とは別なので合わない。"}, {"text": "都心へ車で入るときに料金を取る、TOD を導入した。", "explanation": "ここは〈ロードプライシング〉の意味。車に料金をかける制度で、駅周辺に機能を集める TOD とは別なので合わない。"}, {"text": "大雨の前に、TOD で浸水しやすい地域を確認した。", "explanation": "ここは〈ハザードマップ〉の意味。災害の危険を示す地図で、都市構造を指す TOD とは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37281, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "都市計画は、TOD に基づいた進められている。", "corrected_sentence": "都市計画は、TOD に基づいて進められている。", "error_description": "「基づいた」は誤り。後ろの「進められている」につなぐには、て形の「基づいて」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37281, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅前の再開発は、TOD を沿って進んでいる。", "corrected_sentence": "駅前の再開発は、TOD に沿って進んでいる。", "error_description": "「TOD を沿って」は誤り。「沿う」は「〜に沿う」の形なので、「TOD に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8190f3b2-8b70-4b24-ae10-8485e700dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37282, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "が", "is_correct": false, "explanation": "主語を示す格。「駅が友だちを待っていました」では場所が主語になり、意味が通らない。"}, {"text": "で", "is_correct": true, "explanation": "動作が行われる場所を示す格。「駅で待っていた」として自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "対象を示す格。直後の「友だちを」と二重になり、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格。待っていた場所は行き先ではないので合わない。"}], "correct_answer": "で", "explanations": {"が": "主語を示す格。「駅が友だちを待っていました」では場所が主語になり、意味が通らない。", "で": "動作が行われる場所を示す格。「駅で待っていた」として自然に続く。", "を": "対象を示す格。直後の「友だちを」と二重になり、不自然。", "へ": "方向を示す格。待っていた場所は行き先ではないので合わない。"}, "error_tags": {"が": "主語を示す格。場所を主語にすると意味が通らない", "を": "対象を示す格。直後の「友だちを」と二重になる", "へ": "方向を示す格。待つ場所は行き先ではない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37282, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "と", "is_correct": false, "explanation": "並列を示す格。「次の駅と降りて」では降車の場所を示せず、不自然。"}, {"text": "で", "is_correct": true, "explanation": "動作が行われる場所を示す格。「次の駅で降りて」として自然に続く。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の格。「次の駅の降りて」と続かず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す格。降車の場所を示せないので、文意に合わない。"}], "correct_answer": "で", "explanations": {"と": "並列を示す格。「次の駅と降りて」では降車の場所を示せず、不自然。", "で": "動作が行われる場所を示す格。「次の駅で降りて」として自然に続く。", "の": "連体修飾の格。「次の駅の降りて」と続かず、文が成り立たない。", "より": "比較の基準を示す格。降車の場所を示せないので、文意に合わない。"}, "error_tags": {"と": "並列を示す格。降車の場所を示せない", "の": "連体修飾の格。「降りて」と続かない", "より": "比較の基準を示す格。降車の場所にはならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37282, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "でんしゃやバスにのるためのばしょです。", "primary_collocate": null, "pronunciation": "えき", "ipa": "eki", "syllable_count": 2, "sentences": [{"text": "電車に乗るために、駅まで歩いて行きます。", "target_word": "駅", "complexity_tier": "T3", "furigana": "電車[でんしゃ]に乗[の]るために、駅[えき]まで歩[ある]いて行[い]きます。", "sentence_source": "generated"}, {"text": "駅で友だちを待っていましたが、なかなか来ませんでした。", "target_word": "駅", "complexity_tier": "T3", "furigana": "駅[えき]で友[とも]だちを待[ま]っていましたが、なかなか来[き]ませんでした。", "sentence_source": "generated"}, {"text": "この駅からバスに乗ると、学校まで10分ほどで着きます。", "target_word": "駅", "complexity_tier": "T3", "furigana": "この駅[えき]からバスに乗ると、学校まで10分ほどで着きます。", "sentence_source": "generated"}, {"text": "駅の前に大きいパン屋があって、朝からいい匂いがします。", "target_word": "駅", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]に大[おお]きいパン屋[や]があって、朝[あさ]からいい匂[にお]いがします。", "sentence_source": "generated"}, {"text": "雨が降っていたので、駅まで傘を持って迎えに行きました。", "target_word": "駅", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]っていたので、駅[えき]まで傘[かさ]を持[も]って迎[むか]えに行[い]きました。", "sentence_source": "generated"}, {"text": "家から駅が近いので、毎朝歩いて通勤しています。", "target_word": "駅", "complexity_tier": "T3", "furigana": "家[いえ]から駅[えき]が近[ちか]いので、毎朝[まいあさ]歩[ある]いて通勤[つうきん]しています。", "sentence_source": "generated"}, {"text": "駅で切符を買ってから、ホームに上がりました。", "target_word": "駅", "complexity_tier": "T3", "furigana": "駅[えき]で切符[きっぷ]を買[か]ってから、ホームに上[あ]がりました。", "sentence_source": "generated"}, {"text": "次の駅で降りて、そこから歩いてください。", "target_word": "駅", "complexity_tier": "T3", "furigana": "次[つぎ]の駅[えき]で降[お]りて、そこから歩[ある]いてください。", "sentence_source": "generated"}, {"text": "道に迷ったときは、駅で聞くといいですよ。", "target_word": "駅", "complexity_tier": "T3", "furigana": "道に迷ったときは、駅[えき]で聞くといいですよ。", "sentence_source": "generated"}, {"text": "夜遅くなって、駅には人が少なくなりました。", "target_word": "駅", "complexity_tier": "T3", "furigana": "夜[よる]遅[おそ]くなって、駅[えき]には人[ひと]が少[すく]なくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "駅", "label": "基本形"}], "register": "丁寧体（です・ます）", "sense_fingerprint": "電車やバスに乗るために行く場所。日常の移動で使う身近な場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481ed36a-14ce-4134-9f49-87c6b4fc588f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37282, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切符", "is_correct": false, "explanation": "切符は買うものなので、歩いて行く先の場所にはならない。"}, {"text": "駅", "is_correct": true, "explanation": "電車に乗るための場所で、「まで歩いて行く」の到達点として合う。"}, {"text": "時刻表", "is_correct": false, "explanation": "時刻表は見る資料で、行く先の場所を表さないので合わない。"}, {"text": "運賃", "is_correct": false, "explanation": "運賃は料金のことで、歩いて行く先にはならないので合わない。"}], "explanations": {"切符": "切符は買うものなので、歩いて行く先の場所にはならない。", "駅": "電車に乗るための場所で、「まで歩いて行く」の到達点として合う。", "時刻表": "時刻表は見る資料で、行く先の場所を表さないので合わない。", "運賃": "運賃は料金のことで、歩いて行く先にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "駅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "車のガソリンが少なくなったので、駅で給油しました。", "explanation": "ここは〈ガソリンスタンド〉の意味。駅は電車やバスに乗る場所なので、給油はできない。"}, {"text": "夕方、船は駅を出て、島へ向かいました。", "explanation": "ここは〈港〉の意味。船は港を出るもので、駅は電車やバスのための場所なので合わない。"}, {"text": "飛行機に乗るために、駅まで行きました。", "explanation": "ここは〈空港〉の意味。飛行機に乗るのは空港なので、駅では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37282, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電車", "is_correct": false, "explanation": "電車は乗り物で、切符を買う場所ではないので「で切符を買ってから」に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、切符を買う場所にはならないので合わない。"}, {"text": "駅", "is_correct": true, "explanation": "乗車前に切符を買う場所で、「で切符を買ってから、ホームに上がる」の流れに合う。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は書いたり送ったりするもので、切符を買う場所にはならないので合わない。"}], "explanations": {"電車": "電車は乗り物で、切符を買う場所ではないので「で切符を買ってから」に合わない。", "天気": "天気は空模様のことで、切符を買う場所にはならないので合わない。", "駅": "乗車前に切符を買う場所で、「で切符を買ってから、ホームに上がる」の流れに合う。", "手紙": "手紙は書いたり送ったりするもので、切符を買う場所にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "駅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合を観るために、駅で球場に入りました。", "explanation": "ここは〈球場〉の意味。駅は電車やバスのための施設で、試合を観る場所ではないので合わない。"}, {"text": "休日は、駅でライオンを見て過ごしました。", "explanation": "ここは〈動物園〉の意味。駅は電車やバスのための施設で、動物を見る場所ではないので合わない。"}, {"text": "夜は、駅でベッドに入って眠りました。", "explanation": "ここは〈寝室〉の意味。駅は電車やバスのための施設で、寝る場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37282, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝、学校に行くために、駅で歩いて行きます。", "corrected_sentence": "毎朝、学校に行くために、駅まで歩いて行きます。", "error_description": "「駅で」は動作の場所を示す格。「歩いて行く」の到達点は「まで」で示すので、「で」が誤り。正しくは「駅まで」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37282, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝坊せず、朝早く駅を着きました。", "corrected_sentence": "寝坊せず、朝早く駅に着きました。", "error_description": "「着く」は到着点を「に」で示す。「駅を」の「を」が誤りで、正しくは「駅に着きました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37283, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "対象を示す格。「できる」は主語に「が」を取るので、「を」は不自然。"}, {"text": "が", "is_correct": true, "explanation": "「できる」の主語を示す格。新しい駅が現れた、という意味になり自然。"}, {"text": "に", "is_correct": false, "explanation": "場所・帰着を示す格。「できる」の主語にはならず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を示す格。「できる」の主語にはならず、意味が通らない。"}], "correct_answer": "が", "explanations": {"を": "対象を示す格。「できる」は主語に「が」を取るので、「を」は不自然。", "が": "「できる」の主語を示す格。新しい駅が現れた、という意味になり自然。", "に": "場所・帰着を示す格。「できる」の主語にはならず、文が成り立たない。", "で": "場所・手段を示す格。「できる」の主語にはならず、意味が通らない。"}, "error_tags": {"を": "対象を示す格。「できる」は「が」で主語を示す", "に": "場所・帰着を示す格。主語にはならない", "で": "場所・手段を示す格。主語にはならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37283, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "の", "is_correct": false, "explanation": "連体修飾の格。「駅の」の後に「とても静かだった」が続かず、文が成り立たない。"}, {"text": "は", "is_correct": true, "explanation": "主題を示す。「駅は、とても静かだった」と状態を述べる文になり自然。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す格。「駅と、とても静かだった」では主語と状態がつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格。状態を述べる文には合わない。"}], "correct_answer": "は", "explanations": {"の": "連体修飾の格。「駅の」の後に「とても静かだった」が続かず、文が成り立たない。", "は": "主題を示す。「駅は、とても静かだった」と状態を述べる文になり自然。", "と": "並列を示す格。「駅と、とても静かだった」では主語と状態がつながらない。", "へ": "方向を示す格。状態を述べる文には合わない。"}, "error_tags": {"の": "連体修飾の格。後に述語が続かない", "と": "並列を示す格。主語と状態がつながらない", "へ": "方向を示す格。状態を述べる文に合わない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37283, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "鉄道の駅。電車やバスが停車し、乗客が乗り降りする施設。", "primary_collocate": null, "pronunciation": "えき", "ipa": "eki", "syllable_count": 2, "sentences": [{"text": "この駅は一日に十万人以上の乗客が利用する。", "target_word": "駅", "complexity_tier": "T3", "furigana": "この駅[えき]は一日[いちにち]に十万人[じゅうまんにん]以上[いじょう]の乗客[じょうきゃく]が利用[りよう]する。", "sentence_source": "generated"}, {"text": "新しい駅ができてから、周りに店やマンションが増えた。", "target_word": "駅", "complexity_tier": "T3", "furigana": "新[あたら]しい駅[えき]ができてから、周[まわ]りに店[みせ]やマンションが増[ふ]えた。", "sentence_source": "generated"}, {"text": "駅のホームで電車を待つ人が列を作っている。", "target_word": "駅", "complexity_tier": "T3", "furigana": "駅[えき]のホームで電車[でんしゃ]を待[ま]つ人[ひと]が列[れつ]を作[つく]っている。", "sentence_source": "generated"}, {"text": "事故のため、電車は駅に止まったまま動かない。", "target_word": "駅", "complexity_tier": "T3", "furigana": "事故[じこ]のため、電車[でんしゃ]は駅[えき]に止[と]まったまま動[うご]かない。", "sentence_source": "generated"}, {"text": "急行は小さな駅には停車しないので、乗り換えが必要だ。", "target_word": "駅", "complexity_tier": "T3", "furigana": "急行[きゅうこう]は小[ちい]さな駅[えき]には停車[ていしゃ]しないので、乗[の]り換[か]えが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "駅の改札を出ると、目の前にバス乗り場がある。", "target_word": "駅", "complexity_tier": "T3", "furigana": "駅[えき]の改札[かいさつ]を出[で]ると、目[め]の前[まえ]にバス乗[の]り場[ば]がある。", "sentence_source": "generated"}, {"text": "古い駅の建物は、今も観光客に人気がある。", "target_word": "駅", "complexity_tier": "T3", "furigana": "古[ふる]い駅[えき]の建物[たてもの]は、今[いま]も観光客[かんこうきゃく]に人気[にんき]がある。", "sentence_source": "generated"}, {"text": "終電が出たあとの駅は、とても静かだった。", "target_word": "駅", "complexity_tier": "T3", "furigana": "終電[しゅうでん]が出[で]たあとの駅[えき]は、とても静[しず]かだった。", "sentence_source": "generated"}, {"text": "駅の階段で足を滑らせて、けがをした人がいた。", "target_word": "駅", "complexity_tier": "T3", "furigana": "駅[えき]の階段[かいだん]で足[あし]を滑[すべ]らせて、けがをした人[ひと]がいた。", "sentence_source": "generated"}, {"text": "私は駅の売店で新聞とお茶を買って、電車に乗った。", "target_word": "駅", "complexity_tier": "T3", "furigana": "私[わたし]は駅[えき]の売店[ばいてん]で新聞[しんぶん]とお茶[ちゃ]を買[か]って、電車[でんしゃ]に乗[の]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "駅", "label": "基本形"}], "register": "普通体（だ・である調）", "sense_fingerprint": "鉄道の施設としての駅。ホームや改札があり、列車が停車して乗客が乗り降りする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481ed36a-14ce-4134-9f49-87c6b4fc588f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37283, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切符", "is_correct": false, "explanation": "切符は一枚の券で、十万人が利用する対象にはならないので合わない。"}, {"text": "駅", "is_correct": true, "explanation": "乗客が乗り降りする施設で、一日の利用者数を述べる主語として合う。"}, {"text": "運賃", "is_correct": false, "explanation": "運賃は料金のことで、乗客が利用する施設ではないので合わない。"}, {"text": "時刻表", "is_correct": false, "explanation": "時刻表は情報の資料で、乗客が利用する施設ではないので合わない。"}], "explanations": {"切符": "切符は一枚の券で、十万人が利用する対象にはならないので合わない。", "駅": "乗客が乗り降りする施設で、一日の利用者数を述べる主語として合う。", "運賃": "運賃は料金のことで、乗客が利用する施設ではないので合わない。", "時刻表": "時刻表は情報の資料で、乗客が利用する施設ではないので合わない。"}, "sentence_index": 0, "correct_answer": "駅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生が駅で授業を始めた。", "explanation": "ここは〈教室〉の意味。駅は鉄道の施設で、授業を行う場所ではないので合わない。"}, {"text": "船は駅に着いて、乗客を降ろした。", "explanation": "ここは〈船着き場〉の意味。船が着くのは港や船着き場で、駅は電車やバスのための施設なので合わない。"}, {"text": "夏の午後、駅で海に入って泳ぎました。", "explanation": "ここは〈海水浴場〉の意味。駅は電車やバスのための施設で、海で泳ぐ場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37283, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "座席", "is_correct": false, "explanation": "座席は乗り物の中の席で、「古い〜の建物」の対象にはならないので合わない。"}, {"text": "駅", "is_correct": true, "explanation": "「古い」「建物」を修飾する対象として、駅の建物と自然につながる。"}, {"text": "運転士", "is_correct": false, "explanation": "運転士は人で、建物を修飾する対象にはならないので合わない。"}, {"text": "車両", "is_correct": false, "explanation": "車両は乗り物なので、「古い〜の建物」の対象として合わない。"}], "explanations": {"座席": "座席は乗り物の中の席で、「古い〜の建物」の対象にはならないので合わない。", "駅": "「古い」「建物」を修飾する対象として、駅の建物と自然につながる。", "運転士": "運転士は人で、建物を修飾する対象にはならないので合わない。", "車両": "車両は乗り物なので、「古い〜の建物」の対象として合わない。"}, "sentence_index": 6, "correct_answer": "駅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "休日は、駅で牛の乳をしぼりました。", "explanation": "ここは〈牧場〉の意味。駅は電車やバスのための施設で、牛の世話をする場所ではないので合わない。"}, {"text": "夏休みに、駅でお城の天守閣に登りました。", "explanation": "ここは〈城〉の意味。駅は電車やバスのための施設で、天守閣に登る場所ではないので合わない。"}, {"text": "大切な法事のため、駅でお寺の鐘をつきました。", "explanation": "ここは〈寺〉の意味。駅は鉄道の施設で、鐘をついたりお経を唱えたりする場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37283, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅に乗った電車は、十分ほど遅れて出発した。", "corrected_sentence": "駅で乗った電車は、十分ほど遅れて出発した。", "error_description": "「乗る」の場所は「で」で示す。「駅に乗った」の「に」が誤りで、正しくは「駅で乗った」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37283, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅を着いた人は、急いで改札へ向かった。", "corrected_sentence": "駅に着いた人は、急いで改札へ向かった。", "error_description": "「着く」は到着点を「に」で示す。「駅を」の「を」が誤りで、正しくは「駅に着いた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37284, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「商業の会社」で、名詞を修飾する「の」。「会社」を説明する形として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「商業が会社で働いて」は「働く」の主語として不自然で、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「商業を会社で働いて」は「働く」が目的語を取らず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「商業に会社で」は場所や方向の関係が成り立たず、文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「商業の会社」で、名詞を修飾する「の」。「会社」を説明する形として正しい。", "が": "「商業が会社で働いて」は「働く」の主語として不自然で、文が成り立たない。", "を": "「商業を会社で働いて」は「働く」が目的語を取らず、文が成り立たない。", "に": "「商業に会社で」は場所や方向の関係が成り立たず、文の意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "格の不一致"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37284, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「商業は」で、地域の商業について述べる主題を示す「は」。「よくなった」に続く形として正しい。"}, {"text": "と", "is_correct": false, "explanation": "「商業とよくなった」は成り立たず、「よくなった」の主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「商業へよくなった」は方向の意味にならず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「商業からよくなった」は起点の意味にならず、「よくなった」と結びつかない。"}], "correct_answer": "は", "explanations": {"は": "「商業は」で、地域の商業について述べる主題を示す「は」。「よくなった」に続く形として正しい。", "と": "「商業とよくなった」は成り立たず、「よくなった」の主語にならない。", "へ": "「商業へよくなった」は方向の意味にならず、文が成り立たない。", "から": "「商業からよくなった」は起点の意味にならず、「よくなった」と結びつかない。"}, "error_tags": {"と": "並列・引用", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37284, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お店や会社など、ものを売ったり買ったりすることに関係する仕事や場所のことです。", "primary_collocate": null, "pronunciation": "しょうぎょう", "ipa": "ɕoː.ɡʲoː", "syllable_count": 4, "sentences": [{"text": "この町は商業がさかんで、いつも多くの人が買い物に来ます。", "target_word": "商業", "complexity_tier": "T2", "furigana": "この町[まち]は商業[しょうぎょう]がさかんで、いつも多[おお]くの人[ひと]が買[か]い物[もの]に来[き]ます。", "sentence_source": "generated"}, {"text": "姉は商業の会社で働いていて、毎日たくさんの品物を扱っている。", "target_word": "商業", "complexity_tier": "T3", "furigana": "姉[あね]は商業[しょうぎょう]の会社[かいしゃ]で働[はたら]いていて、毎日[まいにち]たくさんの品物[しなもの]を扱[あつか]っている。", "sentence_source": "generated"}, {"text": "駅の近くは商業の中心で、大きな店がたくさんあります。", "target_word": "商業", "complexity_tier": "T2", "furigana": "駅[えき]の近[ちか]くは商業[しょうぎょう]の中心[ちゅうしん]で、大[おお]きな店[みせ]がたくさんあります。", "sentence_source": "generated"}, {"text": "雨が続いて客が来ないので、町の商業は元気がありません。", "target_word": "商業", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]いて客[きゃく]が来[こ]ないので、町[まち]の商業[しょうぎょう]は元気[げんき]がありません。", "sentence_source": "generated"}, {"text": "父は商業の仕事をしていて、毎日店で品物を売っています。", "target_word": "商業", "complexity_tier": "T2", "furigana": "父[ちち]は商業[しょうぎょう]の仕事[しごと]をしていて、毎日[まいにち]店[みせ]で品物[しなもの]を売[う]っています。", "sentence_source": "generated"}, {"text": "昔、この港は商業で栄えた。", "target_word": "商業", "complexity_tier": "T2", "furigana": "昔[むかし]、この港[みなと]は商業[しょうぎょう]で栄[さか]えた。", "sentence_source": "generated"}, {"text": "商業が発達すると、町はにぎやかになる。", "target_word": "商業", "complexity_tier": "T3", "furigana": "商業[しょうぎょう]が発達[はったつ]すると、町[まち]はにぎやかになる。", "sentence_source": "generated"}, {"text": "新しい道ができて、この地域の商業はよくなった。", "target_word": "商業", "complexity_tier": "T3", "furigana": "新[あたら]しい道[みち]ができて、この地域[ちいき]の商業[しょうぎょう]はよくなった。", "sentence_source": "generated"}, {"text": "市は商業を助けるために、店を開く人にお金を出している。", "target_word": "商業", "complexity_tier": "T3", "furigana": "市[し]は商業[しょうぎょう]を助[たす]けるために、店[みせ]を開[ひら]く人[ひと]にお金[かね]を出[だ]している。", "sentence_source": "generated"}, {"text": "商業と工業のちがいを、先生が地図を使って説明してくれた。", "target_word": "商業", "complexity_tier": "T3", "furigana": "商業[しょうぎょう]と工業[こうぎょう]のちがいを、先生[せんせい]が地図[ちず]を使[つか]って説明[せつめい]してくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "商業", "label": "基本形"}, {"form": "商業的", "label": "形状詞化"}], "register": "中立", "sense_fingerprint": "店や会社の売り買いの仕事・場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37284, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商業", "is_correct": true, "explanation": "「商業がさかんで」の主語となる分野名で、町の経済の様子に合う。"}, {"text": "数学", "is_correct": false, "explanation": "学問の名で、「数学がさかんで」は町の様子の説明として成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "気象を指す語で、「天気がさかんで」は町の様子を表さない。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品の名で、「砂糖がさかんで」は町の経済の説明にならない。"}], "explanations": {"商業": "「商業がさかんで」の主語となる分野名で、町の経済の様子に合う。", "数学": "学問の名で、「数学がさかんで」は町の様子の説明として成り立たない。", "天気": "気象を指す語で、「天気がさかんで」は町の様子を表さない。", "砂糖": "食品の名で、「砂糖がさかんで」は町の経済の説明にならない。"}, "sentence_index": 0, "correct_answer": "商業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "看護師は商業で患者の世話をする。", "explanation": "ここは〈病院〉の意味。患者の世話をする場所は病院で、商業は商店や店舗が集まる所なので合わない。"}, {"text": "商業で子どもたちが遊ぶ。", "explanation": "ここは〈校庭〉の意味。子どもが遊ぶ場所は校庭で、商業は店や商いの場を指すので合わない。"}, {"text": "商業に電車が着く。", "explanation": "ここは〈駅〉の意味。電車が着く場所は駅で、商業は商店が集まる地区を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37284, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商業", "is_correct": true, "explanation": "「商業が発達すると」の主語となる分野名で、町がにぎやかになる文脈に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "眠い感覚を指す語で、「眠気が発達する」とは言えない。"}, {"text": "寒さ", "is_correct": false, "explanation": "気温の状態を指す語で、「寒さが発達する」は成り立たない。"}, {"text": "湿気", "is_correct": false, "explanation": "空気中の水分を指す語で、「湿気が発達する」は成り立たない。"}], "explanations": {"商業": "「商業が発達すると」の主語となる分野名で、町がにぎやかになる文脈に合う。", "眠気": "眠い感覚を指す語で、「眠気が発達する」とは言えない。", "寒さ": "気温の状態を指す語で、「寒さが発達する」は成り立たない。", "湿気": "空気中の水分を指す語で、「湿気が発達する」は成り立たない。"}, "sentence_index": 6, "correct_answer": "商業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商業で眠った。", "explanation": "ここは〈寝室〉の意味。眠る場所は寝室で、商業は眠るための部屋ではないので合わない。"}, {"text": "商業で絵を見る。", "explanation": "ここは〈美術館〉の意味。絵を見る場所は美術館で、商業は店が集まる地区を指すので合わない。"}, {"text": "商業で手を合わせる。", "explanation": "ここは〈寺〉の意味。手を合わせて祈る場所は寺で、商業は店が集まる地区を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37284, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅前の商業に盛んで、客が多い。", "corrected_sentence": "駅前の商業が盛んで、客が多い。", "error_description": "助詞が誤り。「盛んだ」の主語は「が」で示すので、「に」は誤り。正しくは「商業が盛んで」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37284, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は商業的の会社で、新しい機械を売っている。", "corrected_sentence": "兄は商業の会社で、新しい機械を売っている。", "error_description": "語の形が誤り。「商業的」は形状詞なので、名詞の前では「商業的な」と「な」が必要で、「的の」は成り立たない。名詞「商業」を使うなら「商業の会社」となる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37285, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「商業が盛んで」の主語を示す「が」。「盛んだ」の主語として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「商業を盛んで」は「盛んだ」が目的語を取らないため成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「商業に盛んで」は「盛んだ」の形容に合わず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「商業で盛んで」は成り立たず、「盛んだ」と結びつかない。"}], "correct_answer": "が", "explanations": {"が": "「商業が盛んで」の主語を示す「が」。「盛んだ」の主語として正しい。", "を": "「商業を盛んで」は「盛んだ」が目的語を取らないため成り立たない。", "に": "「商業に盛んで」は「盛んだ」の形容に合わず、文が成り立たない。", "で": "「商業で盛んで」は成り立たず、「盛んだ」と結びつかない。"}, "error_tags": {"を": "目的語", "に": "格の不一致", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37285, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「商業が発達すると」の主語を示す「が」。「発達する」の主語として正しい。"}, {"text": "と", "is_correct": false, "explanation": "「商業と発達すると」は「発達する」の主語にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「商業へ発達すると」は方向の意味にならず、「発達する」と結びつかない。"}, {"text": "の", "is_correct": false, "explanation": "「商業の発達すると」は「発達する」が名詞を取れず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「商業が発達すると」の主語を示す「が」。「発達する」の主語として正しい。", "と": "「商業と発達すると」は「発達する」の主語にならず、文が成り立たない。", "へ": "「商業へ発達すると」は方向の意味にならず、「発達する」と結びつかない。", "の": "「商業の発達すると」は「発達する」が名詞を取れず、文が成り立たない。"}, "error_tags": {"と": "並列・引用", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37285, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "商品を売買する活動や、そのための施設・産業のこと。", "primary_collocate": null, "pronunciation": "しょうぎょう", "ipa": "ɕoː.ɡʲoː", "syllable_count": 4, "sentences": [{"text": "現代のパン作りでは、商業の論理によって画一的な効率性が優先されがちであるが、彼が真に渇望するのは、サワードウ特有の繊細かつ複雑な酸味と、穀物本来が秘める深い旨みの極致である。", "target_word": "商業", "complexity_tier": "T5", "furigana": "現代[げんだい]のパン作[づく]りでは、商業[しょうぎょう]の論理[ろんり]によって画一的[かくいつてき]な効率性[こうりつせい]が優先[ゆうせん]されがちであるが、彼[かれ]が真[しん]に渇望[かつぼう]するのは、サワードウ特有[とくゆう]の繊細[せんさい]かつ複雑[ふくざつ]な酸味[さんみ]と、穀物[こくもつ]本来[ほんらい]が秘[ひ]める深[ふか]い旨[うま]みの極致[きょくち]である。", "sentence_source": "generated"}, {"text": "この港町は昔から商業が盛んで、各地から商人が集まってきた。", "target_word": "商業", "complexity_tier": "T3", "furigana": "この港町[みなとまち]は昔[むかし]から商業[しょうぎょう]が盛[さか]んで、各地[かくち]から商人[しょうにん]が集[あつ]まってきた。", "sentence_source": "generated"}, {"text": "駅前は商業の中心なので、平日でも買い物客でにぎわっている。", "target_word": "商業", "complexity_tier": "T3", "furigana": "駅前[えきまえ]は商業[しょうぎょう]の中心[ちゅうしん]なので、平日[へいじつ]でも買[か]い物客[ものきゃく]でにぎわっている。", "sentence_source": "generated"}, {"text": "政府は商業の規制を緩めて、新しい店が参入しやすくした。", "target_word": "商業", "complexity_tier": "T3", "furigana": "政府[せいふ]は商業[しょうぎょう]の規制[きせい]を緩[ゆる]めて、新[あたら]しい店[みせ]が参入[さんにゅう]しやすくした。", "sentence_source": "generated"}, {"text": "町の商業が衰えたため、閉まったままの店が目立つようになった。", "target_word": "商業", "complexity_tier": "T3", "furigana": "町[まち]の商業[しょうぎょう]が衰[おとろ]えたため、閉[し]まったままの店[みせ]が目立[めだ]つようになった。", "sentence_source": "generated"}, {"text": "江戸時代には大坂で商業が大きく発展した。", "target_word": "商業", "complexity_tier": "T3", "furigana": "江戸[えど]時代[じだい]には大坂[おおさか]で商業[しょうぎょう]が大[おお]きく発展[はってん]した。", "sentence_source": "generated"}, {"text": "この地区は工業ではなく商業で栄えてきた。", "target_word": "商業", "complexity_tier": "T3", "furigana": "この地区[ちく]は工業[こうぎょう]ではなく商業[しょうぎょう]で栄[さか]えてきた。", "sentence_source": "generated"}, {"text": "商業が発達すると、人や物の行き来も自然に増える。", "target_word": "商業", "complexity_tier": "T3", "furigana": "商業[しょうぎょう]が発達[はったつ]すると、人[ひと]や物[もの]の行[い]き来[き]も自然[しぜん]に増[ふ]える。", "sentence_source": "generated"}, {"text": "観光客が減って、地元の商業は大きな打撃を受けた。", "target_word": "商業", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]が減[へ]って、地元[じもと]の商業[しょうぎょう]は大[おお]きな打撃[だげき]を受[う]けた。", "sentence_source": "generated"}, {"text": "祖父は長年、商業に携わってきた人で、市場の事情にとても詳しい。", "target_word": "商業", "complexity_tier": "T3", "furigana": "祖父[そふ]は長年[ながねん]、商業[しょうぎょう]に携[たずさ]わってきた人[ひと]で、市場[しじょう]の事情[じじょう]にとても詳[くわ]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "商業", "label": "基本形"}, {"form": "商業的", "label": "形状詞化"}], "register": "中立（書き言葉寄り）", "sense_fingerprint": "商品を売り買いする活動・産業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 6 words above tier T3 (max 3): 画一 (Zipf 2.87), 渇望 (Zipf 2.92), 酸味 (Zipf 3.39), 秘める (Zipf 2.52), 旨み (Zipf 3.01), 極致 (Zipf 2.48)']::text[], 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37285, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商業", "is_correct": true, "explanation": "「商業の論理」の語で、利益を優先する考え方を表す語として文脈に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "眠い感覚を指す語で、「眠気の論理」とは言えない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を指す語で、「天気の論理」は意味が通らない。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品の名で、「砂糖の論理」は成り立たない。"}], "explanations": {"商業": "「商業の論理」の語で、利益を優先する考え方を表す語として文脈に合う。", "眠気": "眠い感覚を指す語で、「眠気の論理」とは言えない。", "天気": "空模様を指す語で、「天気の論理」は意味が通らない。", "砂糖": "食品の名で、「砂糖の論理」は成り立たない。"}, "sentence_index": 0, "correct_answer": "商業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎朝、商業を洗っている。", "explanation": "ここは〈車〉の意味。車を洗う時は洗うを使う。商業は洗えるものではないので合わない。"}, {"text": "工場の商業を炒めた。", "explanation": "ここは〈食材〉の意味。炒めるのは野菜などの食材で、商業は炒められないので合わない。"}, {"text": "商業を運ぶトラックが通る。", "explanation": "ここは〈荷物〉の意味。運ぶのは品物で、商業は運べる対象ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37285, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商業", "is_correct": true, "explanation": "「商業で栄えてきた」の主語となる分野名で、「工業ではなく」と対になる文脈に合う。"}, {"text": "税金", "is_correct": false, "explanation": "税を指す語で、地域が栄える理由として「税金で栄える」とは言えない。"}, {"text": "株価", "is_correct": false, "explanation": "株の値段を指す語で、「株価で栄える」は地域の繁栄の表現にならない。"}, {"text": "通貨", "is_correct": false, "explanation": "貨幣を指す語で、「通貨で栄えてきた」は地域の産業の説明にならない。"}], "explanations": {"商業": "「商業で栄えてきた」の主語となる分野名で、「工業ではなく」と対になる文脈に合う。", "税金": "税を指す語で、地域が栄える理由として「税金で栄える」とは言えない。", "株価": "株の値段を指す語で、「株価で栄える」は地域の繁栄の表現にならない。", "通貨": "貨幣を指す語で、「通貨で栄えてきた」は地域の産業の説明にならない。"}, "sentence_index": 6, "correct_answer": "商業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎朝、商業で歯を磨く。", "explanation": "ここは〈洗面所〉の意味。歯を磨く場所は洗面所で、商業は家の中の水回りを指さないので合わない。"}, {"text": "商業は畑で野菜を育てている。", "explanation": "ここは〈農家〉の意味。畑で野菜を育てるのは農家で、商業は作る主体ではないので合わない。"}, {"text": "医師は商業で患者を診る。", "explanation": "ここは〈病院〉の意味。患者を診る施設は病院で、商業は商いのための施設を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37285, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この通りは商業を盛んで、人が集まる。", "corrected_sentence": "この通りは商業が盛んで、人が集まる。", "error_description": "助詞が誤り。「盛んだ」の主語は「が」で示すので、「を」は誤り。正しくは「商業が盛んで」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37285, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地方の商業的が発達すると、人の往来が増える。", "corrected_sentence": "地方の商業が発達すると、人の往来が増える。", "error_description": "語の形が誤り。「商業的」は形状詞なので「商業的な」の形で使う。名詞の「商業」に「的」を付けて「が」で続けるのは誤り。正しくは「商業が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37286, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "対象を示す格。直後の「避難所を」と二重になり、不自然。"}, {"text": "が", "is_correct": true, "explanation": "主語を示す格。行政が避難所を開いた、と動作の主体になる。"}, {"text": "に", "is_correct": false, "explanation": "相手・位置を示す格。「行政に避難所を開いて」では主語にならず、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格。避難所を開く主体にはならない。"}], "correct_answer": "が", "explanations": {"を": "対象を示す格。直後の「避難所を」と二重になり、不自然。", "が": "主語を示す格。行政が避難所を開いた、と動作の主体になる。", "に": "相手・位置を示す格。「行政に避難所を開いて」では主語にならず、意味が通らない。", "へ": "方向を示す格。避難所を開く主体にはならない。"}, "error_tags": {"を": "対象を示す格。直後の「避難所を」と二重になる", "に": "相手・位置を示す格。主語にならない", "へ": "方向を示す格。開く主体にはならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37286, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "と", "is_correct": false, "explanation": "並列を示す格。「行政と対応が遅い」では名詞がつながらず、意味が通らない。"}, {"text": "の", "is_correct": true, "explanation": "連体修飾の格。「行政の対応」と名詞を修飾して自然に続く。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す格。「行政から対応が遅い」では「の」がないと修飾が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "対象を示す格。「対応が遅い」の主語にはならず、文がつながらない。"}], "correct_answer": "の", "explanations": {"と": "並列を示す格。「行政と対応が遅い」では名詞がつながらず、意味が通らない。", "の": "連体修飾の格。「行政の対応」と名詞を修飾して自然に続く。", "から": "起点を示す格。「行政から対応が遅い」では「の」がないと修飾が成り立たない。", "を": "対象を示す格。「対応が遅い」の主語にはならず、文がつながらない。"}, "error_tags": {"と": "並列を示す格。「対応」とはつながらない", "から": "起点を示す格。名詞修飾に「の」が必要", "を": "対象を示す格。「対応が遅い」の主語にならず文が成り立たない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37286, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国や町の仕事をする人たちのことです。", "primary_collocate": null, "pronunciation": "ぎょうせい", "ipa": "ɡjoːseː", "syllable_count": 4, "sentences": [{"text": "行政の人が、町の道路の工事について説明に来た。", "target_word": "行政", "complexity_tier": "T3", "furigana": "行政[ぎょうせい]の人[ひと]が、町[まち]の道路[どうろ]の工事[こうじ]について説明[せつめい]に来[き]た。", "sentence_source": "generated"}, {"text": "台風のあと、行政が避難所を開いて住民を助けた。", "target_word": "行政", "complexity_tier": "T3", "furigana": "台風[たいふう]のあと、行政[ぎょうせい]が避難所[ひなんじょ]を開[ひら]いて住民[じゅうみん]を助[たす]けた。", "sentence_source": "generated"}, {"text": "ごみの出し方で困ったときは、行政に相談するといい。", "target_word": "行政", "complexity_tier": "T3", "furigana": "ごみの出[だ]し方[かた]で困[こま]ったときは、行政[ぎょうせい]に相談[そうだん]するといい。", "sentence_source": "generated"}, {"text": "行政は、町の人の意見を聞いて新しい公園を作った。", "target_word": "行政", "complexity_tier": "T3", "furigana": "行政[ぎょうせい]は、町[まち]の人[ひと]の意見[いけん]を聞[き]いて新[あたら]しい公園[こうえん]を作[つく]った。", "sentence_source": "generated"}, {"text": "この町では、行政と住民が協力して祭りを開いている。", "target_word": "行政", "complexity_tier": "T3", "furigana": "この町[まち]では、行政[ぎょうせい]と住民[じゅうみん]が協力[きょうりょく]して祭[まつ]りを開[ひら]いている。", "sentence_source": "generated"}, {"text": "行政に連絡したら、すぐに木を切りに来てくれた。", "target_word": "行政", "complexity_tier": "T3", "furigana": "行政[ぎょうせい]に連絡[れんらく]したら、すぐに木[き]を切[き]りに来[き]てくれた。", "sentence_source": "generated"}, {"text": "雪の日は、行政が道に塩をまいて、事故を防ぐ。", "target_word": "行政", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、行政[ぎょうせい]が道[みち]に塩[しお]をまいて、事故[じこ]を防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "行政の対応が遅いと、住民から不満の声が出た。", "target_word": "行政", "complexity_tier": "T3", "furigana": "行政[ぎょうせい]の対応[たいおう]が遅[おそ]いと、住民[じゅうみん]から不満[ふまん]の声[こえ]が出[で]た。", "sentence_source": "generated"}, {"text": "行政が配った地図を見て、避難場所を確かめた。", "target_word": "行政", "complexity_tier": "T3", "furigana": "行政[ぎょうせい]が配[くば]った地図[ちず]を見[み]て、避難場所[ひなんばしょ]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "引っ越しの手続きは、行政の窓口で行う。", "target_word": "行政", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの手続[てつづ]きは、行政[ぎょうせい]の窓口[まどぐち]で行[おこな]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "行政", "label": "基本形"}], "register": "普通体（だ・である調）", "sense_fingerprint": "国や町の役所で仕事をする人たち。住民の生活を支えるために動く役所側の人々", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481ed36a-14ce-4134-9f49-87c6b4fc588f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37286, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天気", "is_correct": false, "explanation": "天気は気象のことで、人を指さないので「〜の人」として合わない。"}, {"text": "行政", "is_correct": true, "explanation": "国や町の仕事をする人たちを指し、「〜の人」として自然に合う。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食べ物のことで、工事の説明に来る人を指さないので合わない。"}, {"text": "芸術", "is_correct": false, "explanation": "芸術は分野の名前で、工事の説明に来る人を指さないので合わない。"}], "explanations": {"天気": "天気は気象のことで、人を指さないので「〜の人」として合わない。", "行政": "国や町の仕事をする人たちを指し、「〜の人」として自然に合う。", "料理": "料理は食べ物のことで、工事の説明に来る人を指さないので合わない。", "芸術": "芸術は分野の名前で、工事の説明に来る人を指さないので合わない。"}, "sentence_index": 0, "correct_answer": "行政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その行政は、ホールで三曲歌って観客を喜ばせた。", "explanation": "ここは〈歌手〉の意味。行政は国や町の仕事をする人たちで、歌を歌う人ではないので合わない。"}, {"text": "友だちは、行政で切手を買った。", "explanation": "ここは〈郵便局〉の意味。行政は仕事や組織のことで、切手を売る場所ではないので合わない。"}, {"text": "週末は、行政で映画を観た。", "explanation": "ここは〈映画館〉の意味。行政は国や町の仕事をする人たちで、映画を観る場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37286, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電車", "is_correct": false, "explanation": "電車は乗り物で、道に塩をまく仕事の主語にはならないので合わない。"}, {"text": "水道", "is_correct": false, "explanation": "水道は水を届ける設備で、道に塩をまく主体にはならないので合わない。"}, {"text": "行政", "is_correct": true, "explanation": "道の安全を守る役所の仕事を担い、「が道に塩をまいて」の主語として合う。"}, {"text": "道路", "is_correct": false, "explanation": "道路は場所なので、塩をまく主体にはならないので合わない。"}], "explanations": {"電車": "電車は乗り物で、道に塩をまく仕事の主語にはならないので合わない。", "水道": "水道は水を届ける設備で、道に塩をまく主体にはならないので合わない。", "行政": "道の安全を守る役所の仕事を担い、「が道に塩をまいて」の主語として合う。", "道路": "道路は場所なので、塩をまく主体にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "行政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪をひいたので、行政で注射を打ってもらった。", "explanation": "ここは〈医者〉の意味。行政は町や国の仕事をする人たちで、注射を打つ立場ではないので合わない。"}, {"text": "久しぶりに、行政が客の髪を短く切った。", "explanation": "ここは〈美容師〉の意味。行政は町や国の仕事をする人たちで、客の髪を切る仕事ではないので合わない。"}, {"text": "朝早く、行政が畑で野菜を収穫した。", "explanation": "ここは〈農家〉の意味。行政は仕事をする人たちで、畑で作物を育てて収穫する仕事ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37286, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "住宅の補助金について、行政を問い合わせた。", "corrected_sentence": "住宅の補助金について、行政に問い合わせた。", "error_description": "「問い合わせる」は相手を「に」で示す。「を」が誤りで、正しくは「行政に問い合わせた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37286, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市民は行政を相談して、補助金を受け取った。", "corrected_sentence": "市民は行政に相談して、補助金を受け取った。", "error_description": "「相談する」は相手を「に」で示す。「を」が誤りで、正しくは「行政に相談して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37287, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "に", "is_correct": false, "explanation": "相手・位置を示す格。「担当する」は「を」で対象を取るので、「行政に担当する」は不自然。"}, {"text": "を", "is_correct": true, "explanation": "対象を示す格。「行政を担当する」と目的語として自然に続く。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格。担当の対象にはならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同を示す格。「行政と担当する」では対象を示せず、不自然。"}], "correct_answer": "を", "explanations": {"に": "相手・位置を示す格。「担当する」は「を」で対象を取るので、「行政に担当する」は不自然。", "を": "対象を示す格。「行政を担当する」と目的語として自然に続く。", "へ": "方向を示す格。担当の対象にはならないので合わない。", "と": "並列・共同を示す格。「行政と担当する」では対象を示せず、不自然。"}, "error_tags": {"に": "相手・位置を示す格。「担当する」は「を」で対象を取る", "へ": "方向を示す格。担当の対象にならない", "と": "並列・共同を示す格。対象を示せない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37287, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "で", "is_correct": false, "explanation": "場所・手段を示す格。「行政で判断は」では名詞を修飾できず、不自然。"}, {"text": "の", "is_correct": true, "explanation": "連体修飾の格。「行政の判断」と名詞を修飾して自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "対象を示す格。「行政を判断は」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す格。「行政から判断は」では修飾がつながらない。"}], "correct_answer": "の", "explanations": {"で": "場所・手段を示す格。「行政で判断は」では名詞を修飾できず、不自然。", "の": "連体修飾の格。「行政の判断」と名詞を修飾して自然に続く。", "を": "対象を示す格。「行政を判断は」では文が成り立たない。", "から": "起点を示す格。「行政から判断は」では修飾がつながらない。"}, "error_tags": {"で": "場所・手段を示す格。名詞修飾に「の」が必要", "を": "対象を示す格。判断と文がつながらない", "から": "起点を示す格。名詞修飾に「の」が必要"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37287, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国や地方公共団体が、法律に基づいて行う政治や管理の仕事。また、その組織。", "primary_collocate": null, "pronunciation": "ぎょうせい", "ipa": "ɡjoːseː", "syllable_count": 4, "sentences": [{"text": "行政は法律に基づいて、国民のための仕事を行う。", "target_word": "行政", "complexity_tier": "T3", "furigana": "行政[ぎょうせい]は法律[ほうりつ]に基[もと]づいて、国民[こくみん]のための仕事[しごと]を行[おこな]う。", "sentence_source": "generated"}, {"text": "国の行政を担当する機関は、各省庁に分かれている。", "target_word": "行政", "complexity_tier": "T3", "furigana": "国[くに]の行政[ぎょうせい]を担当[たんとう]する機関[きかん]は、各省庁[かくしょうちょう]に分[わ]かれている。", "sentence_source": "generated"}, {"text": "行政の無駄をなくすため、予算の使い方が見直された。", "target_word": "行政", "complexity_tier": "T3", "furigana": "行政[ぎょうせい]の無駄[むだ]をなくすため、予算[よさん]の使[つか]い方[かた]が見直[みなお]された。", "sentence_source": "generated"}, {"text": "地方の行政には、住民に近い立場での判断が求められる。", "target_word": "行政", "complexity_tier": "T3", "furigana": "地方[ちほう]の行政[ぎょうせい]には、住民[じゅうみん]に近[ちか]い立場[たちば]での判断[はんだん]が求[もと]められる。", "sentence_source": "generated"}, {"text": "行政の手続きが複雑で、申請に時間がかかった。", "target_word": "行政", "complexity_tier": "T3", "furigana": "行政[ぎょうせい]の手続[てつづ]きが複雑[ふくざつ]で、申請[しんせい]に時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "彼は大学で行政について学び、市役所に就職した。", "target_word": "行政", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]で行政[ぎょうせい]について学[まな]び、市役所[しやくしょ]に就職[しゅうしょく]した。", "sentence_source": "generated"}, {"text": "行政が民間企業に仕事を任せる例が増えている。", "target_word": "行政", "complexity_tier": "T3", "furigana": "行政[ぎょうせい]が民間企業[みんかんきぎょう]に仕事[しごと]を任[まか]せる例[れい]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "法律に反する行政の判断は、裁判で取り消されることがある。", "target_word": "行政", "complexity_tier": "T3", "furigana": "法律[ほうりつ]に反[はん]する行政[ぎょうせい]の判断[はんだん]は、裁判[さいばん]で取[と]り消[け]されることがある。", "sentence_source": "generated"}, {"text": "行政の透明性を高めるため、会議の記録が公開された。", "target_word": "行政", "complexity_tier": "T3", "furigana": "行政[ぎょうせい]の透明性[とうめいせい]を高[たか]めるため、会議[かいぎ]の記録[きろく]が公開[こうかい]された。", "sentence_source": "generated"}, {"text": "災害のとき、行政の判断が遅れると、被害が広がるおそれがある。", "target_word": "行政", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、行政[ぎょうせい]の判断[はんだん]が遅[おく]れると、被害[ひがい]が広[ひろ]がるおそれがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "行政", "label": "基本形"}], "register": "硬い書き言葉（だ・である調）", "sense_fingerprint": "法律に基づいて国や自治体が行う政治・管理の仕事と、その組織。制度としての行政", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481ed36a-14ce-4134-9f49-87c6b4fc588f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37287, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音楽", "is_correct": false, "explanation": "音楽は芸術の一分野で、法律に基づいて仕事を行う主語にはならないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は気象のことで、仕事を行う主語にはならないので合わない。"}, {"text": "行政", "is_correct": true, "explanation": "国や自治体が法律に基づいて行う仕事を担う主体で、主語として自然に合う。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食べ物のことで、仕事を行う主語にはならないので合わない。"}], "explanations": {"音楽": "音楽は芸術の一分野で、法律に基づいて仕事を行う主語にはならないので合わない。", "天気": "天気は気象のことで、仕事を行う主語にはならないので合わない。", "行政": "国や自治体が法律に基づいて行う仕事を担う主体で、主語として自然に合う。", "料理": "料理は食べ物のことで、仕事を行う主語にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "行政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "行政は国民の代表として、新しい法律を作る。", "explanation": "ここは〈国会〉（立法）の意味。法律を作るのは国会の役割で、行政は法律に基づいて仕事をするので合わない。"}, {"text": "行政は、体の具合が悪い患者を診る施設だ。", "explanation": "ここは〈病院〉の意味。行政は仕事や組織のことで、患者を診る施設ではないので合わない。"}, {"text": "行政は毎朝、新鮮な野菜を店頭に並べる。", "explanation": "ここは〈スーパー〉の意味。行政は仕事や組織のことで、野菜を売る店ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37287, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花", "is_correct": false, "explanation": "花は植物で、民間企業に仕事を任せる主語にはならないので合わない。"}, {"text": "電車", "is_correct": false, "explanation": "電車は乗り物で、民間企業に仕事を任せる主語にはならないので合わない。"}, {"text": "行政", "is_correct": true, "explanation": "国や自治体の仕事を担う主体で、民間に仕事を任せる主語として自然に合う。"}, {"text": "天井", "is_correct": false, "explanation": "天井は建物の部分で、仕事を任せる主語にはならないので合わない。"}], "explanations": {"花": "花は植物で、民間企業に仕事を任せる主語にはならないので合わない。", "電車": "電車は乗り物で、民間企業に仕事を任せる主語にはならないので合わない。", "行政": "国や自治体の仕事を担う主体で、民間に仕事を任せる主語として自然に合う。", "天井": "天井は建物の部分で、仕事を任せる主語にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "行政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "行政は、罪の重さを決めて判決を言い渡す。", "explanation": "ここは〈裁判所〉（司法）の意味。判決を言い渡すのは裁判所の役割で、行政は法律に基づいて仕事をするので合わない。"}, {"text": "行政は、客のために新しい料理を作る。", "explanation": "ここは〈料理人〉の意味。行政は国や町の仕事を担う人たちで、料理を作る仕事ではないので合わない。"}, {"text": "行政は、客に花束を作って売る。", "explanation": "ここは〈花屋〉の意味。行政は仕事をする人たちや組織で、花束を売る店ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37287, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市の行政を関わる職員が、住民の相談に応じる。", "corrected_sentence": "市の行政に関わる職員が、住民の相談に応じる。", "error_description": "「関わる」は関係する相手を「に」で示す。「を」が誤りで、正しくは「行政に関わる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37287, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今回の件は、行政な判断が必要になった。", "corrected_sentence": "今回の件は、行政的な判断が必要になった。", "error_description": "「行政」を使った形容動詞は「行政的な」。「行政な」は「的」を介さずに「な」を付けた誤りで、正しくは「行政的な」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37288, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最大", "is_correct": true, "explanation": "大きさの対義語。最小と対になる語として辞典に載る。"}, {"text": "最初", "is_correct": false, "explanation": "「最初」は順序の先頭を表し、大きさの対にはならない。"}, {"text": "最後", "is_correct": false, "explanation": "「最後」は順序の終わりを表し、大きさの対義語ではない。"}, {"text": "中心", "is_correct": false, "explanation": "「中心」は位置を表す語で、大きさの対義語ではない。"}], "correct_answer": "最大", "explanations": {"最大": "大きさの対義語。最小と対になる語として辞典に載る。", "最初": "「最初」は順序の先頭を表し、大きさの対にはならない。", "最後": "「最後」は順序の終わりを表し、大きさの対義語ではない。", "中心": "「中心」は位置を表す語で、大きさの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37288, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最大", "is_correct": true, "explanation": "大きさの対義語。最小と対になる語として辞典に載る。"}, {"text": "平均", "is_correct": false, "explanation": "「平均」は全体の中央的な値を表し、最小の対義語ではない。"}, {"text": "中間", "is_correct": false, "explanation": "「中間」は両端の間を指す語で、最小と対になる語ではない。"}, {"text": "全体", "is_correct": false, "explanation": "「全体」は部分と対になる語で、最小の対義語ではない。"}], "correct_answer": "最大", "explanations": {"最大": "大きさの対義語。最小と対になる語として辞典に載る。", "平均": "「平均」は全体の中央的な値を表し、最小の対義語ではない。", "中間": "「中間」は両端の間を指す語で、最小と対になる語ではない。", "全体": "「全体」は部分と対になる語で、最小の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37288, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "大きさがきわめて小さいこと。", "primary_collocate": null, "pronunciation": "さいしょう", "ipa": "saiɕoː", "syllable_count": 4, "sentences": [{"text": "このカメラは、手のひらに乗る最小のサイズだ。", "target_word": "最小", "complexity_tier": "T3", "furigana": "このカメラは、手[て]のひらに乗[の]る最小[さいしょう]のサイズだ。", "sentence_source": "generated"}, {"text": "最小の部品が一つ壊れただけで、機械は止まった。", "target_word": "最小", "complexity_tier": "T3", "furigana": "最小[さいしょう]の部品[ぶひん]が一[ひと]つ壊[こわ]れただけで、機械[きかい]は止[と]まった。", "sentence_source": "generated"}, {"text": "この部品は、肉眼ではほとんど見えない最小の大きさのものだ。", "target_word": "最小", "complexity_tier": "T3", "furigana": "この部品は、肉眼ではほとんど見えない最小[さいしょう]の大きさのものだ。", "sentence_source": "generated"}, {"text": "最小の虫でも、顕微鏡を使えば形がよく見える。", "target_word": "最小", "complexity_tier": "T3", "furigana": "最小[さいしょう]の虫[むし]でも、顕微鏡[けんびきょう]を使[つか]えば形[かたち]がよく見[み]える。", "sentence_source": "generated"}, {"text": "この箱は最小の大きさにたためるので、旅行に便利だ。", "target_word": "最小", "complexity_tier": "T3", "furigana": "この箱[はこ]は最小[さいしょう]の大[おお]きさにたためるので、旅行[りょこう]に便利[べんり]だ。", "sentence_source": "generated"}, {"text": "最小のねじを落としてしまい、床をさがしても見つからなかった。", "target_word": "最小", "complexity_tier": "T3", "furigana": "最小[さいしょう]のねじを落[お]としてしまい、床[ゆか]をさがしても見[み]つからなかった。", "sentence_source": "generated"}, {"text": "最小のケースに入れたので、かばんの隅に収まった。", "target_word": "最小", "complexity_tier": "T3", "furigana": "最小[さいしょう]のケースに入[い]れたので、かばんの隅[すみ]に収[おさ]まった。", "sentence_source": "generated"}, {"text": "最小の穴から水が漏れて、床がぬれた。", "target_word": "最小", "complexity_tier": "T3", "furigana": "最小[さいしょう]の穴[あな]から水[みず]が漏[も]れて、床[ゆか]がぬれた。", "sentence_source": "generated"}, {"text": "最小の傷でも、写真には目立って写る。", "target_word": "最小", "complexity_tier": "T3", "furigana": "最小[さいしょう]の傷[きず]でも、写真[しゃしん]には目立[めだ]って写[うつ]る。", "sentence_source": "generated"}, {"text": "最小のモーターを使ったので、時計はとても薄くできた。", "target_word": "最小", "complexity_tier": "T3", "furigana": "最小[さいしょう]のモーターを使[つか]ったので、時計[とけい]はとても薄[うす]くできた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "最小", "label": "基本形"}, {"form": "最小の", "label": "名詞＋の（連体形）"}], "register": "普通体（だ・である調）", "sense_fingerprint": "大きさがきわめて小さいこと。部品や道具などが非常に小型であるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481ed36a-14ce-4134-9f49-87c6b4fc588f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37288, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最小", "is_correct": true, "explanation": "「手のひらに乗る最小のサイズ」の形で、大きさがきわめて小さいことを表す正解。"}, {"text": "色", "is_correct": false, "explanation": "「手のひらに乗る色のサイズ」は意味が成り立たない。大きさの話に色は入らない。"}, {"text": "重さ", "is_correct": false, "explanation": "「手のひらに乗る重さのサイズ」は重さと大きさを混ぜており、不自然。"}, {"text": "音", "is_correct": false, "explanation": "「手のひらに乗る音のサイズ」は成り立たない。音は大きさを表す語ではない。"}], "explanations": {"最小": "「手のひらに乗る最小のサイズ」の形で、大きさがきわめて小さいことを表す正解。", "色": "「手のひらに乗る色のサイズ」は意味が成り立たない。大きさの話に色は入らない。", "重さ": "「手のひらに乗る重さのサイズ」は重さと大きさを混ぜており、不自然。", "音": "「手のひらに乗る音のサイズ」は成り立たない。音は大きさを表す語ではない。"}, "sentence_index": 0, "correct_answer": "最小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の作った料理は最小の味だった。", "explanation": "ここは〈最低〉（質が一番悪い）の意味。味の良し悪しは〈最低〉で言い、〈最小〉（とても小さい）では合わない。"}, {"text": "この機械は最小で、重い荷物を動かす力が強い。", "explanation": "ここは〈強力〉の意味。力の強さは〈強力〉で言い、〈最小〉（とても小さい）では矛盾する。"}, {"text": "彼女は最小に驚いて、言葉を失った。", "explanation": "ここは〈少し〉の意味。驚きの程度は〈少し〉〈わずかに〉で言い、〈最小〉は副詞として使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37288, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最小", "is_correct": true, "explanation": "「最小のケースに入れた」の形で、ケースの大きさがきわめて小さいことを表す正解。"}, {"text": "味", "is_correct": false, "explanation": "「味のケースに入れた」は意味が通らない。味はケースの大きさを表さない。"}, {"text": "形", "is_correct": false, "explanation": "「形のケースに入れた」では大きさの話にならず、文が成り立たない。"}, {"text": "数", "is_correct": false, "explanation": "「数のケースに入れた」は意味が通らない。数はケースの大きさを表さない。"}], "explanations": {"最小": "「最小のケースに入れた」の形で、ケースの大きさがきわめて小さいことを表す正解。", "味": "「味のケースに入れた」は意味が通らない。味はケースの大きさを表さない。", "形": "「形のケースに入れた」では大きさの話にならず、文が成り立たない。", "数": "「数のケースに入れた」は意味が通らない。数はケースの大きさを表さない。"}, "sentence_index": 6, "correct_answer": "最小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は最小に喜んで、友達に電話をかけた。", "explanation": "ここは〈とても〉〈大いに〉の意味。喜びの程度は〈とても〉で言い、〈最小〉は副詞として使わない。"}, {"text": "このコートは最小で、雨の日でも濡れにくい。", "explanation": "ここは〈防水〉の意味。雨をはじく性能は〈防水〉で言い、〈最小〉では合わない。"}, {"text": "彼は最小の声で、会議の結論をはっきり宣言した。", "explanation": "ここは〈大きな声〉の意味。宣言の場では声が小さいと合わないが、〈最小〉は声の大きさを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37288, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このバッグは最小な大きさにたためるので、持ち運びが楽だ。", "corrected_sentence": "このバッグは最小の大きさにたためるので、持ち運びが楽だ。", "error_description": "「最小」は名詞なので、名詞の前には「の」を使う。「最小な」は誤りで、正しくは「最小の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37288, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小さな部品ですが、最小な大きさで作られています。", "corrected_sentence": "小さな部品ですが、最小の大きさで作られています。", "error_description": "「最小」は名詞なので、名詞の前には「の」を使う。「最小な」は誤りで、正しくは「最小の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37289, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最大", "is_correct": true, "explanation": "数量の対義語。比べて一番小さい最小に対し、比べて一番大きいことを表す。"}, {"text": "最初", "is_correct": false, "explanation": "「最初」は順序の先頭を表し、数量の対義語ではない。"}, {"text": "最後", "is_correct": false, "explanation": "「最後」は順序の終わりを表し、数量の対義語ではない。"}, {"text": "中心", "is_correct": false, "explanation": "「中心」は位置を表す語で、数量の対義語ではない。"}], "correct_answer": "最大", "explanations": {"最大": "数量の対義語。比べて一番小さい最小に対し、比べて一番大きいことを表す。", "最初": "「最初」は順序の先頭を表し、数量の対義語ではない。", "最後": "「最後」は順序の終わりを表し、数量の対義語ではない。", "中心": "「中心」は位置を表す語で、数量の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
