INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37289, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "数量や程度が、ほかのものと比べて一番小さいこと。", "primary_collocate": null, "pronunciation": "さいしょう", "ipa": "saiɕoː", "syllable_count": 4, "sentences": [{"text": "三つの数のうち、最小の数は2だ。", "target_word": "最小", "complexity_tier": "T3", "furigana": "三[みっ]つの数[かず]のうち、最小[さいしょう]の数[かず]は2[に]だ。", "sentence_source": "generated"}, {"text": "今月の雨の量は、過去十年で最小だった。", "target_word": "最小", "complexity_tier": "T3", "furigana": "今月の雨の量は、過去十年で最小[さいしょう]だった。", "sentence_source": "generated"}, {"text": "この町は、県内で人口が最小の町になった。", "target_word": "最小", "complexity_tier": "T3", "furigana": "この町[まち]は、県内[けんない]で人口[じんこう]が最小[さいしょう]の町[まち]になった。", "sentence_source": "generated"}, {"text": "費用が最小の方法を選んで、計画を立てた。", "target_word": "最小", "complexity_tier": "T3", "furigana": "費用[ひよう]が最小[さいしょう]の方法[ほうほう]を選[えら]んで、計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "並べた数字の中で、最小の値に印をつけた。", "target_word": "最小", "complexity_tier": "T3", "furigana": "並[なら]べた数字[すうじ]の中[なか]で、最小[さいしょう]の値[あたい]に印[しるし]をつけた。", "sentence_source": "generated"}, {"text": "この島は、国内の島の中で面積が最小だ。", "target_word": "最小", "complexity_tier": "T3", "furigana": "この島[しま]は、国内[こくない]の島[しま]の中[なか]で面積[めんせき]が最小[さいしょう]だ。", "sentence_source": "generated"}, {"text": "十個の箱を比べて、最小のものから順に並べた。", "target_word": "最小", "complexity_tier": "T3", "furigana": "十個[じゅっこ]の箱[はこ]を比[くら]べて、最小[さいしょう]のものから順[じゅん]に並[なら]べた。", "sentence_source": "generated"}, {"text": "売り上げが最小だった月は、二月だ。", "target_word": "最小", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが最小[さいしょう]だった月[つき]は、二月[にがつ]だ。", "sentence_source": "generated"}, {"text": "三つの案のうち、リスクが最小の案が選ばれた。", "target_word": "最小", "complexity_tier": "T3", "furigana": "三[みっ]つの案[あん]のうち、リスクが最小[さいしょう]の案[あん]が選[えら]ばれた。", "sentence_source": "generated"}, {"text": "兄弟の中で、末っ子の足のサイズが最小だ。", "target_word": "最小", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]の中[なか]で、末[すえ]っ子[こ]の足[あし]のサイズが最小[さいしょう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "最小", "label": "基本形"}, {"form": "最小の", "label": "名詞＋の（連体形）"}], "register": "普通体（だ・である調）", "sense_fingerprint": "複数のものを比べて、数量や程度が一番小さいこと。「最大」の対", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481ed36a-14ce-4134-9f49-87c6b4fc588f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37289, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最小", "is_correct": true, "explanation": "「三つの数のうち、最小の数」の形で、比べて一番小さいことを表す正解。"}, {"text": "色", "is_correct": false, "explanation": "「三つの数のうち、色の数は2だ」は意味が通らない。色は数量ではない。"}, {"text": "重さ", "is_correct": false, "explanation": "「三つの数のうち、重さの数は2だ」は成り立たない。重さは数の比較に使わない。"}, {"text": "音", "is_correct": false, "explanation": "「三つの数のうち、音の数は2だ」は意味が通らない。"}], "explanations": {"最小": "「三つの数のうち、最小の数」の形で、比べて一番小さいことを表す正解。", "色": "「三つの数のうち、色の数は2だ」は意味が通らない。色は数量ではない。", "重さ": "「三つの数のうち、重さの数は2だ」は成り立たない。重さは数の比較に使わない。", "音": "「三つの数のうち、音の数は2だ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "最小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "料理の味が最小だったので、みんな驚いた。", "explanation": "ここは〈最高〉か〈最低〉で評価する意味。味の良し悪しは〈最高〉〈最低〉で言い、比べる数量を表す〈最小〉では合わない。"}, {"text": "彼の評判は最小で、誰も話題にしなかった。", "explanation": "ここは〈知名度が低い〉の意味。評判の程度は〈低い〉で言い、〈最小〉（数量が一番少ない）は使わない。"}, {"text": "この会社は、社員の笑顔が最小だ。", "explanation": "ここは〈最大〉に対応する〈たくさん〉の意味。笑顔の多さは〈最大〉で言い、〈最小〉（数量が一番少ない）は評価の語として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37289, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最小", "is_correct": true, "explanation": "「十個の箱を比べて、最小のものから」の形で、比べて一番小さいことを表す正解。"}, {"text": "味", "is_correct": false, "explanation": "「味のものから順に並べた」は箱を比べる文脈に合わず、成り立たない。"}, {"text": "香り", "is_correct": false, "explanation": "「香りのものから順に並べた」は箱の数量の比較にならない。"}, {"text": "数", "is_correct": false, "explanation": "「数のものから順に並べた」は意味が通らない。"}], "explanations": {"最小": "「十個の箱を比べて、最小のものから」の形で、比べて一番小さいことを表す正解。", "味": "「味のものから順に並べた」は箱を比べる文脈に合わず、成り立たない。", "香り": "「香りのものから順に並べた」は箱の数量の比較にならない。", "数": "「数のものから順に並べた」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "最小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の笑い声は最小で、会場の端まで届いた。", "explanation": "ここは〈大きな〉〈よく響く〉の意味。声の大きさは〈大きい〉で表し、〈最小〉（比べて一番少ない）では合わない。"}, {"text": "この店は、客の数が最小なのに、いつも行列ができている。", "explanation": "ここは〈最大〉〈混雑〉の意味。客の多さは〈最大〉で言い、〈最小〉（数量が一番少ない）では行列と矛盾する。"}, {"text": "末っ子は最小の大きさで、三人の中で一番背が高い。", "explanation": "ここは〈最大〉の意味。背の高さは〈最大〉〈一番高い〉で言い、〈最小〉（一番小さい）では矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37289, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は最小な費用で新しい機械を買った。", "corrected_sentence": "この会社は最小の費用で新しい機械を買った。", "error_description": "「最小」は名詞なので、名詞の前には「の」を使う。「最小な」は誤りで、正しくは「最小の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37289, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三つの候補のうち、最小な値段の店を選んだ。", "corrected_sentence": "三つの候補のうち、最小の値段の店を選んだ。", "error_description": "「最小」は名詞なので、名詞の前には「の」を使う。「最小な」は誤りで、正しくは「最小の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37290, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "手動", "is_correct": true, "explanation": "『電動』の対義語で、人の力で動かす意味。機械の動かし方の対になる。"}, {"text": "電池", "is_correct": false, "explanation": "電池は電気をためる物で、動かし方の対義語ではない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は通話の道具で、電動と対になる語ではない。"}, {"text": "手作業", "is_correct": false, "explanation": "手作業は人の手で作ること。動かす力の対義語ではない。"}], "correct_answer": "手動", "explanations": {"手動": "『電動』の対義語で、人の力で動かす意味。機械の動かし方の対になる。", "電池": "電池は電気をためる物で、動かし方の対義語ではない。", "電話": "電話は通話の道具で、電動と対になる語ではない。", "手作業": "手作業は人の手で作ること。動かす力の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37290, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "手動", "is_correct": true, "explanation": "『電動』の対義語で、手で操作して動かす意味。文中の対比とも一致する。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱は電線を支える柱で、動かし方の対義語ではない。"}, {"text": "電卓", "is_correct": false, "explanation": "電卓は計算の道具で、電動と対になる語ではない。"}, {"text": "手作り", "is_correct": false, "explanation": "手作りは自分で作ること。動力の対義語ではない。"}], "correct_answer": "手動", "explanations": {"手動": "『電動』の対義語で、手で操作して動かす意味。文中の対比とも一致する。", "電柱": "電柱は電線を支える柱で、動かし方の対義語ではない。", "電卓": "電卓は計算の道具で、電動と対になる語ではない。", "手作り": "手作りは自分で作ること。動力の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37290, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "電気の力で動くこと。", "primary_collocate": null, "pronunciation": "でんどう", "ipa": "dendoː", "syllable_count": 4, "sentences": [{"text": "この自転車は電動なので、坂道でも楽に上がれます。", "target_word": "電動", "complexity_tier": "T3", "furigana": "この自転車[じてんしゃ]は電動[でんどう]なので、坂道[さかみち]でも楽[らく]に上[あ]がれます。", "sentence_source": "generated"}, {"text": "電動の車いすは、手で押さなくても進みます。", "target_word": "電動", "complexity_tier": "T3", "furigana": "電動[でんどう]の車[くるま]いすは、手[て]で押[お]さなくても進[すす]みます。", "sentence_source": "generated"}, {"text": "この缶切りは手動ですが、あちらは電動です。", "target_word": "電動", "complexity_tier": "T3", "furigana": "この缶切[かんき]りは手動[しゅどう]ですが、あちらは電動[でんどう]です。", "sentence_source": "generated"}, {"text": "電動のおもちゃは、電池がなくなると動かなくなる。", "target_word": "電動", "complexity_tier": "T3", "furigana": "電動[でんどう]のおもちゃは、電池[でんち]がなくなると動[うご]かなくなる。", "sentence_source": "generated"}, {"text": "山道では、電動の自転車がとても役に立ちました。", "target_word": "電動", "complexity_tier": "T3", "furigana": "山道[やまみち]では、電動[でんどう]の自転車[じてんしゃ]がとても役[やく]に立[た]ちました。", "sentence_source": "generated"}, {"text": "手で回すのは大変なので、電動のものを買いました。", "target_word": "電動", "complexity_tier": "T3", "furigana": "手[て]で回[まわ]すのは大変[たいへん]なので、電動[でんどう]のものを買[か]いました。", "sentence_source": "generated"}, {"text": "このカーテンは電動で、ボタンを押すと開きます。", "target_word": "電動", "complexity_tier": "T3", "furigana": "このカーテンは電動[でんどう]で、ボタンを押[お]すと開[ひら]きます。", "sentence_source": "generated"}, {"text": "電動の車は、ガソリンではなく電気で走ります。", "target_word": "電動", "complexity_tier": "T3", "furigana": "電動[でんどう]の車[くるま]は、ガソリンではなく電気[でんき]で走[はし]ります。", "sentence_source": "generated"}, {"text": "弟は電動のミニカーで遊ぶのが好きです。", "target_word": "電動", "complexity_tier": "T3", "furigana": "弟[おとうと]は電動[でんどう]のミニカーで遊[あそ]ぶのが好[す]きです。", "sentence_source": "generated"}, {"text": "電動か手動かを選べるので、使いやすいです。", "target_word": "電動", "complexity_tier": "T3", "furigana": "電動[でんどう]か手動[しゅどう]かを選[えら]べるので、使[つか]いやすいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電動の", "label": "attributive form"}, {"form": "電動で", "label": "means/state form"}, {"form": "電動です", "label": "polite copula form"}, {"form": "電動だ", "label": "plain copula form"}], "register": "neutral", "sense_fingerprint": "人の力ではなく電気の力で動く性質（手動の対）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37290, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電動", "is_correct": true, "explanation": "ここは『電気の力で動く』の意味で、自転車の性質を表して文に合う。"}, {"text": "電池", "is_correct": false, "explanation": "電池は電気をためる物。『この自転車は電池なので』では性質を表せない。"}, {"text": "電車", "is_correct": false, "explanation": "電車は鉄道の乗り物。自転車の動力の性質としては合わない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は通話の道具。自転車の状態を表す語ではない。"}], "explanations": {"電動": "ここは『電気の力で動く』の意味で、自転車の性質を表して文に合う。", "電池": "電池は電気をためる物。『この自転車は電池なので』では性質を表せない。", "電車": "電車は鉄道の乗り物。自転車の動力の性質としては合わない。", "電話": "電話は通話の道具。自転車の状態を表す語ではない。"}, "sentence_index": 0, "correct_answer": "電動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この歌は電動で、とても好きです。", "explanation": "ここは〈機械が電気の力で動く〉の意味。歌は機械ではないので、電動とは言わない。"}, {"text": "この缶切りは電動で、手で回して開けます。", "explanation": "ここは〈電気の力で動く〉の意味。手で回す道具は手動で、電動とは言わない。"}, {"text": "電動のおもちゃは、ぜんまいを巻いて動かします。", "explanation": "ここは〈電気の力で動く〉の意味。ぜんまいで動くものは電動ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37290, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電動", "is_correct": true, "explanation": "『電動で、ボタンを押すと開く』の意味で、カーテンの動かし方に合う。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱は電線を支える柱。カーテンの動力の性質としては合わない。"}, {"text": "電卓", "is_correct": false, "explanation": "電卓は計算をする道具。カーテンの動き方を表せない。"}, {"text": "電線", "is_correct": false, "explanation": "電線は電気を送る線。カーテン自体の性質を表す語ではない。"}], "explanations": {"電動": "『電動で、ボタンを押すと開く』の意味で、カーテンの動かし方に合う。", "電柱": "電柱は電線を支える柱。カーテンの動力の性質としては合わない。", "電卓": "電卓は計算をする道具。カーテンの動き方を表せない。", "電線": "電線は電気を送る線。カーテン自体の性質を表す語ではない。"}, "sentence_index": 6, "correct_answer": "電動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方になったので、電動を入れて部屋を明るくした。", "explanation": "ここは〈電源〉の意味。電動は機械の動かし方を指す語で、スイッチを入れる対象ではない。"}, {"text": "この扇風機は電動で、ガスを燃やして風を送ります。", "explanation": "ここは〈電気の力で動く〉の意味。ガスで動くものは電動ではない。"}, {"text": "この椅子は電動で、足で踏んだ力で高さが変わります。", "explanation": "ここは〈電気の力で動く〉の意味。足の力で動くのは人力で、電動ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37290, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このポンプは電動を動きます。", "corrected_sentence": "このポンプは電動で動きます。", "error_description": "『電動で動く』と手段を表すので、『を』ではなく『で』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
