INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37291, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "手動", "is_correct": true, "explanation": "『電動』の対義語で、手で動かす意味。機械の動かし方の対になる。"}, {"text": "電話", "is_correct": false, "explanation": "電話は通話の道具で、電動と対になる語ではない。"}, {"text": "電灯", "is_correct": false, "explanation": "電灯は明かりの器具で、動力の対義語ではない。"}, {"text": "手作業", "is_correct": false, "explanation": "手作業は人の手で作ること。動力の仕組みの対義語としては使わない。"}], "correct_answer": "手動", "explanations": {"手動": "『電動』の対義語で、手で動かす意味。機械の動かし方の対になる。", "電話": "電話は通話の道具で、電動と対になる語ではない。", "電灯": "電灯は明かりの器具で、動力の対義語ではない。", "手作業": "手作業は人の手で作ること。動力の仕組みの対義語としては使わない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
