INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37291, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "機械などを電気の力で動かすこと。また、そのような仕組みになっていること。", "primary_collocate": null, "pronunciation": "でんどう", "ipa": "dendoː", "syllable_count": 4, "sentences": [{"text": "工場では、機械を電動にして作業を早くした。", "target_word": "電動", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、機械[きかい]を電動[でんどう]にして作業[さぎょう]を早[はや]くした。", "sentence_source": "generated"}, {"text": "このドアは電動になっているので、近づくと自動で開きます。", "target_word": "電動", "complexity_tier": "T3", "furigana": "このドアは電動[でんどう]になっているので、近[ちか]づくと自動[じどう]で開[ひら]きます。", "sentence_source": "generated"}, {"text": "昔は手で動かしていた機械を、電動に変えました。", "target_word": "電動", "complexity_tier": "T3", "furigana": "昔[むかし]は手[て]で動[うご]かしていた機械[きかい]を、電動[でんどう]に変[か]えました。", "sentence_source": "generated"}, {"text": "電動の仕組みは、モーターが電気で回ることです。", "target_word": "電動", "complexity_tier": "T3", "furigana": "電動[でんどう]の仕組[しく]みは、モーターが電気[でんき]で回[まわ]ることです。", "sentence_source": "generated"}, {"text": "電動になってから、窓の開け閉めが楽になった。", "target_word": "電動", "complexity_tier": "T3", "furigana": "電動[でんどう]になってから、窓[まど]の開[あ]け閉[し]めが楽[らく]になった。", "sentence_source": "generated"}, {"text": "電動のポンプを使えば、水を簡単に運べます。", "target_word": "電動", "complexity_tier": "T3", "furigana": "電動[でんどう]のポンプを使[つか]えば、水[みず]を簡単[かんたん]に運[はこ]べます。", "sentence_source": "generated"}, {"text": "この椅子は電動で高さを変えられます。", "target_word": "電動", "complexity_tier": "T3", "furigana": "この椅子[いす]は電動[でんどう]で高[たか]さを変[か]えられます。", "sentence_source": "generated"}, {"text": "手動を電動に変えるには、モーターを付ける必要がある。", "target_word": "電動", "complexity_tier": "T3", "furigana": "手動[しゅどう]を電動[でんどう]に変[か]えるには、モーターを付[つ]ける必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "病院のベッドは電動で、背もたれの角度が変わります。", "target_word": "電動", "complexity_tier": "T3", "furigana": "病院[びょういん]のベッドは電動[でんどう]で、背[せ]もたれの角度[かくど]が変[か]わります。", "sentence_source": "generated"}, {"text": "電動の仕組みがこわれて、シャッターが動かない。", "target_word": "電動", "complexity_tier": "T3", "furigana": "電動[でんどう]の仕組[しく]みがこわれて、シャッターが動[うご]かない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電動の", "label": "attributive form"}, {"form": "電動に", "label": "adverbial form"}, {"form": "電動で", "label": "means/state form"}, {"form": "電動だ", "label": "plain copula form"}], "register": "neutral", "sense_fingerprint": "機械や装置を電気で動かすこと、またその仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37291, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電動", "is_correct": true, "explanation": "『機械を電動にする』の形で、機械を電気で動く仕組みに変える意味に合う。"}, {"text": "電池", "is_correct": false, "explanation": "『機械を電池にする』は不自然。電池は動力源の部品で、仕組みの変更を表さない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は通話の道具。機械の仕組みを変える意味では使わない。"}, {"text": "電灯", "is_correct": false, "explanation": "電灯は明かりの器具。機械の動力を変える文脈には合わない。"}], "explanations": {"電動": "『機械を電動にする』の形で、機械を電気で動く仕組みに変える意味に合う。", "電池": "『機械を電池にする』は不自然。電池は動力源の部品で、仕組みの変更を表さない。", "電話": "電話は通話の道具。機械の仕組みを変える意味では使わない。", "電灯": "電灯は明かりの器具。機械の動力を変える文脈には合わない。"}, "sentence_index": 0, "correct_answer": "電動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電動の仕組みは、人が手で力を加えて機械を動かすことです。", "explanation": "ここは〈電気で動かす仕組み〉の意味。人の力で動かすのは手動で、電動の説明としては逆になる。"}, {"text": "電動の仕組みは、ゼンマイを巻いて針を回すことです。", "explanation": "ここは〈電気で動かす仕組み〉の意味。ゼンマイは電気を使わず、電動とは言わない。"}, {"text": "電動の仕組みは、薪を燃やして蒸気で動かすことです。", "explanation": "ここは〈電気で動かす仕組み〉の意味。蒸気の力は電気ではないので、電動の説明にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37291, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電動", "is_correct": true, "explanation": "『電動で高さを変えられる』の意味で、椅子の動かし方に合う。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱は電線を支える柱。椅子の仕組みを表せない。"}, {"text": "電卓", "is_correct": false, "explanation": "電卓は計算の道具。椅子の動力の説明には合わない。"}, {"text": "電線", "is_correct": false, "explanation": "電線は電気を送る線。椅子の動かし方を表す語ではない。"}], "explanations": {"電動": "『電動で高さを変えられる』の意味で、椅子の動かし方に合う。", "電柱": "電柱は電線を支える柱。椅子の仕組みを表せない。", "電卓": "電卓は計算の道具。椅子の動力の説明には合わない。", "電線": "電線は電気を送る線。椅子の動かし方を表す語ではない。"}, "sentence_index": 6, "correct_answer": "電動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このシャッターは電動で、人が押し上げて開けます。", "explanation": "ここは〈電気で動かす仕組み〉の意味。人が押し上げるのは手動で、電動とは矛盾する。"}, {"text": "電動の仕組みは、ロウソクの火で空気を温めて動かすことです。", "explanation": "ここは〈電気で動かす仕組み〉の意味。火の熱は電気ではないので、電動とは言えない。"}, {"text": "電動の仕組みは、風の力で帆を動かすことです。", "explanation": "ここは〈電気で動かす仕組み〉の意味。風の力で帆を動かすのは電気ではないので、電動の説明にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37291, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この機械を電動して、作業を早くしました。", "corrected_sentence": "この機械を電動にして、作業を早くしました。", "error_description": "『電動にする』の形なので、『電動』の後に『に』が必要。『電動して』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37291, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このドアは電動を開きます。", "corrected_sentence": "このドアは電動で開きます。", "error_description": "『電動で開く』と手段を表すので、『を』ではなく『で』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37292, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「水素に火をつける」の形で、火をつける相手を示す正解。"}, {"text": "を", "is_correct": false, "explanation": "「水素を火をつける」は二つの目的語が並び、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「水素へ火をつける」は方向の意味になり、ここでは不自然。"}, {"text": "と", "is_correct": false, "explanation": "「水素と火をつける」は並列の意味になり、火をつける相手を示せない。"}], "correct_answer": "に", "explanations": {"に": "「水素に火をつける」の形で、火をつける相手を示す正解。", "を": "「水素を火をつける」は二つの目的語が並び、文として成り立たない。", "へ": "「水素へ火をつける」は方向の意味になり、ここでは不自然。", "と": "「水素と火をつける」は並列の意味になり、火をつける相手を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37292, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37292, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気よりとても軽い気体です。火をつけると燃えます。", "primary_collocate": null, "pronunciation": "すいそ", "ipa": "sɯiso", "syllable_count": 3, "sentences": [{"text": "水素は空気より軽いので、風船に入れると高く上がります。", "target_word": "水素", "complexity_tier": "T3", "furigana": "水素[すいそ]は空気[くうき]より軽[かる]いので、風船[ふうせん]に入[い]れると高[たか]く上[あ]がります。", "sentence_source": "generated"}, {"text": "水素に火をつけると、よく燃えます。", "target_word": "水素", "complexity_tier": "T2", "furigana": "水素[すいそ]に火[ひ]をつけると、よく燃[も]えます。", "sentence_source": "generated"}, {"text": "理科の時間に、水素を集める実験をしました。", "target_word": "水素", "complexity_tier": "T3", "furigana": "理科[りか]の時間[じかん]に、水素[すいそ]を集[あつ]める実験[じっけん]をしました。", "sentence_source": "generated"}, {"text": "水素は色もにおいもない気体です。", "target_word": "水素", "complexity_tier": "T2", "furigana": "水素[すいそ]は色[いろ]もにおいもない気体[きたい]です。", "sentence_source": "generated"}, {"text": "水素の入った風船は、手をはなすと空へ飛んでいきます。", "target_word": "水素", "complexity_tier": "T3", "furigana": "水素[すいそ]の入[はい]った風船[ふうせん]は、手[て]をはなすと空[そら]へ飛[と]んでいきます。", "sentence_source": "generated"}, {"text": "先生は「水素は火に近づけてはいけません」と言いました。", "target_word": "水素", "complexity_tier": "T3", "furigana": "先生[せんせい]は「水素[すいそ]は火[ひ]に近[ちか]づけてはいけません」と言[い]いました。", "sentence_source": "generated"}, {"text": "水素は軽いから、空気の中では上へ行きます。", "target_word": "水素", "complexity_tier": "T2", "furigana": "水素[すいそ]は軽[かる]いから、空気[くうき]の中[なか]では上[うえ]へ行[い]きます。", "sentence_source": "generated"}, {"text": "水を電気で分けると、水素と酸素ができます。", "target_word": "水素", "complexity_tier": "T3", "furigana": "水[みず]を電気[でんき]で分[わ]けると、水素[すいそ]と酸素[さんそ]ができます。", "sentence_source": "generated"}, {"text": "水素の入った試験管に火を近づけると、ポンと音がしました。", "target_word": "水素", "complexity_tier": "T4", "furigana": "水素[すいそ]の入[はい]った試験管[しけんかん]に火[ひ]を近[ちか]づけると、ポンと音[おと]がしました。", "sentence_source": "generated"}, {"text": "この実験では、水素が出るまで少し時間がかかりました。", "target_word": "水素", "complexity_tier": "T3", "furigana": "この実験[じっけん]では、水素[すいそ]が出[で]るまで少[すこ]し時間[じかん]がかかりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水素", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "hydrogen as a very light, flammable gas, explained at a children''s science level", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481ed36a-14ce-4134-9f49-87c6b4fc588f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37292, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水素", "is_correct": true, "explanation": "「水素は空気より軽いので」の形で、空気より軽い気体を指す正解。"}, {"text": "色", "is_correct": false, "explanation": "「色は空気より軽いので」は意味が通らない。色は軽さを表す語ではない。"}, {"text": "音", "is_correct": false, "explanation": "「音は空気より軽いので」は成り立たない。音は気体の重さを表さない。"}, {"text": "味", "is_correct": false, "explanation": "「味は空気より軽いので」は意味が通らない。"}], "explanations": {"水素": "「水素は空気より軽いので」の形で、空気より軽い気体を指す正解。", "色": "「色は空気より軽いので」は意味が通らない。色は軽さを表す語ではない。", "音": "「音は空気より軽いので」は成り立たない。音は気体の重さを表さない。", "味": "「味は空気より軽いので」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "水素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷たいコップの外側に水素がつき、水滴になった。", "explanation": "ここは〈水蒸気〉の意味。冷やされて水滴になるのは水蒸気で、気体の水素は水滴にならない。"}, {"text": "コップに水素を注いで、のどを潤した。", "explanation": "ここは〈水〉の意味。水素は気体なので注いだり飲んだりできず、水の代わりにはならない。"}, {"text": "水素は火を大きくする働きがあるので、ガスの火を強くするのに使う。", "explanation": "ここは〈酸素〉の意味。火を大きくする働きは酸素で、燃える性質の水素には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37292, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水素", "is_correct": true, "explanation": "「水素は軽いから、空気の中では上へ行きます」の形で、軽い気体を指す正解。"}, {"text": "形", "is_correct": false, "explanation": "「形は軽いから、空気の中では上へ行きます」は意味が通らない。形は気体の軽さを表さない。"}, {"text": "鉄", "is_correct": false, "explanation": "「鉄は軽いから」は事実に反する。鉄は重い金属で、軽い気体の説明にはならない。"}, {"text": "温度", "is_correct": false, "explanation": "「温度は軽いから、空気の中では上へ行きます」は意味が通らない。"}], "explanations": {"水素": "「水素は軽いから、空気の中では上へ行きます」の形で、軽い気体を指す正解。", "形": "「形は軽いから、空気の中では上へ行きます」は意味が通らない。形は気体の軽さを表さない。", "鉄": "「鉄は軽いから」は事実に反する。鉄は重い金属で、軽い気体の説明にはならない。", "温度": "「温度は軽いから、空気の中では上へ行きます」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "水素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ガラスの瓶に水素を入れて火で温めると、白い湯気が出た。", "explanation": "ここは〈湯気〉の意味。湯気は水が蒸発した白いもので、無色の気体の水素からは出ない。"}, {"text": "カップの中の水素を見ると、白く濁っていた。", "explanation": "ここは〈牛乳〉の意味。白く濁るのは牛乳で、無色透明の気体の水素には当てはまらない。"}, {"text": "ごはんを炊くときに水素を入れると、味が引き立つ。", "explanation": "ここは〈塩〉の意味。料理の味を整えるのは塩で、水素を入れても味は変わらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37292, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水素を火をつけると、ポンと音がします。", "corrected_sentence": "水素に火をつけると、ポンと音がします。", "error_description": "「火をつける」の対象は「に」で示す。「水素を」の「を」は誤りで、正しくは「水素に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37292, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水を電気で分けると、水素を酸素が生まれます。", "corrected_sentence": "水を電気で分けると、水素と酸素が生まれます。", "error_description": "「水素と酸素」の並列は「と」で示す。「水素を」の「を」は誤りで、正しくは「水素と」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37293, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「水素は燃料電池の燃料として注目されている」の形で、話題の主題を示す正解。"}, {"text": "を", "is_correct": false, "explanation": "「水素を燃料電池の燃料として注目されている」は目的語の形になり、文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「水素へ燃料電池の燃料として注目されている」は方向の意味になり、ここでは合わない。"}, {"text": "から", "is_correct": false, "explanation": "「水素から燃料電池の燃料として注目されている」は起点の意味になり、話題の主題を示せない。"}], "correct_answer": "は", "explanations": {"は": "「水素は燃料電池の燃料として注目されている」の形で、話題の主題を示す正解。", "を": "「水素を燃料電池の燃料として注目されている」は目的語の形になり、文として不自然。", "へ": "「水素へ燃料電池の燃料として注目されている」は方向の意味になり、ここでは合わない。", "から": "「水素から燃料電池の燃料として注目されている」は起点の意味になり、話題の主題を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37293, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「水素の元素記号はHである」の形で、水素の所属を示す正解。"}, {"text": "と", "is_correct": false, "explanation": "「水素と元素記号はHである」は並列の意味になり、元素記号の所属を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「水素に元素記号はHである」は位置や相手の意味になり、ここでは不自然。"}, {"text": "で", "is_correct": false, "explanation": "「水素で元素記号はHである」は手段の意味になり、所属を示せない。"}], "correct_answer": "の", "explanations": {"の": "「水素の元素記号はHである」の形で、水素の所属を示す正解。", "と": "「水素と元素記号はHである」は並列の意味になり、元素記号の所属を示せない。", "に": "「水素に元素記号はHである」は位置や相手の意味になり、ここでは不自然。", "で": "「水素で元素記号はHである」は手段の意味になり、所属を示せない。"}, "error_tags": {"と": "並列", "に": "位置・相手", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37293, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "元素の一つで、記号はH、原子番号1。無色・無臭で、最も軽い気体。燃える性質があり、燃料や化学工業の原料として使われる。", "primary_collocate": null, "pronunciation": "すいそ", "ipa": "sɯiso", "syllable_count": 3, "sentences": [{"text": "水素は最も軽い気体で、原子番号は1である。", "target_word": "水素", "complexity_tier": "T3", "furigana": "水素[すいそ]は最[もっと]も軽[かる]い気体[きたい]で、原子[げんし]番号[ばんごう]は1である。", "sentence_source": "generated"}, {"text": "水素は燃料電池の燃料として注目されている。", "target_word": "水素", "complexity_tier": "T4", "furigana": "水素[すいそ]は燃料[ねんりょう]電池[でんち]の燃料[ねんりょう]として注目[ちゅうもく]されている。", "sentence_source": "generated"}, {"text": "水素と酸素が結びつくと、水ができる。", "target_word": "水素", "complexity_tier": "T3", "furigana": "水素[すいそ]と酸素[さんそ]が結[むす]びつくと、水[みず]ができる。", "sentence_source": "generated"}, {"text": "化学工業では、水素がアンモニアの原料に使われる。", "target_word": "水素", "complexity_tier": "T4", "furigana": "化学[かがく]工業[こうぎょう]では、水素[すいそ]がアンモニアの原料[げんりょう]に使[つか]われる。", "sentence_source": "generated"}, {"text": "水素は無色・無臭なので、漏れても人は気づきにくい。", "target_word": "水素", "complexity_tier": "T4", "furigana": "水素[すいそ]は無色[むしょく]・無臭[むしゅう]なので、漏[も]れても人[ひと]は気[き]づきにくい。", "sentence_source": "generated"}, {"text": "この車は水素で走り、出すのは水だけだ。", "target_word": "水素", "complexity_tier": "T3", "furigana": "この車[くるま]は水素[すいそ]で走[はし]り、出[だ]すのは水[みず]だけだ。", "sentence_source": "generated"}, {"text": "水素を安全に運ぶには、高い圧力で容器に詰める方法がある。", "target_word": "水素", "complexity_tier": "T4", "furigana": "水素[すいそ]を安全[あんぜん]に運[はこ]ぶには、高[たか]い圧力[あつりょく]で容器[ようき]に詰[つ]める方法[ほうほう]がある。", "sentence_source": "generated"}, {"text": "水素の元素記号はHである。", "target_word": "水素", "complexity_tier": "T3", "furigana": "水素[すいそ]の元素[げんそ]記号[きごう]はHである。", "sentence_source": "generated"}, {"text": "水素を作る方法として、水の電気分解がよく知られている。", "target_word": "水素", "complexity_tier": "T4", "furigana": "水素[すいそ]を作[つく]る方法[ほうほう]として、水[みず]の電気[でんき]分解[ぶんかい]がよく知[し]られている。", "sentence_source": "generated"}, {"text": "太陽の主な成分は水素で、その核融合が光と熱を生む。", "target_word": "水素", "complexity_tier": "T4", "furigana": "太陽[たいよう]の主[おも]な成分[せいぶん]は水素[すいそ]で、その核融合[かくゆうごう]が光[ひかり]と熱[ねつ]を生[う]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水素", "label": "基本形"}], "register": "technical", "sense_fingerprint": "hydrogen as a chemical element (H, atomic number 1), used as fuel and as an industrial raw material", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481ed36a-14ce-4134-9f49-87c6b4fc588f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37293, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水素", "is_correct": true, "explanation": "「水素は最も軽い気体で、原子番号は1である」の形で、元素として説明される正解。"}, {"text": "色", "is_correct": false, "explanation": "「色は最も軽い気体で、原子番号は1である」は意味が通らない。色は元素を指さない。"}, {"text": "味", "is_correct": false, "explanation": "「味は最も軽い気体で、原子番号は1である」は成り立たない。"}, {"text": "音", "is_correct": false, "explanation": "「音は最も軽い気体で、原子番号は1である」は意味が通らない。"}], "explanations": {"水素": "「水素は最も軽い気体で、原子番号は1である」の形で、元素として説明される正解。", "色": "「色は最も軽い気体で、原子番号は1である」は意味が通らない。色は元素を指さない。", "味": "「味は最も軽い気体で、原子番号は1である」は成り立たない。", "音": "「音は最も軽い気体で、原子番号は1である」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "水素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水溶液の水素の濃さをpHで表す。", "explanation": "ここは〈水素イオン〉の意味。pHは水素イオンの濃さを表すので、元素としての水素では言わない。"}, {"text": "鉄の表面に水素をぬると、さびが止まる。", "explanation": "ここは〈防錆剤〉の意味。さびを止めるのは防錆剤で、水素では効果がない。"}, {"text": "料理の味を整えるのに、水素を少し加える。", "explanation": "ここは〈食塩〉の意味。味を整えるのは食塩で、水素は味を変えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37293, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水素", "is_correct": true, "explanation": "「水素を安全に運ぶには、高い圧力で容器に詰める方法がある」の形で、運ぶ対象の正解。"}, {"text": "形", "is_correct": false, "explanation": "「形を安全に運ぶには」は意味が通らない。形は気体を指さない。"}, {"text": "香り", "is_correct": false, "explanation": "「香りを安全に運ぶには、高い圧力で容器に詰める」は成り立たない。"}, {"text": "温度", "is_correct": false, "explanation": "「温度を安全に運ぶには」は意味が通らない。温度は運ぶ対象ではない。"}], "explanations": {"水素": "「水素を安全に運ぶには、高い圧力で容器に詰める方法がある」の形で、運ぶ対象の正解。", "形": "「形を安全に運ぶには」は意味が通らない。形は気体を指さない。", "香り": "「香りを安全に運ぶには、高い圧力で容器に詰める」は成り立たない。", "温度": "「温度を安全に運ぶには」は意味が通らない。温度は運ぶ対象ではない。"}, "sentence_index": 6, "correct_answer": "水素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ガスの火を消す消火剤として、水素を使う。", "explanation": "ここは〈二酸化炭素〉の意味。火を消すのは二酸化炭素などで、燃える水素は消火剤にならない。"}, {"text": "水素は磁石にくっつく金属です。", "explanation": "ここは〈鉄〉の意味。磁石にくっつく金属は鉄で、水素は金属ではない。"}, {"text": "水道水の消毒には、水素を少し入れる。", "explanation": "ここは〈塩素〉の意味。水道水の消毒に使うのは塩素で、水素は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37293, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水素を最も軽い気体で、燃えやすい性質をもつ。", "corrected_sentence": "水素は最も軽い気体で、燃えやすい性質をもつ。", "error_description": "主題を示すのは「は」。「を」は目的語の印で、ここでは誤り。正しくは「水素は」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37293, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このバスは水素と走り、出すのは水だけだ。", "corrected_sentence": "このバスは水素で走り、出すのは水だけだ。", "error_description": "「走る」の手段は「で」で示す。「水素と」の「と」は誤りで、正しくは「水素で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37294, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「燃料として」の「と」。燃料という用途で木を集める文脈に合う。"}, {"text": "を", "is_correct": false, "explanation": "「燃料を木を集めた」は「を」が二つ重なり、集める対象が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「燃料へ木を集めた」は方向を示すが、集める対象の文脈に合わない。"}, {"text": "から", "is_correct": false, "explanation": "「燃料から木を集めた」は起点を示すが、燃料から木を取る意味になり不自然。"}], "correct_answer": "と", "explanations": {"と": "「燃料として」の「と」。燃料という用途で木を集める文脈に合う。", "を": "「燃料を木を集めた」は「を」が二つ重なり、集める対象が成り立たない。", "へ": "「燃料へ木を集めた」は方向を示すが、集める対象の文脈に合わない。", "から": "「燃料から木を集めた」は起点を示すが、燃料から木を取る意味になり不自然。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37294, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「燃料が高くなった」の主語を示す。値段が上がるのは燃料なので「が」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「燃料に高くなった」は、高くなる相手や場所を示す形として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「燃料と高くなった」は並列の形で、高くなる主語として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「燃料の高くなったので」は名詞修飾の形で、主語の役割を果たさず不自然。"}], "correct_answer": "が", "explanations": {"が": "「燃料が高くなった」の主語を示す。値段が上がるのは燃料なので「が」が正しい。", "に": "「燃料に高くなった」は、高くなる相手や場所を示す形として成り立たない。", "と": "「燃料と高くなった」は並列の形で、高くなる主語として成り立たない。", "の": "「燃料の高くなったので」は名詞修飾の形で、主語の役割を果たさず不自然。"}, "error_tags": {"に": "相手", "と": "並列", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37294, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を燃やすためのもの、例えば車を動かすのに使うガソリンのようなものです。", "primary_collocate": null, "pronunciation": "ねんりょう", "ipa": "neɴɾjoː", "syllable_count": 4, "sentences": [{"text": "車の燃料がなくなりそうなので、ガソリンを入れに行く。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "車[くるま]の燃料[ねんりょう]がなくなりそうなので、ガソリンを入[い]れに行[い]く。", "sentence_source": "generated"}, {"text": "キャンプでは、火を起こすための燃料として木を集めた。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "キャンプでは、火[ひ]を起[お]こすための燃料[ねんりょう]として木[き]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "ストーブの燃料がなくなって、部屋が急に寒くなった。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "ストーブの燃料[ねんりょう]がなくなって、部屋[へや]が急[きゅう]に寒[さむ]くなった。", "sentence_source": "generated"}, {"text": "船が止まったのは、燃料が切れたからだ。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "船[ふね]が止[と]まったのは、燃料[ねんりょう]が切[き]れたからだ。", "sentence_source": "generated"}, {"text": "昔の人は、枯れた枝を燃料にして料理をした。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、枯[か]れた枝[えだ]を燃料[ねんりょう]にして料理[りょうり]をした。", "sentence_source": "generated"}, {"text": "バスは、出発する前に燃料を入れる。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "バスは、出発[しゅっぱつ]する前[まえ]に燃料[ねんりょう]を入[い]れる。", "sentence_source": "generated"}, {"text": "大きな飛行機は、たくさんの燃料を使って空を飛ぶ。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "大[おお]きな飛行機[ひこうき]は、たくさんの燃料[ねんりょう]を使[つか]って空[そら]を飛[と]ぶ。", "sentence_source": "generated"}, {"text": "燃料が高くなったので、遠くへ車で行くのをやめた。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "燃料[ねんりょう]が高[たか]くなったので、遠[とお]くへ車[くるま]で行[い]くのをやめた。", "sentence_source": "generated"}, {"text": "父はバーベキュー用に、燃料として使う炭を買ってきた。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "父[ちち]はバーベキュー用[よう]に、燃料[ねんりょう]として使[つか]う炭[すみ]を買[か]ってきた。", "sentence_source": "generated"}, {"text": "発電所では、燃料を燃やして電気を作っている。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "発電所[はつでんしょ]では、燃料[ねんりょう]を燃[も]やして電気[でんき]を作[つく]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "燃料", "label": "基本形(名詞)"}], "register": "neutral", "sense_fingerprint": "車や火を動かすために燃やすもの(ガソリン・炭・木など、やさしい説明)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37294, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "燃料", "is_correct": true, "explanation": "車の燃料がなくなりそうなので、ガソリンを入れに行くという文脈に合う。"}, {"text": "食料", "is_correct": false, "explanation": "食べ物は車に入れるものではなく、ガソリンを入れる文脈と合わない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は車の動力ではなく、なくなりそうで給油に行く理由にならない。"}, {"text": "菓子", "is_correct": false, "explanation": "菓子は食べるもので、車を動かす物ではないので給油の文脈に合わない。"}], "explanations": {"燃料": "車の燃料がなくなりそうなので、ガソリンを入れに行くという文脈に合う。", "食料": "食べ物は車に入れるものではなく、ガソリンを入れる文脈と合わない。", "切符": "切符は車の動力ではなく、なくなりそうで給油に行く理由にならない。", "菓子": "菓子は食べるもので、車を動かす物ではないので給油の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "燃料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山で息が苦しくなり、燃料を吸った。", "explanation": "ここは〈酸素〉の意味。燃料は吸うものではないので、息が苦しいときの対処としては合わない。"}, {"text": "庭の花に燃料をやった。", "explanation": "ここは〈肥料〉の意味。燃料は植物を育てるものではなく、花にやる物としては合わない。"}, {"text": "燃料で皿を洗った。", "explanation": "ここは〈洗剤〉の意味。燃料は汚れを落とすものではないので、皿洗いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37294, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "燃料", "is_correct": true, "explanation": "大きな飛行機が空を飛ぶのに使うものとして、文の内容に合う。"}, {"text": "言葉", "is_correct": false, "explanation": "言葉は飛行機を飛ばすための物ではなく、空を飛ぶのに使わない。"}, {"text": "布団", "is_correct": false, "explanation": "布団は飛行機の動力にならず、空を飛ぶのに使う物ではない。"}, {"text": "歌", "is_correct": false, "explanation": "歌は飛行機を動かす材料ではなく、たくさん使って空を飛ぶ理由にならない。"}], "explanations": {"燃料": "大きな飛行機が空を飛ぶのに使うものとして、文の内容に合う。", "言葉": "言葉は飛行機を飛ばすための物ではなく、空を飛ぶのに使わない。", "布団": "布団は飛行機の動力にならず、空を飛ぶのに使う物ではない。", "歌": "歌は飛行機を動かす材料ではなく、たくさん使って空を飛ぶ理由にならない。"}, "sentence_index": 6, "correct_answer": "燃料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コーヒーに燃料を入れた。", "explanation": "ここは〈砂糖〉の意味。燃料は甘味づけに使うものではなく、コーヒーには入れない。"}, {"text": "メモを燃料に書いた。", "explanation": "ここは〈紙〉の意味。燃料は文字を書く物ではないので、メモには合わない。"}, {"text": "台風で、家の燃料が傾いた。", "explanation": "ここは〈柱〉の意味。燃料は建物を支える物ではないので、家が傾く対象としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37294, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い夜に備えて、ストーブの燃料で夜のうちに入れておいた。", "corrected_sentence": "寒い夜に備えて、ストーブの燃料を夜のうちに入れておいた。", "error_description": "助詞の誤り。「入れる」は入れる対象を「を」で示す。「で」では手段や場所になり、入れる物が欠けて文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37294, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は遠くの店で燃料を買いてから、帰った。", "corrected_sentence": "父は遠くの店で燃料を買ってから、帰った。", "error_description": "活用の誤り。「買う」の音便形は「買って」で、「買いて」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
