INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37295, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37295, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "火をつけて燃やすことで熱やエネルギーを生み出す物質。車や飛行機を動かすためのガソリンや軽油、灯油などの総称。", "primary_collocate": null, "pronunciation": "ねんりょう", "ipa": "neɴɾjoː", "syllable_count": 4, "sentences": [{"text": "木や石油のような燃料は、燃やすと熱を出す。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "木[き]や石油[せきゆ]のような燃料[ねんりょう]は、燃[も]やすと熱[ねつ]を出[だ]す。", "sentence_source": "generated"}, {"text": "飛行機は離陸の前に、長い距離を飛ぶための燃料を補給する。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は離陸[りりく]の前[まえ]に、長[なが]い距離[きょり]を飛[と]ぶための燃料[ねんりょう]を補給[ほきゅう]する。", "sentence_source": "generated"}, {"text": "燃料が残り少なくなったので、車は近くのガソリンスタンドに寄った。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "燃料[ねんりょう]が残[のこ]り少[すく]なくなったので、車[くるま]は近[ちか]くのガソリンスタンドに寄[よ]った。", "sentence_source": "generated"}, {"text": "登山者は、小さなコンロ用の燃料を荷物に入れた。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "登山者[とざんしゃ]は、小[ちい]さなコンロ用[よう]の燃料[ねんりょう]を荷物[にもつ]に入[い]れた。", "sentence_source": "generated"}, {"text": "ロケットは大量の燃料を積んでいるため、打ち上げの準備に時間がかかる。", "target_word": "燃料", "complexity_tier": "T4", "furigana": "ロケットは大量[たいりょう]の燃料[ねんりょう]を積[つ]んでいるため、打[う]ち上[あ]げの準備[じゅんび]に時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "原油の価格が上がると、トラックの燃料にかかる費用も増える。", "target_word": "燃料", "complexity_tier": "T4", "furigana": "原油[げんゆ]の価格[かかく]が上[あ]がると、トラックの燃料[ねんりょう]にかかる費用[ひよう]も増[ふ]える。", "sentence_source": "generated"}, {"text": "燃料が切れて、ボートは海の真ん中で動けなくなった。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "燃料[ねんりょう]が切[き]れて、ボートは海[うみ]の真[ま]ん中[なか]で動[うご]けなくなった。", "sentence_source": "generated"}, {"text": "冬になると、この地域の家庭では暖房のための燃料として灯油を使う。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、この地域[ちいき]の家庭[かてい]では暖房[だんぼう]のための燃料[ねんりょう]として灯油[とうゆ]を使[つか]う。", "sentence_source": "generated"}, {"text": "薪は昔から、料理や暖をとるための燃料として使われてきた。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "薪[まき]は昔[むかし]から、料理[りょうり]や暖[だん]をとるための燃料[ねんりょう]として使[つか]われてきた。", "sentence_source": "generated"}, {"text": "この車は、少ない燃料で長い距離を走れるので経済的だ。", "target_word": "燃料", "complexity_tier": "T3", "furigana": "この車[くるま]は、少[すく]ない燃料[ねんりょう]で長[なが]い距離[きょり]を走[はし]れるので経済的[けいざいてき]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "燃料", "label": "基本形(名詞)"}], "register": "neutral", "sense_fingerprint": "ガソリン・灯油・薪など、燃やして熱や動力を得るための物質の総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 残り少なく (Zipf 2.43)']::text[], 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37295, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "燃料", "is_correct": true, "explanation": "木や石油は燃やして熱を出す物質なので、燃料が主語として文の内容に合う。"}, {"text": "食料", "is_correct": false, "explanation": "食料は食べ物で、燃やして熱を出すものではないので文が成り立たない。"}, {"text": "電力", "is_correct": false, "explanation": "電力は電気のエネルギーで、燃やして熱を出す物ではないので合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は行為で、燃やして熱を出すものにはならないので文が成り立たない。"}], "explanations": {"燃料": "木や石油は燃やして熱を出す物質なので、燃料が主語として文の内容に合う。", "食料": "食料は食べ物で、燃やして熱を出すものではないので文が成り立たない。", "電力": "電力は電気のエネルギーで、燃やして熱を出す物ではないので合わない。", "掃除": "掃除は行為で、燃やして熱を出すものにはならないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "燃料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "料理を作るため、燃料を冷蔵庫から出した。", "explanation": "ここは〈材料〉の意味。燃料は燃やして熱や動力を得るもので、料理の材料としては使わない。"}, {"text": "リモコンが動かないので、燃料を交換した。", "explanation": "ここは〈電池〉の意味。リモコンの電源は電池で、燃料は燃やして使うものなので合わない。"}, {"text": "寒いので、燃料をかけて寝た。", "explanation": "ここは〈毛布〉の意味。燃料は体にかけるものではなく、寒さをしのぐ布の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37295, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "燃料", "is_correct": true, "explanation": "燃料が切れると燃やすものがなくなり、ボートが海の真ん中で止まる文脈に合う。"}, {"text": "会話", "is_correct": false, "explanation": "会話は切れるものだが、ボートが動けなくなる理由にはならない。"}, {"text": "洗剤", "is_correct": false, "explanation": "洗剤は船の動力と関係がなく、切れてもボートが止まる理由にならない。"}, {"text": "歌", "is_correct": false, "explanation": "歌はボートの動力に関わらず、切れてボートが動けなくなる理由にはならない。"}], "explanations": {"燃料": "燃料が切れると燃やすものがなくなり、ボートが海の真ん中で止まる文脈に合う。", "会話": "会話は切れるものだが、ボートが動けなくなる理由にはならない。", "洗剤": "洗剤は船の動力と関係がなく、切れてもボートが止まる理由にならない。", "歌": "歌はボートの動力に関わらず、切れてボートが動けなくなる理由にはならない。"}, "sentence_index": 6, "correct_answer": "燃料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "のどが渇いたので、燃料を一杯飲んだ。", "explanation": "ここは〈水〉の意味。燃料は燃やして熱や動力を得るもので、飲み物としては使わない。"}, {"text": "玄関に燃料を飾った。", "explanation": "ここは〈花〉の意味。燃料は観賞用に飾るものではなく、玄関に置く物としては合わない。"}, {"text": "風邪をひいたので、燃料を飲んだ。", "explanation": "ここは〈薬〉の意味。燃料は体の治療に使うものではなく、風邪のときに飲む物としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37295, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒くなってきたので、ストーブの燃料が入れた。", "corrected_sentence": "寒くなってきたので、ストーブの燃料を入れた。", "error_description": "助詞の誤り。「入れる」は入れる対象を「を」で示すので「燃料を」が正しい。「燃料が」では燃料が入れる主体になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37295, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬の前に燃料を買いておけば、安心だ。", "corrected_sentence": "冬の前に燃料を買っておけば、安心だ。", "error_description": "活用の誤り。「買う」の音便形は「買って」で、「買いて」は誤り。「買っておけば」と言う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37296, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「将来のこと」の連体修飾。「こと」を修飾して、将来についての事柄を表す。"}, {"text": "が", "is_correct": false, "explanation": "主格。「将来がことは」は名詞を修飾できず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的格。「こと」の前に目的語は立たず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向。「将来へこと」は方向を表さず不自然。"}], "correct_answer": "の", "explanations": {"の": "「将来のこと」の連体修飾。「こと」を修飾して、将来についての事柄を表す。", "が": "主格。「将来がことは」は名詞を修飾できず、文が成り立たない。", "を": "目的格。「こと」の前に目的語は立たず不自然。", "へ": "方向。「将来へこと」は方向を表さず不自然。"}, "error_tags": {"が": "主格", "を": "目的語", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "過去", "is_correct": true, "explanation": "まだ来ていない時間である「将来」に対して、すでに過ぎた時間を表す対義語。"}, {"text": "原因", "is_correct": false, "explanation": "「原因」は「結果」と対になる語で、時間の対義語ではない。"}, {"text": "結果", "is_correct": false, "explanation": "「結果」は「原因」と対になる語で、将来の反対語ではない。"}, {"text": "故郷", "is_correct": false, "explanation": "「故郷」は場所を表す語で、時間の対義語ではない。"}], "correct_answer": "過去", "explanations": {"過去": "まだ来ていない時間である「将来」に対して、すでに過ぎた時間を表す対義語。", "原因": "「原因」は「結果」と対になる語で、時間の対義語ではない。", "結果": "「結果」は「原因」と対になる語で、将来の反対語ではない。", "故郷": "「故郷」は場所を表す語で、時間の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37296, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "過去", "is_correct": true, "explanation": "まだ来ていない時間である「将来」に対して、すでに過ぎた時間を表す対義語。"}, {"text": "中心", "is_correct": false, "explanation": "「中心」は物事の真ん中を指す語で、時間の対義語ではない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節」は一年の区分を表す語で、将来の反対語ではない。"}, {"text": "出発", "is_correct": false, "explanation": "「出発」は「到着」と対になる語で、時間の対義語ではない。"}], "correct_answer": "過去", "explanations": {"過去": "まだ来ていない時間である「将来」に対して、すでに過ぎた時間を表す対義語。", "中心": "「中心」は物事の真ん中を指す語で、時間の対義語ではない。", "季節": "「季節」は一年の区分を表す語で、将来の反対語ではない。", "出発": "「出発」は「到着」と対になる語で、時間の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37296, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あとで来る時間のこと。", "primary_collocate": null, "pronunciation": "しょうらい", "ipa": "ɕoːɾai", "syllable_count": 4, "sentences": [{"text": "将来、宇宙飛行士になるのが私の目標です。", "target_word": "将来", "complexity_tier": "T2", "furigana": "将来[しょうらい]、宇宙飛行士[うちゅうひこうし]になるのが私[わたし]の目標[もくひょう]です。", "sentence_source": "generated"}, {"text": "将来のことは誰にもわからないので、今を大切にしたい。", "target_word": "将来", "complexity_tier": "T3", "furigana": "将来[しょうらい]のことは誰[だれ]にもわからないので、今[いま]を大切[たいせつ]にしたい。", "sentence_source": "generated"}, {"text": "祖父は孫の将来を楽しみにしている。", "target_word": "将来", "complexity_tier": "T2", "furigana": "祖父[そふ]は孫[まご]の将来[しょうらい]を楽[たの]しみにしている。", "sentence_source": "generated"}, {"text": "将来に備えて、英語の勉強を始めた。", "target_word": "将来", "complexity_tier": "T3", "furigana": "将来[しょうらい]に備[そな]えて、英語[えいご]の勉強[べんきょう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "将来どんな仕事をしたいか、まだ決まっていない。", "target_word": "将来", "complexity_tier": "T2", "furigana": "将来[しょうらい]どんな仕事[しごと]をしたいか、まだ決[き]まっていない。", "sentence_source": "generated"}, {"text": "遠い将来には、人が火星に住んでいるかもしれない。", "target_word": "将来", "complexity_tier": "T3", "furigana": "遠[とお]い将来[しょうらい]には、人[ひと]が火星[かせい]に住[す]んでいるかもしれない。", "sentence_source": "generated"}, {"text": "先生は私の将来を心配して、何度も相談に乗ってくれた。", "target_word": "将来", "complexity_tier": "T3", "furigana": "先生[せんせい]は私[わたし]の将来[しょうらい]を心配[しんぱい]して、何度[なんど]も相談[そうだん]に乗[の]ってくれた。", "sentence_source": "generated"}, {"text": "この計画は将来、町の大きな観光地になるだろう。", "target_word": "将来", "complexity_tier": "T3", "furigana": "この計画[けいかく]は将来[しょうらい]、町[まち]の大[おお]きな観光地[かんこうち]になるだろう。", "sentence_source": "generated"}, {"text": "彼は将来の目標を決めて、来年大学に入る。", "target_word": "将来", "complexity_tier": "T3", "furigana": "彼[かれ]は将来[しょうらい]の目標[もくひょう]を決[き]めて、来年[らいねん]大学[だいがく]に入[はい]る。", "sentence_source": "generated"}, {"text": "将来の安心のために、早めに保険に入っておいた。", "target_word": "将来", "complexity_tier": "T3", "furigana": "将来[しょうらい]の安心[あんしん]のために、早[はや]めに保険[ほけん]に入[はい]っておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "将来", "label": "基本形"}, {"form": "将来の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "あとで来る時間、これから先", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b24d15-9ff0-4e3d-8f40-83d3e5a40e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37296, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "文頭で時期を示す名詞。「将来、宇宙飛行士になるのが私の目標」という文脈に合う。"}, {"text": "去年", "is_correct": false, "explanation": "過去の時間を指し、未来の目標を述べる文と合わない。"}, {"text": "過去", "is_correct": false, "explanation": "「過去、目標です」は過去の出来事の説明になり、将来の目標とは合わない。"}, {"text": "深夜", "is_correct": false, "explanation": "時間帯を表すが、「深夜、目標です」では文脈に合わない。"}], "explanations": {"将来": "文頭で時期を示す名詞。「将来、宇宙飛行士になるのが私の目標」という文脈に合う。", "去年": "過去の時間を指し、未来の目標を述べる文と合わない。", "過去": "「過去、目標です」は過去の出来事の説明になり、将来の目標とは合わない。", "深夜": "時間帯を表すが、「深夜、目標です」では文脈に合わない。"}, "sentence_index": 0, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "将来、子どものころ住んでいた町を訪ねた。", "explanation": "ここは〈以前〉の意味。子どものころという過去を述べる文で、まだ来ていない時間を指す将来とは合わない。"}, {"text": "将来、英語の勉強を始めた。", "explanation": "ここは〈去年〉の意味。将来はまだ来ていない時間なので、すでに起きた出来事には使わない。"}, {"text": "将来は、まだ英語が苦手だった。", "explanation": "ここは〈最初〉の意味。過去の状態を述べる文で、まだ来ていない将来とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37296, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "「私の将来を心配して」の目的語。心配の対象として自然に入る。"}, {"text": "天気", "is_correct": false, "explanation": "「私の天気を心配して」は心配の対象として不自然。"}, {"text": "空腹", "is_correct": false, "explanation": "「私の空腹を心配して」は文脈に合わない。"}, {"text": "自転車", "is_correct": false, "explanation": "「私の自転車を心配して」は相談の内容として成り立たない。"}], "explanations": {"将来": "「私の将来を心配して」の目的語。心配の対象として自然に入る。", "天気": "「私の天気を心配して」は心配の対象として不自然。", "空腹": "「私の空腹を心配して」は文脈に合わない。", "自転車": "「私の自転車を心配して」は相談の内容として成り立たない。"}, "sentence_index": 6, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "将来は保険に入っていなかった。", "explanation": "ここは〈昨夜〉の意味。過去の状態を述べる文で、まだ来ていない将来とは合わない。"}, {"text": "将来の面接は三時です。", "explanation": "ここは〈次回〉の意味。将来は漠然とした先の時間で、三時という特定の時刻には合わない。"}, {"text": "二人は将来、同時に保険に入った。", "explanation": "ここは〈一斉〉の意味。その場で一緒に起きた出来事を表すので、まだ来ていない時間を指す将来とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37296, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "将来が仕事について、先生に相談してみよう。", "corrected_sentence": "将来の仕事について、先生に相談してみよう。", "error_description": "「将来」は「の」で「仕事」を修飾する。「が」は主語を示すため、「将来が仕事について」は不自然。正しくは「将来の仕事について」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37296, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "将来を夢に向けて、毎日少しずつ練習しています。", "corrected_sentence": "将来の夢に向けて、毎日少しずつ練習しています。", "error_description": "「将来の夢」は「の」で「夢」を修飾する。「を」は目的語を示すため、「将来を夢に向けて」は不自然。正しくは「将来の夢に向けて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37297, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「将来の夢」の連体修飾。「夢」を修飾して、将来の夢という意味になる。"}, {"text": "が", "is_correct": false, "explanation": "主格。「将来が夢について」は主語として成り立たず不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的格。「将来を夢について」は目的語を取る形として不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所。「将来で夢について」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「将来の夢」の連体修飾。「夢」を修飾して、将来の夢という意味になる。", "が": "主格。「将来が夢について」は主語として成り立たず不自然。", "を": "目的格。「将来を夢について」は目的語を取る形として不自然。", "で": "手段・場所。「将来で夢について」は意味が通らない。"}, "error_tags": {"が": "主格", "を": "目的語", "で": "手段・場所"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "過去", "is_correct": true, "explanation": "まだ来ていない時間である「将来」に対して、すでに過ぎた時間を表す対義語。"}, {"text": "原因", "is_correct": false, "explanation": "「原因」は「結果」と対になる語で、時間の対義語ではない。"}, {"text": "結果", "is_correct": false, "explanation": "「結果」は「原因」と対になる語で、将来の反対語ではない。"}, {"text": "故郷", "is_correct": false, "explanation": "「故郷」は場所を表す語で、時間の対義語ではない。"}], "correct_answer": "過去", "explanations": {"過去": "まだ来ていない時間である「将来」に対して、すでに過ぎた時間を表す対義語。", "原因": "「原因」は「結果」と対になる語で、時間の対義語ではない。", "結果": "「結果」は「原因」と対になる語で、将来の反対語ではない。", "故郷": "「故郷」は場所を表す語で、時間の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37297, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「将来を守る」の目的語。守る対象として「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "主格。「将来が守る」では、守る主体に将来が立つことになり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「将来に守る」は動詞と合わず、守る対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向。「将来へ守る」は方向を表さず、守る対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「将来を守る」の目的語。守る対象として「を」が入る。", "が": "主格。「将来が守る」では、守る主体に将来が立つことになり不自然。", "に": "「将来に守る」は動詞と合わず、守る対象を示せない。", "へ": "方向。「将来へ守る」は方向を表さず、守る対象として成り立たない。"}, "error_tags": {"が": "主格", "に": "位置・相手", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "過去", "is_correct": true, "explanation": "まだ来ていない時間である「将来」に対して、すでに過ぎた時間を表す対義語。"}, {"text": "中心", "is_correct": false, "explanation": "「中心」は物事の真ん中を指す語で、時間の対義語ではない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節」は一年の区分を表す語で、将来の反対語ではない。"}, {"text": "出発", "is_correct": false, "explanation": "「出発」は「到着」と対になる語で、時間の対義語ではない。"}], "correct_answer": "過去", "explanations": {"過去": "まだ来ていない時間である「将来」に対して、すでに過ぎた時間を表す対義語。", "中心": "「中心」は物事の真ん中を指す語で、時間の対義語ではない。", "季節": "「季節」は一年の区分を表す語で、将来の反対語ではない。", "出発": "「出発」は「到着」と対になる語で、時間の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37297, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これから先の、まだ来ていない時間。", "primary_collocate": null, "pronunciation": "しょうらい", "ipa": "ɕoːɾai", "syllable_count": 4, "sentences": [{"text": "将来、ベンチャーキャピタルの投資先は社会に役立つ企業になるだろう。", "target_word": "将来", "complexity_tier": "T3", "furigana": "将来[しょうらい]、ベンチャーキャピタルの投資先[とうしさき]は社会[しゃかい]に役立[やくだ]つ企業[きぎょう]になるだろう。", "sentence_source": "generated"}, {"text": "将来の夢について、クラスのみんなの前で発表しました。", "target_word": "将来", "complexity_tier": "T2", "furigana": "将来[しょうらい]の夢[ゆめ]について、クラスのみんなの前[まえ]で発表[はっぴょう]しました。", "sentence_source": "generated"}, {"text": "私は将来、小さな病院で働きたいと考えています。", "target_word": "将来", "complexity_tier": "T2", "furigana": "私[わたし]は将来[しょうらい]、小[ちい]さな病院[びょういん]で働[はたら]きたいと考[かんが]えています。", "sentence_source": "generated"}, {"text": "将来のために、毎月少しずつ貯金しています。", "target_word": "将来", "complexity_tier": "T3", "furigana": "将来[しょうらい]のために、毎月[まいつき]少[すこ]しずつ貯金[ちょきん]しています。", "sentence_source": "generated"}, {"text": "近い将来、この町にも新しい駅ができる予定だ。", "target_word": "将来", "complexity_tier": "T3", "furigana": "近[ちか]い将来[しょうらい]、この町[まち]にも新[あたら]しい駅[えき]ができる予定[よてい]だ。", "sentence_source": "generated"}, {"text": "将来が不安で、最近よく眠れない。", "target_word": "将来", "complexity_tier": "T3", "furigana": "将来[しょうらい]が不安[ふあん]で、最近[さいきん]よく眠[ねむ]れない。", "sentence_source": "generated"}, {"text": "兄は将来を考えて、大学で経済を学ぶことにした。", "target_word": "将来", "complexity_tier": "T3", "furigana": "兄[あに]は将来[しょうらい]を考[かんが]えて、大学[だいがく]で経済[けいざい]を学[まな]ぶことにした。", "sentence_source": "generated"}, {"text": "子どもたちの将来を守るために、環境問題に取り組むべきだ。", "target_word": "将来", "complexity_tier": "T4", "furigana": "子[こ]どもたちの将来[しょうらい]を守[まも]るために、環境問題[かんきょうもんだい]に取[と]り組[く]むべきだ。", "sentence_source": "generated"}, {"text": "将来どんな大人になりたいか想像して、手紙を書いてみましょう。", "target_word": "将来", "complexity_tier": "T3", "furigana": "将来[しょうらい]どんな大人になりたいか想像して、手紙を書いてみましょう。", "sentence_source": "generated"}, {"text": "人口が減ると、将来は働く人が足りなくなると言われている。", "target_word": "将来", "complexity_tier": "T4", "furigana": "人口[じんこう]が減[へ]ると、将来[しょうらい]は働[はたら]く人[ひと]が足[た]りなくなると言[い]われている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "将来", "label": "基本形"}, {"form": "将来の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "これから先の時間、未来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b24d15-9ff0-4e3d-8f40-83d3e5a40e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37297, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "文頭で時期を示す名詞。「将来、…になるだろう」と先の見通しを述べる文に合う。"}, {"text": "過去", "is_correct": false, "explanation": "過去を指すので、「…になるだろう」という未来の予測と合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は人の年数を示し、この文の時期を表せない。"}, {"text": "順番", "is_correct": false, "explanation": "順番は並びを示す語で、時期を表す文頭には入らない。"}], "explanations": {"将来": "文頭で時期を示す名詞。「将来、…になるだろう」と先の見通しを述べる文に合う。", "過去": "過去を指すので、「…になるだろう」という未来の予測と合わない。", "年齢": "年齢は人の年数を示し、この文の時期を表せない。", "順番": "順番は並びを示す語で、時期を表す文頭には入らない。"}, "sentence_index": 0, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "将来、彼は大学を卒業した。", "explanation": "ここは〈去年〉の意味。将来はまだ来ていない時間を指すので、すでに終わった出来事には使わない。"}, {"text": "将来の会議は来週の月曜日です。", "explanation": "ここは〈次回〉の意味。将来は漠然とした先の時間で、来週の月曜日のような特定の日付には使わない。"}, {"text": "将来の写真を見て、懐かしくなった。", "explanation": "ここは〈当時〉の意味。懐かしむのはすでに過ぎた出来事で、まだ来ていない将来とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37297, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "「将来を考えて」の目的語。考える対象として自然に入る。"}, {"text": "天気", "is_correct": false, "explanation": "「天気を考えて、大学で経済を学ぶ」は因果がつながらず不自然。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹を考えて」は考える対象として成り立たない。"}, {"text": "自転車", "is_correct": false, "explanation": "「自転車を考えて」は進路の判断を表せず、文脈に合わない。"}], "explanations": {"将来": "「将来を考えて」の目的語。考える対象として自然に入る。", "天気": "「天気を考えて、大学で経済を学ぶ」は因果がつながらず不自然。", "空腹": "「空腹を考えて」は考える対象として成り立たない。", "自転車": "「自転車を考えて」は進路の判断を表せず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "将来、いま電話に出ています。", "explanation": "ここは〈現在〉の意味。将来はまだ来ていない時間を指すので、今まさに行っている動作の文には合わない。"}, {"text": "二人は将来、同時に手を挙げた。", "explanation": "ここは〈一斉〉の意味。その場で一緒に起きた動作を表す文で、まだ来ていない時間を指す将来とは合わない。"}, {"text": "将来、ちょうど出かけたところだ。", "explanation": "ここは〈直前〉の意味。出かけたばかりの出来事を述べる文で、まだ来ていない時間を指す将来とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37297, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "将来を進路について、先生と話し合う予定です。", "corrected_sentence": "将来の進路について、先生と話し合う予定です。", "error_description": "「将来」のあとは「の」で「進路」を修飾する。「を」は目的語を示すため、「将来を進路について」は不自然。正しくは「将来の進路について」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37297, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "将来で備えて、毎日少しずつお金を貯めています。", "corrected_sentence": "将来に備えて、毎日少しずつお金を貯めています。", "error_description": "「将来に備える」の「に」は目的を示す。「で」は手段・場所を表すので、「将来で備えて」は不自然。正しくは「将来に備えて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37298, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「残る」は自動詞で、主語に「が」を取る。「黒いカーボンが残っていた」と正しく続く。"}, {"text": "を", "is_correct": false, "explanation": "「残る」は目的語を取らないので、「を」は続かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「黒いカーボンで残っていた」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を示すため、「カーボンと残っていた」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「残る」は自動詞で、主語に「が」を取る。「黒いカーボンが残っていた」と正しく続く。", "を": "「残る」は目的語を取らないので、「を」は続かない。", "で": "「で」は手段や場所を示すため、「黒いカーボンで残っていた」は文として成り立たない。", "と": "「と」は相手や共同を示すため、「カーボンと残っていた」は意味が通らない。"}, "error_tags": {"を": "対象（目的語）", "で": "手段・場所", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37298, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜になる」で結果を表す「に」。「木がカーボンになった」と正しく続く。"}, {"text": "が", "is_correct": false, "explanation": "「なる」は「に」を取るので、「カーボンがなった」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「なる」は目的語を取らないので、「を」は続かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や材料を示すので、「カーボンでなった」は文として通らない。"}], "correct_answer": "に", "explanations": {"に": "「〜になる」で結果を表す「に」。「木がカーボンになった」と正しく続く。", "が": "「なる」は「に」を取るので、「カーボンがなった」は成り立たない。", "を": "「なる」は目的語を取らないので、「を」は続かない。", "で": "「で」は手段や材料を示すので、「カーボンでなった」は文として通らない。"}, "error_tags": {"が": "主語（主格）", "を": "対象（目的語）", "で": "手段・材料"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37298, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「カーボン」は、石炭や木炭のもとになる、黒い色の物質のことです。", "primary_collocate": null, "pronunciation": "かーぼん", "ipa": "kaːboɴ", "syllable_count": 4, "sentences": [{"text": "木炭の黒い色は、カーボンの色です。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "木炭[もくたん]の黒[くろ]い色[いろ]は、カーボンの色[いろ]です。", "sentence_source": "generated"}, {"text": "石炭を燃やしたあと、ストーブの中に黒いカーボンが残っていた。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "石炭[せきたん]を燃[も]やしたあと、ストーブの中[なか]に黒[くろ]いカーボンが残[のこ]っていた。", "sentence_source": "generated"}, {"text": "火のあとに残った黒い粉は、カーボンでした。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "火[ひ]のあとに残[のこ]った黒[くろ]い粉[こな]は、カーボンでした。", "sentence_source": "generated"}, {"text": "ろうそくの炎を皿に当てると、黒いカーボンが付いた。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "ろうそくの炎[ほのお]を皿[さら]に当[あ]てると、黒[くろ]いカーボンが付[つ]いた。", "sentence_source": "generated"}, {"text": "木を焼くと、黒いカーボンが残ります。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "木[き]を焼[や]くと、黒[くろ]いカーボンが残[のこ]ります。", "sentence_source": "generated"}, {"text": "壁についた黒いカーボンを、布でふいた。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "壁[かべ]についた黒[くろ]いカーボンを、布[ぬの]でふいた。", "sentence_source": "generated"}, {"text": "カーボンは黒いので、白い紙に落ちるとすぐ目立つ。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "カーボンは黒[くろ]いので、白[しろ]い紙[かみ]に落[お]ちるとすぐ目立[めだ]つ。", "sentence_source": "generated"}, {"text": "炭は、木がカーボンになったものです。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "炭[すみ]は、木[き]がカーボンになったものです。", "sentence_source": "generated"}, {"text": "煙突の中に、カーボンがたくさんたまっていた。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "煙突[えんとつ]の中[なか]に、カーボンがたくさんたまっていた。", "sentence_source": "generated"}, {"text": "焼けた木の表面は、カーボンで真っ黒だった。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "焼[や]けた木[き]の表面[ひょうめん]は、カーボンで真[ま]っ黒[くろ]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カーボン", "label": "基本形"}], "register": "中立", "sense_fingerprint": "石炭や木炭のもとになる黒い物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37298, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カーボン", "is_correct": true, "explanation": "木炭の黒い色の正体を指す語で、「黒い色の物質」としてこの空欄に入る。"}, {"text": "雪", "is_correct": false, "explanation": "雪は白いので、「木炭の黒い色」と並べると文として矛盾する。"}, {"text": "牛乳", "is_correct": false, "explanation": "牛乳は白い飲み物で、木炭の黒い色の説明にならない。"}, {"text": "小麦粉", "is_correct": false, "explanation": "白っぽい粉で、木炭の黒さを言う文に合わない。"}], "explanations": {"カーボン": "木炭の黒い色の正体を指す語で、「黒い色の物質」としてこの空欄に入る。", "雪": "雪は白いので、「木炭の黒い色」と並べると文として矛盾する。", "牛乳": "牛乳は白い飲み物で、木炭の黒い色の説明にならない。", "小麦粉": "白っぽい粉で、木炭の黒さを言う文に合わない。"}, "sentence_index": 0, "correct_answer": "カーボン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "薪を燃やしたあと、白いカーボンが山のように残った。", "explanation": "ここは〈灰〉の意味。灰は白っぽい粉だが、カーボンは黒い物質なので白いとは言わない。"}, {"text": "鉄の扉の表面に、赤いカーボンが浮き出ていた。", "explanation": "ここは〈さび〉の意味。さびは赤茶色だが、カーボンは黒い物質なので赤いとは言わない。"}, {"text": "硯にカーボンをすって、筆で字を練習した。", "explanation": "ここは〈墨〉の意味。墨は硯ですって使うが、カーボンを硯ですって字を書くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37298, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カーボン", "is_correct": true, "explanation": "黒い物質で、「黒いので白い紙で目立つ」と説明される主語になる。"}, {"text": "片栗粉", "is_correct": false, "explanation": "白い粉で、黒さを理由に目立つという文と矛盾する。"}, {"text": "豆腐", "is_correct": false, "explanation": "白い食品で、黒さを理由に目立つという文と矛盾する。"}, {"text": "ご飯", "is_correct": false, "explanation": "白いご飯は黒くないので、「黒いので目立つ」の主語として成り立たない。"}], "explanations": {"カーボン": "黒い物質で、「黒いので白い紙で目立つ」と説明される主語になる。", "片栗粉": "白い粉で、黒さを理由に目立つという文と矛盾する。", "豆腐": "白い食品で、黒さを理由に目立つという文と矛盾する。", "ご飯": "白いご飯は黒くないので、「黒いので目立つ」の主語として成り立たない。"}, "sentence_index": 6, "correct_answer": "カーボン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に喉が渇いて、カーボンをコップに注いで飲んだ。", "explanation": "ここは〈ジュース〉の意味。コップに注いで飲むのは飲み物で、黒い物質のカーボンは飲み物とは言わない。"}, {"text": "窓から差し込む朝日で、カーボンが透けて見えた。", "explanation": "ここは〈薄いカーテン〉の意味。薄い布は透けて見えるが、黒い物質のカーボンは透けないので使わない。"}, {"text": "この服は、カーボンのように肌触りがやわらかい。", "explanation": "ここは〈綿〉の意味。綿は肌触りがやわらかいと言うが、黒い物質のカーボンは肌触りの話では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37298, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "調理器具の底に、黒いカーボンをこびりついていた。", "corrected_sentence": "調理器具の底に、黒いカーボンがこびりついていた。", "error_description": "「こびりつく」は自動詞なので、主語に「が」を使う。ここの「を」は誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37298, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "換気扇の羽に、黒いカーボンに積もっていた。", "corrected_sentence": "換気扇の羽に、黒いカーボンが積もっていた。", "error_description": "「積もる」は自動詞で、主語に「が」を使う。ここの「に」は誤りで、正しくは「が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37299, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「欠かせない」は主語に「が」を取る。「カーボンが欠かせません」と正しく続く。"}, {"text": "を", "is_correct": false, "explanation": "「欠かせない」は目的語を取らないので、「を」は続かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すため、「カーボンで欠かせません」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を示すため、「カーボンと欠かせません」は不自然で通らない。"}], "correct_answer": "が", "explanations": {"が": "「欠かせない」は主語に「が」を取る。「カーボンが欠かせません」と正しく続く。", "を": "「欠かせない」は目的語を取らないので、「を」は続かない。", "で": "「で」は手段を示すため、「カーボンで欠かせません」は文として成り立たない。", "と": "「と」は相手や共同を示すため、「カーボンと欠かせません」は不自然で通らない。"}, "error_tags": {"を": "対象（目的語）", "で": "手段・方法", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
