INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37299, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「カーボン」は、元素の一つで、炭素を意味します。化学記号はCで、すべての生物の基本成分であり、石炭やダイヤモンドなどの形で存在します。", "primary_collocate": null, "pronunciation": "かーぼん", "ipa": "kaːboɴ", "syllable_count": 4, "sentences": [{"text": "カーボンは、元素の一つで、記号はCです。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "カーボンは、元素[げんそ]の一[ひと]つで、記号[きごう]はCです。", "sentence_source": "generated"}, {"text": "生き物の体には、カーボンが欠かせません。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "生[い]き物[もの]の体[からだ]には、カーボンが欠[か]かせません。", "sentence_source": "generated"}, {"text": "ダイヤモンドは、カーボンでできた宝石です。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "ダイヤモンドは、カーボンでできた宝石[ほうせき]です。", "sentence_source": "generated"}, {"text": "理科の授業で、カーボンの原子番号は6だと習った。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、カーボンの原子番号[げんしばんごう]は6だと習[なら]った。", "sentence_source": "generated"}, {"text": "カーボンは、石炭の形でも自然の中にある。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "カーボンは、石炭[せきたん]の形[かたち]でも自然[しぜん]の中[なか]にある。", "sentence_source": "generated"}, {"text": "化学の試験に、カーボンの記号が出た。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "化学[かがく]の試験[しけん]に、カーボンの記号[きごう]が出[で]た。", "sentence_source": "generated"}, {"text": "植物は空気中の二酸化炭素から、カーボンを取り入れる。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は空気中[くうきちゅう]の二酸化炭素[にさんかたんそ]から、カーボンを取[と]り入[い]れる。", "sentence_source": "generated"}, {"text": "鉛筆の黒鉛も、カーボンの仲間です。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "鉛筆[えんぴつ]の黒鉛[こくえん]も、カーボンの仲間[なかま]です。", "sentence_source": "generated"}, {"text": "カーボンは、日本語で炭素といいます。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "カーボンは、日本語[にほんご]で炭素[たんそ]といいます。", "sentence_source": "generated"}, {"text": "水の分子にはカーボンが入っていないが、砂糖には入っている。", "target_word": "カーボン", "complexity_tier": "T3", "furigana": "水[みず]の分子[ぶんし]にはカーボンが入[はい]っていないが、砂糖[さとう]には入[はい]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カーボン", "label": "基本形"}], "register": "中立", "sense_fingerprint": "元素の炭素（記号C）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37299, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カーボン", "is_correct": true, "explanation": "記号Cの元素の名前で、「元素の一つで、記号はCです」と正しく対応する。"}, {"text": "水素", "is_correct": false, "explanation": "水素の記号はHで、記号Cと一致しない。"}, {"text": "窒素", "is_correct": false, "explanation": "窒素の記号はNで、記号Cと一致しない。"}, {"text": "硫黄", "is_correct": false, "explanation": "硫黄の記号はSで、記号Cと一致しない。"}], "explanations": {"カーボン": "記号Cの元素の名前で、「元素の一つで、記号はCです」と正しく対応する。", "水素": "水素の記号はHで、記号Cと一致しない。", "窒素": "窒素の記号はNで、記号Cと一致しない。", "硫黄": "硫黄の記号はSで、記号Cと一致しない。"}, "sentence_index": 0, "correct_answer": "カーボン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食品の袋には、カーボンを入れて酸化を防ぐ。", "explanation": "ここは〈窒素〉の意味。袋に入れて酸化を防ぐのは窒素で、炭素のカーボンは使わない。"}, {"text": "冬は、カーボンをおこして部屋を暖めた。", "explanation": "ここは〈炭〉の意味。炭はおこして燃やすが、元素名のカーボンをおこすとは言わない。"}, {"text": "プールの水には、カーボンを入れて消毒する。", "explanation": "ここは〈塩素〉の意味。プールの消毒に入れるのは塩素で、炭素のカーボンは消毒には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37299, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カーボン", "is_correct": true, "explanation": "植物が二酸化炭素から取り入れる炭素のことで、ここに正しく入る。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は植物が二酸化炭素から取り入れる物質ではない。"}, {"text": "銅", "is_correct": false, "explanation": "銅は植物が取り入れる物質ではなく、文の意味が通らない。"}, {"text": "塩素", "is_correct": false, "explanation": "塩素は空気中の二酸化炭素に含まれず、「二酸化炭素から取り入れる」物質ではないので、ここには入らない。"}], "explanations": {"カーボン": "植物が二酸化炭素から取り入れる炭素のことで、ここに正しく入る。", "鉄": "鉄は植物が二酸化炭素から取り入れる物質ではない。", "銅": "銅は植物が取り入れる物質ではなく、文の意味が通らない。", "塩素": "塩素は空気中の二酸化炭素に含まれず、「二酸化炭素から取り入れる」物質ではないので、ここには入らない。"}, "sentence_index": 6, "correct_answer": "カーボン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "植物は光を浴びて、カーボンを出す。", "explanation": "ここは〈酸素〉の意味。光合成で植物が放出するのは酸素で、カーボンを出すとは言わない。"}, {"text": "紅茶に、カーボンを入れて甘くして飲んだ。", "explanation": "ここは〈砂糖〉の意味。甘くするために入れるのは砂糖で、炭素のカーボンを入れて甘くするとは言わない。"}, {"text": "料理に、カーボンを少し入れて味を整えた。", "explanation": "ここは〈食塩〉の意味。味を整えるために入れるのは食塩で、炭素のカーボンは味付けには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37299, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "カーボンを、空気中の酸素と結びついて二酸化炭素になる。", "corrected_sentence": "カーボンは、空気中の酸素と結びついて二酸化炭素になる。", "error_description": "「結びつく」は自動詞で、主題は「は」を使う。ここの「を」は誤りで、正しくは「は」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37299, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "木炭にも石炭にも、カーボンを多く含まれている。", "corrected_sentence": "木炭にも石炭にも、カーボンが多く含まれている。", "error_description": "「含まれる」は受け身で、主語に「が」を使う。ここの「を」は誤りで、正しくは「が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37300, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏向的", "is_correct": true, "explanation": "正解。一方に傾いた状態を表し、中立の反対の意味で対になる。"}, {"text": "客観的", "is_correct": false, "explanation": "『客観的』は中立に近い意味で、対義語ではない。"}, {"text": "慎重", "is_correct": false, "explanation": "『慎重』は行動の注意深さを表し、偏りの対義語にはならない。"}, {"text": "冷静", "is_correct": false, "explanation": "『冷静』は感情を抑える様子で、偏りの対義語ではない。"}], "correct_answer": "偏向的", "explanations": {"偏向的": "正解。一方に傾いた状態を表し、中立の反対の意味で対になる。", "客観的": "『客観的』は中立に近い意味で、対義語ではない。", "慎重": "『慎重』は行動の注意深さを表し、偏りの対義語にはならない。", "冷静": "『冷静』は感情を抑える様子で、偏りの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
