INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37300, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "「中立」という意味で、どちらにもかたよらないこと。", "primary_collocate": null, "pronunciation": "にゅーとらる", "ipa": "ɲɯːtoɾaɾɯ", "syllable_count": 5, "sentences": [{"text": "先生は二人のけんかを、ニュートラルな立場で聞いてくれた。", "target_word": "ニュートラル", "complexity_tier": "T3", "furigana": "先生[せんせい]は二人[ふたり]のけんかを、ニュートラルな立場[たちば]で聞[き]いてくれた。", "sentence_source": "generated"}, {"text": "記者は、ニュートラルな言葉でニュースを伝えるべきだ。", "target_word": "ニュートラル", "complexity_tier": "T3", "furigana": "記者[きしゃ]は、ニュートラルな言葉[ことば]でニュースを伝[つた]えるべきだ。", "sentence_source": "generated"}, {"text": "どちらの味方もしたくないので、私はニュートラルでいたい。", "target_word": "ニュートラル", "complexity_tier": "T3", "furigana": "どちらの味方[みかた]もしたくないので、私[わたし]はニュートラルでいたい。", "sentence_source": "generated"}, {"text": "司会者がニュートラルに進めたので、両方の意見が出た。", "target_word": "ニュートラル", "complexity_tier": "T3", "furigana": "司会者[しかいしゃ]がニュートラルに進[すす]めたので、両方[りょうほう]の意見[いけん]が出[で]た。", "sentence_source": "generated"}, {"text": "この記事はニュートラルに書かれていて、どちらの考えにも偏っていない。", "target_word": "ニュートラル", "complexity_tier": "T3", "furigana": "この記事[きじ]はニュートラルに書[か]かれていて、どちらの考[かんが]えにも偏[かたよ]っていない。", "sentence_source": "generated"}, {"text": "意見が分かれたとき、彼はいつもニュートラルな態度をとる。", "target_word": "ニュートラル", "complexity_tier": "T3", "furigana": "意見[いけん]が分[わ]かれたとき、彼[かれ]はいつもニュートラルな態度[たいど]をとる。", "sentence_source": "generated"}, {"text": "審判はニュートラルでなければならないので、どのチームも応援しない。", "target_word": "ニュートラル", "complexity_tier": "T3", "furigana": "審判[しんぱん]はニュートラルでなければならないので、どのチームも応援[おうえん]しない。", "sentence_source": "generated"}, {"text": "私は賛成でも反対でもなく、ニュートラルな気持ちです。", "target_word": "ニュートラル", "complexity_tier": "T3", "furigana": "私[わたし]は賛成[さんせい]でも反対[はんたい]でもなく、ニュートラルな気持[きも]ちです。", "sentence_source": "generated"}, {"text": "友達の相談を聞くときは、ニュートラルに考えるようにしている。", "target_word": "ニュートラル", "complexity_tier": "T3", "furigana": "友達[ともだち]の相談[そうだん]を聞[き]くときは、ニュートラルに考[かんが]えるようにしている。", "sentence_source": "generated"}, {"text": "国どうしの争いでは、ニュートラルな第三者が話し合いを助けた。", "target_word": "ニュートラル", "complexity_tier": "T3", "furigana": "国[くに]どうしの争[あらそ]いでは、ニュートラルな第三者[だいさんしゃ]が話[はな]し合[あ]いを助[たす]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ニュートラル", "label": "基本形"}, {"form": "ニュートラルな", "label": "連体形"}, {"form": "ニュートラルに", "label": "連用形"}], "register": "標準（丁寧体・普通体）", "sense_fingerprint": "どちらの立場にもつかない中立の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '729dc63f-8b18-4b3c-895a-efbae94aab11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37300, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ニュートラル", "is_correct": true, "explanation": "正解。偏らない立場を表し、『〜な立場で聞いてくれた』に合う。"}, {"text": "元気", "is_correct": false, "explanation": "『元気な立場』は立場の性質として成り立たず、文が不自然。"}, {"text": "派手", "is_correct": false, "explanation": "『派手な立場』は偏らない立場を表さず、文脈に合わない。"}, {"text": "便利", "is_correct": false, "explanation": "『便利な立場』は意味が通らず、けんかの仲裁の文脈に合わない。"}], "explanations": {"ニュートラル": "正解。偏らない立場を表し、『〜な立場で聞いてくれた』に合う。", "元気": "『元気な立場』は立場の性質として成り立たず、文が不自然。", "派手": "『派手な立場』は偏らない立場を表さず、文脈に合わない。", "便利": "『便利な立場』は意味が通らず、けんかの仲裁の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ニュートラル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの子はニュートラルなので、先生の注意をすぐ受け入れる。", "explanation": "ここは〈素直〉の意味。ニュートラルは立場が偏らないことで、言われたことをすぐ受け入れる性格は表さない。"}, {"text": "毎日がニュートラルで、特に変わったことがない。", "explanation": "ここは〈平凡〉の意味。ニュートラルは立場が偏らないことで、毎日の変化のなさを言う語ではない。"}, {"text": "ニュートラルな計算で、答えはすぐ出た。", "explanation": "ここは〈単純〉の意味。ニュートラルは立場の偏りを言う語で、計算の易しさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37300, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ニュートラル", "is_correct": true, "explanation": "正解。審判に求められる偏らない態度を表し、応援しない理由に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "審判に陽気であることが求められるとは言わず、文が不自然。"}, {"text": "大胆", "is_correct": false, "explanation": "審判が大胆であるべき理由がなく、文の論理に合わない。"}, {"text": "地味", "is_correct": false, "explanation": "審判が地味でなければならないとは言わず、文脈に合わない。"}], "explanations": {"ニュートラル": "正解。審判に求められる偏らない態度を表し、応援しない理由に合う。", "陽気": "審判に陽気であることが求められるとは言わず、文が不自然。", "大胆": "審判が大胆であるべき理由がなく、文の論理に合わない。", "地味": "審判が地味でなければならないとは言わず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "ニュートラル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ニュートラルな天気が続き、洗濯日和になった。", "explanation": "ここは〈穏やか〉の意味。ニュートラルは立場の偏らなさで、天気の穏やかさには使わない。"}, {"text": "ニュートラルな風が吹いて、窓ガラスが割れた。", "explanation": "ここは〈強さ〉の意味。ニュートラルは立場が偏らないことで、風の強さは表さない。"}, {"text": "ニュートラルな作戦で、試合に勝った。", "explanation": "ここは〈大胆〉の意味。ニュートラルは偏らないことで、作戦の思い切りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37300, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "審判は、どちらのチームにもニュートラルを判断する。", "corrected_sentence": "審判は、どちらのチームにもニュートラルに判断する。", "error_description": "『ニュートラル』は形容動詞なので、連用形『ニュートラルに』で動詞を修飾する。『を』は目的語を示すため、『ニュートラルを判断する』は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ニュートラルな", "is_correct": true, "explanation": "正解。『ニュートラルな言葉で』と名詞を修飾する連体形で、この文に合う。"}, {"text": "ニュートラル", "is_correct": false, "explanation": "基本形のままでは『言葉』を修飾できず、『ニュートラル言葉』となって不自然。"}, {"text": "ニュートラルに", "is_correct": false, "explanation": "連用形は動詞を修飾するため、名詞『言葉』の前には置けず不自然。"}, {"text": "ニュートラルで", "is_correct": false, "explanation": "『ニュートラルで言葉』では名詞を修飾できず、文の構造が崩れる。"}], "correct_form": "ニュートラルな", "base_form": "ニュートラル", "form_label": "連体形", "sentence_index": 1, "explanations": {"ニュートラルな": "正解。『ニュートラルな言葉で』と名詞を修飾する連体形で、この文に合う。", "ニュートラル": "基本形のままでは『言葉』を修飾できず、『ニュートラル言葉』となって不自然。", "ニュートラルに": "連用形は動詞を修飾するため、名詞『言葉』の前には置けず不自然。", "ニュートラルで": "『ニュートラルで言葉』では名詞を修飾できず、文の構造が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37300, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の説明はニュートラルくない。", "corrected_sentence": "彼の説明はニュートラルではない。", "error_description": "『ニュートラル』は形容動詞なので、否定は『ではない』。『くない』は形容詞の活用で、この語には使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ニュートラルな", "is_correct": true, "explanation": "正解。『ニュートラルな気持ち』と名詞を修飾する連体形で、この文に合う。"}, {"text": "ニュートラルだ", "is_correct": false, "explanation": "終止形の『ニュートラルだ』は名詞『気持ち』を直接修飾できず、『ニュートラルだ気持ち』となって不自然。"}, {"text": "ニュートラルなら", "is_correct": false, "explanation": "仮定形の『ニュートラルなら』では名詞『気持ち』を修飾できず、文の構造が崩れる。"}, {"text": "ニュートラルならば", "is_correct": false, "explanation": "仮定形の硬い形『ニュートラルならば』も名詞『気持ち』を修飾できず、文に合わない。"}], "correct_form": "ニュートラルな", "base_form": "ニュートラル", "form_label": "連体形", "sentence_index": 7, "explanations": {"ニュートラルな": "正解。『ニュートラルな気持ち』と名詞を修飾する連体形で、この文に合う。", "ニュートラルだ": "終止形の『ニュートラルだ』は名詞『気持ち』を直接修飾できず、『ニュートラルだ気持ち』となって不自然。", "ニュートラルなら": "仮定形の『ニュートラルなら』では名詞『気持ち』を修飾できず、文の構造が崩れる。", "ニュートラルならば": "仮定形の硬い形『ニュートラルならば』も名詞『気持ち』を修飾できず、文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37302, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「設計に三年かかる」は、設計にかけた時間を表す。"}, {"text": "と", "is_correct": false, "explanation": "「設計と三年かかった」は並列の助詞で、時間の経過を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「設計へ三年かかった」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「設計の三年かかった」は文として不自然。"}], "correct_answer": "に", "explanations": {"に": "「設計に三年かかる」は、設計にかけた時間を表す。", "と": "「設計と三年かかった」は並列の助詞で、時間の経過を表せない。", "へ": "方向を表す助詞で、「設計へ三年かかった」は成り立たない。", "の": "連体修飾の助詞で、「設計の三年かかった」は文として不自然。"}, "error_tags": {"と": "並列", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37302, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「考える」の対象を表す助詞で、「設計を考えてから」が自然。"}, {"text": "に", "is_correct": false, "explanation": "「設計に考えてから」は、考える対象の取り方として不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す助詞で、「設計が考えてから」は設計が考える主体になり意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「設計より考えてから」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「考える」の対象を表す助詞で、「設計を考えてから」が自然。", "に": "「設計に考えてから」は、考える対象の取り方として不自然。", "が": "主語を表す助詞で、「設計が考えてから」は設計が考える主体になり意味が通らない。", "より": "比較の助詞で、「設計より考えてから」は文が成り立たない。"}, "error_tags": {"に": "対象", "が": "主語", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37302, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものをつくるときに、どんな形にするか、どんなふうに動くかを考えること。", "primary_collocate": null, "pronunciation": "せっけい", "ipa": "sekkeː", "syllable_count": 4, "sentences": [{"text": "この家は有名な建築家が設計した。", "target_word": "設計", "complexity_tier": "T3", "furigana": "この家[いえ]は有名[ゆうめい]な建築家[けんちくか]が設計[せっけい]した。", "sentence_source": "generated"}, {"text": "新しい橋の設計に、三年かかった。", "target_word": "設計", "complexity_tier": "T3", "furigana": "新[あたら]しい橋[はし]の設計[せっけい]に、三年[さんねん]かかった。", "sentence_source": "generated"}, {"text": "設計を変えたので、機械が前より静かになった。", "target_word": "設計", "complexity_tier": "T3", "furigana": "設計[せっけい]を変[か]えたので、機械[きかい]が前[まえ]より静[しず]かになった。", "sentence_source": "generated"}, {"text": "兄は自動車会社で、エンジンの設計をしている。", "target_word": "設計", "complexity_tier": "T3", "furigana": "兄[あに]は自動車[じどうしゃ]会社[がいしゃ]で、エンジンの設計[せっけい]をしている。", "sentence_source": "generated"}, {"text": "設計が悪いと、使いやすい道具はできない。", "target_word": "設計", "complexity_tier": "T3", "furigana": "設計[せっけい]が悪[わる]いと、使[つか]いやすい道具[どうぐ]はできない。", "sentence_source": "generated"}, {"text": "学校の図書館を設計する仕事に憧れている。", "target_word": "設計", "complexity_tier": "T4", "furigana": "学校[がっこう]の図書館[としょかん]を設計[せっけい]する仕事[しごと]に憧[あこが]れている。", "sentence_source": "generated"}, {"text": "設計の段階で問題を見つければ、あとで直す費用が少なくてすむ。", "target_word": "設計", "complexity_tier": "T4", "furigana": "設計[せっけい]の段階[だんかい]で問題[もんだい]を見[み]つければ、あとで直[なお]す費用[ひよう]が少[すく]なくてすむ。", "sentence_source": "generated"}, {"text": "先生は「まず設計を考えてから、作り始めましょう」と言った。", "target_word": "設計", "complexity_tier": "T3", "furigana": "先生[せんせい]は「まず設計[せっけい]を考[かんが]えてから、作[つく]り始[はじ]めましょう」と言[い]った。", "sentence_source": "generated"}, {"text": "彼女は椅子の設計で賞をもらった。", "target_word": "設計", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は椅子[いす]の設計[せっけい]で賞[しょう]をもらった。", "sentence_source": "generated"}, {"text": "雨に強い設計だから、台風の日でも安心だ。", "target_word": "設計", "complexity_tier": "T3", "furigana": "雨[あめ]に強[つよ]い設計[せっけい]だから、台風[たいふう]の日[ひ]でも安心[あんしん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "設計", "label": "基本形"}, {"form": "設計する", "label": "する動詞・辞書形"}, {"form": "設計した", "label": "過去形"}, {"form": "設計され", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "design: planning the form and function of a thing (building, machine, tool) before making it", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481ed36a-14ce-4134-9f49-87c6b4fc588f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37302, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "設計", "is_correct": true, "explanation": "建築家が家の形や構造を考えて図面にする、という意味で文に合う。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まることで、建築家が行う動作としては成り立たない。"}, {"text": "解凍", "is_correct": false, "explanation": "凍った食品をもとに戻すことで、建築家の行為としては意味が通らない。"}, {"text": "噴火", "is_correct": false, "explanation": "火山が噴き出すことで、人の行為には使わない。"}], "explanations": {"設計": "建築家が家の形や構造を考えて図面にする、という意味で文に合う。", "停電": "電気が止まることで、建築家が行う動作としては成り立たない。", "解凍": "凍った食品をもとに戻すことで、建築家の行為としては意味が通らない。", "噴火": "火山が噴き出すことで、人の行為には使わない。"}, "sentence_index": 0, "correct_answer": "設計"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の天気の設計を、予報士が発表した。", "explanation": "ここは〈予報〉の意味。天気の見通しは予報と言い、形や動きを考える設計とは言わない。"}, {"text": "今日の夕食の設計を、家族と考えた。", "explanation": "ここは〈献立〉の意味。食事の内容を決めることは設計とは言わない。"}, {"text": "試合の得点を、審判が設計した。", "explanation": "ここは〈計算〉の意味。点数を数えて示すことは設計とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37302, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "設計", "is_correct": true, "explanation": "建物や道具の構造を考える段階を指し、文に合う。"}, {"text": "日焼け", "is_correct": false, "explanation": "肌が日光で焦げること。「日焼けの段階」では意味が通らない。"}, {"text": "大雪", "is_correct": false, "explanation": "大量に降る雪のことで、作業の段階を表す語としては合わない。"}, {"text": "雷鳴", "is_correct": false, "explanation": "雷の鳴る音のことで、問題を見つける段階とは結びつかない。"}], "explanations": {"設計": "建物や道具の構造を考える段階を指し、文に合う。", "日焼け": "肌が日光で焦げること。「日焼けの段階」では意味が通らない。", "大雪": "大量に降る雪のことで、作業の段階を表す語としては合わない。", "雷鳴": "雷の鳴る音のことで、問題を見つける段階とは結びつかない。"}, "sentence_index": 6, "correct_answer": "設計"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友だちの手紙に設計を書いた。", "explanation": "ここは〈返事〉の意味。相手への答えを書くことは設計とは言わない。"}, {"text": "結婚式の乾杯の設計を、友だちに頼んだ。", "explanation": "ここは〈挨拶〉の意味。乾杯のスピーチを述べることは設計とは言わない。"}, {"text": "子どもの絵を設計して、壁に飾った。", "explanation": "ここは〈描く〉の意味。絵を描くことは設計とは言わず、形や構造を考えることにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37302, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この家の設計を、半年かかった。", "corrected_sentence": "この家の設計に、半年かかった。", "error_description": "時間や手間がかかることを表すには〈に〉を使う。「設計を」は誤りで、正しくは「設計に半年かかった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37302, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの建物を設計ている建築家は、有名だ。", "corrected_sentence": "あの建物を設計している建築家は、有名だ。", "error_description": "「設計」は名詞なので、動詞として使うには「する」が必要。「設計ている」は誤りで、正しくは「設計している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
