INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37304, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "いくつかのものを一つにまとめること。", "primary_collocate": null, "pronunciation": "とうごう", "ipa": "toːɡoː", "syllable_count": 4, "sentences": [{"text": "三つの小さな学校が統合して、新しい学校になった。", "target_word": "統合", "complexity_tier": "T3", "furigana": "三[みっ]つの小[ちい]さな学校[がっこう]が統合[とうごう]して、新[あたら]しい学校[がっこう]になった。", "sentence_source": "generated"}, {"text": "別々だった意見を統合するのは、簡単ではない。", "target_word": "統合", "complexity_tier": "T3", "furigana": "別々[べつべつ]だった意見[いけん]を統合[とうごう]するのは、簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "会社は二つの部署を統合することに決めた。", "target_word": "統合", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は二[ふた]つの部署[ぶしょ]を統合[とうごう]することに決[き]めた。", "sentence_source": "generated"}, {"text": "古い資料を統合して、一冊の本にまとめた。", "target_word": "統合", "complexity_tier": "T3", "furigana": "古[ふる]い資料[しりょう]を統合[とうごう]して、一冊[いっさつ]の本[ほん]にまとめた。", "sentence_source": "generated"}, {"text": "町の図書館が統合され、大きな図書館が一つできた。", "target_word": "統合", "complexity_tier": "T3", "furigana": "町[まち]の図書館[としょかん]が統合[とうごう]され、大[おお]きな図書館[としょかん]が一[ひと]つできた。", "sentence_source": "generated"}, {"text": "統合の話が出ると、社員たちは不安になった。", "target_word": "統合", "complexity_tier": "T3", "furigana": "統合[とうごう]の話[はなし]が出[で]ると、社員[しゃいん]たちは不安[ふあん]になった。", "sentence_source": "generated"}, {"text": "複数のアプリを一つに統合すれば、使うのが楽になる。", "target_word": "統合", "complexity_tier": "T4", "furigana": "複数[ふくすう]のアプリを一[ひと]つに統合[とうごう]すれば、使[つか]うのが楽[らく]になる。", "sentence_source": "generated"}, {"text": "統合したあとも、昔の名前を残すことにした。", "target_word": "統合", "complexity_tier": "T3", "furigana": "統合[とうごう]したあとも、昔[むかし]の名前[なまえ]を残[のこ]すことにした。", "sentence_source": "generated"}, {"text": "近所の小さな店が二つ統合して、広い店ができた。", "target_word": "統合", "complexity_tier": "T3", "furigana": "近所[きんじょ]の小[ちい]さな店[みせ]が二[ふた]つ統合[とうごう]して、広[ひろ]い店[みせ]ができた。", "sentence_source": "generated"}, {"text": "班ごとの案を統合し、全員で一つの計画を作った。", "target_word": "統合", "complexity_tier": "T4", "furigana": "班[はん]ごとの案[あん]を統合[とうごう]し、全員[ぜんいん]で一[ひと]つの計画[けいかく]を作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "統合", "label": "基本形"}, {"form": "統合する", "label": "する動詞・辞書形"}, {"form": "統合した", "label": "過去形"}, {"form": "統合され", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "tougou: gathering several things (schools, opinions, shops, documents) into one", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481ed36a-14ce-4134-9f49-87c6b4fc588f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37304, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "統合", "is_correct": true, "explanation": "いくつかの学校を一つにまとめる意味で、文に合う。"}, {"text": "点火", "is_correct": false, "explanation": "火をつけることで、学校の再編を表す文脈には合わない。"}, {"text": "激突", "is_correct": false, "explanation": "強くぶつかることで、学校が新しくなる文脈とは合わない。"}, {"text": "誤解", "is_correct": false, "explanation": "思い違いのことで、学校が一つになるという文の意味を表せない。"}], "explanations": {"統合": "いくつかの学校を一つにまとめる意味で、文に合う。", "点火": "火をつけることで、学校の再編を表す文脈には合わない。", "激突": "強くぶつかることで、学校が新しくなる文脈とは合わない。", "誤解": "思い違いのことで、学校が一つになるという文の意味を表せない。"}, "sentence_index": 0, "correct_answer": "統合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二種類の薬を統合して、一緒に飲んだ。", "explanation": "ここは〈併用〉の意味。統合は一つにまとめることで、二つを同時に使う意味ではない。"}, {"text": "車のブレーキを統合して、異常がないか確かめた。", "explanation": "ここは〈点検〉の意味。ブレーキの状態を調べて確かめることは統合とは言わない。"}, {"text": "三つの材料を体に統合して、元気になった。", "explanation": "ここは〈吸収〉の意味。食べ物を体に取り入れることは統合とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37304, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "統合", "is_correct": true, "explanation": "複数のアプリを一つにまとめる意味で、文に合う。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつけることで、アプリをまとめる文脈には合わない。"}, {"text": "落雷", "is_correct": false, "explanation": "雷が落ちることで、アプリを一つにする意味にはならない。"}, {"text": "誤嚥", "is_correct": false, "explanation": "食べ物が気管に入ることで、アプリを扱う文とは無関係。"}], "explanations": {"統合": "複数のアプリを一つにまとめる意味で、文に合う。", "点灯": "明かりをつけることで、アプリをまとめる文脈には合わない。", "落雷": "雷が落ちることで、アプリを一つにする意味にはならない。", "誤嚥": "食べ物が気管に入ることで、アプリを扱う文とは無関係。"}, "sentence_index": 6, "correct_answer": "統合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部活の疲れを統合して、ぐっすり眠った。", "explanation": "ここは〈回復〉の意味。疲れを取ることは統合とは言わない。"}, {"text": "隊長は部下を統合して、山頂を目指した。", "explanation": "ここは〈統率〉の意味。人を率いて動かすことは統合とは言わない。"}, {"text": "壊れた水道管を統合して、水が出るようにした。", "explanation": "ここは〈修理〉の意味。壊れたものを直すことは統合とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37304, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三つの村の統合を、昨年行われた。", "corrected_sentence": "三つの村の統合が、昨年行われた。", "error_description": "「行われる」は主語に〈が〉を取る。「統合を」は誤りで、正しくは「統合が行われた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37304, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班ごとの案を統合する、全員で一つの計画を作った。", "corrected_sentence": "班ごとの案を統合して、全員で一つの計画を作った。", "error_description": "次の節へつなぐときは「統合して」と連用形にする。「統合する、」は文が続かず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37306, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「向いている」の主語を示す「が」。学ぶアプローチが適していることを表す。"}, {"text": "を", "is_correct": false, "explanation": "「向いている」は目的語を取らないので、「を」では文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、「向いている」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、「向いている」の主語として不自然。"}], "correct_answer": "が", "explanations": {"が": "「向いている」の主語を示す「が」。学ぶアプローチが適していることを表す。", "を": "「向いている」は目的語を取らないので、「を」では文が成立しない。", "で": "「で」は手段や場所を示し、「向いている」の主語にはならない。", "と": "「と」は並列や相手を示し、「向いている」の主語として不自然。"}, "error_tags": {"を": "対象", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37306, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37306, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることに近づく方法や考え方", "primary_collocate": null, "pronunciation": "あぷろーち", "ipa": "apɯɾoːt͡ɕi", "syllable_count": 5, "sentences": [{"text": "この課題に対するアプローチを変えたら、作業がずっと楽になった。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "この課題(かだい)に対(たい)するアプローチを変(か)えたら、作業(さぎょう)がずっと楽(らく)になった。", "sentence_source": "generated"}, {"text": "初心者には、まず基本から学ぶアプローチが向いている。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "初心者(しょしんしゃ)には、まず基本(きほん)から学(まな)ぶアプローチが向(む)いている。", "sentence_source": "generated"}, {"text": "チームで意見が分かれたので、二つのアプローチを比べてみた。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "チームで意見(いけん)が分(わ)かれたので、二(ふた)つのアプローチを比(くら)べてみた。", "sentence_source": "generated"}, {"text": "新しいアプローチを取り入れて、会社の売り上げが伸びた。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "新(あたら)しいアプローチを取(と)り入(い)れて、会社(かいしゃ)の売(う)り上(あ)げが伸(の)びた。", "sentence_source": "generated"}, {"text": "彼のアプローチは理論中心だが、私のアプローチは実践中心だ。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "彼(かれ)のアプローチは理論(りろん)中心(ちゅうしん)だが、私(わたし)のアプローチは実践(じっせん)中心(ちゅうしん)だ。", "sentence_source": "generated"}, {"text": "健康づくりには、食事と睡眠の両方からアプローチすることが大切だ。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "健康(けんこう)づくりには、食事(しょくじ)と睡眠(すいみん)の両方(りょうほう)からアプローチすることが大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "問題の原因が分からないときは、視点を変えたアプローチが役に立つ。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "問題(もんだい)の原因(げんいん)が分(わ)からないときは、視点(してん)を変(か)えたアプローチが役(やく)に立(た)つ。", "sentence_source": "generated"}, {"text": "外国語の学習には、読むことから始めるアプローチもある。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "外国語(がいこくご)の学習(がくしゅう)には、読(よ)むことから始(はじ)めるアプローチもある。", "sentence_source": "generated"}, {"text": "この本は、歴史を地理の面から見る面白いアプローチで書かれている。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "この本(ほん)は、歴史(れきし)を地理(ちり)の面(めん)から見(み)る面白(おもしろ)いアプローチで書(か)かれている。", "sentence_source": "generated"}, {"text": "同じ目標でも、アプローチが違えば必要な時間も変わる。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "同(おな)じ目標(もくひょう)でも、アプローチが違(ちが)えば必要(ひつよう)な時間(じかん)も変(か)わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アプローチする", "label": "dictionary form (suru verb)"}, {"form": "アプローチした", "label": "past"}, {"form": "アプローチして", "label": "te-form"}], "register": "neutral written", "sense_fingerprint": "物事に近づくための方法・考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '448d110d-502d-4765-a516-917bc7c1e24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37306, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アプローチ", "is_correct": true, "explanation": "ここは課題への取り組み方を表す語。「対するアプローチを変えたら」の対象として文が成り立つ。"}, {"text": "偶然", "is_correct": false, "explanation": "起きる出来事であり、取り組み方を変える対象にはならない。"}, {"text": "歓声", "is_correct": false, "explanation": "人が上げる声の反応で、課題への取り組みを変える対象とは言えない。"}, {"text": "寝息", "is_correct": false, "explanation": "眠る人の呼吸であり、作業の進め方を変える対象にはならない。"}], "explanations": {"アプローチ": "ここは課題への取り組み方を表す語。「対するアプローチを変えたら」の対象として文が成り立つ。", "偶然": "起きる出来事であり、取り組み方を変える対象にはならない。", "歓声": "人が上げる声の反応で、課題への取り組みを変える対象とは言えない。", "寝息": "眠る人の呼吸であり、作業の進め方を変える対象にはならない。"}, "sentence_index": 0, "correct_answer": "アプローチ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は背筋を伸ばすアプローチを保つよう、注意された。", "explanation": "ここは〈姿勢〉（体の構え）の意味。アプローチは取り組み方なので、身体の構えには合わない。"}, {"text": "このクッキーは、アプローチが多すぎて、一度に食べきれない。", "explanation": "ここは〈数量〉（個数）の意味。アプローチは方法を指すので、クッキーの個数には合わない。"}, {"text": "彼は歴史のアプローチが乏しく、年号を一つも言えなかった。", "explanation": "ここは〈知識〉の意味。アプローチは取り組み方を指すので、知識の乏しさには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37306, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アプローチ", "is_correct": true, "explanation": "ここは取り組み方を表す語。視点を変えた方法が役に立つ、という主語として合う。"}, {"text": "悲鳴", "is_correct": false, "explanation": "悲鳴は声の反応で、「視点を変えた悲鳴が役に立つ」は意味をなさないので入らない。"}, {"text": "視点", "is_correct": false, "explanation": "ものの見方そのものを指す語で、「視点を変えた視点」と重なり意味をなさない。"}, {"text": "温度", "is_correct": false, "explanation": "数値で表される状態であり、視点の文脈には合わない。"}], "explanations": {"アプローチ": "ここは取り組み方を表す語。視点を変えた方法が役に立つ、という主語として合う。", "悲鳴": "悲鳴は声の反応で、「視点を変えた悲鳴が役に立つ」は意味をなさないので入らない。", "視点": "ものの見方そのものを指す語で、「視点を変えた視点」と重なり意味をなさない。", "温度": "数値で表される状態であり、視点の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "アプローチ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この楽器は、アプローチが澄んでいて、音が美しい。", "explanation": "ここは〈音色〉（音の響き）の意味。アプローチは方法を指すので、楽器の響きには合わない。"}, {"text": "彼はアプローチがあり、毎朝十キロ走れる。", "explanation": "ここは〈体力〉の意味。アプローチは方法を指すので、体の持久力には合わない。"}, {"text": "彼女はアプローチが鮮明で、昔の出来事を正確に話せる。", "explanation": "ここは〈記憶〉の意味。アプローチは取り組み方なので、思い出す力には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37306, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この課題に対するアプローチが変えたら、作業が楽に進んだ。", "corrected_sentence": "この課題に対するアプローチを変えたら、作業が楽に進んだ。", "error_description": "「変える」は「を」で目的語を取る他動詞。「アプローチが変えたら」は助詞の誤りで、「アプローチを変えたら」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37306, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は新しいアプローチを試すして、成果を上げた。", "corrected_sentence": "彼は新しいアプローチを試して、成果を上げた。", "error_description": "「試す」のテ形は「試して」。「試すして」は活用の誤りで、「試して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
