INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37307, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "問題や課題に取り組む方法や態度。特に、ある目標を達成するための手段や考え方。", "primary_collocate": null, "pronunciation": "あぷろーち", "ipa": "apɯɾoːtɕi", "syllable_count": 5, "sentences": [{"text": "まず、現場や鑑識ラボにおいて、肉眼では捉えられぬ潜在指紋を、シアノアクリレート法や光学的手法といったアプローチにより顕在化させる。", "target_word": "アプローチ", "complexity_tier": "T5", "furigana": "まず、現場(げんば)や鑑識(かんしき)ラボにおいて、肉眼(にくがん)では捉(とら)えられぬ潜在指紋(せんざいしもん)を、シアノアクリレート法(ほう)や光学的(こうがくてき)手法(しゅほう)といったアプローチにより顕在化(けんざいか)させる。", "sentence_source": "mined"}, {"text": "子どもの学習意欲を高めるには、叱るよりほめるアプローチのほうが効果的だ。", "target_word": "アプローチ", "complexity_tier": "T4", "furigana": "子(こ)どもの学習意欲(がくしゅういよく)を高(たか)めるには、叱(しか)るよりほめるアプローチのほうが効果的(こうかてき)だ。", "sentence_source": "generated"}, {"text": "この問題には、数学と物理学の両方からアプローチしてみよう。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "この問題(もんだい)には、数学(すうがく)と物理学(ぶつりがく)の両方(りょうほう)からアプローチしてみよう。", "sentence_source": "generated"}, {"text": "新しい商品を売るために、会社は若者向けの広告という新たなアプローチを試した。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "新(あたら)しい商品(しょうひん)を売(う)るために、会社(かいしゃ)は若者向(わかものむ)けの広告(こうこく)という新(あら)たなアプローチを試(ため)した。", "sentence_source": "generated"}, {"text": "医師は薬だけに頼らず、生活習慣を見直すアプローチで患者を治療した。", "target_word": "アプローチ", "complexity_tier": "T4", "furigana": "医師(いし)は薬(くすり)だけに頼(たよ)らず、生活習慣(せいかつしゅうかん)を見直(みなお)すアプローチで患者(かんじゃ)を治療(ちりょう)した。", "sentence_source": "generated"}, {"text": "二人は同じ課題に対して全く違うアプローチを取ったが、結果は同じだった。", "target_word": "アプローチ", "complexity_tier": "T3", "furigana": "二人(ふたり)は同(おな)じ課題(かだい)に対(たい)して全(まった)く違(ちが)うアプローチを取(と)ったが、結果(けっか)は同(おな)じだった。", "sentence_source": "generated"}, {"text": "環境問題の解決には、個人の努力だけでなく、社会全体でのアプローチが必要だ。", "target_word": "アプローチ", "complexity_tier": "T4", "furigana": "環境問題(かんきょうもんだい)の解決(かいけつ)には、個人(こじん)の努力(どりょく)だけでなく、社会全体(しゃかいぜんたい)でのアプローチが必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "彼の教え方は、まず例を見せてから説明するという独特なアプローチだった。", "target_word": "アプローチ", "complexity_tier": "T4", "furigana": "彼(かれ)の教(おし)え方(かた)は、まず例(れい)を見(み)せてから説明(せつめい)するという独特(どくとく)なアプローチだった。", "sentence_source": "generated"}, {"text": "会議では、各部署が異なるアプローチを提案し、議論が長引いた。", "target_word": "アプローチ", "complexity_tier": "T4", "furigana": "会議(かいぎ)では、各部署(かくぶしょ)が異(こと)なるアプローチを提案(ていあん)し、議論(ぎろん)が長引(ながび)いた。", "sentence_source": "generated"}, {"text": "研究者は従来とは違うアプローチで、病気の原因を調べることにした。", "target_word": "アプローチ", "complexity_tier": "T4", "furigana": "研究者(けんきゅうしゃ)は従来(じゅうらい)とは違(ちが)うアプローチで、病気(びょうき)の原因(げんいん)を調(しら)べることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アプローチ", "label": "基本形"}, {"form": "アプローチの", "label": "連体修飾(の)"}, {"form": "アプローチを", "label": "を格"}], "register": "neutral", "sense_fingerprint": "課題に取り組む方法・手段・考え方を表す外来語の名詞(approach)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: シアノアクリレート (Zipf 1.04)']::text[], '08e7e9f6-0f05-455b-afc5-ee87762d7379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37307, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アプローチ", "is_correct": true, "explanation": "問題を顕在化させる取り組み方を表し、「手法といったアプローチにより」と手段の列挙に合う。"}, {"text": "指紋", "is_correct": false, "explanation": "顕在化させる対象であって取り組みの方法ではないので、「指紋といったにより」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態を表す語で、顕在化の方法ではない。「天気といったにより」は文が成り立たない。"}, {"text": "被害者", "is_correct": false, "explanation": "事件の当事者を表す語で、手段を表さないので文に入らない。"}], "explanations": {"アプローチ": "問題を顕在化させる取り組み方を表し、「手法といったアプローチにより」と手段の列挙に合う。", "指紋": "顕在化させる対象であって取り組みの方法ではないので、「指紋といったにより」は意味が通らない。", "天気": "気象の状態を表す語で、顕在化の方法ではない。「天気といったにより」は文が成り立たない。", "被害者": "事件の当事者を表す語で、手段を表さないので文に入らない。"}, "sentence_index": 0, "correct_answer": "アプローチ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風が本州にアプローチしている。", "explanation": "ここは〈接近〉の場面。台風が近づく動きには接近を使い、取り組み方を表すアプローチは合わない。"}, {"text": "今朝はアプローチが十度を下回るほど冷え込んだ。", "explanation": "ここは〈気温〉の場面。アプローチは取り組み方の語で、気温が下がるという意味には合わないので、この言葉はこうは使わない。"}, {"text": "三日間休んで、アプローチが回復した。", "explanation": "ここは〈体力〉の場面。アプローチは取り組み方の語で、体力が戻るという意味には合わないので、この言葉はこうは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37307, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アプローチ", "is_correct": true, "explanation": "社会全体での取り組み方を表し、「社会全体でのアプローチが必要だ」と文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態を表す語で、取り組みの方法ではないので「社会全体での天気が必要だ」は成り立たない。"}, {"text": "電卓", "is_correct": false, "explanation": "計算器具で、社会全体での取り組みを表さない。文の意味に合わない。"}, {"text": "落書き", "is_correct": false, "explanation": "書かれた絵や文字を指し、解決の方法にはならない。文に合わない。"}], "explanations": {"アプローチ": "社会全体での取り組み方を表し、「社会全体でのアプローチが必要だ」と文に合う。", "天気": "気象の状態を表す語で、取り組みの方法ではないので「社会全体での天気が必要だ」は成り立たない。", "電卓": "計算器具で、社会全体での取り組みを表さない。文の意味に合わない。", "落書き": "書かれた絵や文字を指し、解決の方法にはならない。文に合わない。"}, "sentence_index": 6, "correct_answer": "アプローチ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この牛乳は夏の間に、アプローチが増えた。", "explanation": "ここは〈増殖〉の場面。アプローチは取り組み方の語で、細菌が数を増やす意味には合わないので、この言葉はこうは使わない。"}, {"text": "この機械は先週からアプローチが故障している。", "explanation": "ここは〈不具合〉の場面。アプローチは取り組み方の語で、機械が壊れている状態の意味には合わないので、この言葉はこうは使わない。"}, {"text": "朝から頭痛がひどく、アプローチが治まらない。", "explanation": "ここは〈体調〉の場面。アプローチは取り組み方の語で、体の不調が和らぐという意味には合わないので、この言葉はこうは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37307, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この研究では、新しいアプローチに試した。", "corrected_sentence": "この研究では、新しいアプローチを試した。", "error_description": "誤りは「に」。「試す」は「〜を試す」と目的語に「を」を取るので、アプローチの後は「を」。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37307, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は従来とは違うアプローチを選ぶで、病気の原因を調べた。", "corrected_sentence": "研究者は従来とは違うアプローチを選んで、病気の原因を調べた。", "error_description": "誤りは「選ぶで」。「選ぶ」のて形は撥音便で「選んで」になるので、「ぶで」を「んで」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37310, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。この位置に合う助詞。"}, {"text": "に", "is_correct": false, "explanation": "「に」はここでは文法的に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」はここでは文法的に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」はここでは文法的に合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。この位置に合う助詞。", "に": "「に」はここでは文法的に合わない。", "で": "「で」はここでは文法的に合わない。", "と": "「と」はここでは文法的に合わない。"}, "error_tags": {"に": "wrong_particle", "で": "wrong_particle", "と": "wrong_particle"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '055b2145-1f90-4d76-a44b-cd27e88baf3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37310, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。この位置に合う助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」はここでは文法的に合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」はここでは文法的に合わない。"}, {"text": "まで", "is_correct": false, "explanation": "「まで」はここでは文法的に合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。この位置に合う助詞。", "へ": "「へ」はここでは文法的に合わない。", "から": "「から」はここでは文法的に合わない。", "まで": "「まで」はここでは文法的に合わない。"}, "error_tags": {"へ": "wrong_particle", "から": "wrong_particle", "まで": "wrong_particle"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '055b2145-1f90-4d76-a44b-cd27e88baf3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37310, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や心に、色や感じがつく。", "primary_collocate": null, "pronunciation": "おびる", "ipa": "obiɾɯ", "syllable_count": 3, "sentences": [{"text": "空が赤みを帯びる。", "target_word": "帯びる", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "月が青みを帯びる。", "target_word": "帯びる", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "葉が黄色みを帯びました。", "target_word": "帯びました", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光は少し青みを帯びます。", "target_word": "帯びます", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨のあと、道が湿り気を帯びている。", "target_word": "帯びている", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "悲しみを帯びた声で彼は話した。", "target_word": "帯びた", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夕方になると、空は赤みを帯びて美しくなる。", "target_word": "帯びて", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "もし光が青みを帯びていたら、夜明けだと思っただろう。", "target_word": "帯びて", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "窓から差し込む光が、夕暮れとともに少しずつ金色の暖かみを帯びていった。", "target_word": "帯びて", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "古い木の机は、長い年月のうちに深い茶色の艶を帯びるようになった。", "target_word": "帯びる", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "帯びた", "label": "活用"}, {"form": "帯びて", "label": "活用"}, {"form": "帯びない", "label": "活用"}, {"form": "帯びている", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 物や心に色や感じがつく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b16e14-36e1-4b2f-ae25-fea49fdf019b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
