INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37312, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表す「で」。「アクションで気持ちを見せた」と正しく続く。"}, {"text": "を", "is_correct": false, "explanation": "「気持ちを」と目的語がすでにあるため、「を」を重ねると文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「アクションに気持ちを見せた」は、相手や方向を示す「に」の使い方として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、「アクションへ見せた」のように続けると意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "手段を表す「で」。「アクションで気持ちを見せた」と正しく続く。", "を": "「気持ちを」と目的語がすでにあるため、「を」を重ねると文が成り立たない。", "に": "「アクションに気持ちを見せた」は、相手や方向を示す「に」の使い方として不自然。", "へ": "方向を示す「へ」は、「アクションへ見せた」のように続けると意味が通らない。"}, "error_tags": {"を": "対象（目的語）", "に": "相手・方向", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37312, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "「何のアクションもない」の「も」で、「何もない」という全面的な否定を作る。"}, {"text": "を", "is_correct": false, "explanation": "「ない」の前に目的語は立たないので、「を」は続かない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や対象を示すため、「何のアクションにないまま」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を示すため、「何のアクションとないまま」は文として通らない。"}], "correct_answer": "も", "explanations": {"も": "「何のアクションもない」の「も」で、「何もない」という全面的な否定を作る。", "を": "「ない」の前に目的語は立たないので、「を」は続かない。", "に": "「に」は方向や対象を示すため、「何のアクションにないまま」は成り立たない。", "と": "「と」は相手や共同を示すため、「何のアクションとないまま」は文として通らない。"}, "error_tags": {"を": "対象（目的語）", "に": "方向・結果", "と": "相手・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37312, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が何かをすることを言います。", "primary_collocate": null, "pronunciation": "あくしょん", "ipa": "akɯɕoɴ", "syllable_count": 4, "sentences": [{"text": "問題に気づいたら、すぐにアクションを起こしてください。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "問題[もんだい]に気[き]づいたら、すぐにアクションを起[お]こしてください。", "sentence_source": "generated"}, {"text": "言葉より先に、アクションで気持ちを見せた。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "言葉[ことば]より先[さき]に、アクションで気持[きも]ちを見[み]せた。", "sentence_source": "generated"}, {"text": "彼のアクションは早くて、みんなが助かった。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "彼[かれ]のアクションは早[はや]くて、みんなが助[たす]かった。", "sentence_source": "generated"}, {"text": "話すだけでなく、何かアクションが必要だ。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "話[はな]すだけでなく、何[なに]かアクションが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "新しい店の件で、社長がやっとアクションを起こした。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]の件[けん]で、社長[しゃちょう]がやっとアクションを起[お]こした。", "sentence_source": "generated"}, {"text": "小さなアクションでも、続ければ町は変わる。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "小[ちい]さなアクションでも、続[つづ]ければ町[まち]は変[か]わる。", "sentence_source": "generated"}, {"text": "彼女のアクションを見て、周りの人も動き出した。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のアクションを見[み]て、周[まわ]りの人[ひと]も動[うご]き出[だ]した。", "sentence_source": "generated"}, {"text": "何のアクションもないまま、一週間がたった。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "何[なん]のアクションもないまま、一週間[いっしゅうかん]がたった。", "sentence_source": "generated"}, {"text": "意見を言うだけで、実際のアクションを取らない人が多い。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "意見[いけん]を言[い]うだけで、実際[じっさい]のアクションを取[と]らない人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "反応が遅く、次のアクションを決められなかった。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "反応[はんのう]が遅[おそ]く、次[つぎ]のアクションを決[き]められなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アクション", "label": "基本形"}], "register": "中立", "sense_fingerprint": "問題や状況に対して人が起こす行動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37312, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アクション", "is_correct": true, "explanation": "「起こす」と結びつく、人が起こす行動の意味で、ここに正しく入る。"}, {"text": "準備", "is_correct": false, "explanation": "「準備を起こす」は成り立たず、「すぐに準備を起こして」は不自然。"}, {"text": "休憩", "is_correct": false, "explanation": "「休憩を起こす」とは言わないので、文として合わない。"}, {"text": "返信", "is_correct": false, "explanation": "「返信を起こす」とは言わないので、この空欄には入らない。"}], "explanations": {"アクション": "「起こす」と結びつく、人が起こす行動の意味で、ここに正しく入る。", "準備": "「準備を起こす」は成り立たず、「すぐに準備を起こして」は不自然。", "休憩": "「休憩を起こす」とは言わないので、文として合わない。", "返信": "「返信を起こす」とは言わないので、この空欄には入らない。"}, "sentence_index": 0, "correct_answer": "アクション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は、アクションが広い。", "explanation": "ここは〈面積〉の意味。部屋の広さは面積で言い、人の行動を指すアクションには広いとは言わない。"}, {"text": "薬を飲んだあと、体に強いアクションが出た。", "explanation": "ここは〈反応〉の意味。体に起きる変化は反応と言い、人が起こす行動としてのアクションとは言わない。"}, {"text": "夕食のあと、アクションを片付けた。", "explanation": "ここは〈食器〉の意味。片付けるのは食器で、アクションは片付けるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37312, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アクション", "is_correct": true, "explanation": "「彼女のアクションを見て」の対象として、人の動きを指す語が入る。"}, {"text": "足音", "is_correct": false, "explanation": "足音は聞くもので、「彼女の足音を見て」は不自然。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は見るものではないので、「寝息を見て」は成り立たない。"}, {"text": "鼓動", "is_correct": false, "explanation": "鼓動は感じるもので、「鼓動を見て」とは言わない。"}], "explanations": {"アクション": "「彼女のアクションを見て」の対象として、人の動きを指す語が入る。", "足音": "足音は聞くもので、「彼女の足音を見て」は不自然。", "寝息": "寝息は見るものではないので、「寝息を見て」は成り立たない。", "鼓動": "鼓動は感じるもので、「鼓動を見て」とは言わない。"}, "sentence_index": 6, "correct_answer": "アクション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は、駅からのアクションがいい。", "explanation": "ここは〈アクセス〉の意味。交通の便の良さを言う語で、動きを表すアクションとは言わない。"}, {"text": "先生の質問に、生徒がアクションを書いた。", "explanation": "ここは〈答え〉の意味。質問への答えは紙に書くもので、アクションを書くとは言わない。"}, {"text": "洗濯物の代わりに、アクションをベランダに干した。", "explanation": "ここは〈洗濯物〉の意味。ベランダに干すのは洗濯物で、アクションは干せるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37312, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その会社は、クレームに対してすぐアクションに取った。", "corrected_sentence": "その会社は、クレームに対してすぐアクションを取った。", "error_description": "「取る」は目的語に「を」を使う。ここの「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37312, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい計画の、最初のアクションを何ですか。", "corrected_sentence": "新しい計画の、最初のアクションは何ですか。", "error_description": "「〜は何ですか」の主題には「は」を使う。ここの「を」は誤りで、正しくは「は」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37313, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「アクションをつける」の目的語を示す「を」。「アクションをつけた」と正しく続く。"}, {"text": "が", "is_correct": false, "explanation": "「つける」は目的語を取るので、「アクションがつけた」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すため、「アクションでつけた」は目的語を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を示すため、「アクションとつけた」は文として通らない。"}], "correct_answer": "を", "explanations": {"を": "「アクションをつける」の目的語を示す「を」。「アクションをつけた」と正しく続く。", "が": "「つける」は目的語を取るので、「アクションがつけた」は成り立たない。", "で": "「で」は手段を示すため、「アクションでつけた」は目的語を示せず不自然。", "と": "「と」は相手や共同を示すため、「アクションとつけた」は文として通らない。"}, "error_tags": {"が": "主語（主格）", "で": "手段・方法", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37313, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見本のアクションを見せた」の目的語を示す「を」。正しく続く。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を示すため、「見本のアクションとゆっくり見せた」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「アクションへ見せた」は目的語の役割を果たせない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は修飾や所属を示すため、「アクションのゆっくり見せた」は文の構造が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「見本のアクションを見せた」の目的語を示す「を」。正しく続く。", "と": "「と」は相手や共同を示すため、「見本のアクションとゆっくり見せた」は意味が通らない。", "へ": "「へ」は方向を示すため、「アクションへ見せた」は目的語の役割を果たせない。", "の": "「の」は修飾や所属を示すため、「アクションのゆっくり見せた」は文の構造が崩れる。"}, "error_tags": {"と": "相手・共同", "へ": "方向", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37313, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "行動や動作のこと。人や動物が体で行う動きを指します。", "primary_collocate": null, "pronunciation": "あくしょん", "ipa": "akɯɕoɴ", "syllable_count": 4, "sentences": [{"text": "子どもの大きなアクションに、みんなが笑った。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "子[こ]どもの大[おお]きなアクションに、みんなが笑[わら]った。", "sentence_source": "generated"}, {"text": "歌手は、歌に合わせてアクションをつけた。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "歌手[かしゅ]は、歌[うた]に合[あ]わせてアクションをつけた。", "sentence_source": "generated"}, {"text": "この絵本は、動物のアクションがかわいい。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "この絵本[えほん]は、動物[どうぶつ]のアクションがかわいい。", "sentence_source": "generated"}, {"text": "彼女のアクションは大きくて、遠くからもよく分かる。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のアクションは大[おお]きくて、遠[とお]くからもよく分[わ]かる。", "sentence_source": "generated"}, {"text": "先生は、アクションを交えて説明してくれた。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "先生[せんせい]は、アクションを交[まじ]えて説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "投げられたボールを追う犬の、元気なアクションを見た。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "投[な]げられたボールを追[お]う犬[いぬ]の、元気[げんき]なアクションを見[み]た。", "sentence_source": "generated"}, {"text": "舞台では、小さなアクションも客席から見える。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "舞台[ぶたい]では、小[ちい]さなアクションも客席[きゃくせき]から見[み]える。", "sentence_source": "generated"}, {"text": "ダンスの先生が、見本のアクションをゆっくり見せた。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "ダンスの先生[せんせい]が、見本[みほん]のアクションをゆっくり見[み]せた。", "sentence_source": "generated"}, {"text": "彼のアクションが面白くて、写真を撮った。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "彼[かれ]のアクションが面白[おもしろ]くて、写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "この動画は、猫のかわいいアクションがたくさん映っている。", "target_word": "アクション", "complexity_tier": "T3", "furigana": "この動画[どうが]は、猫[ねこ]のかわいいアクションがたくさん映[うつ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アクション", "label": "基本形"}], "register": "口語", "sense_fingerprint": "体の動きや身ぶりとしての動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37313, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アクション", "is_correct": true, "explanation": "子どもの体の動きを指す語で、「大きなアクションに笑った」と自然に続く。"}, {"text": "計算", "is_correct": false, "explanation": "計算は体の動きではないので、「大きな計算に笑った」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は体で表すものではないので、「大きな天気に笑った」は文として合わない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は動きではないので、「大きな地図に笑った」は成り立たない。"}], "explanations": {"アクション": "子どもの体の動きを指す語で、「大きなアクションに笑った」と自然に続く。", "計算": "計算は体の動きではないので、「大きな計算に笑った」は意味が通らない。", "天気": "天気は体で表すものではないので、「大きな天気に笑った」は文として合わない。", "地図": "地図は動きではないので、「大きな地図に笑った」は成り立たない。"}, "sentence_index": 0, "correct_answer": "アクション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは、アクションが濃くておいしい。", "explanation": "ここは〈味〉の意味。スープの濃さは味で言い、体の動きのアクションとは言わない。"}, {"text": "この皿は、アクションが丸い。", "explanation": "ここは〈形〉の意味。皿の形は形で言い、体の動きのアクションを皿に当てては言わない。"}, {"text": "彼女のアクションは大きくて、教室の端まで届いた。", "explanation": "ここは〈声〉の意味。届くのは声で、体の動きが教室の端まで届くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37313, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アクション", "is_correct": true, "explanation": "舞台上の体の動きを指す語で、「小さなアクションも客席から見える」と正しく続く。"}, {"text": "足音", "is_correct": false, "explanation": "足音は見えるものではないので、「小さな足音も客席から見える」は成り立たない。"}, {"text": "鼓動", "is_correct": false, "explanation": "鼓動は客席から見えないものなので、この文には合わない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は聞こえるもので、客席から見えるという文と合わない。"}], "explanations": {"アクション": "舞台上の体の動きを指す語で、「小さなアクションも客席から見える」と正しく続く。", "足音": "足音は見えるものではないので、「小さな足音も客席から見える」は成り立たない。", "鼓動": "鼓動は客席から見えないものなので、この文には合わない。", "寝言": "寝言は聞こえるもので、客席から見えるという文と合わない。"}, "sentence_index": 6, "correct_answer": "アクション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この服のアクションは、鮮やかな赤だ。", "explanation": "ここは〈色〉の意味。服の色は色で言い、体の動きのアクションを服の色として言うことはない。"}, {"text": "この花はいいアクションがする。", "explanation": "ここは〈におい〉の意味。香りを言う語で、体の動きのアクションとは言わない。"}, {"text": "この言葉はアクションが難しい。", "explanation": "ここは〈アクセント〉の意味。音の高さや強さを言う語で、体の動きの意味とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37313, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ダンサーは、曲のリズムに合わせて、細かいアクションに重ねた。", "corrected_sentence": "ダンサーは、曲のリズムに合わせて、細かいアクションを重ねた。", "error_description": "「重ねる」は目的語に「を」を使う。ここの「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37313, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その選手は、ボールを持つ前のアクションを素早い。", "corrected_sentence": "その選手は、ボールを持つ前のアクションが素早い。", "error_description": "「素早い」は形容詞で、主語に「が」を使う。ここの「を」は誤りで、正しくは「が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37314, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「話し合う」の対象を表す。「戦略を話し合った」が自然。"}, {"text": "に", "is_correct": false, "explanation": "「戦略に話し合った」は相手や対象の取り方として不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「戦略より話し合った」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「戦略の、話し合った」は文として不自然。"}], "correct_answer": "を", "explanations": {"を": "「話し合う」の対象を表す。「戦略を話し合った」が自然。", "に": "「戦略に話し合った」は相手や対象の取り方として不自然。", "より": "比較の助詞で、「戦略より話し合った」は文が成り立たない。", "の": "連体修飾の助詞で、「戦略の、話し合った」は文として不自然。"}, "error_tags": {"に": "対象", "より": "比較", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37314, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表す〈で〉で、「戦略で客を集める」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「戦略を客を集める」は対象が二つ重なり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「戦略へ客を集める」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列の助詞で、「戦略と客を集める」は手段を表せない。"}], "correct_answer": "で", "explanations": {"で": "手段を表す〈で〉で、「戦略で客を集める」が自然。", "を": "「戦略を客を集める」は対象が二つ重なり不自然。", "へ": "方向を表す助詞で、「戦略へ客を集める」は意味が通らない。", "と": "並列の助詞で、「戦略と客を集める」は手段を表せない。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37314, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをうまく進めるための、長い目で見た計画や方法のこと。", "primary_collocate": null, "pronunciation": "せんりゃく", "ipa": "seɲɾʲaku", "syllable_count": 4, "sentences": [{"text": "会社は新しい戦略を立てて、海外で商品を売り始めた。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい戦略[せんりゃく]を立[た]てて、海外[かいがい]で商品[しょうひん]を売[う]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "勝つための戦略を、チーム全員で話し合った。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "勝[か]つための戦略[せんりゃく]を、チーム全員[ぜんいん]で話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "長い目で見ると、この戦略は正しかったと言える。", "target_word": "戦略", "complexity_tier": "T4", "furigana": "長[なが]い目[め]で見[み]ると、この戦略[せんりゃく]は正[ただ]しかったと言[い]える。", "sentence_source": "generated"}, {"text": "彼は戦略が上手で、いつも試合の流れを読んでいる。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "彼[かれ]は戦略[せんりゃく]が上手[じょうず]で、いつも試合[しあい]の流[なが]れを読[よ]んでいる。", "sentence_source": "generated"}, {"text": "広告に頼らない戦略に変えたら、売り上げが伸びた。", "target_word": "戦略", "complexity_tier": "T4", "furigana": "広告[こうこく]に頼[たよ]らない戦略[せんりゃく]に変[か]えたら、売[う]り上[あ]げが伸[の]びた。", "sentence_source": "generated"}, {"text": "戦略がないまま始めると、途中で行き詰まりやすい。", "target_word": "戦略", "complexity_tier": "T4", "furigana": "戦略[せんりゃく]がないまま始[はじ]めると、途中[とちゅう]で行[い]き詰[づ]まりやすい。", "sentence_source": "generated"}, {"text": "先生は「勉強にも戦略が必要だ」と言った。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "先生[せんせい]は「勉強[べんきょう]にも戦略[せんりゃく]が必要[ひつよう]だ」と言[い]った。", "sentence_source": "generated"}, {"text": "小さな店は、大きな店とは別の戦略で客を集めている。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "小[ちい]さな店[みせ]は、大[おお]きな店[みせ]とは別[べつ]の戦略[せんりゃく]で客[きゃく]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "監督は決勝戦に向けて、夜遅くまで戦略を練った。", "target_word": "戦略", "complexity_tier": "T4", "furigana": "監督[かんとく]は決勝戦[けっしょうせん]に向[む]けて、夜[よる]遅[おそ]くまで戦略[せんりゃく]を練[ね]った。", "sentence_source": "generated"}, {"text": "戦略どおりに進まなくても、あわてず計画を直せばいい。", "target_word": "戦略", "complexity_tier": "T4", "furigana": "戦略[せんりゃく]どおりに進[すす]まなくても、あわてず計画[けいかく]を直[なお]せばいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦略", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "strategy: a long-range plan or method for carrying something out successfully (business, sports, study)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481ed36a-14ce-4134-9f49-87c6b4fc588f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37314, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戦略", "is_correct": true, "explanation": "長い目で見た計画を立てる意味で、文に合う。"}, {"text": "感想", "is_correct": false, "explanation": "感じたことの意見のことで、立てるものではない。"}, {"text": "好み", "is_correct": false, "explanation": "気に入る傾向のことで、「立てて」とは結びつかない。"}, {"text": "疑念", "is_correct": false, "explanation": "疑いの気持ちのことで、「立てて」と組み合わせると意味が通らない。"}], "explanations": {"戦略": "長い目で見た計画を立てる意味で、文に合う。", "感想": "感じたことの意見のことで、立てるものではない。", "好み": "気に入る傾向のことで、「立てて」とは結びつかない。", "疑念": "疑いの気持ちのことで、「立てて」と組み合わせると意味が通らない。"}, "sentence_index": 0, "correct_answer": "戦略"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来学期の戦略を、先生が配った。", "explanation": "ここは〈時間割〉の意味。授業の割り振りは戦略とは言わない。"}, {"text": "本の戦略を、先に読んだ。", "explanation": "ここは〈目次〉の意味。本の章立てを示すもので、戦略とは言わない。"}, {"text": "新しい戦略を、ピアノで弾いた。", "explanation": "ここは〈演奏〉の意味。楽器で音を鳴らすことは戦略とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37314, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戦略", "is_correct": true, "explanation": "勉強にも必要な長期的な計画の意味で、文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空の状態のことで、勉強に必要だという文には合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "車などが込み合うことで、勉強の必要性の文とは合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気中の水分の割合で、勉強に必要という文では意味が通らない。"}], "explanations": {"戦略": "勉強にも必要な長期的な計画の意味で、文に合う。", "天気": "空の状態のことで、勉強に必要だという文には合わない。", "渋滞": "車などが込み合うことで、勉強の必要性の文とは合わない。", "湿度": "空気中の水分の割合で、勉強に必要という文では意味が通らない。"}, "sentence_index": 6, "correct_answer": "戦略"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店の戦略を、レジで済ませた。", "explanation": "ここは〈会計〉の意味。支払いを済ませることは戦略とは言わない。"}, {"text": "映画を見たあと、戦略を冷蔵庫に入れた。", "explanation": "ここは〈保存〉の意味。計画を冷蔵庫に入れることは戦略とは言わない。"}, {"text": "新聞の戦略を、大きく書いた。", "explanation": "ここは〈見出し〉の意味。記事の題名は見出しと言い、戦略とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37314, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい戦略を、会社の成功につながった。", "corrected_sentence": "新しい戦略が、会社の成功につながった。", "error_description": "「つながる」は主語に〈が〉を取る。「戦略を」は誤りで、正しくは「戦略が成功につながった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37314, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "コーチは試合に向けて、夜遅くまで戦略を練いた。", "corrected_sentence": "コーチは試合に向けて、夜遅くまで戦略を練った。", "error_description": "「練る」の過去形は「練った」。「練いた」は活用の誤りで、正しくは「練った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b98fecb-1aba-45df-ba52-82d73d05d9df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37316, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外す", "is_correct": true, "explanation": "「付ける」の対義語で、取り付けたものを取り去る意味。"}, {"text": "食べる", "is_correct": false, "explanation": "動詞だが、取り付けとは無関係で対義語ではない。"}, {"text": "眺める", "is_correct": false, "explanation": "見る行為を表す動詞で、「付ける」の対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "移動させる動詞だが、「付ける」の対義語とはされない。"}], "correct_answer": "外す", "explanations": {"外す": "「付ける」の対義語で、取り付けたものを取り去る意味。", "食べる": "動詞だが、取り付けとは無関係で対義語ではない。", "眺める": "見る行為を表す動詞で、「付ける」の対義語ではない。", "運ぶ": "移動させる動詞だが、「付ける」の対義語とはされない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37316, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「カバーを付けたい」の目的を示す格助詞で、付けたいものを表す。"}, {"text": "や", "is_correct": false, "explanation": "並列の「や」は後に名詞が続く必要があり、「カバーや付けたい」は文として成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「カバーと付けたい」では並列の関係にならず、不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "「カバーの付けたい」では名詞修飾として成立せず、文が不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「カバーを付けたい」の目的を示す格助詞で、付けたいものを表す。", "や": "並列の「や」は後に名詞が続く必要があり、「カバーや付けたい」は文として成立しない。", "と": "「カバーと付けたい」では並列の関係にならず、不自然になる。", "の": "「カバーの付けたい」では名詞修飾として成立せず、文が不自然になる。"}, "error_tags": {"と": "並列を示すが、動詞の目的語にならない", "の": "名詞修飾にしかならず、動詞を続けられない", "や": "並列の助詞だが、単独では文が成立しない"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外す", "is_correct": true, "explanation": "「付ける」の対義語で、取り付けたものを取り去る意味。"}, {"text": "作る", "is_correct": false, "explanation": "動詞だが、作り出す意味で対義語ではない。"}, {"text": "歌う", "is_correct": false, "explanation": "声を出す動詞だが、「付ける」の対義語ではない。"}, {"text": "押す", "is_correct": false, "explanation": "力を加える動詞だが、「付ける」の対義語とはされない。"}], "correct_answer": "外す", "explanations": {"外す": "「付ける」の対義語で、取り付けたものを取り去る意味。", "作る": "動詞だが、作り出す意味で対義語ではない。", "歌う": "声を出す動詞だが、「付ける」の対義語ではない。", "押す": "力を加える動詞だが、「付ける」の対義語とはされない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37316, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをつけることです。", "primary_collocate": null, "pronunciation": "つける", "ipa": "tsɯkeɾɯ", "syllable_count": 3, "sentences": [{"text": "箱にリボンを付けました。", "target_word": "付けました", "complexity_tier": "T3", "furigana": "箱[はこ]にリボンを付[つ]けました。", "sentence_source": "generated"}, {"text": "服にボタンを付けるのを忘れました。", "target_word": "付ける", "complexity_tier": "T3", "furigana": "服[ふく]にボタンを付[つ]けるのを忘[わす]れました。", "sentence_source": "generated"}, {"text": "鍵にキーホルダーを付けて、なくさないようにしています。", "target_word": "付けて", "complexity_tier": "T3", "furigana": "鍵[かぎ]にキーホルダーを付[つ]けて、なくさないようにしています。", "sentence_source": "generated"}, {"text": "手紙に写真を付けて送ります。", "target_word": "付けて", "complexity_tier": "T3", "furigana": "手紙[てがみ]に写真[しゃしん]を付[つ]けて送[おく]ります。", "sentence_source": "generated"}, {"text": "カバンに名札を付けておけば、間違えません。", "target_word": "付けて", "complexity_tier": "T3", "furigana": "カバンに名札[なふだ]を付[つ]けておけば、間違[まちが]えません。", "sentence_source": "generated"}, {"text": "椅子の足にゴムを付けたので、床に傷がつきません。", "target_word": "付けた", "complexity_tier": "T3", "furigana": "椅子[いす]の足[あし]にゴムを付[つ]けたので、床[ゆか]に傷[きず]がつきません。", "sentence_source": "generated"}, {"text": "地図に印を付けて、行く場所を決めました。", "target_word": "付けて", "complexity_tier": "T3", "furigana": "地図[ちず]に印[しるし]を付[つ]けて、行[い]く場所[ばしょ]を決[き]めました。", "sentence_source": "generated"}, {"text": "本にカバーを付けたいので、手伝ってくれますか。", "target_word": "付けたい", "complexity_tier": "T3", "furigana": "本[ほん]にカバーを付[つ]けたいので、手伝[てつだ]ってくれますか。", "sentence_source": "generated"}, {"text": "犬に首輪を付けてから、散歩に出ます。", "target_word": "付けて", "complexity_tier": "T3", "furigana": "犬[いぬ]に首輪[くびわ]を付[つ]けてから、散歩[さんぽ]に出[で]ます。", "sentence_source": "generated"}, {"text": "自転車にかごを付けたら、買い物が楽になりました。", "target_word": "付けたら", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]にかごを付[つ]けたら、買[か]い物[もの]が楽[らく]になりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "付けます", "label": "丁寧形"}, {"form": "付けない", "label": "否定形"}, {"form": "付けて", "label": "て形"}, {"form": "付けた", "label": "た形"}, {"form": "付ければ", "label": "仮定形"}, {"form": "付けよう", "label": "意志形"}, {"form": "付けられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "物や印などを別の物にくっつけて取り付ける（下一段動詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24bff216-7aef-4422-8d8a-73355dcf2e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37316, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付けました", "is_correct": true, "explanation": "丁寧な過去形で文末に入り、「リボンを付けた」という完了の意味が成り立つ。"}, {"text": "付けて", "is_correct": false, "explanation": "て形は文末に置けず、文が途中で切れて不完全になる。"}, {"text": "付ければ", "is_correct": false, "explanation": "仮定形は後ろに主節が必要で、ここでは文を終えられない。"}, {"text": "付けられ", "is_correct": false, "explanation": "連用形の語幹で、文末に置くと未完成の文になる。"}], "explanations": {"付けました": "丁寧な過去形で文末に入り、「リボンを付けた」という完了の意味が成り立つ。", "付けて": "て形は文末に置けず、文が途中で切れて不完全になる。", "付ければ": "仮定形は後ろに主節が必要で、ここでは文を終えられない。", "付けられ": "連用形の語幹で、文末に置くと未完成の文になる。"}, "sentence_index": 0, "correct_answer": "付けました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が降ってきたので、傘を付けて出かけました。", "explanation": "ここは〈傘をさす〉の意味。傘は「さす」と言うので、物を取り付ける「付ける」では合わない。"}, {"text": "彼女は、やさしい笑顔を付けてあいさつしました。", "explanation": "ここは〈笑顔を浮かべる〉の意味。笑顔は「浮かべる」と言い、「付ける」では合わない。"}, {"text": "子どもの頃から、大きな夢を付けて生きてきました。", "explanation": "ここは〈夢を抱く・持つ〉の意味。夢は「抱く」「持つ」と言い、「付ける」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37316, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付けて", "is_correct": true, "explanation": "て形で後続の「行く場所を決めました」につなげられ、文の流れが成立する。"}, {"text": "付けろ", "is_correct": false, "explanation": "命令形で、後続の文とつながらず文意が通らない。"}, {"text": "付けない", "is_correct": false, "explanation": "ない形のままでは後ろに続かず、「付けないで」などの形が必要になる。"}, {"text": "付けまい", "is_correct": false, "explanation": "否定意志の形で、文が途中で切れて不自然になる。"}], "explanations": {"付けて": "て形で後続の「行く場所を決めました」につなげられ、文の流れが成立する。", "付けろ": "命令形で、後続の文とつながらず文意が通らない。", "付けない": "ない形のままでは後ろに続かず、「付けないで」などの形が必要になる。", "付けまい": "否定意志の形で、文が途中で切れて不自然になる。"}, "sentence_index": 6, "correct_answer": "付けて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は丁寧な返事を付けて、お客さんに送りました。", "explanation": "ここは〈返事を書く〉の意味。返事は「書く」と言い、「付ける」では合わない。"}, {"text": "試合の前に、彼は強い決意を付けました。", "explanation": "ここは〈決意を固める〉の意味。決意は「固める」と言い、「付ける」では合わない。"}, {"text": "悲しい別れのあと、彼女は涙を付けました。", "explanation": "ここは〈涙を流す〉の意味。涙は「流す」と言い、「付ける」では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37316, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ペンケースから名札を付けました。", "corrected_sentence": "ペンケースに名札を付けました。", "error_description": "「付ける」は取り付け先を「に」で示す。「から」は起点を表すので、ここでは誤り。正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "付ける", "is_correct": true, "explanation": "辞書形で、「〜のを忘れました」の前に名詞句として入れる形。"}, {"text": "付けます", "is_correct": false, "explanation": "丁寧形は「〜のを」の前に入れられず、文が成り立たない。"}, {"text": "付けよう", "is_correct": false, "explanation": "意志形は「〜のを」の前に置けず、文法的に成立しない。"}, {"text": "付ければ", "is_correct": false, "explanation": "仮定形は「〜のを」の前に置けず、文が続かない。"}], "correct_form": "付ける", "base_form": "付ける", "form_label": "辞書形", "sentence_index": 1, "explanations": {"付ける": "辞書形で、「〜のを忘れました」の前に名詞句として入れる形。", "付けます": "丁寧形は「〜のを」の前に入れられず、文が成り立たない。", "付けよう": "意志形は「〜のを」の前に置けず、文法的に成立しない。", "付ければ": "仮定形は「〜のを」の前に置けず、文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37316, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "かばんにタグを付けおくと、探しやすいです。", "corrected_sentence": "かばんにタグを付けておくと、探しやすいです。", "error_description": "「付けておく」は「付けて」＋「おく」の形。「て」が抜けているので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "付けたい", "is_correct": true, "explanation": "希望の形で、「〜ので」の前に続けて文の意味が通る。"}, {"text": "付けなくて", "is_correct": false, "explanation": "否定のて形は「〜ので」に続かず、文が成り立たない。"}, {"text": "付けろ", "is_correct": false, "explanation": "命令形は「〜ので」の前に置けない。"}, {"text": "付けまい", "is_correct": false, "explanation": "否定意志の形は「〜ので」の前に置けず、文法的に不自然。"}], "correct_form": "付けたい", "base_form": "付ける", "form_label": "願望形（〜たい）", "sentence_index": 7, "explanations": {"付けたい": "希望の形で、「〜ので」の前に続けて文の意味が通る。", "付けなくて": "否定のて形は「〜ので」に続かず、文が成り立たない。", "付けろ": "命令形は「〜ので」の前に置けない。", "付けまい": "否定意志の形は「〜ので」の前に置けず、文法的に不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37318, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「教える」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「ゲームが教えてくれた」は主語が二つになり文が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「ゲームへ教える」は目的語として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "相手を示すが、「ゲームに教えてくれました」は人でない対象に教えることになり不自然。"}], "correct_answer": "を", "explanations": {"を": "正解。「教える」の目的語を示す「を」。", "が": "主語を示すが、「ゲームが教えてくれた」は主語が二つになり文が崩れる。", "へ": "方向を示すが、「ゲームへ教える」は目的語として成り立たない。", "に": "相手を示すが、「ゲームに教えてくれました」は人でない対象に教えることになり不自然。"}, "error_tags": {"が": "主語", "へ": "方向", "に": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37318, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「する」の目的語を示す「を」。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「ゲームへしました」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「ゲームがしました」は主語と述語が合わず文が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "所属・修飾を示すが、「ゲームのしました」は文が崩れる。"}], "correct_answer": "を", "explanations": {"を": "正解。「する」の目的語を示す「を」。", "へ": "方向を示すが、「ゲームへしました」は成り立たない。", "が": "主語を示すが、「ゲームがしました」は主語と述語が合わず文が崩れる。", "の": "所属・修飾を示すが、「ゲームのしました」は文が崩れる。"}, "error_tags": {"へ": "方向", "が": "主語", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37318, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たのしいあそびのことです。", "primary_collocate": null, "pronunciation": "げーむ", "ipa": "ɡeːmɯ", "syllable_count": 3, "sentences": [{"text": "雨の日は、家族でトランプのゲームをして遊びます。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、家族[かぞく]でトランプのゲームをして遊[あそ]びます。", "sentence_source": "generated"}, {"text": "授業のあとで、先生が楽しいゲームを教えてくれました。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]のあとで、先生[せんせい]が楽[たの]しいゲームを教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "パーティーで、みんなで言葉のゲームをしました。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "パーティーで、みんなで言葉[ことば]のゲームをしました。", "sentence_source": "generated"}, {"text": "このゲームは、四人いればできます。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "このゲームは、四人[よにん]いればできます。", "sentence_source": "generated"}, {"text": "子どもたちは公園で、鬼ごっこのようなゲームを考えました。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "子[こ]どもたちは公園[こうえん]で、鬼[おに]ごっこのようなゲームを考[かんが]えました。", "sentence_source": "generated"}, {"text": "負けたほうがお茶をいれるというゲームで、盛り上がりました。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "負[ま]けたほうがお茶[ちゃ]をいれるというゲームで、盛[も]り上[あ]がりました。", "sentence_source": "generated"}, {"text": "ルールが簡単なゲームなので、おばあちゃんも一緒に遊べます。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "ルールが簡単[かんたん]なゲームなので、おばあちゃんも一緒[いっしょ]に遊[あそ]べます。", "sentence_source": "generated"}, {"text": "遠足のバスの中で、しりとりのゲームをしました。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "遠足[えんそく]のバスの中[なか]で、しりとりのゲームをしました。", "sentence_source": "generated"}, {"text": "ゲームに勝って、小さなおかしをもらいました。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "ゲームに勝[か]って、小[ちい]さなおかしをもらいました。", "sentence_source": "generated"}, {"text": "夜は電気を消して、トランプのゲームを楽しみました。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "夜[よる]は電気[でんき]を消[け]して、トランプのゲームを楽[たの]しみました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゲーム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ルールのある楽しい遊び一般(トランプ・言葉遊びなど)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0118fb7-8c88-4730-aa9e-d75a197e3036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37318, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ゲーム", "is_correct": true, "explanation": "正解。トランプなど、ルールのある遊びを指す。"}, {"text": "料理", "is_correct": false, "explanation": "料理はトランプの遊びの対象にならず、「トランプの料理をして」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は遊びの対象ではないので、「トランプの天気をして」は通らない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は遊びではないので、文が成り立たない。"}], "explanations": {"ゲーム": "正解。トランプなど、ルールのある遊びを指す。", "料理": "料理はトランプの遊びの対象にならず、「トランプの料理をして」は成り立たない。", "天気": "天気は遊びの対象ではないので、「トランプの天気をして」は通らない。", "郵便": "郵便は遊びではないので、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "ゲーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お昼に、ゲームを食べました。", "explanation": "ここは〈食べ物を食べる〉の意味。〈ゲーム〉は食べられないので、「食べる」の対象として合わない。"}, {"text": "寒い朝に、ゲームを着ました。", "explanation": "ここは〈服を着る〉の意味。〈ゲーム〉は身につけられないので、「着る」の対象として合わない。"}, {"text": "畑に、ゲームを植えました。", "explanation": "ここは〈植物を植える〉の意味。〈ゲーム〉は植えられないので、「植える」の対象として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37318, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ゲーム", "is_correct": true, "explanation": "正解。ルールのある遊びを指す。"}, {"text": "雨", "is_correct": false, "explanation": "雨にはルールがなく、遊びの対象ではないので文が成り立たない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は遊びの対象にならず、「ルールが簡単な眠気」は通らない。"}, {"text": "空気", "is_correct": false, "explanation": "空気はルールを持たず、遊びにならないので合わない。"}], "explanations": {"ゲーム": "正解。ルールのある遊びを指す。", "雨": "雨にはルールがなく、遊びの対象ではないので文が成り立たない。", "眠気": "眠気は遊びの対象にならず、「ルールが簡単な眠気」は通らない。", "空気": "空気はルールを持たず、遊びにならないので合わない。"}, "sentence_index": 6, "correct_answer": "ゲーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お母さんは、ゲームを縫って服を作りました。", "explanation": "ここは〈布を縫う〉の意味。〈ゲーム〉は縫えないので、「縫う」の対象として合わない。"}, {"text": "ゲームを焼いて、みんなで食べました。", "explanation": "ここは〈食べ物を焼く〉の意味。〈ゲーム〉は焼けないので、「焼く」の対象として合わない。"}, {"text": "台所で、ゲームを切りました。", "explanation": "ここは〈野菜や肉を切る〉の意味。〈ゲーム〉は切れないので、「切る」の対象として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37318, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放課後、ゲームを遊んで帰りました。", "corrected_sentence": "放課後、ゲームで遊んで帰りました。", "error_description": "「遊ぶ」の手段・場所を示す「で」が正しい。「を」は目的語になり、「遊ぶ」と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
