INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37319, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "コンピュータやテレビなどで遊ぶ、楽しい活動です。", "primary_collocate": null, "pronunciation": "げーむ", "ipa": "ɡeːmɯ", "syllable_count": 3, "sentences": [{"text": "私はゲームの世界であそびます。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "私[わたし]はゲームの世界[せかい]であそびます。", "sentence_source": "mined"}, {"text": "兄は毎晩、新しいゲームを夢中でしています。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "兄[あに]は毎晩[まいばん]、新[あたら]しいゲームを夢中[むちゅう]でしています。", "sentence_source": "generated"}, {"text": "このゲームは、スマートフォンでも遊べます。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "このゲームは、スマートフォンでも遊[あそ]べます。", "sentence_source": "generated"}, {"text": "宿題が終わってから、ゲームをする約束です。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が終[お]わってから、ゲームをする約束[やくそく]です。", "sentence_source": "generated"}, {"text": "ゲームのやりすぎで、目が疲れてしまいました。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "ゲームのやりすぎで、目[め]が疲[つか]れてしまいました。", "sentence_source": "generated"}, {"text": "友だちとオンラインのゲームで対戦しました。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "友[とも]だちとオンラインのゲームで対戦[たいせん]しました。", "sentence_source": "generated"}, {"text": "新しいゲームが発売される日に、店の前に行列ができました。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "新[あたら]しいゲームが発売[はつばい]される日[ひ]に、店[みせ]の前[まえ]に行列[ぎょうれつ]ができました。", "sentence_source": "generated"}, {"text": "このゲームは操作が簡単なので、子どもでもすぐ遊べます。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "このゲームは操作[そうさ]が簡単[かんたん]なので、子[こ]どもでもすぐ遊[あそ]べます。", "sentence_source": "generated"}, {"text": "ゲームの画面を見すぎないように、一時間ごとに休みます。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "ゲームの画面[がめん]を見[み]すぎないように、一時間[いちじかん]ごとに休[やす]みます。", "sentence_source": "generated"}, {"text": "弟は誕生日に、ゲームのソフトを買ってもらいました。", "target_word": "ゲーム", "complexity_tier": "T3", "furigana": "弟[おとうと]は誕生日[たんじょうび]に、ゲームのソフトを買[か]ってもらいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゲーム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "コンピュータ・テレビ・スマートフォンなどで遊ぶ電子的なゲーム", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0118fb7-8c88-4730-aa9e-d75a197e3036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37319, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ゲーム", "is_correct": true, "explanation": "正解。「世界であそぶ」対象として、コンピュータなどで遊ぶ電子的なゲームを指す。"}, {"text": "病院", "is_correct": false, "explanation": "病院は遊ぶ対象ではないので、「病院の世界であそびます」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は遊ぶ対象ではないので、「天気の世界であそぶ」は成り立たない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は遊ぶ対象ではないので、ここには入らない。"}], "explanations": {"ゲーム": "正解。「世界であそぶ」対象として、コンピュータなどで遊ぶ電子的なゲームを指す。", "病院": "病院は遊ぶ対象ではないので、「病院の世界であそびます」は成り立たない。", "天気": "天気は遊ぶ対象ではないので、「天気の世界であそぶ」は成り立たない。", "郵便": "郵便は遊ぶ対象ではないので、ここには入らない。"}, "sentence_index": 0, "correct_answer": "ゲーム"}, "level_6": {"correct_sentence_index": 2, "wrong_sentences": [{"text": "お腹が空いたので、ゲームを食べました。", "explanation": "ここは〈食べ物を食べる〉の意味。〈ゲーム〉は食べられないので、「食べる」の対象として合わない。"}, {"text": "寒い日は、ゲームを着て出かけました。", "explanation": "ここは〈服を着る〉の意味。〈ゲーム〉は身につけられないので、「着る」の対象として合わない。"}, {"text": "庭に、ゲームを植えました。", "explanation": "ここは〈植物を植える〉の意味。〈ゲーム〉は植えられないので、「植える」の対象として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37319, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ゲーム", "is_correct": true, "explanation": "正解。「発売される」対象になる、電子的なゲームを指す。"}, {"text": "空気", "is_correct": false, "explanation": "空気は発売される対象にならず、文が成り立たない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は発売されないので、「新しい雨が発売される」は意味が通らない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は発売されないので、この文には入らない。"}], "explanations": {"ゲーム": "正解。「発売される」対象になる、電子的なゲームを指す。", "空気": "空気は発売される対象にならず、文が成り立たない。", "雨": "雨は発売されないので、「新しい雨が発売される」は意味が通らない。", "眠気": "眠気は発売されないので、この文には入らない。"}, "sentence_index": 6, "correct_answer": "ゲーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝ごはんに、ゲームを飲みました。", "explanation": "ここは〈飲み物を飲む〉の意味。〈ゲーム〉は飲めないので、「飲む」の対象として合わない。"}, {"text": "プールで、ゲームを泳ぎました。", "explanation": "ここは〈水中を進む〉の意味。〈ゲーム〉は泳げないので、「泳ぐ」の対象として合わない。"}, {"text": "家族みんなで、ゲームを干しました。", "explanation": "ここは〈洗濯物を干す〉の意味。〈ゲーム〉は干せないので、「干す」の対象として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37319, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜はゲームに遊んで、目が疲れました。", "corrected_sentence": "夜はゲームで遊んで、目が疲れました。", "error_description": "「遊ぶ」の手段・場所を示すのは「で」。「に」は方向・位置を示し、「遊ぶ」の対象にできないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37319, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちとゲームを対戦しました。", "corrected_sentence": "友だちとゲームで対戦しました。", "error_description": "「対戦」の手段・場を示す「で」が正しい。「を」は目的語にできないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37320, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「入る」は「～に入る」の形で、集まりに加わることを表すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「入る」は目的語をとらないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「チームで入る」は意味が通らないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は出発点を示すが、「入る」の相手を示す形にはならないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「入る」は「～に入る」の形で、集まりに加わることを表すので正しい。", "を": "「を」は目的語を示すが、「入る」は目的語をとらないので合わない。", "で": "「で」は場所や手段を示すが、「チームで入る」は意味が通らないので合わない。", "から": "「から」は出発点を示すが、「入る」の相手を示す形にはならないので合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37320, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「ほかのチームと練習試合をする」の「と」は相手を示し、正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は練習試合の相手を示す形にはならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、練習試合の相手は方向ではないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる相手を示すが、ここでは練習試合の相手にはならないので合わない。"}], "correct_answer": "と", "explanations": {"と": "「ほかのチームと練習試合をする」の「と」は相手を示し、正しい。", "に": "「に」は練習試合の相手を示す形にはならないので合わない。", "へ": "「へ」は方向を示すが、練習試合の相手は方向ではないので合わない。", "より": "「より」は比べる相手を示すが、ここでは練習試合の相手にはならないので合わない。"}, "error_tags": {"に": "相手", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37320, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みんなでいっしょにするグループのこと。", "primary_collocate": null, "pronunciation": "ちーむ", "ipa": "tɕiːmɯ", "syllable_count": 3, "sentences": [{"text": "わたしたちのチームは、きのうの試合に勝ちました。", "target_word": "チーム", "complexity_tier": "T2", "furigana": "わたしたちのチームは、きのうの試合[しあい]に勝[か]ちました。", "sentence_source": "generated"}, {"text": "兄はサッカーのチームに入っています。", "target_word": "チーム", "complexity_tier": "T2", "furigana": "兄[あに]はサッカーのチームに入[はい]っています。", "sentence_source": "generated"}, {"text": "このチームには、子どもが十二人います。", "target_word": "チーム", "complexity_tier": "T2", "furigana": "このチームには、子[こ]どもが十二人[じゅうににん]います。", "sentence_source": "generated"}, {"text": "チームのみんなで、毎朝グラウンドを走ります。", "target_word": "チーム", "complexity_tier": "T3", "furigana": "チームのみんなで、毎朝[まいあさ]グラウンドを走[はし]ります。", "sentence_source": "generated"}, {"text": "田中さんは、わたしと同じチームです。", "target_word": "チーム", "complexity_tier": "T3", "furigana": "田中[たなか]さんは、わたしと同[おな]じチームです。", "sentence_source": "generated"}, {"text": "人が多いので、チームを二つに分けました。", "target_word": "チーム", "complexity_tier": "T3", "furigana": "人[ひと]が多[おお]いので、チームを二[ふた]つに分[わ]けました。", "sentence_source": "generated"}, {"text": "負けたので、チームのみんなが悲しそうでした。", "target_word": "チーム", "complexity_tier": "T3", "furigana": "負[ま]けたので、チームのみんなが悲[かな]しそうでした。", "sentence_source": "generated"}, {"text": "来週、ほかのチームと練習試合をします。", "target_word": "チーム", "complexity_tier": "T3", "furigana": "来週[らいしゅう]、ほかのチームと練習試合[れんしゅうじあい]をします。", "sentence_source": "generated"}, {"text": "先生はチームの名前を黒板に書きました。", "target_word": "チーム", "complexity_tier": "T3", "furigana": "先生[せんせい]はチームの名前[なまえ]を黒板[こくばん]に書[か]きました。", "sentence_source": "generated"}, {"text": "新しいチームで、友だちがたくさんできました。", "target_word": "チーム", "complexity_tier": "T3", "furigana": "新[あたら]しいチームで、友[とも]だちがたくさんできました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チーム", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "スポーツや遊びなどをいっしょにする仲間のグループ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37320, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チーム", "is_correct": true, "explanation": "「わたしたちのチーム」は試合に勝つ仲間の集まりを指すので正しい。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は本で、試合に勝つ主体にはならないので合わない。"}, {"text": "台所", "is_correct": false, "explanation": "台所は場所で、試合に勝つことはないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様で、試合に勝つ主体にはならないので合わない。"}], "explanations": {"チーム": "「わたしたちのチーム」は試合に勝つ仲間の集まりを指すので正しい。", "辞書": "辞書は本で、試合に勝つ主体にはならないので合わない。", "台所": "台所は場所で、試合に勝つことはないので合わない。", "天気": "天気は空模様で、試合に勝つ主体にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "チーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この駅の周りのチームは、夜になると静かになります。", "explanation": "ここは〈エリア〉の意味。チームは人の集まりを指すので、地域を表す言い方には使えない。"}, {"text": "彼は、一人でチームを演奏しました。", "explanation": "ここは〈曲〉の意味。チームは人の集まりなので、演奏する曲の名前にはならない。"}, {"text": "この箱は、チームが大きいので重いです。", "explanation": "ここは〈サイズ〉の意味。箱の大きさは寸法の話で、人の集まりのチームは当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37320, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チーム", "is_correct": true, "explanation": "「チームのみんな」は一緒に試合をする仲間を指すので、負けて悲しむ文に合う。"}, {"text": "電車", "is_correct": false, "explanation": "「電車のみんな」は人の集まりにならないので合わない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消しゴムは文房具で、悲しむ人の集まりを表さないので合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は天気で、「雨のみんな」は人の集まりにならないので合わない。"}], "explanations": {"チーム": "「チームのみんな」は一緒に試合をする仲間を指すので、負けて悲しむ文に合う。", "電車": "「電車のみんな」は人の集まりにならないので合わない。", "消しゴム": "消しゴムは文房具で、悲しむ人の集まりを表さないので合わない。", "雨": "雨は天気で、「雨のみんな」は人の集まりにならないので合わない。"}, "sentence_index": 6, "correct_answer": "チーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店のチームは、一番人気のケーキです。", "explanation": "ここは〈名物〉の意味。チームは人の集まりなので、店の看板になる食べ物には使えない。"}, {"text": "この服は、チームが明るいです。", "explanation": "ここは〈色〉の意味。チームは人の集まりなので、服の色の明るさには使わない。"}, {"text": "テストのチームが上がりました。", "explanation": "ここは〈点数〉の意味。チームは人の集まりなので、テストの数値の上昇には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37320, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟は野球のチームを入っています。", "corrected_sentence": "弟は野球のチームに入っています。", "error_description": "「チームに入る」が正しい形。「入る」は「～に入る」で相手や組織を示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37320, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人でチームを結びました。", "corrected_sentence": "二人でチームを組みました。", "error_description": "「チームを組む」が正しい形。「結ぶ」は線や約束などに使うので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37321, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「が」は主語を示し、チームが患者を助けたという文になるので正しい。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、主語の位置に入ると文が成り立たないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、ここは主語の位置なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すが、ここは主語にあたるので合わない。"}], "correct_answer": "が", "explanations": {"が": "「が」は主語を示し、チームが患者を助けたという文になるので正しい。", "の": "「の」は名詞をつなぐ助詞で、主語の位置に入ると文が成り立たないので合わない。", "を": "「を」は目的語を示すが、ここは主語の位置なので合わない。", "に": "「に」は相手や場所を示すが、ここは主語にあたるので合わない。"}, "error_tags": {"の": "連体修飾", "を": "目的語", "に": "相手・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37321, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37321, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "共通の目的のために集まった人々の集まり。", "primary_collocate": null, "pronunciation": "ちーむ", "ipa": "tɕiːmɯ", "syllable_count": 3, "sentences": [{"text": "私たちのチームは、新しい商品を作っています。", "target_word": "チーム", "complexity_tier": "T3", "furigana": "私[わたし]たちのチームは、新[あたら]しい商品[しょうひん]を作[つく]っています。", "sentence_source": "generated"}, {"text": "医者と看護師のチームが、患者を助けました。", "target_word": "チーム", "complexity_tier": "T3", "furigana": "医者[いしゃ]と看護師[かんごし]のチームが、患者[かんじゃ]を助[たす]けました。", "sentence_source": "generated"}, {"text": "会議のあと、チームの全員で昼ご飯を食べました。", "target_word": "チーム", "complexity_tier": "T3", "furigana": "会議[かいぎ]のあと、チームの全員[ぜんいん]で昼[ひる]ご飯[はん]を食[た]べました。", "sentence_source": "generated"}, {"text": "山田さんは、このプロジェクトのチームを率いています。", "target_word": "チーム", "complexity_tier": "T4", "furigana": "山田[やまだ]さんは、このプロジェクトのチームを率[ひき]いています。", "sentence_source": "generated"}, {"text": "目標を達成するために、チームで遅くまで働きました。", "target_word": "チーム", "complexity_tier": "T4", "furigana": "目標[もくひょう]を達成[たっせい]するために、チームで遅[おそ]くまで働[はたら]きました。", "sentence_source": "generated"}, {"text": "災害の現場に、専門家のチームが向かいました。", "target_word": "チーム", "complexity_tier": "T4", "furigana": "災害[さいがい]の現場[げんば]に、専門家[せんもんか]のチームが向[む]かいました。", "sentence_source": "generated"}, {"text": "新しい人が入って、チームの雰囲気が明るくなりました。", "target_word": "チーム", "complexity_tier": "T4", "furigana": "新[あたら]しい人[ひと]が入[はい]って、チームの雰囲気[ふんいき]が明[あか]るくなりました。", "sentence_source": "generated"}, {"text": "チームで意見を出し合えば、よい案が生まれます。", "target_word": "チーム", "complexity_tier": "T4", "furigana": "チームで意見[いけん]を出[だ]し合[あ]えば、よい案[あん]が生[う]まれます。", "sentence_source": "generated"}, {"text": "この仕事は、一人ではなく、チームで進めます。", "target_word": "チーム", "complexity_tier": "T3", "furigana": "この仕事[しごと]は、一人[ひとり]ではなく、チームで進[すす]めます。", "sentence_source": "generated"}, {"text": "あの会社には、デザインを担当するチームがあります。", "target_word": "チーム", "complexity_tier": "T4", "furigana": "あの会社[かいしゃ]には、デザインを担当[たんとう]するチームがあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チーム", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "仕事や活動の目的を共有して協力する人々の集団", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: contains vocabulary far above tier T1: 出し合え (Zipf 1.3)']::text[], 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37321, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チーム", "is_correct": true, "explanation": "「私たちのチーム」は新しい商品を作る集団を指すので正しい。"}, {"text": "黒板", "is_correct": false, "explanation": "黒板は教室の設備で、商品を作る主体にはならないので合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、商品を作る主体にはならないので合わない。"}, {"text": "階段", "is_correct": false, "explanation": "階段は建物の設備で、商品を作る主体にはならないので合わない。"}], "explanations": {"チーム": "「私たちのチーム」は新しい商品を作る集団を指すので正しい。", "黒板": "黒板は教室の設備で、商品を作る主体にはならないので合わない。", "冷蔵庫": "冷蔵庫は家電で、商品を作る主体にはならないので合わない。", "階段": "階段は建物の設備で、商品を作る主体にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "チーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋のチームが下がりました。", "explanation": "ここは〈温度〉の意味。チームは人の集まりなので、部屋の温度の変化には使えない。"}, {"text": "このスープはチームが濃いです。", "explanation": "ここは〈味〉の意味。チームは人の集まりなので、スープの味の濃さには使わない。"}, {"text": "遠くからチームが聞こえました。", "explanation": "ここは〈音〉の意味。チームは人の集まりなので、耳で聞こえる音には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37321, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チーム", "is_correct": true, "explanation": "「チームの雰囲気」は集まった人々の空気を指すので、新しい人が入って明るくなる文に合う。"}, {"text": "体重", "is_correct": false, "explanation": "「体重の雰囲気」は意味が通らないので合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は調味料で、「砂糖の雰囲気」は意味が通らないので合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は文房具で、「鉛筆の雰囲気」は意味が通らないので合わない。"}], "explanations": {"チーム": "「チームの雰囲気」は集まった人々の空気を指すので、新しい人が入って明るくなる文に合う。", "体重": "「体重の雰囲気」は意味が通らないので合わない。", "砂糖": "砂糖は調味料で、「砂糖の雰囲気」は意味が通らないので合わない。", "鉛筆": "鉛筆は文房具で、「鉛筆の雰囲気」は意味が通らないので合わない。"}, "sentence_index": 6, "correct_answer": "チーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手紙にチームを貼りました。", "explanation": "ここは〈切手〉の意味。チームは人の集まりなので、手紙に貼るものではない。"}, {"text": "このチームは窓が大きいです。", "explanation": "ここは〈部屋〉の意味。チームは人の集まりなので、窓の大きさを説明する主語にはならない。"}, {"text": "焼きたてのチームを買いました。", "explanation": "ここは〈パン〉の意味。チームは人の集まりなので、店で買える食べ物には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37321, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生のチームに大会で優勝しました。", "corrected_sentence": "先生のチームが大会で優勝しました。", "error_description": "「優勝する」の主語は「が」で示す。「に」を使うと主語が成り立たないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37321, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しいチームを建てました。", "corrected_sentence": "新しいチームを作りました。", "error_description": "「チームを作る」が正しい形。「建てる」は建物などに使うので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
