INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37322, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「モンスターの絵」として、絵の対象を示す「の」。"}, {"text": "を", "is_correct": false, "explanation": "「モンスターを絵を描いて」となり、目的語が二つ続いて文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の助詞で、「モンスターより絵を描く」は比べる文になり、絵の対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「モンスターから絵を描く」は出どころの意味になり、絵との結びつきが合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「モンスターの絵」として、絵の対象を示す「の」。", "を": "「モンスターを絵を描いて」となり、目的語が二つ続いて文が成り立たない。", "より": "「より」は比較の助詞で、「モンスターより絵を描く」は比べる文になり、絵の対象を示せない。", "から": "「から」は起点を表すので、「モンスターから絵を描く」は出どころの意味になり、絵との結びつきが合わない。"}, "error_tags": {"を": "目的語の格（絵を描く）", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37322, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ゲームの中に出てくる、こわい生き物のことです。", "primary_collocate": null, "pronunciation": "もんすたー", "ipa": "monsɯtaː", "syllable_count": 5, "sentences": [{"text": "ゲームの中で、大きなモンスターと戦いました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "ゲームの中[なか]で、大[おお]きなモンスターと戦[たたか]いました。", "sentence_source": "generated"}, {"text": "このモンスターは、火をはいて勇者を追いかけてきます。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "このモンスターは、火[ひ]をはいて勇者[ゆうしゃ]を追[お]いかけてきます。", "sentence_source": "generated"}, {"text": "弟はモンスターが出てくるゲームが大好きです。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "弟[おとうと]はモンスターが出[で]てくるゲームが大好[だいす]きです。", "sentence_source": "generated"}, {"text": "洞窟の奥に、こわいモンスターがかくれています。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の奥[おく]に、こわいモンスターがかくれています。", "sentence_source": "generated"}, {"text": "モンスターを倒すと、アイテムがもらえます。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "モンスターを倒[たお]すと、アイテムがもらえます。", "sentence_source": "generated"}, {"text": "夜のダンジョンでは、強いモンスターが多いので気をつけます。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "夜[よる]のダンジョンでは、強[つよ]いモンスターが多[おお]いので気[き]をつけます。", "sentence_source": "generated"}, {"text": "画面に突然モンスターが出て、私は声を上げました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "画面[がめん]に突然[とつぜん]モンスターが出[で]て、私[わたし]は声[こえ]を上[あ]げました。", "sentence_source": "generated"}, {"text": "友達とモンスターの絵を描いて、名前をつけました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "友達[ともだち]とモンスターの絵[え]を描[か]いて、名前[なまえ]をつけました。", "sentence_source": "generated"}, {"text": "このゲームでは、モンスターを仲間にして育てられます。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "このゲームでは、モンスターを仲間[なかま]にして育[そだ]てられます。", "sentence_source": "generated"}, {"text": "ボスのモンスターは強くて、何度も負けてしまいました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "ボスのモンスターは強[つよ]くて、何度[なんど]も負[ま]けてしまいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "モンスター", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "ゲームに登場して戦う相手になるこわい生き物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a7c10f-7617-45e5-a3d0-bcfe1bdfc1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37322, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "モンスター", "is_correct": true, "explanation": "正解。「大きなモンスター」は、戦う相手になる生き物として文脈に合う。"}, {"text": "ゲーム", "is_correct": false, "explanation": "「大きなゲームと戦う」では、遊ぶものを戦う相手にすることになり、意味が通らない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は読んで学ぶもので、戦う相手にはならないので文に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は戦う対象ではないので、「大きな天気と戦いました」は不自然で合わない。"}], "explanations": {"モンスター": "正解。「大きなモンスター」は、戦う相手になる生き物として文脈に合う。", "ゲーム": "「大きなゲームと戦う」では、遊ぶものを戦う相手にすることになり、意味が通らない。", "教科書": "教科書は読んで学ぶもので、戦う相手にはならないので文に合わない。", "天気": "天気は戦う対象ではないので、「大きな天気と戦いました」は不自然で合わない。"}, "sentence_index": 0, "correct_answer": "モンスター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は打撃のモンスターと呼ばれ、毎年たくさんホームランを打ちます。", "explanation": "ここは〈並外れた力を持つ人〉のたとえの意味。こわい生き物の意味ではない。"}, {"text": "夜中の作業を乗り切るため、缶のモンスターを一本開けました。", "explanation": "ここはエナジードリンクを指す俗称の意味。ゲームに出る生き物とは別。"}, {"text": "ライバル社のモンスター企業が、市場の半分を握っています。", "explanation": "ここは〈巨大で強い存在〉のたとえの意味。ゲームの生き物とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37322, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "モンスター", "is_correct": true, "explanation": "正解。「画面に突然モンスターが出て」は、驚いて声を上げる対象として自然。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機が画面に突然出ることは考えにくく、声を上げる対象にもならないので文に合わない。"}, {"text": "ふとん", "is_correct": false, "explanation": "ふとんが画面に出てくるのは不自然で、文の意味が通らない。"}, {"text": "電子レンジ", "is_correct": false, "explanation": "電子レンジは画面に現れるものではないので、この文には合わない。"}], "explanations": {"モンスター": "正解。「画面に突然モンスターが出て」は、驚いて声を上げる対象として自然。", "洗濯機": "洗濯機が画面に突然出ることは考えにくく、声を上げる対象にもならないので文に合わない。", "ふとん": "ふとんが画面に出てくるのは不自然で、文の意味が通らない。", "電子レンジ": "電子レンジは画面に現れるものではないので、この文には合わない。"}, "sentence_index": 6, "correct_answer": "モンスター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい社長は、業界のモンスターと呼ばれるほどの成功者です。", "explanation": "ここは〈並外れた力を持つ人〉のたとえの意味。こわい生き物の意味ではない。"}, {"text": "コンビニで、眠気覚ましの缶のモンスターを買いました。", "explanation": "ここはエナジードリンクを指す俗称の意味。ゲームの生き物とは別。"}, {"text": "学校には、要求の多いモンスターペアレントがいるそうです。", "explanation": "ここは〈非常識な要求をする保護者〉の意味。ゲームの生き物とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37322, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "森には、こわいモンスターに住んでいます。", "corrected_sentence": "森には、こわいモンスターが住んでいます。", "error_description": "「住む」の主語は「が」で示す。「に」にすると、モンスターを住む場所のように扱う形になり不自然。正しくは「モンスターが住んでいます」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37322, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "勇者はモンスターを襲われました。", "corrected_sentence": "勇者はモンスターに襲われました。", "error_description": "「襲う」の相手は「に」で示す。「を」にすると目的語になり、受身の文として成り立たない。正しくは「モンスターに襲われました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37323, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「映画のモンスターを見て」で、見る対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「見る」は対象に「を」を取るので、「映画のモンスターに見て」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すため、「モンスターで見て」は見る対象を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「モンスターへ見て」は見る対象を示せず合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「映画のモンスターを見て」で、見る対象を示す「を」。", "に": "「見る」は対象に「を」を取るので、「映画のモンスターに見て」は成り立たない。", "で": "「で」は手段や場所を表すため、「モンスターで見て」は見る対象を示せず不自然。", "へ": "「へ」は方向を表すので、「モンスターへ見て」は見る対象を示せず合わない。"}, "error_tags": {"に": "格の不一致（見る対象は「を」）", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37323, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「おびえる」は「に」で対象を示すので、「モンスターに」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「おびえる」は「を」を取らないので、「モンスターを、船の人はおびえました」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐだけで、「モンスターの、船の人はおびえました」は文が続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、おびえる対象にはならないので合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。「おびえる」は「に」で対象を示すので、「モンスターに」が自然。", "を": "「おびえる」は「を」を取らないので、「モンスターを、船の人はおびえました」は成り立たない。", "の": "名詞をつなぐだけで、「モンスターの、船の人はおびえました」は文が続かない。", "へ": "「へ」は方向を表し、おびえる対象にはならないので合わない。"}, "error_tags": {"を": "おびえる対象の格（「おびえる」は「に」）", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37323, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ファンタジーやゲームなどに登場する、人間をこわがらせるような大きな生き物。", "primary_collocate": null, "pronunciation": "もんすたー", "ipa": "monsɯtaː", "syllable_count": 5, "sentences": [{"text": "物語の森には、人をおそう巨大なモンスターが住んでいます。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "物語[ものがたり]の森[もり]には、人[ひと]をおそう巨大[きょだい]なモンスターが住[す]んでいます。", "sentence_source": "generated"}, {"text": "映画のモンスターを見て、小さな子が泣き出しました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "映画[えいが]のモンスターを見[み]て、小[ちい]さな子[こ]が泣[な]き出[だ]しました。", "sentence_source": "generated"}, {"text": "勇者はモンスターから村を守るため、旅に出ました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "勇者[ゆうしゃ]はモンスターから村[むら]を守[まも]るため、旅[たび]に出[で]ました。", "sentence_source": "generated"}, {"text": "そのモンスターは山のように大きく、足音で地面がゆれました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "そのモンスターは山[やま]のように大[おお]きく、足音[あしおと]で地面[じめん]がゆれました。", "sentence_source": "generated"}, {"text": "魔法使いが、湖にいるモンスターの話をしてくれました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "魔法使[まほうつか]いが、湖[みずうみ]にいるモンスターの話[はなし]をしてくれました。", "sentence_source": "generated"}, {"text": "ファンタジーの小説では、モンスターが人間をこわがらせます。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "ファンタジーの小説[しょうせつ]では、モンスターが人間[にんげん]をこわがらせます。", "sentence_source": "generated"}, {"text": "ドラゴンのようなモンスターが空から降りてきました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "ドラゴンのようなモンスターが空[そら]から降[お]りてきました。", "sentence_source": "generated"}, {"text": "夜の海から現れたモンスターに、船の人はおびえました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "夜[よる]の海[うみ]から現[あらわ]れたモンスターに、船[ふね]の人[ひと]はおびえました。", "sentence_source": "generated"}, {"text": "絵本のモンスターは大きな口で、ほえていました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "絵本[えほん]のモンスターは大[おお]きな口[くち]で、ほえていました。", "sentence_source": "generated"}, {"text": "王様は、町をこわすモンスターを倒す人を探しました。", "target_word": "モンスター", "complexity_tier": "T3", "furigana": "王様[おうさま]は、町[まち]をこわすモンスターを倒[たお]す人[ひと]を探[さが]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "モンスター", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "物語や映画に出てくる人をおびえさせる巨大な怪物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: こわがら (Zipf 1.87)']::text[], '30a7c10f-7617-45e5-a3d0-bcfe1bdfc1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37323, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "モンスター", "is_correct": true, "explanation": "正解。「人をおそう巨大な」に合う、人をこわがらせる大きな生き物。"}, {"text": "妖精", "is_correct": false, "explanation": "妖精は小さくやさしいものなので、「人をおそう巨大な」と意味が矛盾する。"}, {"text": "王子", "is_correct": false, "explanation": "王子は人をおそう巨大な存在ではないので、この文には合わない。"}, {"text": "宝箱", "is_correct": false, "explanation": "宝箱は人をおそわないので、「人をおそう巨大な宝箱」は文の意味が通らない。"}], "explanations": {"モンスター": "正解。「人をおそう巨大な」に合う、人をこわがらせる大きな生き物。", "妖精": "妖精は小さくやさしいものなので、「人をおそう巨大な」と意味が矛盾する。", "王子": "王子は人をおそう巨大な存在ではないので、この文には合わない。", "宝箱": "宝箱は人をおそわないので、「人をおそう巨大な宝箱」は文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "モンスター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は打撃のモンスターと呼ばれ、毎年たくさんホームランを打ちます。", "explanation": "ここは〈並外れた力を持つ人〉のたとえの意味。こわい生き物の意味ではない。"}, {"text": "夜中の作業を乗り切るため、缶のモンスターを一本開けました。", "explanation": "ここはエナジードリンクを指す俗称の意味。ゲームに出る生き物とは別。"}, {"text": "ライバル社のモンスター企業が、市場の半分を握っています。", "explanation": "ここは〈巨大で強い存在〉のたとえの意味。ゲームの生き物とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37323, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "モンスター", "is_correct": true, "explanation": "正解。「ドラゴンのような」の後に入り、空から降りてくる生き物として自然。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "ハンカチが空から降りてくることは考えにくく、「ドラゴンのような」とも合わない。"}, {"text": "ランドセル", "is_correct": false, "explanation": "ランドセルは空から降りてくる生き物ではないので、この文には合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は「ドラゴンのような」と結びつかず、空から降りてくる文の意味が通らない。"}], "explanations": {"モンスター": "正解。「ドラゴンのような」の後に入り、空から降りてくる生き物として自然。", "ハンカチ": "ハンカチが空から降りてくることは考えにくく、「ドラゴンのような」とも合わない。", "ランドセル": "ランドセルは空から降りてくる生き物ではないので、この文には合わない。", "教科書": "教科書は「ドラゴンのような」と結びつかず、空から降りてくる文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "モンスター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい社長は、業界のモンスターと呼ばれるほどの成功者です。", "explanation": "ここは〈並外れた力を持つ人〉のたとえの意味。こわい生き物の意味ではない。"}, {"text": "コンビニで、眠気覚ましの缶のモンスターを買いました。", "explanation": "ここはエナジードリンクを指す俗称の意味。人をこわがらせる生き物とは別。"}, {"text": "学校には、要求の多いモンスターペアレントがいるそうです。", "explanation": "ここは〈非常識な要求をする保護者〉の意味。生き物の意味とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37323, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "勇者は、モンスターに戦うために旅をしました。", "corrected_sentence": "勇者は、モンスターと戦うために旅をしました。", "error_description": "「戦う」の相手は「と」で示す。「に」では相手を表せず、「モンスターに戦う」は文として成り立たない。正しくは「モンスターと戦う」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37323, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村人は、モンスターを追われて逃げました。", "corrected_sentence": "村人は、モンスターに追われて逃げました。", "error_description": "受身文で、追う側（動作主）は「に」で示す。「を」にすると、「追われる」の目的語として成り立たない。正しくは「モンスターに追われて逃げました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37324, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「戦う」は相手を示す「と」を取る。「魔王と戦う」で相手を表す。ここに入る正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「戦う」は目的語に「を」を取らず、「魔王を戦う」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象や方向を示すが、「戦う」は「と」で相手を示すので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「魔王へ戦う」は成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「戦う」は相手を示す「と」を取る。「魔王と戦う」で相手を表す。ここに入る正しい助詞。", "を": "「戦う」は目的語に「を」を取らず、「魔王を戦う」は不自然。", "に": "「に」は対象や方向を示すが、「戦う」は「と」で相手を示すので合わない。", "へ": "「へ」は方向を示すので、「魔王へ戦う」は成り立たない。"}, "error_tags": {"を": "目的語", "に": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37324, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "「最後まで」で続く時間や範囲を示し、そこに「戦う」がつながる。ここに入る正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「最後を戦う」は目的語として成り立たず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「最後の戦う」は名詞修飾の形にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「最後へ戦う」は成り立たない。"}], "correct_answer": "まで", "explanations": {"まで": "「最後まで」で続く時間や範囲を示し、そこに「戦う」がつながる。ここに入る正しい助詞。", "を": "「最後を戦う」は目的語として成り立たず、不自然。", "の": "「最後の戦う」は名詞修飾の形にならず、文が成り立たない。", "へ": "「へ」は方向を示すので、「最後へ戦う」は成り立たない。"}, "error_tags": {"を": "目的語", "の": "名詞修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37324, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "てきを うちまけようと する こと。", "primary_collocate": null, "pronunciation": "たたかう", "ipa": "tatakaɯ", "syllable_count": 4, "sentences": [{"text": "兵士たちは、国を守るために敵と戦った。", "target_word": "戦った", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは、国[くに]を守[まも]るために敵[てき]と戦[たたか]った。", "sentence_source": "generated"}, {"text": "勇者は、剣を持って魔王と戦う。", "target_word": "戦う", "complexity_tier": "T3", "furigana": "勇者[ゆうしゃ]は、剣[けん]を持[も]って魔王[まおう]と戦[たたか]う。", "sentence_source": "generated"}, {"text": "小さな国は、大きな国と何年も戦っていた。", "target_word": "戦って", "complexity_tier": "T3", "furigana": "小[ちい]さな国[くに]は、大[おお]きな国[くに]と何年[なんねん]も戦[たたか]っていた。", "sentence_source": "generated"}, {"text": "戦う前に、王様は兵士たちに水を配った。", "target_word": "戦う", "complexity_tier": "T3", "furigana": "戦[たたか]う前[まえ]に、王様[おうさま]は兵士[へいし]たちに水[みず]を配[くば]った。", "sentence_source": "generated"}, {"text": "ライオンは、群れを守るために敵と戦う。", "target_word": "戦う", "complexity_tier": "T3", "furigana": "ライオンは、群[む]れを守[まも]るために敵[てき]と戦[たたか]う。", "sentence_source": "generated"}, {"text": "村人は力を合わせて、盗賊と戦った。", "target_word": "戦った", "complexity_tier": "T3", "furigana": "村人[むらびと]は力[ちから]を合[あ]わせて、盗賊[とうぞく]と戦[たたか]った。", "sentence_source": "generated"}, {"text": "戦いたくない兵士もいたが、命令には逆らえなかった。", "target_word": "戦いたくない", "complexity_tier": "T3", "furigana": "戦[たたか]いたくない兵士[へいし]もいたが、命令[めいれい]には逆[さか]らえなかった。", "sentence_source": "generated"}, {"text": "侍は、主君のために最後まで戦う覚悟をした。", "target_word": "戦う", "complexity_tier": "T3", "furigana": "侍[さむらい]は、主君[しゅくん]のために最後[さいご]まで戦[たたか]う覚悟[かくご]をした。", "sentence_source": "generated"}, {"text": "町を取り戻すため、住民は敵の軍と戦った。", "target_word": "戦った", "complexity_tier": "T3", "furigana": "町[まち]を取[と]り戻[もど]すため、住民[じゅうみん]は敵[てき]の軍[ぐん]と戦[たたか]った。", "sentence_source": "generated"}, {"text": "敵の城を囲んで、武士たちは夜明けまで戦った。", "target_word": "戦った", "complexity_tier": "T3", "furigana": "敵[てき]の城[しろ]を囲[かこ]んで、武士[ぶし]たちは夜明[よあ]けまで戦[たたか]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦った", "label": "過去形"}, {"form": "戦って", "label": "て形"}, {"form": "戦わない", "label": "否定形"}, {"form": "戦える", "label": "可能形"}, {"form": "戦えば", "label": "仮定形"}], "register": "標準・常体", "sense_fingerprint": "敵を倒そうと、武器や力を使って実際に争う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37324, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戦った", "is_correct": true, "explanation": "過去形で、過去の出来事として「敵と戦った」と述べる。ここに入る正しい形。"}, {"text": "戦って", "is_correct": false, "explanation": "て形は文を終えられず、「敵と戦って。」では文が成り立たない。"}, {"text": "戦わせ", "is_correct": false, "explanation": "使役の連用形は文を終えられず、「戦わせ」で文が切れない。"}, {"text": "戦えなく", "is_correct": false, "explanation": "「なく」で止まる形は文を終えられず、「戦えなく。」は不自然。"}], "explanations": {"戦った": "過去形で、過去の出来事として「敵と戦った」と述べる。ここに入る正しい形。", "戦って": "て形は文を終えられず、「敵と戦って。」では文が成り立たない。", "戦わせ": "使役の連用形は文を終えられず、「戦わせ」で文が切れない。", "戦えなく": "「なく」で止まる形は文を終えられず、「戦えなく。」は不自然。"}, "sentence_index": 0, "correct_answer": "戦った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "リーグ戦で、二つのチームが優勝をかけて戦った。", "explanation": "ここは〈競う〉の意味。勝ち負けを競う場面で〈戦う〉を使うと、敵を打ち負かす意味とは違うので合わない。"}, {"text": "怖くて、膝が戦った。", "explanation": "ここは〈戦く〉（おののく）の意味。恐怖で震えることは〈戦く〉で、〈戦う〉とは別の語。"}, {"text": "台風で、船が岸壁と戦った。", "explanation": "ここは〈衝突〉の意味。ぶつかることは〈衝突〉で言い、〈戦う〉は争う相手に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37324, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戦いたくない", "is_correct": true, "explanation": "「戦いたくない」で、後ろの「兵士」を修飾する形として成り立つ。ここに入る正しい形。"}, {"text": "戦いたくなく", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「兵士」にかからない。"}, {"text": "戦いたくても", "is_correct": false, "explanation": "逆接の形は名詞を修飾できず、「兵士」に続けられない。"}, {"text": "戦いたくて", "is_correct": false, "explanation": "て形は名詞を修飾できず、「戦いたくて兵士」は成り立たない。"}], "explanations": {"戦いたくない": "「戦いたくない」で、後ろの「兵士」を修飾する形として成り立つ。ここに入る正しい形。", "戦いたくなく": "連用形は名詞を直接修飾できず、「兵士」にかからない。", "戦いたくても": "逆接の形は名詞を修飾できず、「兵士」に続けられない。", "戦いたくて": "て形は名詞を修飾できず、「戦いたくて兵士」は成り立たない。"}, "sentence_index": 6, "correct_answer": "戦いたくない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒さで、手が戦った。", "explanation": "ここは〈震える〉の意味。寒さで体が震えることは〈震える〉で言い、〈戦う〉の意味では使わない。"}, {"text": "地震で、建物が地面と戦った。", "explanation": "ここは〈衝突〉の意味。ぶつかることは〈衝突〉で言い、〈戦う〉とは言わない。"}, {"text": "店の前で、客たちが店員とゲームで戦った。", "explanation": "ここは〈勝負する〉の意味。ゲームで勝ち負けを競う場面の〈戦う〉で、敵を打ち負かす意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37324, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "勇者は魔王を戦うために、旅に出た。", "corrected_sentence": "勇者は魔王と戦うために、旅に出た。", "error_description": "誤りは「戦う」に付く助詞が「を」になっている点。正しくは「と」で、相手を表す「魔王と戦う」になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "戦う", "is_correct": true, "explanation": "辞書形で、文末の現在・未来の形。ここで使われている正しい形。"}, {"text": "戦えば", "is_correct": false, "explanation": "仮定形は文を終えられず、「勇者は…魔王と戦えば。」で文が切れる。"}, {"text": "戦って", "is_correct": false, "explanation": "て形は文を終えられず、文末に置けない。"}, {"text": "戦わせ", "is_correct": false, "explanation": "使役の連用形は文を終えられず、「戦わせ。」では文が成り立たない。"}], "correct_form": "戦う", "base_form": "戦う", "form_label": "辞書形", "sentence_index": 1, "explanations": {"戦う": "辞書形で、文末の現在・未来の形。ここで使われている正しい形。", "戦えば": "仮定形は文を終えられず、「勇者は…魔王と戦えば。」で文が切れる。", "戦って": "て形は文を終えられず、文末に置けない。", "戦わせ": "使役の連用形は文を終えられず、「戦わせ。」では文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37324, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "侍は、主君のために最後まで戦ったで、覚悟をした。", "corrected_sentence": "侍は、主君のために最後まで戦って、覚悟をした。", "error_description": "誤りは「戦って」の「って」が「ったで」になっている点。正しくは「戦って」（て形）で、後ろの「覚悟をした」につながる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "戦う", "is_correct": true, "explanation": "辞書形で、後ろの「覚悟」を修飾する形として正しい。ここで使われている形。"}, {"text": "戦え", "is_correct": false, "explanation": "命令形は文を言い切る形で、名詞「覚悟」を修飾できず、「戦え覚悟」は成り立たない。"}, {"text": "戦おう", "is_correct": false, "explanation": "意志形は文を言い切る形で、名詞「覚悟」を修飾できず、「戦おう覚悟」は成り立たない。"}, {"text": "戦わず", "is_correct": false, "explanation": "ず形（否定の連用形）は名詞を直接修飾できず、「戦わず覚悟」は不自然で成り立たない。"}], "correct_form": "戦う", "base_form": "戦う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"戦う": "辞書形で、後ろの「覚悟」を修飾する形として正しい。ここで使われている形。", "戦え": "命令形は文を言い切る形で、名詞「覚悟」を修飾できず、「戦え覚悟」は成り立たない。", "戦おう": "意志形は文を言い切る形で、名詞「覚悟」を修飾できず、「戦おう覚悟」は成り立たない。", "戦わず": "ず形（否定の連用形）は名詞を直接修飾できず、「戦わず覚悟」は不自然で成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37325, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「戦う」は相手を示す「と」を取る。「相手と戦う」で勝敗を競う相手を表す。ここに入る正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「戦う」は目的語に「を」を取らず、「相手を戦う」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象や方向を示すが、「戦う」は「と」で相手を示すので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「相手へ戦う」は成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「戦う」は相手を示す「と」を取る。「相手と戦う」で勝敗を競う相手を表す。ここに入る正しい助詞。", "を": "「戦う」は目的語に「を」を取らず、「相手を戦う」は不自然。", "に": "「に」は対象や方向を示すが、「戦う」は「と」で相手を示すので合わない。", "へ": "「へ」は方向を示すので、「相手へ戦う」は成り立たない。"}, "error_tags": {"を": "目的語", "に": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37325, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「全力で戦えば」で、戦い方や手段を示す「で」。ここに入る正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「全力が戦えば」では「全力」が主語になり、人が戦うという意味が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「全力から戦えば」は起点を示す形で、戦い方を表す「で」の代わりにならない。"}, {"text": "より", "is_correct": false, "explanation": "「全力より戦えば」は比較の形で、ここでは戦い方を表せず不自然。"}], "correct_answer": "で", "explanations": {"で": "「全力で戦えば」で、戦い方や手段を示す「で」。ここに入る正しい助詞。", "が": "「全力が戦えば」では「全力」が主語になり、人が戦うという意味が成り立たない。", "から": "「全力から戦えば」は起点を示す形で、戦い方を表す「で」の代わりにならない。", "より": "「全力より戦えば」は比較の形で、ここでは戦い方を表せず不自然。"}, "error_tags": {"が": "主格", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37325, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "互いに勝ち負けを競うために、力や技を出し合って争う。", "primary_collocate": null, "pronunciation": "たたかう", "ipa": "tatakaɯ", "syllable_count": 4, "sentences": [{"text": "決勝で、日本の選手がブラジルの選手と戦う。", "target_word": "戦う", "complexity_tier": "T3", "furigana": "決勝[けっしょう]で、日本[にほん]の選手[せんしゅ]がブラジルの選手[せんしゅ]と戦[たたか]う。", "sentence_source": "generated"}, {"text": "私たちのチームは、強い相手と戦って、一対〇で勝った。", "target_word": "戦って", "complexity_tier": "T3", "furigana": "私[わたし]たちのチームは、強[つよ]い相手[あいて]と戦[たたか]って、一対〇[いちたいぜろ]で勝[か]った。", "sentence_source": "generated"}, {"text": "彼女は、ボクシングの世界王者と戦うために練習している。", "target_word": "戦う", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、ボクシングの世界王者[せかいおうじゃ]と戦[たたか]うために練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "二人は将棋で、タイトルをかけて戦った。", "target_word": "戦った", "complexity_tier": "T3", "furigana": "二人[ふたり]は将棋[しょうぎ]で、タイトルをかけて戦[たたか]った。", "sentence_source": "generated"}, {"text": "全国大会で戦うには、まず県大会で勝たなければならない。", "target_word": "戦う", "complexity_tier": "T3", "furigana": "全国大会[ぜんこくたいかい]で戦[たたか]うには、まず県大会[けんたいかい]で勝[か]たなければならない。", "sentence_source": "generated"}, {"text": "選手たちは、最後まで正々堂々と戦った。", "target_word": "戦った", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは、最後[さいご]まで正々堂々[せいせいどうどう]と戦[たたか]った。", "sentence_source": "generated"}, {"text": "弟は、同じクラスの友達とゲームで戦うのが好きだ。", "target_word": "戦う", "complexity_tier": "T3", "furigana": "弟[おとうと]は、同[おな]じクラスの友達[ともだち]とゲームで戦[たたか]うのが好[す]きだ。", "sentence_source": "generated"}, {"text": "相手が強くても、全力で戦えば悔いは残らない。", "target_word": "戦えば", "complexity_tier": "T3", "furigana": "相手[あいて]が強[つよ]くても、全力[ぜんりょく]で戦[たたか]えば悔[く]いは残[のこ]らない。", "sentence_source": "generated"}, {"text": "今夜は、兄の学校が野球の準決勝で戦う。", "target_word": "戦う", "complexity_tier": "T3", "furigana": "今夜[こんや]は、兄[あに]の学校[がっこう]が野球[やきゅう]の準決勝[じゅんけっしょう]で戦[たたか]う。", "sentence_source": "generated"}, {"text": "大会では、世界じゅうの選手が金メダルをかけて戦う。", "target_word": "戦う", "complexity_tier": "T3", "furigana": "大会[たいかい]では、世界[せかい]じゅうの選手[せんしゅ]が金[きん]メダルをかけて戦[たたか]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦った", "label": "過去形"}, {"form": "戦って", "label": "て形"}, {"form": "戦わない", "label": "否定形"}, {"form": "戦える", "label": "可能形"}, {"form": "戦えば", "label": "仮定形"}], "register": "標準・常体", "sense_fingerprint": "試合や勝負で、力や技を出して相手と勝敗を競う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 世界じゅう (Zipf 2.13)']::text[], '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37325, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戦う", "is_correct": true, "explanation": "辞書形で、「決勝で〜と戦う」と予定を述べる文として成り立つ。ここに入る正しい形。"}, {"text": "戦って", "is_correct": false, "explanation": "て形は文を終えられず、「ブラジルの選手と戦って。」では文が成り立たない。"}, {"text": "戦わせ", "is_correct": false, "explanation": "使役の連用形は文を終えられず、文が成り立たない。"}, {"text": "戦えば", "is_correct": false, "explanation": "仮定形は続く文がなければ成り立たず、「戦えば。」で文が切れる。"}], "explanations": {"戦う": "辞書形で、「決勝で〜と戦う」と予定を述べる文として成り立つ。ここに入る正しい形。", "戦って": "て形は文を終えられず、「ブラジルの選手と戦って。」では文が成り立たない。", "戦わせ": "使役の連用形は文を終えられず、文が成り立たない。", "戦えば": "仮定形は続く文がなければ成り立たず、「戦えば。」で文が切れる。"}, "sentence_index": 0, "correct_answer": "戦う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その頃、兵士たちは国境の町で戦った。", "explanation": "ここは〈戦争する〉の意味。国や軍が武力で敵と争うことで、勝ち負けを競う〈戦う〉とは違うので合わない。"}, {"text": "重い荷物で、腕が戦った。", "explanation": "ここは〈戦く〉（おののく）の意味。重さで腕が震えることは〈戦く〉で、〈戦う〉とは別の語。"}, {"text": "強い風で、旗が電線と戦った。", "explanation": "ここは〈衝突〉の意味。ぶつかることは〈衝突〉で言い、〈戦う〉は勝敗を競う相手に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37325, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戦う", "is_correct": true, "explanation": "辞書形で、後ろの「のが好きだ」につながり、好みを述べる文が成り立つ。ここに入る正しい形。"}, {"text": "戦えなく", "is_correct": false, "explanation": "「なく」で止まる形は「のが」に続かず、文が成り立たない。"}, {"text": "戦え", "is_correct": false, "explanation": "命令形は文を言い切る形で、「のが」に続けられず成り立たない。"}, {"text": "戦わ", "is_correct": false, "explanation": "未然形だけでは「のが」に続かず、「戦わのが」は文が成り立たない。"}], "explanations": {"戦う": "辞書形で、後ろの「のが好きだ」につながり、好みを述べる文が成り立つ。ここに入る正しい形。", "戦えなく": "「なく」で止まる形は「のが」に続かず、文が成り立たない。", "戦え": "命令形は文を言い切る形で、「のが」に続けられず成り立たない。", "戦わ": "未然形だけでは「のが」に続かず、「戦わのが」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "戦う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕立で、庭の草花が雨と戦った。", "explanation": "ここは〈しおれる〉の意味。草花が弱ることは〈戦う〉では言わず、〈しおれる〉などを使う。"}, {"text": "その年の冬、山の村人たちは大雪と戦った。", "explanation": "ここは〈耐える〉の意味。雪や寒さに耐え忍ぶことは〈耐える〉で言い、勝ち負けを競う〈戦う〉とは違う。"}, {"text": "選手は、寒さで指が戦った。", "explanation": "ここは〈戦く〉（おののく）の意味。寒さで指が震えることは〈戦く〉で言い、〈戦う〉とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37325, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "決勝で、強いチームを戦うために練習した。", "corrected_sentence": "決勝で、強いチームと戦うために練習した。", "error_description": "誤りは「戦う」に付く助詞が「を」になっている点。正しくは「と」で、相手を表す「強いチームと戦う」になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "戦って", "is_correct": true, "explanation": "て形で、後ろの「勝った」へ続けて結果を述べる。ここで使われている正しい形。"}, {"text": "戦おう", "is_correct": false, "explanation": "意志形は文を言い切る形で、「、」で続けて「勝った」へつなぐと不自然。"}, {"text": "戦う", "is_correct": false, "explanation": "辞書形は文を終える形で、後ろの「勝った」へ続けられない。"}, {"text": "戦わない", "is_correct": false, "explanation": "否定形にすると「戦わず勝った」という意味になり、文の内容が変わる。"}], "correct_form": "戦って", "base_form": "戦う", "form_label": "て形", "sentence_index": 1, "explanations": {"戦って": "て形で、後ろの「勝った」へ続けて結果を述べる。ここで使われている正しい形。", "戦おう": "意志形は文を言い切る形で、「、」で続けて「勝った」へつなぐと不自然。", "戦う": "辞書形は文を終える形で、後ろの「勝った」へ続けられない。", "戦わない": "否定形にすると「戦わず勝った」という意味になり、文の内容が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37325, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強いチームを戦ったことがある。", "corrected_sentence": "強いチームと戦ったことがある。", "error_description": "誤りは「戦った」に付く助詞が「を」になっている点。正しくは「と」で、相手を表す「強いチームと戦った」になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "戦えば", "is_correct": true, "explanation": "仮定形で、「〜すれば〜ない」という条件の文を作る。ここで使われている正しい形。"}, {"text": "戦え", "is_correct": false, "explanation": "命令形は文を言い切る形で、「戦え、悔いは残らない」と条件の文にならない。"}, {"text": "戦わせ", "is_correct": false, "explanation": "使役の連用形は条件の文を作れず、「戦わせ、悔いは残らない」は意味が合わない。"}, {"text": "戦おう", "is_correct": false, "explanation": "意志形は文を言い切る形で、「戦おう、悔いは残らない」と条件の文にならない。"}], "correct_form": "戦えば", "base_form": "戦う", "form_label": "仮定形", "sentence_index": 7, "explanations": {"戦えば": "仮定形で、「〜すれば〜ない」という条件の文を作る。ここで使われている正しい形。", "戦え": "命令形は文を言い切る形で、「戦え、悔いは残らない」と条件の文にならない。", "戦わせ": "使役の連用形は条件の文を作れず、「戦わせ、悔いは残らない」は意味が合わない。", "戦おう": "意志形は文を言い切る形で、「戦おう、悔いは残らない」と条件の文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37326, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「チームワークがよくて」で、よい状態の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「よい」は目的語を取らないので、「チームワークをよくて」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「チームワークへよくて」は状態の主語を示せず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を表すので、「チームワークからよくて」は主語を示せず合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「チームワークがよくて」で、よい状態の主語を示す「が」。", "を": "「よい」は目的語を取らないので、「チームワークをよくて」は成り立たない。", "へ": "「へ」は方向を示すので、「チームワークへよくて」は状態の主語を示せず不自然。", "から": "「から」は起点や理由を表すので、「チームワークからよくて」は主語を示せず合わない。"}, "error_tags": {"を": "目的語の格", "へ": "方向（誤用）", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
