INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37326, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなで力をあわせて、ひとつのことをすることです。", "primary_collocate": null, "pronunciation": "ちーむわーく", "ipa": "tɕiːmɯwaːkɯ", "syllable_count": 6, "sentences": [{"text": "クラスの劇は、チームワークのおかげで成功しました。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "クラスの劇[げき]は、チームワークのおかげで成功[せいこう]しました。", "sentence_source": "generated"}, {"text": "チームワークがよくて、私たちは試合に勝ちました。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "チームワークがよくて、私[わたし]たちは試合[しあい]に勝[か]ちました。", "sentence_source": "generated"}, {"text": "掃除はチームワークが大切で、一人でするより早く終わります。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "掃除[そうじ]はチームワークが大切[たいせつ]で、一人[ひとり]でするより早[はや]く終[お]わります。", "sentence_source": "generated"}, {"text": "合唱は、チームワークがないときれいに歌えません。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "合唱[がっしょう]は、チームワークがないときれいに歌[うた]えません。", "sentence_source": "generated"}, {"text": "チームワークを高めるために、みんなで山に登りました。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "チームワークを高[たか]めるために、みんなで山[やま]に登[のぼ]りました。", "sentence_source": "generated"}, {"text": "運動会の綱引きでは、チームワークが勝つ決め手です。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の綱[つな]引[ひ]きでは、チームワークが勝[か]つ決[き]め手[て]です。", "sentence_source": "generated"}, {"text": "誰かが休んでも、チームワークで仕事を回しました。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "誰[だれ]かが休[やす]んでも、チームワークで仕事[しごと]を回[まわ]しました。", "sentence_source": "generated"}, {"text": "私たちのチームは、チームワークだけは負けません。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "私[わたし]たちのチームは、チームワークだけは負[ま]けません。", "sentence_source": "generated"}, {"text": "チームワークが悪いと、小さなことで言い合いになります。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "チームワークが悪[わる]いと、小[ちい]さなことで言[い]い合[あ]いになります。", "sentence_source": "generated"}, {"text": "料理の係は、チームワークよくカレーを作りました。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "料理[りょうり]の係[かかり]は、チームワークよくカレーを作[つく]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チームワーク", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "仲間と力を合わせてひとつのことに取り組むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a7c10f-7617-45e5-a3d0-bcfe1bdfc1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37326, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チームワーク", "is_correct": true, "explanation": "正解。「チームワークのおかげで成功」として、協力の力が成功の理由になる。"}, {"text": "居眠り", "is_correct": false, "explanation": "居眠りは成功の理由にならず、「居眠りのおかげで成功」は文の意味が通らない。"}, {"text": "忘れ物", "is_correct": false, "explanation": "忘れ物は成功の原因にはならないので、この文には合わない。"}, {"text": "遅刻", "is_correct": false, "explanation": "遅刻は成功の理由にならず、「遅刻のおかげで成功」は文に合わない。"}], "explanations": {"チームワーク": "正解。「チームワークのおかげで成功」として、協力の力が成功の理由になる。", "居眠り": "居眠りは成功の理由にならず、「居眠りのおかげで成功」は文の意味が通らない。", "忘れ物": "忘れ物は成功の原因にはならないので、この文には合わない。", "遅刻": "遅刻は成功の理由にならず、「遅刻のおかげで成功」は文に合わない。"}, "sentence_index": 0, "correct_answer": "チームワーク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女はパソコンのチームワークが高く、資料をすぐ作れます。", "explanation": "ここは〈スキル〉（腕前）の意味。チームワークは人との協力を指すので、パソコンの腕前の高さには使えないので合わない。"}, {"text": "彼は歴史のチームワークが豊富で、何でも答えてくれます。", "explanation": "ここは「知識」の意味。歴史の知識を指すので、協力の意味のチームワークとは合わない。"}, {"text": "やかんのチームワークが、ぐらぐら沸きました。", "explanation": "ここは〈お湯〉（熱い水）の意味。チームワークは協力のことで、水が沸くものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37326, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チームワーク", "is_correct": true, "explanation": "正解。「チームワークで仕事を回しました」として、協力して仕事を進めた意味になる。"}, {"text": "ふとん", "is_correct": false, "explanation": "ふとんで仕事を回すことはできず、文の意味が通らない。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "ハンカチで仕事を回すという使い方は不自然で、文に合わない。"}, {"text": "虫歯", "is_correct": false, "explanation": "虫歯で仕事を回すという意味にはならず、文に合わない。"}], "explanations": {"チームワーク": "正解。「チームワークで仕事を回しました」として、協力して仕事を進めた意味になる。", "ふとん": "ふとんで仕事を回すことはできず、文の意味が通らない。", "ハンカチ": "ハンカチで仕事を回すという使い方は不自然で、文に合わない。", "虫歯": "虫歯で仕事を回すという意味にはならず、文に合わない。"}, "sentence_index": 6, "correct_answer": "チームワーク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、チームワークをかけて新聞を読みます。", "explanation": "ここは〈メガネ〉（目を補う道具）の意味。チームワークは協力のことで、身につけて使う物ではないので合わない。"}, {"text": "明日のチームワークは晴れです。", "explanation": "ここは「天気」の意味。チームワークは天候ではないので、「晴れ」と組み合わない。"}, {"text": "転んで膝にチームワークができました。", "explanation": "ここは「傷」の意味。チームワークは体にできるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37326, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "選手たちはチームワークを強いので、勝ち続けています。", "corrected_sentence": "選手たちはチームワークが強いので、勝ち続けています。", "error_description": "「強い」の主語は「が」で示す。「を」にすると目的語になり、「チームワークを強い」は不自然。正しくは「チームワークが強い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37326, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、チームワークが生かして作戦を立てました。", "corrected_sentence": "彼女は、チームワークを生かして作戦を立てました。", "error_description": "「生かす」の目的語は「を」で示す。「が」にすると、チームワークが主語になり、「生かして」の目的語がなくなって文として成り立たない。正しくは「チームワークを生かして」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37327, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「大事にする」の対象は「を」で示すので、「チームワークを大事にする」となる。"}, {"text": "が", "is_correct": false, "explanation": "「が」だとチームワークが主語になり、「大事にする」の目的語にならないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「大事にする」は目的語を「を」で示すため、「に」では対象として結びつかず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「大事にする」の対象を表す位置には入らない。"}], "correct_answer": "を", "explanations": {"を": "正解。「大事にする」の対象は「を」で示すので、「チームワークを大事にする」となる。", "が": "「が」だとチームワークが主語になり、「大事にする」の目的語にならないので合わない。", "に": "「大事にする」は目的語を「を」で示すため、「に」では対象として結びつかず不自然。", "で": "「で」は手段や場所を示すので、「大事にする」の対象を表す位置には入らない。"}, "error_tags": {"が": "主語の格", "に": "格の不一致", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37327, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「看護師のチームワーク」として、看護師が属する協力の関係を「の」で結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すため、名詞と名詞を結ぶ位置には入らず、文として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は名詞同士を結ぶ格として使えず、「看護師にチームワーク」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、名詞と名詞をつなぐ位置には合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「看護師のチームワーク」として、看護師が属する協力の関係を「の」で結ぶ。", "を": "「を」は動作の対象を示すため、名詞と名詞を結ぶ位置には入らず、文として不自然。", "に": "「に」は名詞同士を結ぶ格として使えず、「看護師にチームワーク」では意味が通らない。", "へ": "「へ」は方向を示すため、名詞と名詞をつなぐ位置には合わない。"}, "error_tags": {"を": "目的語の格", "に": "格の不一致", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37327, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の人が協力して、共通の目標に向かって行動すること。", "primary_collocate": null, "pronunciation": "ちーむわーく", "ipa": "tɕiːmɯwaːkɯ", "syllable_count": 6, "sentences": [{"text": "会社の新しい商品は、開発部の強いチームワークから生まれました。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の新[あたら]しい商品[しょうひん]は、開発部[かいはつぶ]の強[つよ]いチームワークから生[う]まれました。", "sentence_source": "generated"}, {"text": "チームワークを大事にする監督は、全員に声をかけます。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "チームワークを大事[だいじ]にする監督[かんとく]は、全員[ぜんいん]に声[こえ]をかけます。", "sentence_source": "generated"}, {"text": "目標を決めたあと、チームワークで計画を進めました。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "目標[もくひょう]を決[き]めたあと、チームワークで計画[けいかく]を進[すす]めました。", "sentence_source": "generated"}, {"text": "救助隊はチームワークで、短い時間に全員を助けました。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "救助隊[きゅうじょたい]はチームワークで、短[みじか]い時間[じかん]に全員[ぜんいん]を助[たす]けました。", "sentence_source": "generated"}, {"text": "優れたチームワークがあれば、難しい仕事もやり遂げられます。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "優[すぐ]れたチームワークがあれば、難[むずか]しい仕事[しごと]もやり遂[と]げられます。", "sentence_source": "generated"}, {"text": "新入社員の研修では、チームワークを学ぶ活動があります。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]の研修[けんしゅう]では、チームワークを学[まな]ぶ活動[かつどう]があります。", "sentence_source": "generated"}, {"text": "チームワークが乱れて、プロジェクトの進みが遅れました。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "チームワークが乱[みだ]れて、プロジェクトの進[すす]みが遅[おく]れました。", "sentence_source": "generated"}, {"text": "医者と看護師のチームワークのおかげで、手術は成功しました。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "医者[いしゃ]と看護師[かんごし]のチームワークのおかげで、手術[しゅじゅつ]は成功[せいこう]しました。", "sentence_source": "generated"}, {"text": "チームワークの強さは、試合の最後の場面でよく分かります。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "チームワークの強[つよ]さは、試合[しあい]の最後[さいご]の場面[ばめん]でよく分[わ]かります。", "sentence_source": "generated"}, {"text": "全員が同じ目標に向かう、そんなチームワークを作りたいです。", "target_word": "チームワーク", "complexity_tier": "T3", "furigana": "全員[ぜんいん]が同[おな]じ目標[もくひょう]に向[む]かう、そんなチームワークを作[つく]りたいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チームワーク", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "複数の人が共通の目標のために協力して動くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a7c10f-7617-45e5-a3d0-bcfe1bdfc1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37327, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チームワーク", "is_correct": true, "explanation": "正解。「開発部の強いチームワークから生まれました」として、協力の力が商品を生んだ意味になる。"}, {"text": "大雨", "is_correct": false, "explanation": "大雨から商品が生まれることはなく、文の意味が通らない。"}, {"text": "地震", "is_correct": false, "explanation": "地震から商品が生まれるという文は不自然で、文に合わない。"}, {"text": "寝不足", "is_correct": false, "explanation": "寝不足から商品が生まれるという意味にはならず、文に合わない。"}], "explanations": {"チームワーク": "正解。「開発部の強いチームワークから生まれました」として、協力の力が商品を生んだ意味になる。", "大雨": "大雨から商品が生まれることはなく、文の意味が通らない。", "地震": "地震から商品が生まれるという文は不自然で、文に合わない。", "寝不足": "寝不足から商品が生まれるという意味にはならず、文に合わない。"}, "sentence_index": 0, "correct_answer": "チームワーク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅行のチームワークを立てました。", "explanation": "ここは「計画」の意味。チームワークは計画として立てるものではないので合わない。"}, {"text": "毎日、チームワークを終わらせてから遊びます。", "explanation": "ここは「宿題」の意味。チームワークは終わらせる作業の対象にならないので合わない。"}, {"text": "旅行のためにチームワークを買いました。", "explanation": "ここは「地図」の意味。チームワークは買えるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37327, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チームワーク", "is_correct": true, "explanation": "正解。「チームワークが乱れて」として、協力の状態が乱れて進みが遅れた意味になる。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題が乱れるという言い方は不自然で、文の意味が通らない。"}, {"text": "ケーキ", "is_correct": false, "explanation": "ケーキが乱れるという言い方は不自然で、文に合わない。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "ハンカチが乱れてプロジェクトの進みが遅れるという意味にはならない。"}], "explanations": {"チームワーク": "正解。「チームワークが乱れて」として、協力の状態が乱れて進みが遅れた意味になる。", "宿題": "宿題が乱れるという言い方は不自然で、文の意味が通らない。", "ケーキ": "ケーキが乱れるという言い方は不自然で、文に合わない。", "ハンカチ": "ハンカチが乱れてプロジェクトの進みが遅れるという意味にはならない。"}, "sentence_index": 6, "correct_answer": "チームワーク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しいチームワークが、来週から練習に加わります。", "explanation": "ここは〈メンバー〉（仲間の一人）の意味。チームワークは協力のことで、練習に加わる人の代わりにはならないので合わない。"}, {"text": "ダンスの練習で、チームワークを間違えました。", "explanation": "ここは〈ステップ〉（踊りの足の動き）の意味。チームワークは協力のことで、踊りの動きを指さないので、間違える対象として合わない。"}, {"text": "明日のチームワークは、晴れのち曇りです。", "explanation": "ここは〈天気〉の意味。チームワークは協力のことで、晴れや曇りという天候には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37327, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "全員がチームワークが大切にして、仕事を進めました。", "corrected_sentence": "全員がチームワークを大切にして、仕事を進めました。", "error_description": "「大切にする」の目的語は「を」で示す。「が」にすると、チームワークが主語になり文として不自然。正しくは「チームワークを大切にして」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37327, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私たちは、チームワークを自信があります。", "corrected_sentence": "私たちは、チームワークに自信があります。", "error_description": "「自信がある」は「に」で対象を示す。「を」だと不自然。正しくは「チームワークに自信があります」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37328, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「仮想」を修飾する「の」。「仮想の町」は想定された町の意味で文脈に合う。"}, {"text": "を", "is_correct": false, "explanation": "「仮想を町を」は目的語が二重になり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「仮想が町」では仮想が主語になり、町を歩くという文意に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「仮想へ町」は方向を示す格として不自然で、修飾関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「仮想」を修飾する「の」。「仮想の町」は想定された町の意味で文脈に合う。", "を": "「仮想を町を」は目的語が二重になり、文が成り立たない。", "が": "「仮想が町」では仮想が主語になり、町を歩くという文意に合わない。", "へ": "「仮想へ町」は方向を示す格として不自然で、修飾関係が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "現実", "is_correct": true, "explanation": "「現実」は実際に存在するものを指し、想定された世界を表す「仮想」の対義語。"}, {"text": "夢", "is_correct": false, "explanation": "「夢」は眠っている間に見るものであり、「仮想」の対義語ではない。"}, {"text": "理論", "is_correct": false, "explanation": "「理論」は物事を説明する体系を指し、「仮想」との対義関係にはない。"}, {"text": "伝説", "is_correct": false, "explanation": "「伝説」は言い伝えられた話を指し、「仮想」との対義関係にはない。"}], "correct_answer": "現実", "explanations": {"現実": "「現実」は実際に存在するものを指し、想定された世界を表す「仮想」の対義語。", "夢": "「夢」は眠っている間に見るものであり、「仮想」の対義語ではない。", "理論": "「理論」は物事を説明する体系を指し、「仮想」との対義関係にはない。", "伝説": "「伝説」は言い伝えられた話を指し、「仮想」との対義関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37328, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "現実", "is_correct": true, "explanation": "「現実」は実際に存在するものを指し、想定された存在を表す「仮想」の対義語。"}, {"text": "空論", "is_correct": false, "explanation": "「空論」は現実性のない議論を指し、「仮想」との対義関係にはない。"}, {"text": "幻", "is_correct": false, "explanation": "「幻」は見えても実体のないものを指し、「仮想」の対義語ではない。"}, {"text": "童話", "is_correct": false, "explanation": "「童話」は子ども向けの物語を指し、「仮想」との対義関係にはない。"}], "correct_answer": "現実", "explanations": {"現実": "「現実」は実際に存在するものを指し、想定された存在を表す「仮想」の対義語。", "空論": "「空論」は現実性のない議論を指し、「仮想」との対義関係にはない。", "幻": "「幻」は見えても実体のないものを指し、「仮想」の対義語ではない。", "童話": "「童話」は子ども向けの物語を指し、「仮想」との対義関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37328, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ほんとうにはないけれど、あるとおもってつくるせかいのこと。", "primary_collocate": null, "pronunciation": "かそう", "ipa": "kasoː", "syllable_count": 3, "sentences": [{"text": "子どもたちは仮想の世界で冒険ごっこを楽しんだ。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "子[こ]どもたちは仮想[かそう]の世界[せかい]で冒険[ぼうけん]ごっこを楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "このゲームでは、仮想の町を自由に歩ける。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "このゲームでは、仮想[かそう]の町[まち]を自由[じゆう]に歩[ある]ける。", "sentence_source": "generated"}, {"text": "妹は仮想の国の地図を描いて遊んでいる。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "妹[いもうと]は仮想[かそう]の国[くに]の地図[ちず]を描[か]いて遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "仮想の世界には、本当の雨は降らない。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "仮想[かそう]の世界[せかい]には、本当[ほんとう]の雨[あめ]は降[ふ]らない。", "sentence_source": "generated"}, {"text": "兄は仮想の動物を作って、絵本に描いた。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "兄[あに]は仮想[かそう]の動物[どうぶつ]を作[つく]って、絵本[えほん]に描[えが]いた。", "sentence_source": "generated"}, {"text": "仮想の店で、友だちと買い物ごっこをした。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "仮想[かそう]の店[みせ]で、友[とも]だちと買[か]い物[もの]ごっこをした。", "sentence_source": "generated"}, {"text": "本物の島ではなく、画面の中の仮想の島を探検した。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "本物[ほんもの]の島[しま]ではなく、画面[がめん]の中[なか]の仮想[かそう]の島[しま]を探検[たんけん]した。", "sentence_source": "generated"}, {"text": "先生は仮想の町を使って、道の渡り方を教えてくれた。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "先生[せんせい]は仮想[かそう]の町[まち]を使[つか]って、道[みち]の渡[わた]り方[かた]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "仮想の世界の中でも、約束はきちんと守りたい。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "仮想[かそう]の世界[せかい]の中[なか]でも、約束[やくそく]はきちんと守[まも]りたい。", "sentence_source": "generated"}, {"text": "彼は仮想の友だちと話すのが好きな子どもだった。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "彼[かれ]は仮想[かそう]の友[とも]だちと話[はな]すのが好[す]きな子[こ]どもだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仮想", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "本当はないが、あると思って作る世界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37328, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仮想", "is_correct": true, "explanation": "「仮想の世界」は現実にはないが、あるとして作られた世界を指し、冒険ごっこの舞台として合う。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹の世界」は意味をなさず、冒険ごっこの舞台としても合わない。"}, {"text": "返事", "is_correct": false, "explanation": "「返事の世界」は成り立たず、子どもが遊ぶ場面に合わない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重の世界」は意味が通らず、冒険ごっこの文脈に合わない。"}], "explanations": {"仮想": "「仮想の世界」は現実にはないが、あるとして作られた世界を指し、冒険ごっこの舞台として合う。", "空腹": "「空腹の世界」は意味をなさず、冒険ごっこの舞台としても合わない。", "返事": "「返事の世界」は成り立たず、子どもが遊ぶ場面に合わない。", "体重": "「体重の世界」は意味が通らず、冒険ごっこの文脈に合わない。"}, "sentence_index": 0, "correct_answer": "仮想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ハロウィンの夜、子どもたちは仮想をして町を歩いた。", "explanation": "「仮装」（衣装を着ること）と同音で混同しやすい語。「仮想」は想定を表すので、衣装を着る行為には使わない。"}, {"text": "引っ越しが決まるまで、私たちは仮想の住まいで暮らしている。", "explanation": "ここは〈仮住まい〉の意味。「仮想」は想定された世界を指し、一時的な住まいの意味にはならない。"}, {"text": "薬を飲んでから、彼は部屋の中に仮想を見るようになった。", "explanation": "ここは〈幻覚〉の意味。「幻覚を見る」の形で使う語で、「仮想」は見る対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37328, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仮想", "is_correct": true, "explanation": "「仮想の島」は画面の中だけに想定された島を指し、「本物の島」と対比されて文意に合う。"}, {"text": "湿気", "is_correct": false, "explanation": "「湿気の島」は成り立たず、探検の対象にならない。"}, {"text": "倫理", "is_correct": false, "explanation": "「倫理の島」は意味が通らず、画面の中の島という文脈に合わない。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足の島」は意味をなさず、探検の文脈に合わない。"}], "explanations": {"仮想": "「仮想の島」は画面の中だけに想定された島を指し、「本物の島」と対比されて文意に合う。", "湿気": "「湿気の島」は成り立たず、探検の対象にならない。", "倫理": "「倫理の島」は意味が通らず、画面の中の島という文脈に合わない。", "寝不足": "「寝不足の島」は意味をなさず、探検の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "仮想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "決勝で圧倒的だった彼は、仮想の優勝者として表彰された。", "explanation": "ここは〈実質的〉〈事実上〉の意味。「仮想」は想定された存在を指すので、この意味では使わない。"}, {"text": "その計画は一度も実行されず、仮想に終わった。", "explanation": "ここは〈空論〉の意味。「空論に終わる」の形で使う語で、「仮想」は「終わる」の結果にならない。"}, {"text": "長年の仮想が、ついにかなった。", "explanation": "ここは〈夢〉の意味。「夢がかなう」の形で使う語で、「仮想」は願いの対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37328, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゲームの中で仮想に町を歩いた。", "corrected_sentence": "ゲームの中で仮想の町を歩いた。", "error_description": "「仮想」の後の「に」は誤りで、名詞を修飾するには「の」を使う。正しくは「仮想の町」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37328, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は仮想な友だちを作って、寂しさを埋めた。", "corrected_sentence": "彼は仮想の友だちを作って、寂しさを埋めた。", "error_description": "「仮想」は名詞なので、「な」ではなく「の」で修飾する。正しくは「仮想の友だち」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37329, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「仮想」を修飾する「の」。「仮想の敵」は想定された敵の意味で文脈に合う。"}, {"text": "が", "is_correct": false, "explanation": "「仮想が敵」では仮想が主語になり、軍が敵を設定するという文意に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「仮想に敵」は名詞を結ぶ格として不自然で、「仮想の敵」の修飾関係が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「仮想から敵」は仮想を起点とする意味になり、想定された敵という意味にならない。"}], "correct_answer": "の", "explanations": {"の": "「仮想」を修飾する「の」。「仮想の敵」は想定された敵の意味で文脈に合う。", "が": "「仮想が敵」では仮想が主語になり、軍が敵を設定するという文意に合わない。", "に": "「仮想に敵」は名詞を結ぶ格として不自然で、「仮想の敵」の修飾関係が成り立たない。", "から": "「仮想から敵」は仮想を起点とする意味になり、想定された敵という意味にならない。"}, "error_tags": {"が": "主語", "に": "位置・対象", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "現実", "is_correct": true, "explanation": "「現実」は実際に存在するものを指し、存在しないが存在するとみなす「仮想」の対義語。"}, {"text": "夢", "is_correct": false, "explanation": "「夢」は見るものであり、「仮想」の対義語にはならない。"}, {"text": "空想", "is_correct": false, "explanation": "「空想」は「仮想」に近い意味の語で、対義語の関係にはない。"}, {"text": "理論", "is_correct": false, "explanation": "「理論」は物事を説明する体系を指し、「仮想」との対義関係にはない。"}], "correct_answer": "現実", "explanations": {"現実": "「現実」は実際に存在するものを指し、存在しないが存在するとみなす「仮想」の対義語。", "夢": "「夢」は見るものであり、「仮想」の対義語にはならない。", "空想": "「空想」は「仮想」に近い意味の語で、対義語の関係にはない。", "理論": "「理論」は物事を説明する体系を指し、「仮想」との対義関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
