INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37329, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "現実には存在しないが、あたかも存在するかのように想定したもの。", "primary_collocate": null, "pronunciation": "かそう", "ipa": "kasoː", "syllable_count": 3, "sentences": [{"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな冷徹さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "仮想", "complexity_tier": "T4", "furigana": "仮想[かそう]空間[くうかん]上[じょう]で構築[こうちく]される3Dモデリングやアルゴリズムによる生成物[せいせいぶつ]は、かつての「仕立[した]て屋[や]」の矜持[きょうじ]をどう書[か]き換[か]えているのか。そこには、アナログな温[ぬく]もりとデジタルな冷徹[れいてつ]さの間[あいだ]の絶[た]え間[ま]ない緊張[きんちょう]関係[かんけい]が見[み]て取[と]れ、それは創造性[そうぞうせい]の本質[ほんしつ]を問[と]うている。", "sentence_source": "mined"}, {"text": "軍は仮想の敵を設定して、防衛訓練を行った。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "軍[ぐん]は仮想[かそう]の敵[てき]を設定[せってい]して、防衛[ぼうえい]訓練[くんれん]を行[おこな]った。", "sentence_source": "generated"}, {"text": "この研究では、人口が半分に減る仮想の状況を考える。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "この研究[けんきゅう]では、人口[じんこう]が半分[はんぶん]に減[へ]る仮想[かそう]の状況[じょうきょう]を考[かんが]える。", "sentence_source": "generated"}, {"text": "仮想の登場人物を作り、その人の一日を詳しく描いた。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "仮想[かそう]の登場人物[とうじょうじんぶつ]を作[つく]り、その人[ひと]の一日[いちにち]を詳[くわ]しく描[えが]いた。", "sentence_source": "generated"}, {"text": "実際の事故ではなく、仮想の事例を使って安全教育を行う。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "実際[じっさい]の事故[じこ]ではなく、仮想[かそう]の事例[じれい]を使[つか]って安全[あんぜん]教育[きょういく]を行[おこな]う。", "sentence_source": "generated"}, {"text": "授業では、仮想の会社を作って経営を学ぶ。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]では、仮想[かそう]の会社[かいしゃ]を作[つく]って経営[けいえい]を学[まな]ぶ。", "sentence_source": "generated"}, {"text": "仮想の数字を入れて計算したので、結果は実際と異なる。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "仮想[かそう]の数字[すうじ]を入[い]れて計算[けいさん]したので、結果[けっか]は実際[じっさい]と異[こと]なる。", "sentence_source": "generated"}, {"text": "彼は仮想の相手を前にして、何度も面接の練習をした。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "彼[かれ]は仮想[かそう]の相手[あいて]を前[まえ]にして、何度[なんど]も面接[めんせつ]の練習[れんしゅう]をした。", "sentence_source": "generated"}, {"text": "仮想の災害を舞台にした避難訓練に、町の全員が参加した。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "仮想[かそう]の災害[さいがい]を舞台[ぶたい]にした避難訓練[ひなんくんれん]に、町[まち]の全員[ぜんいん]が参加[さんか]した。", "sentence_source": "generated"}, {"text": "現実と仮想を混同すると、判断を誤ることがある。", "target_word": "仮想", "complexity_tier": "T3", "furigana": "現実[げんじつ]と仮想[かそう]を混同[こんどう]すると、判断[はんだん]を誤[あやま]ることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仮想", "label": "基本形"}], "register": "formal", "sense_fingerprint": "現実にはないものを、あるものとして想定すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 7 words above tier T3 (max 3): モデリング (Zipf 3.39), 仕立て屋 (Zipf 2.64), 矜持 (Zipf 2.79), 温もり (Zipf 3.24), 冷徹 (Zipf 3.22), 絶え間 (Zipf 3.08)']::text[], '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37329, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仮想", "is_correct": true, "explanation": "「仮想空間」は現実には存在しないが存在するものとして想定した空間を指し、3Dモデリングの文脈に合う。"}, {"text": "恋愛", "is_correct": false, "explanation": "「恋愛空間」という語はなく、「空間上で構築される」の前に置くと意味が通らない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "ものの名前で、「空間上で構築される」の修飾として意味が成り立たない。"}, {"text": "交通", "is_correct": false, "explanation": "「交通空間」は一般的な語ではなく、「空間上で構築される」の修飾として文脈に合わない。"}], "explanations": {"仮想": "「仮想空間」は現実には存在しないが存在するものとして想定した空間を指し、3Dモデリングの文脈に合う。", "恋愛": "「恋愛空間」という語はなく、「空間上で構築される」の前に置くと意味が通らない。", "鉛筆": "ものの名前で、「空間上で構築される」の修飾として意味が成り立たない。", "交通": "「交通空間」は一般的な語ではなく、「空間上で構築される」の修飾として文脈に合わない。"}, "sentence_index": 0, "correct_answer": "仮想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨で試合が中止になり、勝ち点の多いチームが仮想の優勝者になった。", "explanation": "「事実上の優勝者」の意味で「仮想」を使うのは誤り。「仮想」は想定された存在を指す語で、この意味では使わない。"}, {"text": "授業中、彼は仮想にふけって窓の外を見ていた。", "explanation": "ここは〈空想〉の意味。「空想にふける」の形で使う語で、「仮想」はふける対象にならない。"}, {"text": "彼の論文は仮想を置いて議論を組み立てている。", "explanation": "ここは〈仮定〉の意味。「仮定を置く」の形で使う語で、「仮想」は置く対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37329, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仮想", "is_correct": true, "explanation": "「仮想の数字」は実際にはない想定の数字を指し、計算の文脈に合う。"}, {"text": "感情", "is_correct": false, "explanation": "「感情の数字」は成り立たず、数字を入れて計算する文脈に合わない。"}, {"text": "倫理", "is_correct": false, "explanation": "「倫理の数字」は意味が通らず、計算に数字を入れるという文に合わない。"}, {"text": "信念", "is_correct": false, "explanation": "「信念の数字」は不自然で、計算の文脈には合わない。"}], "explanations": {"仮想": "「仮想の数字」は実際にはない想定の数字を指し、計算の文脈に合う。", "感情": "「感情の数字」は成り立たず、数字を入れて計算する文脈に合わない。", "倫理": "「倫理の数字」は意味が通らず、計算に数字を入れるという文に合わない。", "信念": "「信念の数字」は不自然で、計算の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "仮想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会長が退いたので、実権を握る彼は仮想の社長になった。", "explanation": "ここは〈事実上〉の意味。「仮想」は想定された存在を指すので、実際に権限を持つ人には使わない。"}, {"text": "会社は仮想を掲げ、社員と共に目標に向かった。", "explanation": "ここは〈理想〉の意味。「理想を掲げる」の形で使う語で、「仮想」は掲げる対象にならない。"}, {"text": "昨夜、彼は仮想を見て、朝まで眠れなかった。", "explanation": "ここは〈夢〉の意味。「夢を見る」の形で使う語で、「仮想」は見る対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37329, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この調査では、仮想な状況を想定してデータを集めた。", "corrected_sentence": "この調査では、仮想の状況を想定してデータを集めた。", "error_description": "「仮想」は名詞なので、名詞を修飾するには「の」を使う。「仮想な」は誤りで、正しくは「仮想の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37329, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は仮想に敵と戦う訓練をした。", "corrected_sentence": "彼は仮想の敵と戦う訓練をした。", "error_description": "「仮想」は名詞を修飾するので「の」を使う。「に」は誤りで、正しくは「仮想の敵」の「の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
