INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37330, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「ゲームを為る」は、あそびをすることです。", "primary_collocate": null, "pronunciation": "げーむをする", "ipa": "ɡeːmɯ o sɯɾɯ", "syllable_count": 6, "sentences": [{"text": "宿題が終わったら、ゲームをします。", "target_word": "ゲームをします", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が終[お]わったら、ゲームをします。", "sentence_source": "generated"}, {"text": "弟は毎晩、友達とゲームをして遊びます。", "target_word": "ゲームをして", "complexity_tier": "T3", "furigana": "弟[おとうと]は毎晩[まいばん]、友達[ともだち]とゲームをして遊[あそ]びます。", "sentence_source": "generated"}, {"text": "雨の日は外に出られないので、家でゲームをした。", "target_word": "ゲームをした", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は外[そと]に出[で]られないので、家[いえ]でゲームをした。", "sentence_source": "generated"}, {"text": "夜遅くまでゲームをすると、朝起きられません。", "target_word": "ゲームをする", "complexity_tier": "T3", "furigana": "夜遅[よるおそ]くまでゲームをすると、朝起[あさお]きられません。", "sentence_source": "generated"}, {"text": "試験の前なので、今週はゲームをしないつもりだ。", "target_word": "ゲームをしない", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]なので、今週[こんしゅう]はゲームをしないつもりだ。", "sentence_source": "generated"}, {"text": "休み時間に、みんなでゲームをして笑った。", "target_word": "ゲームをして", "complexity_tier": "T3", "furigana": "休[やす]み時間[じかん]に、みんなでゲームをして笑[わら]った。", "sentence_source": "generated"}, {"text": "父は仕事から帰ると、少しだけゲームをします。", "target_word": "ゲームをします", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]から帰[かえ]ると、少[すこ]しだけゲームをします。", "sentence_source": "generated"}, {"text": "昨日は妹とずっとゲームをしていたので、疲れた。", "target_word": "ゲームをして", "complexity_tier": "T3", "furigana": "昨日[きのう]は妹[いもうと]とずっとゲームをしていたので、疲[つか]れた。", "sentence_source": "generated"}, {"text": "目が悪くなるから、暗い部屋でゲームをしてはいけません。", "target_word": "ゲームをして", "complexity_tier": "T4", "furigana": "目[め]が悪[わる]くなるから、暗[くら]い部屋[へや]でゲームをしてはいけません。", "sentence_source": "generated"}, {"text": "今度の日曜日に、いとこと一緒にゲームをしたい。", "target_word": "ゲームをしたい", "complexity_tier": "T3", "furigana": "今度[こんど]の日曜日[にちようび]に、いとこと一緒[いっしょ]にゲームをしたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゲームをする", "label": "dictionary"}, {"form": "ゲームをして", "label": "te-form"}, {"form": "ゲームをした", "label": "past"}, {"form": "ゲームをしない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "ゲームで遊ぶ（遊びとして行う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7bfaf5f-7601-4049-bf95-765962747195') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37330, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ゲームをします", "is_correct": true, "explanation": "宿題のあとにゲームで遊ぶという意味で、文の内容に合う。"}, {"text": "ゲームを読みます", "is_correct": false, "explanation": "「読む」はゲームには使わないので、この文には合わない。"}, {"text": "ゲームを食べます", "is_correct": false, "explanation": "ゲームは食べられないので、「食べる」とは組み合わない。"}, {"text": "ゲームを飲みます", "is_correct": false, "explanation": "ゲームは飲めないので、「飲む」とは組み合わない。"}], "explanations": {"ゲームをします": "宿題のあとにゲームで遊ぶという意味で、文の内容に合う。", "ゲームを読みます": "「読む」はゲームには使わないので、この文には合わない。", "ゲームを食べます": "ゲームは食べられないので、「食べる」とは組み合わない。", "ゲームを飲みます": "ゲームは飲めないので、「飲む」とは組み合わない。"}, "sentence_index": 0, "correct_answer": "ゲームをします"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その店は毎週、新作のゲームをしている。", "explanation": "「ゲームをする」は遊ぶ意味だけなので、店が商品を扱う文には合わない。"}, {"text": "あの会社は毎年、新しいゲームをしている。", "explanation": "「ゲームをする」は遊ぶ意味だけなので、会社が開発する文には合わない。"}, {"text": "医者は患者の血液を、ゲームをして調べた。", "explanation": "「ゲームをする」は遊ぶ意味だけなので、医療の検査の文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37330, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ゲームをします", "is_correct": true, "explanation": "仕事のあとに少し遊ぶという意味で、文の内容に合う。"}, {"text": "ゲームを洗います", "is_correct": false, "explanation": "「洗う」はゲームには使わないので、この文には合わない。"}, {"text": "ゲームを煮ます", "is_correct": false, "explanation": "ゲームは煮ることができないので、「煮る」とは組み合わない。"}, {"text": "ゲームを歌います", "is_correct": false, "explanation": "ゲームは歌えないので、「歌う」とは組み合わない。"}], "explanations": {"ゲームをします": "仕事のあとに少し遊ぶという意味で、文の内容に合う。", "ゲームを洗います": "「洗う」はゲームには使わないので、この文には合わない。", "ゲームを煮ます": "ゲームは煮ることができないので、「煮る」とは組み合わない。", "ゲームを歌います": "ゲームは歌えないので、「歌う」とは組み合わない。"}, "sentence_index": 6, "correct_answer": "ゲームをします"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "いとこは来年、工場で新しいゲームをしたい。", "explanation": "「ゲームをする」は遊ぶ意味だけなので、工場で作る文には合わない。"}, {"text": "いとこは会議で、予算の数字をゲームをして変えた。", "explanation": "「ゲームをする」は遊ぶ意味だけなので、数字を書き換える文には合わない。"}, {"text": "いとこは宿題の答えを、ゲームをして書き写した。", "explanation": "「ゲームをする」は遊ぶ意味だけなので、答えを写す作業には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37330, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日は一時間ゲームをするました。", "corrected_sentence": "昨日は一時間ゲームをしました。", "error_description": "「ゲームをする」の連用形は「し」で、「ました」に続けるには「しました」が正しい。「するました」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ゲームをする", "is_correct": false, "explanation": "辞書形なので、「ゲームをして遊びます」の「して」の形にならない。"}, {"text": "ゲームをした", "is_correct": false, "explanation": "過去形なので、「ゲームをして遊びます」の形にならない。"}, {"text": "ゲームをしない", "is_correct": false, "explanation": "否定形なので、友達と遊ぶという文の内容と合わない。"}, {"text": "ゲームをして", "is_correct": true, "explanation": "て形で、「遊びます」につながる文の形に合う。"}], "correct_form": "ゲームをして", "base_form": "ゲームをする", "form_label": "て形", "sentence_index": 1, "explanations": {"ゲームをする": "辞書形なので、「ゲームをして遊びます」の「して」の形にならない。", "ゲームをした": "過去形なので、「ゲームをして遊びます」の形にならない。", "ゲームをしない": "否定形なので、友達と遊ぶという文の内容と合わない。", "ゲームをして": "て形で、「遊びます」につながる文の形に合う。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37330, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕方、弟とゲームをするて遊んだ。", "corrected_sentence": "夕方、弟とゲームをして遊んだ。", "error_description": "「ゲームをする」の連用形は「し」で、「て」に続けるには「して」が正しい。「するて」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ゲームをして", "is_correct": true, "explanation": "て形で、「ずっとしていた」につながる文の形として合う。"}, {"text": "ゲームをしよう", "is_correct": false, "explanation": "意志形なので、過去の出来事を述べる文には合わない。"}, {"text": "ゲームをしたら", "is_correct": false, "explanation": "条件形なので、「ずっと遊んでいた」という文の意味と合わない。"}, {"text": "ゲームをさせた", "is_correct": false, "explanation": "使役形なので、誰かに遊ばせたという意味になり文と合わない。"}], "correct_form": "ゲームをして", "base_form": "ゲームをする", "form_label": "て形", "sentence_index": 7, "explanations": {"ゲームをして": "て形で、「ずっとしていた」につながる文の形として合う。", "ゲームをしよう": "意志形なので、過去の出来事を述べる文には合わない。", "ゲームをしたら": "条件形なので、「ずっと遊んでいた」という文の意味と合わない。", "ゲームをさせた": "使役形なので、誰かに遊ばせたという意味になり文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37332, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "本物", "is_correct": true, "explanation": "「偽」の対義語で、本当に作られた本来の品物を指す。"}, {"text": "模造", "is_correct": false, "explanation": "本物に似せた品で、「偽」の類義語であって対義語ではない。"}, {"text": "複製", "is_correct": false, "explanation": "写しを作る意味で、「偽」と同じ側にある類義語であり対義語ではない。"}, {"text": "装飾", "is_correct": false, "explanation": "飾りを表す名詞で、「偽」の対義語とはされない。"}], "correct_answer": "本物", "explanations": {"本物": "「偽」の対義語で、本当に作られた本来の品物を指す。", "模造": "本物に似せた品で、「偽」の類義語であって対義語ではない。", "複製": "写しを作る意味で、「偽」と同じ側にある類義語であり対義語ではない。", "装飾": "飾りを表す名詞で、「偽」の対義語とはされない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37332, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "本物", "is_correct": true, "explanation": "「偽」の対義語で、本当に作られた本来の品物を指す。"}, {"text": "贋作", "is_correct": false, "explanation": "偽物の作品を指す名詞で、「偽」の類義語であって対義語ではない。"}, {"text": "手作り", "is_correct": false, "explanation": "自分で作った品を指す名詞で、「偽」の対義語とはされない。"}, {"text": "大人", "is_correct": false, "explanation": "成人を指す名詞で、「偽」とは関係がなく対義語でもない。"}], "correct_answer": "本物", "explanations": {"本物": "「偽」の対義語で、本当に作られた本来の品物を指す。", "贋作": "偽物の作品を指す名詞で、「偽」の類義語であって対義語ではない。", "手作り": "自分で作った品を指す名詞で、「偽」の対義語とはされない。", "大人": "成人を指す名詞で、「偽」とは関係がなく対義語でもない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37332, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "本物ではないこと。本当ではないこと。", "primary_collocate": null, "pronunciation": "にせ", "ipa": "ɲise", "syllable_count": 2, "sentences": [{"text": "この時計は偽のブランド品だったので、店で返品しました。", "target_word": "偽", "complexity_tier": "T3", "furigana": "この時計[とけい]は偽[にせ]のブランド品[ひん]だったので、店[みせ]で返品[へんぴん]しました。", "sentence_source": "generated"}, {"text": "偽のダイヤモンドは、光り方が本物と少し違います。", "target_word": "偽", "complexity_tier": "T3", "furigana": "偽[にせ]のダイヤモンドは、光[ひか]り方[かた]が本物[ほんもの]と少[すこ]し違[ちが]います。", "sentence_source": "generated"}, {"text": "美術館に飾られていた名画が偽の作品だと分かり、大きな問題になりました。", "target_word": "偽", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]に飾[かざ]られていた名画[めいが]が偽[にせ]の作品[さくひん]だと分かり、大[おお]きな問題[もんだい]になりました。", "sentence_source": "generated"}, {"text": "友だちにもらった財布は偽の革製品で、すぐに糸がほどけてしまいました。", "target_word": "偽", "complexity_tier": "T3", "furigana": "友[とも]だちにもらった財布[さいふ]は偽[にせ]の革製品[かわせいひん]で、すぐに糸[いと]がほどけてしまいました。", "sentence_source": "generated"}, {"text": "偽のサインが入った写真は、本物より安く売られていました。", "target_word": "偽", "complexity_tier": "T3", "furigana": "偽[にせ]のサインが入[はい]った写真[しゃしん]は、本物[ほんもの]より安[やす]く売[う]られていました。", "sentence_source": "generated"}, {"text": "偽の薬を飲んでも、病気は治りません。", "target_word": "偽", "complexity_tier": "T3", "furigana": "偽[にせ]の薬[くすり]を飲[の]んでも、病気[びょうき]は治[なお]りません。", "sentence_source": "generated"}, {"text": "偽のお金を使うことは、法律で禁止されています。", "target_word": "偽", "complexity_tier": "T3", "furigana": "偽[にせ]のお金[かね]を使[つか]うことは、法律[ほうりつ]で禁止[きんし]されています。", "sentence_source": "generated"}, {"text": "玄関に偽の花を飾っていますが、近くで見ると作り物だと分かります。", "target_word": "偽", "complexity_tier": "T3", "furigana": "玄関[げんかん]に偽[にせ]の花[はな]を飾[かざ]っていますが、近[ちか]くで見[み]ると作[つく]り物[もの]だと分かります。", "sentence_source": "generated"}, {"text": "偽の宝石をつけていましたが、店の人にすぐ見破られました。", "target_word": "偽", "complexity_tier": "T3", "furigana": "偽[にせ]の宝石[ほうせき]をつけていましたが、店[みせ]の人[ひと]にすぐ見破[みやぶ]られました。", "sentence_source": "generated"}, {"text": "彼は偽の切符を見せて、電車に乗ろうとしました。", "target_word": "偽", "complexity_tier": "T3", "furigana": "彼[かれ]は偽[にせ]の切符[きっぷ]を見[み]せて、電車[でんしゃ]に乗[の]ろうとしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "偽", "label": "基本形"}, {"form": "偽の", "label": "連体修飾（の）"}, {"form": "偽だ", "label": "断定形"}, {"form": "偽で", "label": "で形"}], "register": "neutral", "sense_fingerprint": "本物に似せて作った物で、本物ではないこと（偽造品・模造品）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24bff216-7aef-4422-8d8a-73355dcf2e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37332, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偽", "is_correct": true, "explanation": "名詞として「偽のブランド品」と続け、本物ではない品物を表す。"}, {"text": "偽る", "is_correct": false, "explanation": "動詞で、名詞の前に「の」を付けて修飾する形にならない。"}, {"text": "偽って", "is_correct": false, "explanation": "て形の動詞で、名詞句の一部として「の」に続けられない。"}, {"text": "偽ろう", "is_correct": false, "explanation": "意志形の動詞で、名詞の前に置いて修飾することができない。"}], "explanations": {"偽": "名詞として「偽のブランド品」と続け、本物ではない品物を表す。", "偽る": "動詞で、名詞の前に「の」を付けて修飾する形にならない。", "偽って": "て形の動詞で、名詞句の一部として「の」に続けられない。", "偽ろう": "意志形の動詞で、名詞の前に置いて修飾することができない。"}, "sentence_index": 0, "correct_answer": "偽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "偽のダイヤモンドを鑑定したら、本物だと分かりました。", "explanation": "ここは〈本物〉の意味で使っている。偽は本物ではないという意味なので、「偽のダイヤが本物だ」は矛盾する。"}, {"text": "彼の偽の言葉は、いつも本当の気持ちを表していた。", "explanation": "ここは〈本当の・真実の〉の意味。偽は本当ではないという意味なので、「偽の言葉が本当の気持ちを表す」は矛盾する。"}, {"text": "この偽の地図は、正確な道を示していた。", "explanation": "ここは〈正確な・正しい〉の意味。偽は本物ではないという意味なので、「偽の地図が正確だ」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37332, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偽", "is_correct": true, "explanation": "名詞として「偽のお金」と続け、本物ではない紙幣や硬貨を表す。"}, {"text": "偽らない", "is_correct": false, "explanation": "否定形の動詞で、名詞の前に「の」を付けて修飾することができない。"}, {"text": "偽れ", "is_correct": false, "explanation": "命令形で、名詞句の一部として成立しない。"}, {"text": "偽ります", "is_correct": false, "explanation": "丁寧形の動詞で、「の」に続けて名詞を修飾できない。"}], "explanations": {"偽": "名詞として「偽のお金」と続け、本物ではない紙幣や硬貨を表す。", "偽らない": "否定形の動詞で、名詞の前に「の」を付けて修飾することができない。", "偽れ": "命令形で、名詞句の一部として成立しない。", "偽ります": "丁寧形の動詞で、「の」に続けて名詞を修飾できない。"}, "sentence_index": 6, "correct_answer": "偽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "偽の約束を守って、彼は本当に信用を得た。", "explanation": "ここは〈守られた約束〉の意味で使っている。偽は本当ではないという意味なので、「偽の約束を守る」は矛盾する。"}, {"text": "偽の値札は、商品の本当の価格をそのまま示していた。", "explanation": "ここは〈正しい・本当〉の意味。偽は本当ではないという意味なので、「偽の値札が本当の価格を示す」は矛盾する。"}, {"text": "偽の友人が、いつも本当の味方になってくれた。", "explanation": "ここは〈本当の味方〉の意味。偽は本当ではないという意味なので、「偽の友人が本当の味方になる」は矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
